window.LEGE_CONTROL = {"items":[{"id":"art-1-1","article":"1","articleNumber":1,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"Unde se aplică ROFUIP?","options":["în toate unitățile de învățământ","numai în școlile cu personalitate juridică","numai în școlile de stat","numai în școlile gimnaziale"],"answer":0,"term":"în toate unitățile de învățământ","quote":"Regulamentul-cadru de organizare și funcționare a unităților de învățământ preuniversitar, denumit în continuare regulament, reglementează organizarea și funcționarea unităților de învățământ preuniversitar, denumite în continuare unități de învățământ, în cadrul sistemului de învățământ din România, în conformitate cu prevederile legale în vigoare, și se aplică în toate unitățile de învățământ.","context":"","source":"Art. 1, alin. (1)","unit":1},{"id":"art-2-1","article":"2","articleNumber":2,"block":1,"fromPoint":1,"toPoint":8,"pointCount":12,"prompt":"Cine aprobă regulamentul propriu de organizare și funcționare?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"Regulamentul de organizare și funcționare a unității de învățământ, precum și modificările ulterioare ale acestuia se aprobă, prin hotărâre, de către consiliul de administrație.","context":"","source":"Art. 2, alin. (5)","unit":5},{"id":"art-2-2","article":"2","articleNumber":2,"block":2,"fromPoint":9,"toPoint":12,"pointCount":12,"prompt":"Cine aprobă regulamentul de ordine interioară?","options":["consiliului clasei","Consiliului de Administrație","consiliului elevilor","consiliului profesoral"],"answer":1,"term":"Consiliului de Administrație","quote":"Regulamentul de ordine interioară se aprobă prin hotărâre a consiliului de administrație, după consultarea consiliului profesoral, a consiliului școlar al beneficiarilor primari, a consiliului reprezentativ al părinților/reprezentanților legali și asociației de părinți, acolo unde există, a reprezentanților organizațiilor sindicale care au membri în unitatea de învățământ, afiliate la federațiile sindicale reprezentative la nivel de sector de activitate negociere colectivă învățământ preuniversitar și se aduce la cunoștință prin afișare pe site sau punerea la dispoziția autorităților prevăzute la art. 63 alin. (1) din Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare.","context":"","source":"Art. 2, alin. (11)","unit":11},{"id":"art-3-1","article":"3","articleNumber":3,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Pe ce își fundamentează conducerea deciziile?","options":["decizia exclusivă a directorului","dialog și consultare","solicitările operatorilor economici","votul exclusiv al părinților"],"answer":1,"term":"dialog și consultare","quote":"Conducerile unităților de învățământ își fundamentează deciziile pe dialog și consultare, promovând participarea părinților/reprezentanților legali la viața școlii, respectând dreptul la opinie al elevului și asigurând transparența deciziilor și a rezultatelor, printr-o comunicare periodică, adecvată a acestora, în conformitate cu Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare.","context":"","source":"Art. 3, alin. (2)","unit":2},{"id":"art-4-1","article":"4","articleNumber":4,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Școala funcționează independent de ce ingerințe?","options":["administrative sau contabile","educative sau culturale","pedagogice sau metodice","politice sau religioase"],"answer":3,"term":"politice sau religioase","quote":"Unitățile de învățământ se organizează și funcționează independent de orice ingerințe politice sau religioase, în incinta acestora fiind interzise crearea și funcționarea oricăror formațiuni politice, organizarea și desfășurarea activităților de natură politică și prozelitism religios, precum și orice formă de activitate care încalcă normele de conduită morală și conviețuire socială, care pun în pericol sănătatea, integritatea fizică sau psihică a beneficiarilor primari sau a personalului din unitatea de învățământ.","context":"","source":"Art. 4","unit":1},{"id":"art-5-1","article":"5","articleNumber":5,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"În ce sistem se includ datele beneficiarilor primari?","options":["Registrul asociațiilor și fundațiilor","Registrul unic al salariaților","Sistemul Electronic de Achiziții Publice","Sistemul Informatic Integrat al Învățământului din România (SIIIR)"],"answer":3,"term":"Sistemul Informatic Integrat al Învățământului din România (SIIIR)","quote":"Unitățile de învățământ care fac parte din rețeaua școlară națională au obligația de a include în Sistemul Informatic Integrat al Învățământului din România (SIIIR), datele referitoare la beneficiarii primari școlarizați.","context":"","source":"Art. 5","unit":2},{"id":"art-6-1","article":"6","articleNumber":6,"block":1,"fromPoint":1,"toPoint":8,"pointCount":9,"prompt":"Ce cod este element definitoriu al unei școli cu personalitate juridică?","options":["cod de acces electronic","cod de clasificare a ocupațiilor","cod de identificare fiscală (CIF)","cod poștal unic"],"answer":2,"term":"cod de identificare fiscală (CIF)","quote":"cod de identificare fiscală (CIF);","context":"Unitatea de învățământ preuniversitar cu personalitate juridică (PJ) este orice unitate de învățământ autorizată să funcționeze provizoriu/acreditată din sistemul național de învățământ preuniversitar, care are următoarele elemente definitorii:","source":"Art. 6","unit":5},{"id":"art-6-2","article":"6","articleNumber":6,"block":2,"fromPoint":9,"toPoint":9,"pointCount":9,"prompt":"Structurile școlare arondate au personalitate juridică?","options":["cu personalitate juridică distinctă","cu personalitate juridică proprie","cu personalitate juridică temporară","fără personalitate juridică"],"answer":3,"term":"fără personalitate juridică","quote":"O unitate de învățământ cu personalitate juridică poate avea în componența sa una sau mai multe structuri școlare arondate, fără personalitate juridică, în care se desfășoară doar activitate didactică și/sau alte locații în care se desfășoară activitate didactică și/sau administrativă.","context":"","source":"Art. 6","unit":9},{"id":"art-7-1","article":"7","articleNumber":7,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce pot decide să înființeze școlile și autoritățile locale?","options":["circumscripțiilor electorale","consorțiilor școlare","direcțiilor de sănătate publică","inspectoratelor școlare"],"answer":1,"term":"consorțiilor școlare","quote":"În vederea creșterii calității educației și a optimizării gestionării resurselor, unitățile de învățământ și autoritățile administrației publice locale pot decide înființarea consorțiilor școlare, în conformitate cu metodologia pentru înființarea consorțiilor școlare.","context":"","source":"Art. 7","unit":1},{"id":"art-8-1","article":"8","articleNumber":8,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Cine aprobă înscrierea la altă școală decât cea de circumscripție?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"Părintele/reprezentantul legal are dreptul de a solicita școlarizarea copilului la o altă unitate de învățământ decât aceea la care domiciliul său este arondat. Înscrierea se face în urma unei solicitări scrise din partea părintelui, a tutorelui sau a reprezentantului legal și se aprobă de către consiliul de administrație al unității de învățământ la care se solicită înscrierea, în limita planului de școlarizare aprobat, după asigurarea școlarizării beneficiarilor primari din circumscripția școlară a unității de învățământ respective.","context":"","source":"Art. 8","unit":4},{"id":"art-9-1","article":"9","articleNumber":9,"block":1,"fromPoint":1,"toPoint":8,"pointCount":14,"prompt":"La ce dată începe anul școlar?","options":["1 august","1 ianuarie","1 septembrie","15 septembrie"],"answer":2,"term":"1 septembrie","quote":"Anul școlar începe la 1 septembrie și se încheie la 31 august din anul calendaristic următor.","context":"","source":"Art. 9","unit":1},{"id":"art-9-2","article":"9","articleNumber":9,"block":2,"fromPoint":9,"toPoint":14,"pointCount":14,"prompt":"Ce aviz este necesar pentru suspendarea individuală prevăzută la alin. (4) lit. a) și b)?","options":["avizul asociației de părinți","avizul comitetului clasei","avizul verbal al dirigintelui","avizul, motivat în scris, al consiliului de administrație"],"answer":3,"term":"avizul, motivat în scris, al consiliului de administrație","quote":"Suspendarea cursurilor cu prezență fizică la nivel individual, conform alin. (4) lit.a) și lit.b), se realizează cu avizul, motivat în scris, al consiliului de administrație al unității de învățământ. Suspendarea cursurilor cu prezență fizică în cazul elevelor gravide și a beneficiarilor primari părinți, precum și revenirea acestora cu prezență fizică în unitatea de învățământ se va realiza cu informarea ISJ/ISMB.","context":"Suspendarea cursurilor cu prezență fizică se poate face, după caz:","source":"Art. 9","unit":10},{"id":"art-10-1","article":"10","articleNumber":10,"block":1,"fromPoint":1,"toPoint":8,"pointCount":15,"prompt":"Câte ore are programul prelungit în educația timpurie?","options":["10 ore pe zi","15 ore pe zi","20 ore pe zi","5 ore pe zi"],"answer":0,"term":"10 ore pe zi","quote":"cu program prelungit – 10 ore pe zi, activitate cu copiii.","context":"În funcție de programul de activitate, unitățile de educație timpurie funcționează astfel:","source":"Art. 10","unit":2},{"id":"art-10-2","article":"10","articleNumber":10,"block":2,"fromPoint":9,"toPoint":15,"pointCount":15,"prompt":"Ce trebuie asigurat personalului în organizarea activităților de vacanță?","options":["anulării concediului de odihnă","efectuării concediului de odihnă","înlocuirii concediului cu voluntariat","suspendării tuturor contractelor"],"answer":1,"term":"efectuării concediului de odihnă","quote":"asigurarea efectuării concediului de odihnă pentru personalul unității de educație timpurie;","context":"Activitățile menționate la alin. (6) se vor desfășura cu respectarea următoarelor condiții specifice :","source":"Art. 10","unit":14},{"id":"art-11-1","article":"11","articleNumber":11,"block":1,"fromPoint":1,"toPoint":8,"pointCount":12,"prompt":"Cât durează ora de curs în învățământul primar?","options":["40 de minute","45 de minute","50 de minute","55 de minute"],"answer":1,"term":"45 de minute","quote":"În învățământul primar, ora de curs este de 45 de minute, cu o pauză de 15 minute după fiecare oră și o pauză de 20 de minute după cea de-a doua oră de curs. La clasa pregătitoare și la clasa I, activitățile de predare-învățare-evaluare acoperă 30 – 35 de minute, restul de timp fiind destinat activităților liber alese, recreative.","context":"","source":"Art. 11","unit":4},{"id":"art-11-2","article":"11","articleNumber":11,"block":2,"fromPoint":9,"toPoint":12,"pointCount":12,"prompt":"Ce program pot avea elevele gravide și elevii părinți?","options":["program exclusiv de weekend","program exclusiv online","program exclusiv seral","program școlar flexibil"],"answer":3,"term":"program școlar flexibil","quote":"Elevele gravide și elevii părinți pot beneficia de un program școlar flexibil, în vederea prevenirii și combaterii abandonului școlar. Programul flexibil se stabilește, prin consultare cu părinții/tutorii/reprezentanții legali ai beneficiarilor primari minori, de către o comisie care include și consilierul școlar. Programul poată să prevadă atât un plan individualizat de învățare, cât și un orar școlar adaptat nevoilor acestora, precum și alte măsuri stabilite de către comisie.","context":"","source":"Art. 11","unit":10},{"id":"art-12-1","article":"12","articleNumber":12,"block":1,"fromPoint":1,"toPoint":8,"pointCount":8,"prompt":"Prin ce act sunt aprobate reglementările specifice programelor școlare menționate?","options":["decizie a directorului","hotărâre a consiliului clasei","hotărâre a consiliului local","ordin al ministrului educației"],"answer":3,"term":"ordin al ministrului educației","quote":"Organizarea programelor și, respectiv, dobândirea statutului menționat la alin. (2) se face în conformitate cu reglementările specifice, aprobate prin ordin al ministrului educației.","context":"","source":"Art. 12","unit":8},{"id":"art-13-1","article":"13","articleNumber":13,"block":1,"fromPoint":1,"toPoint":8,"pointCount":14,"prompt":"Cu câți beneficiari se poate depăși efectivul maxim în situațiile excepționale prevăzute?","options":["cel mult 3 beneficiari","cel mult 4 beneficiari","cel mult 5 beneficiari","cel mult 6 beneficiari"],"answer":1,"term":"cel mult 4 beneficiari","quote":"În situații excepționale, formațiunile de antepreșcolari, preșcolari sau de elevi pot funcționa cu cel mult 2 beneficiari sub efectivul minim și, respectiv, cu cel mult 4 beneficiari peste efectivul maxim prevăzut la art. 23 alin. (1) din Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare, după caz, cu aprobarea inspectoratului școlar, pe baza unei justificări din partea consiliului de administrație al unității de învățământ care solicită exceptarea de la prevederilealin. (1).","context":"","source":"Art. 13","unit":5},{"id":"art-13-2","article":"13","articleNumber":13,"block":2,"fromPoint":9,"toPoint":14,"pointCount":14,"prompt":"Cum se constituie clasele la început de nivel, când există mai multe clase pe an?","options":["distribuția aleatorie","ordinea alfabetică a părinților","selecția după mediile elevilor","selecția după veniturile părinților"],"answer":0,"term":"distribuția aleatorie","quote":"În vederea asigurării și respectării principiului desegregării școlare și al combaterii oricăror forme de discriminare asumat la nivelul sistemului național de învățământ, la începutul nivelului de învățământ, formațiunile de studiu se constituie prin distribuția aleatorie a beneficiarilor primari, acolo unde există mai multe clase pe an de studiu, conform procedurii în vigoare, aprobate prin ordin al ministrului educației.","context":"","source":"Art. 13","unit":14},{"id":"art-14-1","article":"14","articleNumber":14,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"De ce depind efectivele din învățământul special?","options":["numărul asociațiilor de părinți","tipul și de gradul deficienței","vechimea directorului","veniturile familiei"],"answer":1,"term":"tipul și de gradul deficienței","quote":"Învățământul special și special integrat pentru preșcolarii/elevii cu deficiențe ușoare și moderate sau grave/profunde/severe/asociate se organizează individual, pe grupe sau clase cu efective stabilite prin lege, în funcție de tipul și de gradul deficienței.","context":"","source":"Art. 14","unit":1},{"id":"art-15-1","article":"15","articleNumber":15,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"Cine poate hotărî schimbarea limbilor moderne, la cerere motivată?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"În situații temeinic motivate, la solicitarea scrisă a părinților/reprezentanților legali sau a beneficiarilor primari majori, consiliul de administrație poate hotărî ordinea studierii limbilor moderne sau schimbarea lor.","context":"","source":"Art. 15","unit":4},{"id":"art-16-1","article":"16","articleNumber":16,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Cine conduce școala cu personalitate juridică?","options":["consiliul de administrație, de director și, după caz, de directori adjuncți","numai autoritatea administrației publice locale","numai consiliul profesoral","numai consiliul reprezentativ al părinților"],"answer":0,"term":"consiliul de administrație, de director și, după caz, de directori adjuncți","quote":"Unitatea de învățământ cu personalitate juridică, cu excepția celor din sistemul de apărare, ordine publică și securitate națională, este condusă de consiliul de administrație, de director și, după caz, de directori adjuncți, unde este cazul.","context":"","source":"Art. 16, alin. (2)","unit":2},{"id":"art-17-1","article":"17","articleNumber":17,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cine asigură reprezentarea școlii de stat în litigii?","options":["administratorul de patrimoniu","administratorul financiar","directorul","secretarul-șef"],"answer":2,"term":"directorul","quote":"Pentru toate litigiile în care este implicată unitatea de învățământ de stat, directorul, în calitate de reprezentant legal, este obligat să asigure dreptul la apărare și reprezentarea unității în fața instanțelor de judecată sau a altor organe de specialitate.","context":"","source":"Art. 17, alin. (1)","unit":1},{"id":"art-18-1","article":"18","articleNumber":18,"block":1,"fromPoint":1,"toPoint":8,"pointCount":8,"prompt":"Ce fel de organ de conducere este consiliul de administrație?","options":["consultativ","deliberativ","jurisdicțional","legislativ"],"answer":1,"term":"deliberativ","quote":"Consiliul de administrație este organul deliberativ de conducere al unităților de învățământ preuniversitar de stat.","context":"","source":"Art. 18, alin. (1)","unit":1},{"id":"art-19-1","article":"19","articleNumber":19,"block":1,"fromPoint":1,"toPoint":8,"pointCount":10,"prompt":"Ce statut are președintele consiliului elevilor la ședințele CA din școlile exclusiv tehnologice?","options":["membru cu drept de veto","observator","președinte de ședință","secretar permanent"],"answer":1,"term":"observator","quote":"În unitățile de învățământ care organizează exclusiv învățământ tehnologic, președintele consiliului școlar al beneficiarilor primari participă obligatoriu, cu statut de observator, la toate ședințele consiliului de administrație.","context":"","source":"Art. 19, alin. (2)","unit":2},{"id":"art-19-2","article":"19","articleNumber":19,"block":2,"fromPoint":9,"toPoint":10,"pointCount":10,"prompt":"În ce limite poate CA aproba măsuri financiare?","options":["creditele solicitate de elevi","prevederile bugetare aprobate","solicitările individuale ale părinților","veniturile estimate fără aprobare"],"answer":1,"term":"prevederile bugetare aprobate","quote":"Consiliul de administrație poate decide aprobarea unor acțiuni/măsuri cu caracter financiar/bugetar doar cu încadrarea în prevederile bugetare aprobate.","context":"","source":"Art. 19, alin. (10)","unit":10},{"id":"art-20-1","article":"20","articleNumber":20,"block":1,"fromPoint":1,"toPoint":8,"pointCount":22,"prompt":"Cum se ocupă funcția de director la școlile de stat?","options":["alegere de către elevi","concurs național","numire de către primar","tragere la sorți"],"answer":1,"term":"concurs național","quote":"Recrutarea pentru ocuparea funcțiilor de director din unitățile de învățământ de stat se realizează prin concurs național, organizat prin inspectoratele școlare, sub coordonarea Ministerului Educației, potrivit metodologiei aprobate prin ordin al ministrului educației.","context":"","source":"Art. 20, alin. (2)","unit":2},{"id":"art-20-2","article":"20","articleNumber":20,"block":2,"fromPoint":9,"toPoint":16,"pointCount":22,"prompt":"Cunoașterea cărei limbi este obligatorie pentru directorul școlii cu predare integrală în limba unei minorități?","options":["limbii alese de consiliul părinților","limbii respective","limbii stabilite de primar","oricărei limbi străine"],"answer":1,"term":"limbii respective","quote":"În cazul unităților de învățământ cu predare integrală în limbile minorităților naționale, directorul are obligația cunoașterii limbii respective. În cazul unităților de învățământ cu secții de predare în limbile minorităților naționale/studiul limbii minorității naționale, unul dintre directori are obligația cunoașterii limbii respective. În aceste cazuri, numirea directorului se face cu consultarea organizației care reprezintă minoritatea respectivă în Parlamentul României sau, dacă minoritatea nu are reprezentare parlamentară, cu consultarea Grupului parlamentar al minorităților naționale. Respectarea criteriilor de competență profesională este obligatorie.","context":"","source":"Art. 20, alin. (9)","unit":9},{"id":"art-20-3","article":"20","articleNumber":20,"block":3,"fromPoint":17,"toPoint":22,"pointCount":22,"prompt":"Cât poate dura conducerea interimară prin delegare, când detașarea nu este posibilă?","options":["55 de zile calendaristice","60 de zile calendaristice","65 de zile calendaristice","70 de zile calendaristice"],"answer":1,"term":"60 de zile calendaristice","quote":"În cazul în care nu se poate asigura numirea prin detașare în interesul învățământului, conducerea interimară va fi asigurată de un cadru didactic membru al consiliului de administrație din unitatea de învățământ, cu acordul acestuia, căruia i se deleagă atribuțiile specifice funcției de conducere, până la organizarea concursului, dar nu mai mult de 60 de zile calendaristice și fără a depăși sfârșitul anului școlar. În această ultimă situație, în baza avizului consiliului de administrație al ISJ/ISMB, inspectorul școlar general emite decizie de delegare a atribuțiilor specifice funcției.","context":"","source":"Art. 20, alin. (16)","unit":20},{"id":"art-21-1","article":"21","articleNumber":21,"block":1,"fromPoint":1,"toPoint":8,"pointCount":71,"prompt":"Ce calitate are directorul în raport cu școala?","options":["reprezentantul elevilor","reprezentantul furnizorilor","reprezentantul legal","reprezentantul părinților"],"answer":2,"term":"reprezentantul legal","quote":"este reprezentantul legal al unității de învățământ și realizează conducerea executivă a acesteia;","context":"În exercitarea funcției de conducere executivă, directorul are următoarele atribuții:","source":"Art. 21, lit. a)","unit":1},{"id":"art-21-2","article":"21","articleNumber":21,"block":2,"fromPoint":9,"toPoint":16,"pointCount":71,"prompt":"În ce termen de la începutul anului școlar este făcut public raportul asupra calității educației?","options":["maximum 25 de zile","maximum 30 de zile","maximum 35 de zile","maximum 40 de zile"],"answer":1,"term":"maximum 30 de zile","quote":"prezintă anual un raport asupra calității educației în unitatea de învățământ; raportul este prezentat în fața consiliului de administrație, a consiliului profesoral, în fața consiliului reprezentativ al părinților/reprezentanților legali și a conducerii asociației de părinți, acolo unde există; raportul este adus la cunoștința autorităților administrației publice locale și a ISJ/ISMB și postat pe site-ul unității de învățământ și prin orice altă formă de comunicare publică existentă la nivelul unității școlare, în termen de maximum 30 de zile de la data începerii anului școlar.","context":"În exercitarea funcției de conducere executivă, directorul are următoarele atribuții:","source":"Art. 21, lit. l)","unit":12},{"id":"art-21-3","article":"21","articleNumber":21,"block":3,"fromPoint":17,"toPoint":24,"pointCount":71,"prompt":"În ce limită angajează directorul cheltuielile?","options":["creditelor bugetare aprobate","donațiilor estimate de părinți","solicitărilor individuale ale angajaților","sponsorizărilor promise verbal"],"answer":0,"term":"creditelor bugetare aprobate","quote":"răspunde de angajarea, lichidarea și ordonanțarea cheltuielilor, în limita creditelor bugetare aprobate;","context":"Directorul are calitatea de ordonator de credite și are responsabilitățile prevăzute de legislația în vigoare pentru această calitate. În exercitarea funcției de ordonator de credite, directorul are următoarele atribuții:","source":"Art. 21, lit. e)","unit":18},{"id":"art-21-4","article":"21","articleNumber":21,"block":4,"fromPoint":25,"toPoint":32,"pointCount":71,"prompt":"Cui propune directorul oferta educațională spre aprobare, ca regulă generală?","options":["consiliului clasei","consiliului de administrație","consiliului elevilor","consiliului profesoral"],"answer":1,"term":"consiliului de administrație","quote":"coordonează activitatea de elaborare a ofertei educaționale a unității de învățământ și o propune spre aprobare consiliului de administrație; prin excepție, în unitățile de învățământ preuniversitar care școlarizează elevi exclusiv în învățământ profesional și tehnic cu o pondere majoritară a învățământului dual, directorul aprobă curriculumul la decizia elevului din oferta școlii cu obligativitatea consultării, în prealabil, a reprezentanților operatorilor economici implicați în instruirea practică și pregătirea de specialitate a beneficiarilor primari în calificarea respectivă;","context":"Alte atribuții ale directorului sunt:","source":"Art. 21, lit. b)","unit":29},{"id":"art-21-5","article":"21","articleNumber":21,"block":5,"fromPoint":33,"toPoint":40,"pointCount":71,"prompt":"În baza cărei hotărâri numește directorul profesorii diriginți?","options":["hotărârii comitetului de părinți","hotărârii consiliului clasei","hotărârii consiliului de administrație","hotărârii consiliului elevilor"],"answer":2,"term":"hotărârii consiliului de administrație","quote":"numește, după consultarea consiliului profesoral, în baza hotărârii consiliului de administrație, profesorii diriginți, educatorii/profesorii pentru educație timpurie de la grupele pentru educație timpurie, în cazul în care unitatea de învățământ are și acest nivel de educație, învățătorii/profesorii pentru învățământul primar la clase, precum și coordonatorul pentru proiecte și programe educative școlare și extrașcolare, respectiv coordonatorul pentru proiecte educaționale europene;","context":"Alte atribuții ale directorului sunt:","source":"Art. 21, lit. g)","unit":34},{"id":"art-21-6","article":"21","articleNumber":21,"block":6,"fromPoint":41,"toPoint":48,"pointCount":71,"prompt":"Alături de cine își asumă directorul răspunderea publică pentru performanțele școlii?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"își asumă, alături de consiliul de administrație, răspunderea publică pentru performanțele unității de învățământ pe care o conduce;","context":"Alte atribuții ale directorului sunt:","source":"Art. 21, lit. u)","unit":48},{"id":"art-21-7","article":"21","articleNumber":21,"block":7,"fromPoint":49,"toPoint":56,"pointCount":71,"prompt":"Cui propune directorul procedura de sesizare confidențială a violenței, spre aprobare?","options":["consiliului clasei","consiliului de administrație","consiliului elevilor","consiliului profesoral"],"answer":1,"term":"consiliului de administrație","quote":"supune, spre aprobare, consiliului de administrație, procedura de sesizare a suspiciunilor și faptelor de violență la nivelul unității de învățământ precum și metoda de sesizare confidențială a suspiciunilor și cazurilor de violență la nivelul unității de învățământ, în condițiile stabilite prin regulamentul de ordine interioară a unității de învățământ; procedura și metoda de sesizare a suspiciunilor și cazurilor de violență se afișează, la loc vizibil, la intrarea în unitatea de învățământ;","context":"Alte atribuții ale directorului sunt:","source":"Art. 21, lit. z)","unit":53},{"id":"art-21-8","article":"21","articleNumber":21,"block":8,"fromPoint":57,"toPoint":64,"pointCount":71,"prompt":"Ce cazuri coordonează directorul pentru protecția elevilor și personalului?","options":["cazurilor de violență","exclusiv alegerile locale","exclusiv creditele familiilor","exclusiv litigiile furnizorilor"],"answer":0,"term":"cazurilor de violență","quote":"coordonează managementul cazurilor de violență asupra beneficiarilor primari și asupra personalului la nivelul unității de învățământ;","context":"Alte atribuții ale directorului sunt:","source":"Art. 21, lit. gg)","unit":60},{"id":"art-21-9","article":"21","articleNumber":21,"block":9,"fromPoint":65,"toPoint":71,"pointCount":71,"prompt":"Când se emite decizia pentru situațiile excepționale în care directorul nu poate delega atribuțiile?","options":["după apariția situației excepționale","după încheierea anului școlar","la începutul anului școlar","la sfârșitul mandatului"],"answer":2,"term":"la începutul anului școlar","quote":"Pentru situațiile excepționale (accident, boală și altele asemenea) în care directorul nu poate delega atribuțiile, acesta emite la începutul anului școlar decizia de delegare a atribuțiilor către directorul adjunct sau, în cazul în care nu există funcția de director adjunct, către un cadru didactic membru al consiliului de administrație. Decizia va conține și un supleant, cadru didactic titular. Neîndeplinirea acestor obligații constituie abatere disciplinară și se sancționează conform legii.","context":"","source":"Art. 21, alin. (8)","unit":69},{"id":"art-22-1","article":"22","articleNumber":22,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce acte emite directorul pentru exercitarea atribuțiilor?","options":["decizii, și note de serviciu","hotărâri de guvern","legi și ordonanțe","ordine de ministru"],"answer":0,"term":"decizii, și note de serviciu","quote":"În exercitarea atribuțiilor și a responsabilităților stabilite în conformitate cu prevederile art. 21, directorul emite decizii, și note de serviciu.","context":"","source":"Art. 22","unit":1},{"id":"art-23-1","article":"23","articleNumber":23,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cine aprobă concediul de odihnă al directorului?","options":["directorul adjunct","inspectorul școlar general","profesorul diriginte","secretarul-șef"],"answer":1,"term":"inspectorul școlar general","quote":"Perioada concediului anual de odihnă al directorului se aprobă de către inspectorul școlar general.","context":"","source":"Art. 23, alin. (2)","unit":2},{"id":"art-24-1","article":"24","articleNumber":24,"block":1,"fromPoint":1,"toPoint":8,"pointCount":10,"prompt":"Câți directori adjuncți pot ajuta directorul?","options":["minimum patru","numai doi","numai unul","unul, doi sau trei"],"answer":3,"term":"unul, doi sau trei","quote":"În activitatea sa, directorul poate fi ajutat de unul, doi sau trei directori adjuncți.","context":"","source":"Art. 24, alin. (1)","unit":1},{"id":"art-24-2","article":"24","articleNumber":24,"block":2,"fromPoint":9,"toPoint":10,"pointCount":10,"prompt":"Peste câte formațiuni de studiu se pot norma două funcții de director adjunct?","options":["45 de formațiuni de studiu","50 de formațiuni de studiu","55 de formațiuni de studiu","60 de formațiuni de studiu"],"answer":1,"term":"50 de formațiuni de studiu","quote":"Se pot norma două funcții de director adjunct pentru unitățile de învățământ de nivel gimnazial, liceal sau postliceal care funcționează cu peste 50 de formațiuni de studiu.","context":"Se poate norma o funcție de director adjunct pentru:","source":"Art. 24, alin. (3)","unit":9},{"id":"art-25-1","article":"25","articleNumber":25,"block":1,"fromPoint":1,"toPoint":8,"pointCount":18,"prompt":"Cine poate participa la concursul pentru director adjunct?","options":["numai membrii comitetului de părinți","numai personalul administrativ","numai personalul didactic auxiliar","personalul didactic de predare titular"],"answer":3,"term":"personalul didactic de predare titular","quote":"La concursul pentru ocuparea funcțiilor de director adjunct participă personalul didactic de predare titular în învățământul preuniversitar.","context":"","source":"Art. 25, alin. (2)","unit":2},{"id":"art-25-2","article":"25","articleNumber":25,"block":2,"fromPoint":9,"toPoint":16,"pointCount":18,"prompt":"Care este limita delegării interimare când detașarea adjunctului nu este posibilă?","options":["55 de zile calendaristice","60 de zile calendaristice","65 de zile calendaristice","70 de zile calendaristice"],"answer":1,"term":"60 de zile calendaristice","quote":"În cazul în care nu se poate asigura numirea prin detașare în interesul învățământului, conducerea interimară va fi asigurată de un cadru didactic membru al consiliului de administrație din unitatea de învățământ, cu acordul acestuia, căruia i se deleagă atribuțiile specifice funcției de conducere, până la organizarea concursului, dar nu mai mult de 60 de zile calendaristice și fără a depăși sfârșitul anului școlar. În această ultimă situație, în baza avizului consiliului de administrație al ISJ/ISMB, inspectorul școlar general emite decizie de delegare a atribuțiilor specifice funcției.","context":"","source":"Art. 25, alin. (11)","unit":14},{"id":"art-25-3","article":"25","articleNumber":25,"block":3,"fromPoint":17,"toPoint":18,"pointCount":18,"prompt":"Prin decizia cui poate fi eliberat din funcție adjunctul unei școli particulare?","options":["comitetului de părinți","consiliului clasei","consiliului elevilor","persoanei juridice fondatoare"],"answer":3,"term":"persoanei juridice fondatoare","quote":"Directorul adjunct al unității de învățământ particular poate fi eliberat din funcție prin decizia persoanei juridice fondatoare.","context":"Asigurarea conducerii unei unități de învățământ preuniversitar particular, până la organizarea concursului, dar nu mai mult de sfârșitul anului școlar, se poate realiza de personalul didactic de predare care se distinge prin calități profesionale, manageriale și morale, după cum urmează:","source":"Art. 25, alin. (13)","unit":18},{"id":"art-26-1","article":"26","articleNumber":26,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Cum exercită adjunctul atribuțiile directorului în lipsa acestuia?","options":["automat, fără niciun act","prin alegerea de către elevi","prin delegare","prin desemnarea de către părinți"],"answer":2,"term":"prin delegare","quote":"Directorul adjunct exercită, prin delegare, în condițiile art. 21 alin. (7) și (8), toate atribuțiile directorului, în lipsa acestuia.","context":"","source":"Art. 26, alin. (2)","unit":2},{"id":"art-27-1","article":"27","articleNumber":27,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Cine aprobă concediul directorului adjunct?","options":["administratorul financiar","directorul unității de învățământ","președintele comitetului de părinți","președintele consiliului elevilor"],"answer":1,"term":"directorul unității de învățământ","quote":"Perioada concediului anual de odihnă al directorului adjunct se aprobă de către directorul unității de învățământ.","context":"","source":"Art. 27, alin. (1)","unit":1},{"id":"art-28-1","article":"28","articleNumber":28,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Care este o categorie de documente manageriale?","options":["campanie electorală","diagnoză","promovare comercială","propagandă"],"answer":1,"term":"diagnoză","quote":"documente de diagnoză;","context":"Pentru optimizarea managementului unității de învățământ, conducerea acesteia elaborează documente manageriale, astfel:","source":"Art. 28, lit. a)","unit":1},{"id":"art-29-1","article":"29","articleNumber":29,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Ce fel de document este raportul anual asupra calității educației?","options":["diagnoză","evidență de inventar","evidență financiară","prognoză"],"answer":0,"term":"diagnoză","quote":"Conducerea unității de învățământ poate elabora și alte documente de diagnoză privind domenii specifice de interes, care să contribuie la dezvoltarea instituțională și la atingerea obiectivelor educaționale.","context":"Documentele de diagnoză ale unității de învățământ sunt:","source":"Art. 29, alin. (2)","unit":4},{"id":"art-30-1","article":"30","articleNumber":30,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cine validează raportul anual asupra calității educației?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":3,"term":"consiliul profesoral","quote":"Raportul anual asupra calității educației se analizează, se dezbate și se validează de către consiliul profesoral și se aprobă de către consiliul de administrație, la propunerea directorului, în primele patru săptămâni de la începutul anului școlar.","context":"","source":"Art. 30, alin. (2)","unit":2},{"id":"art-31-1","article":"31","articleNumber":31,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Unde se postează raportul anual asupra calității educației?","options":["numai în catalogul clasei","numai în dosarul de personal","numai în registrul de inventar","site-ul unității de învățământ"],"answer":3,"term":"site-ul unității de învățământ","quote":"Raportul anual asupra calității educației este adus la cunoștința autorităților administrației publice locale și a ISJ/ISMB și postat pe site-ul unității de învățământ și prin orice altă formă de comunicare publică existentă la nivelul unității școlare.","context":"","source":"Art. 31","unit":1},{"id":"art-32-1","article":"32","articleNumber":32,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Cine întocmește RAEI?","options":["comisia de inventariere","comisia pentru evaluarea și asigurarea calității educației","comitetul de părinți al clasei","compartimentul administrativ"],"answer":1,"term":"comisia pentru evaluarea și asigurarea calității educației","quote":"Raportul anual de evaluare internă (RAEI) se întocmește de către comisia pentru evaluarea și asigurarea calității educației, se prezintă, spre analiză și validare consiliului profesoral și se aprobă de către consiliul de administrație, la propunerea coordonatorului comisiei, și se prezintă, spre analiză, consiliului profesoral.","context":"","source":"Art. 32, alin. (1)","unit":1},{"id":"art-33-1","article":"33","articleNumber":33,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"Din ce categorie face parte planul managerial?","options":["diagnoză","evidență a personalului","evidență contabilă","prognoză"],"answer":3,"term":"prognoză","quote":"Directorul poate elabora și alte documente de prognoză, în scopul optimizării managementului unității de învățământ.","context":"Documentele de prognoză ale unității de învățământ realizate pe baza documentelor de diagnoză ale perioadei anterioare sunt:","source":"Art. 33, alin. (2)","unit":4},{"id":"art-34-1","article":"34","articleNumber":34,"block":1,"fromPoint":1,"toPoint":8,"pointCount":11,"prompt":"Pentru ce perioadă se elaborează PDI?","options":["1 – 2 ani","3 – 5 ani","6 – 8 ani","8 – 10 ani"],"answer":1,"term":"3 – 5 ani","quote":"(1) Planul de dezvoltare instituțională constituie documentul de prognoză pe termen lung și se elaborează de către o echipă coordonată de către director, pentru o perioadă de 3 – 5 ani. Acesta conține:","context":"","source":"Art. 34","unit":1},{"id":"art-34-2","article":"34","articleNumber":34,"block":2,"fromPoint":9,"toPoint":11,"pointCount":11,"prompt":"Cine aprobă revizuirea PDI/PAS?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"Propunerea de revizuire se dezbate și se avizează de către consiliul profesoral și se aprobă de către consiliul de administrație, devenind anexă la PDI/PAS.","context":"","source":"Art. 34, alin. (7)","unit":11},{"id":"art-35-1","article":"35","articleNumber":35,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"Pentru ce perioadă elaborează directorul planul managerial?","options":["doi ani școlari","întregul mandat","un an școlar","un semestru"],"answer":2,"term":"un an școlar","quote":"Planul managerial constituie documentul de acțiune pe termen scurt și se elaborează de către director pentru o perioadă de un an școlar.","context":"","source":"Art. 35, alin. (1)","unit":1},{"id":"art-36-1","article":"36","articleNumber":36,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce sistem trebuie să elaboreze sau să dezvolte directorul?","options":["sistemului de control intern managerial","sistemului de cotizații ale elevilor","sistemului de promovare comercială","sistemului electoral local"],"answer":0,"term":"sistemului de control intern managerial","quote":"Directorul ia măsurile necesare, în conformitate cu legislația în vigoare, pentru elaborarea și/sau dezvoltarea sistemului de control intern managerial, inclusiv a procedurilor formalizate pe activități. Planul de dezvoltare a sistemului de control intern managerial va cuprinde obiectivele, acțiunile, responsabilitățile, termenele, precum și alte componente.","context":"","source":"Art. 36","unit":1},{"id":"art-37-1","article":"37","articleNumber":37,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Care este un document managerial de evidență?","options":["planul de dezvoltare instituțională","planul managerial","raportul anual de evaluare internă","statul de funcții"],"answer":3,"term":"statul de funcții","quote":"statul de funcții;","context":"Documentele manageriale de evidență sunt:","source":"Art. 37, lit. a)","unit":1},{"id":"art-38-1","article":"38","articleNumber":38,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Prin ce se realizează angajarea personalului școlii cu personalitate juridică?","options":["contractului de parteneriat","contractului de sponsorizare","contractului educațional","contractului individual de muncă"],"answer":3,"term":"contractului individual de muncă","quote":"Angajarea personalului didactic de predare, didactic auxiliar și administrativ în unitățile de învățământ cu personalitate juridică se realizează prin încheierea contractului individual de muncă cu unitatea de învățământ, prin reprezentantul său legal.","context":"","source":"Art. 38, alin. (3)","unit":3},{"id":"art-39-1","article":"39","articleNumber":39,"block":1,"fromPoint":1,"toPoint":8,"pointCount":8,"prompt":"Ce îi este interzis personalului să aplice elevilor?","options":["activități remediale","evaluări formative","măsuri de sprijin","pedepse corporale"],"answer":3,"term":"pedepse corporale","quote":"Personalului din învățământul preuniversitar îi este interzis să aplice pedepse corporale, precum și să agreseze verbal, fizic sau emoțional beneficiarii primari și/sau colegii.","context":"","source":"Art. 39, alin. (5)","unit":5},{"id":"art-40-1","article":"40","articleNumber":40,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cine aprobă organigrama?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"Organigrama se propune de către director la începutul fiecărui an școlar, se aprobă de către consiliul de administrație și se înregistrează la secretariatul unității de învățământ.","context":"","source":"Art. 40, alin. (3)","unit":3},{"id":"art-41-1","article":"41","articleNumber":41,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Prin ce act este numit coordonatorul unei structuri școlare?","options":["cerere a părinților","hotărâre a consiliului clasei","hotărâre a consiliului de administrație","vot al elevilor"],"answer":2,"term":"hotărâre a consiliului de administrație","quote":"Coordonarea activității structurilor unităților de învățământ se realizează de către un coordonator numit, de regulă, dintre cadrele didactice titulare, prin hotărâre a consiliului de administrație, la propunerea directorului.","context":"","source":"Art. 41","unit":1},{"id":"art-42-1","article":"42","articleNumber":42,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Cui se subordonează compartimentele de specialitate?","options":["comitetului de părinți","consiliului clasei","consiliului elevilor","directorului/directorului adjunct"],"answer":3,"term":"directorului/directorului adjunct","quote":"Personalul didactic auxiliar și administrativ este organizat în compartimente de specialitate care se află în subordinea directorului/directorului adjunct, în conformitate cu organigrama unității de învățământ.","context":"","source":"Art. 42","unit":1},{"id":"art-43-1","article":"43","articleNumber":43,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Care sunt compartimentele obișnuite ale școlii?","options":["electoral, comercial, diplomatic","judiciar, militar, vamal","secretariat, financiar, administrativ","sportiv, turistic, confesional"],"answer":2,"term":"secretariat, financiar, administrativ","quote":"La nivelul fiecărei unități de învățământ funcționează, de regulă, următoarele compartimente: secretariat, financiar, administrativ, precum și alte compartimente sau servicii, potrivit legislației în vigoare.","context":"","source":"Art. 43","unit":1},{"id":"art-44-1","article":"44","articleNumber":44,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Pe lângă lege, ce reglementează drepturile și obligațiile personalului didactic?","options":["contractele colective de muncă aplicabile","deciziile consiliului elevilor","hotărârile comitetelor de părinți","regulamentele operatorilor economici"],"answer":0,"term":"contractele colective de muncă aplicabile","quote":"Personalul didactic are drepturile și obligațiile prevăzute de legislația în vigoare și de contractele colective de muncă aplicabile.","context":"","source":"Art. 44","unit":1},{"id":"art-45-1","article":"45","articleNumber":45,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce document medical trebuie să prezinte personalul didactic?","options":["adeverință de venit","bilet de trimitere","certificat de naștere","certificat medical"],"answer":3,"term":"certificat medical","quote":"Pentru încadrarea și menținerea în funcție, personalul didactic are obligația să prezinte un certificat medical, eliberat de medicul specializat de medicina muncii, care atestă că este apt pentru prestarea activității în învățământ, precum și cazierul judiciar și certificatul de integritate comportamentală.","context":"","source":"Art. 45","unit":1},{"id":"art-46-1","article":"46","articleNumber":46,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"La ce activități are obligația să participe personalul didactic?","options":["colectare de fonduri de protocol","formare continuă","promovare comercială","propagandă electorală"],"answer":1,"term":"formare continuă","quote":"Personalul didactic are obligația de a participa la activități de formare continuă, în condițiile legii.","context":"","source":"Art. 46","unit":1},{"id":"art-47-1","article":"47","articleNumber":47,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"În câte școli face serviciul un profesor care lucrează în mai multe unități?","options":["în nicio unitate","în toate unitățile în aceeași zi","într-o singură unitate de învățământ","numai la inspectorat"],"answer":2,"term":"într-o singură unitate de învățământ","quote":"În cazul în care un cadru didactic își desfășoară activitatea în mai multe unități de învățământ, acesta va efectua serviciul pe școală într-o singură unitate de învățământ, la alegere, cu acordul conducerii acesteia.","context":"","source":"Art. 47, alin. (2)","unit":2},{"id":"art-48-1","article":"48","articleNumber":48,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Cine coordonează concursul pentru posturile administrative?","options":["director","președintele comitetului de părinți","reprezentantul elevilor","secretarul consiliului clasei"],"answer":0,"term":"director","quote":"Organizarea și desfășurarea concursului de ocupare a posturilor administrative dintr-o unitate de învățământ sunt coordonate de director. Consiliul de administrație al unității de învățământ aprobă comisiile de concurs și validează rezultatele concursului.","context":"","source":"Art. 48, alin. (2)","unit":2},{"id":"art-49-1","article":"49","articleNumber":49,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"Cine coordonează, de regulă, personalul administrativ?","options":["administratorul de patrimoniu","bibliotecarul","profesorul diriginte","secretarul-șef"],"answer":0,"term":"administratorul de patrimoniu","quote":"Activitatea personalului administrativ este coordonată, de regulă, de administratorul de patrimoniu.","context":"","source":"Art. 49, alin. (1)","unit":1},{"id":"art-50-1","article":"50","articleNumber":50,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Conform căror norme se evaluează personalul?","options":["exclusiv opiniilor partenerilor economici","exclusiv solicitărilor părinților","exclusiv votului elevilor","legislației în vigoare și contractelor colective de muncă aplicabile"],"answer":3,"term":"legislației în vigoare și contractelor colective de muncă aplicabile","quote":"Evaluarea personalului se face conform legislației în vigoare și contractelor colective de muncă aplicabile.","context":"","source":"Art. 50","unit":1},{"id":"art-51-1","article":"51","articleNumber":51,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Când este evaluat personalul administrativ pentru anul anterior?","options":["1 – 30 iunie","1 – 30 septembrie","1 – 31 ianuarie","1 – 31 martie"],"answer":2,"term":"1 – 31 ianuarie","quote":"Evaluarea personalului administrativ se realizează în perioada 1 – 31 ianuarie a fiecărui an, pentru anul calendaristic anterior.","context":"","source":"Art. 51, alin. (2)","unit":2},{"id":"art-52-1","article":"52","articleNumber":52,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Cum răspunde disciplinar personalul didactic?","options":["conform legii","exclusiv prin votul elevilor","exclusiv prin votul părinților","numai în baza unui acord verbal"],"answer":0,"term":"conform legii","quote":"Personalul didactic răspunde disciplinar conform legii.","context":"","source":"Art. 52","unit":1},{"id":"art-53-1","article":"53","articleNumber":53,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce act reglementează răspunderea disciplinară a personalului administrativ?","options":["Codul electoral","Codul muncii","Codul silvic","Codul vamal"],"answer":1,"term":"Codul muncii","quote":"Personalul administrativ răspunde disciplinar în conformitate cu prevederile Legii nr. 53/2003 – Codul muncii, republicată, cu modificările și completările ulterioare.","context":"","source":"Art. 53","unit":1},{"id":"art-54-1","article":"54","articleNumber":54,"block":1,"fromPoint":1,"toPoint":8,"pointCount":16,"prompt":"Care este cvorumul consiliului profesoral?","options":["1/3 din numărul total al membrilor","1/4 din numărul total al membrilor","2/3 din numărul total al membrilor","toți membrii, obligatoriu"],"answer":2,"term":"2/3 din numărul total al membrilor","quote":"Cvorumul necesar pentru întrunirea în ședință a consiliului profesoral este de 2/3 din numărul total al membrilor, cadre didactice cu norma de bază în unitatea de învățământ.","context":"","source":"Art. 54","unit":4},{"id":"art-54-2","article":"54","articleNumber":54,"block":2,"fromPoint":9,"toPoint":16,"pointCount":16,"prompt":"Cum se pot desfășura ședințele consiliului profesoral, potrivit procedurii școlii?","options":["exclusiv prin corespondență poștală","exclusiv prin delegați ai părinților","exclusiv prin votul elevilor","format hibrid sau online"],"answer":3,"term":"format hibrid sau online","quote":"Ședințele consiliului profesoral se pot desfășura, după caz, în format hibrid sau online, prin mijloace electronice de comunicare, în sistem de videoconferință, conform unei proceduri stabilite la nivelul unității de învățământ.","context":"","source":"Art. 54","unit":16},{"id":"art-55-1","article":"55","articleNumber":55,"block":1,"fromPoint":1,"toPoint":8,"pointCount":22,"prompt":"Cum alege consiliul profesoral reprezentanții cadrelor didactice în CA?","options":["numire de către elevi","tragere la sorți","vot public al părinților","vot secret"],"answer":3,"term":"vot secret","quote":"alege, prin vot secret, reprezentanții personalului didactic în consiliul de administrație;","context":"Consiliul profesoral are următoarele atribuții:","source":"Art. 55","unit":2},{"id":"art-55-2","article":"55","articleNumber":55,"block":2,"fromPoint":9,"toPoint":16,"pointCount":22,"prompt":"Cine validează mediile la purtare mai mici de 7?","options":["Comitetul de părinți","Consiliul clasei","Consiliul de administrație","Consiliul profesoral"],"answer":3,"term":"Consiliul profesoral","quote":"avizează oferta de curriculumul la decizia elevului din oferta școlii (CDEOȘ) pentru anul școlar următor și o propune spre aprobare consiliului de administrație. În stabilirea listei de opționale, consiliul profesoral va ține cont de numărul și ordinea opțiunilor pentru CDEOȘ exprimate de către preșcolari/elevi și părinți/reprezentanții legali ai acestora;","context":"Consiliul profesoral are următoarele atribuții:","source":"Art. 55","unit":14},{"id":"art-55-3","article":"55","articleNumber":55,"block":3,"fromPoint":17,"toPoint":22,"pointCount":22,"prompt":"Ce atribuție are consiliul profesoral față de eliberarea directorului din funcție?","options":["anulează concursul național","dispune singur eliberarea din funcție","numește un director pe viață","propune eliberarea din funcție"],"answer":3,"term":"propune eliberarea din funcție","quote":"propune eliberarea din funcție a directorului unității de învățământ, conform legii.","context":"Consiliul profesoral are următoarele atribuții:","source":"Art. 55","unit":22},{"id":"art-56-1","article":"56","articleNumber":56,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"În ce registru se consemnează ședințele consiliului profesoral?","options":["registrul de casă","registrul de inventar","registrul de procese-verbale","registrul matricol"],"answer":2,"term":"registrul de procese-verbale","quote":"registrul de procese-verbale al consiliului profesoral, însoțit de dosarul cu anexele proceselor- verbale.","context":"Documentele consiliului profesoral sunt:","source":"Art. 56","unit":3},{"id":"art-57-1","article":"57","articleNumber":57,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Cât de des se întrunește cel puțin consiliul clasei?","options":["numai la cererea primarului","numai la încheierea ciclului școlar","o dată la doi ani","o dată, în fiecare interval de cursuri"],"answer":3,"term":"o dată, în fiecare interval de cursuri","quote":"Consiliul clasei se întrunește cel puțin o dată, în fiecare interval de cursuri sau ori de câte ori este necesar, la solicitarea învățătorului/institutorului/profesorului pentru învățământul primar, respectiv a profesorului diriginte, a reprezentanților părinților/ reprezentanților legali și ai beneficiarilor primari.","context":"","source":"Art. 57","unit":3},{"id":"art-58-1","article":"58","articleNumber":58,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Cine stabilește mediile la purtare ale elevilor clasei?","options":["Comitetul de părinți","Compartimentul secretariat","Consiliul clasei","Consiliul de administrație"],"answer":2,"term":"Consiliul clasei","quote":"stabilește notele/calificativele, respectiv mediile la purtare pentru fiecare elev al clasei, în funcție de frecvența și comportamentul acestora în activitatea școlară și extrașcolară; propune consiliului profesoral validarea notelor mai mici de 7, respectiv mai mici de 8, pentru unitățile de învățământ cu profil pedagogic, teologic și militar, sau a calificativelor mai mici de \"bine\", pentru învățământul primar;","context":"Consiliul clasei are următoarele atribuții:","source":"Art. 58","unit":3},{"id":"art-59-1","article":"59","articleNumber":59,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Cu ce vot adoptă hotărâri consiliul clasei?","options":["jumătate din cei prezenți","jumătate plus unu din totalul membrilor săi","o treime din cei prezenți","votul exclusiv al dirigintelui"],"answer":1,"term":"jumătate plus unu din totalul membrilor săi","quote":"Consiliul clasei se întrunește în prezența a cel puțin 2/3 din totalul membrilor și adoptă hotărâri cu votul a jumătate plus unu din totalul membrilor săi.","context":"","source":"Art. 59","unit":1},{"id":"art-60-1","article":"60","articleNumber":60,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Cine aprobă coordonatorul pentru proiecte și programe educative?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"Coordonatorul pentru proiecte și programe educative școlare și extrașcolare este, de regulă, un cadru didactic titular, propus de consiliul profesoral și aprobat de către consiliul de administrație, în baza unor criterii specifice aprobate de către consiliul de administrație al unității de învățământ.","context":"","source":"Art. 60","unit":1},{"id":"art-61-1","article":"61","articleNumber":61,"block":1,"fromPoint":1,"toPoint":8,"pointCount":25,"prompt":"Cui prezintă coordonatorul educativ rapoarte anuale?","options":["consiliului clasei","consiliului de administrație","consiliului elevilor","consiliului profesoral"],"answer":1,"term":"consiliului de administrație","quote":"prezintă consiliului de administrație rapoarte anuale privind activitatea educativă și rezultatele acesteia;","context":"Coordonatorul pentru proiecte și programe educative școlare și extrașcolare are următoarele atribuții:","source":"Art. 61","unit":6},{"id":"art-61-2","article":"61","articleNumber":61,"block":2,"fromPoint":9,"toPoint":16,"pointCount":25,"prompt":"Cui înaintează coordonatorul educativ propunerile de parteneriat?","options":["consiliului clasei","consiliului de administrație","consiliului elevilor","consiliului profesoral"],"answer":1,"term":"consiliului de administrație","quote":"analizează oferta furnizorilor de educație extrașcolară și înaintează consiliului de administrație propuneri de parteneriat în funcție de resursele existente umane, materiale și financiare existente la nivelul unității de învățământ;","context":"Coordonatorul pentru proiecte și programe educative școlare și extrașcolare are următoarele atribuții:","source":"Art. 61","unit":12},{"id":"art-61-3","article":"61","articleNumber":61,"block":3,"fromPoint":17,"toPoint":24,"pointCount":25,"prompt":"Ce plan intră în portofoliul coordonatorului educativ?","options":["planul anual al activității educative extrașcolare","planul de achiziții publice","planul de investiții al furnizorului","planul de pază al primăriei"],"answer":0,"term":"planul anual al activității educative extrașcolare","quote":"planul anual al activității educative extrașcolare;","context":"Portofoliul coordonatorului pentru proiecte și programe educative școlare și extrașcolare conține:","source":"Art. 61","unit":18},{"id":"art-61-4","article":"61","articleNumber":61,"block":4,"fromPoint":25,"toPoint":25,"pointCount":25,"prompt":"În ce format poate fi realizat și stocat portofoliul coordonatorului educativ?","options":["exclusiv audio","exclusiv manuscris","exclusiv prin afișe","format electronic"],"answer":3,"term":"format electronic","quote":"Portofoliul menționat la alin. (2) poate fi realizat și stocat și în format electronic.","context":"Portofoliul coordonatorului pentru proiecte și programe educative școlare și extrașcolare conține:","source":"Art. 61","unit":25},{"id":"art-62-1","article":"62","articleNumber":62,"block":1,"fromPoint":1,"toPoint":8,"pointCount":22,"prompt":"Cine aprobă coordonatorul proiectelor educaționale europene?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"Coordonatorul pentru proiecte educaționale europene este un cadru didactic titular, propus de consiliul profesoral și aprobat de către consiliul de administrație, în baza unor criterii specifice aprobate de către consiliul de administrație al unității de învățământ.","context":"","source":"Art. 62","unit":1},{"id":"art-62-2","article":"62","articleNumber":62,"block":2,"fromPoint":9,"toPoint":16,"pointCount":22,"prompt":"Cui prezintă coordonatorul proiectelor europene rapoarte anuale?","options":["consiliului clasei","consiliului de administrație","consiliului elevilor","consiliului profesoral"],"answer":1,"term":"consiliului de administrație","quote":"prezintă consiliului de administrație rapoarte anuale privind implementarea proiectelor europene, rezultatele și impactul acestora;","context":"Coordonatorul pentru proiecte educaționale europene are următoarele atribuții:","source":"Art. 62","unit":14},{"id":"art-62-3","article":"62","articleNumber":62,"block":3,"fromPoint":17,"toPoint":22,"pointCount":22,"prompt":"Ce documente intră în portofoliul coordonatorului proiectelor europene?","options":["cataloagele tuturor claselor","cereri de finanțare depuse","dosarele medicale ale elevilor","registrele de casă ale primăriei"],"answer":1,"term":"cereri de finanțare depuse","quote":"schițe de proiect și cereri de finanțare depuse;","context":"Portofoliul coordonatorului pentru proiecte educaționale europene conține:","source":"Art. 62","unit":19},{"id":"art-63-1","article":"63","articleNumber":63,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Cine stabilește ziua metodică a coordonatorilor de proiecte?","options":["Comitetul de părinți","Consiliul clasei","Consiliul elevilor","Inspectoratul școlar"],"answer":3,"term":"Inspectoratul școlar","quote":"Inspectoratul școlar stabilește o zi metodică pentru coordonatorii pentru proiecte și programe educative școlare și extrașcolare și pentru coordonatorul pentru proiecte educaționale europene.","context":"","source":"Art. 63","unit":1},{"id":"art-64-1","article":"64","articleNumber":64,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"La câte formațiuni de studiu poate fi diriginte un cadru didactic?","options":["două formațiuni de studiu","o singură formațiune de studiu","oricâte formațiuni de studiu","trei formațiuni de studiu"],"answer":1,"term":"o singură formațiune de studiu","quote":"Un cadru didactic poate îndeplini atribuțiile de profesor diriginte la o singură formațiune de studiu.","context":"","source":"Art. 64","unit":2},{"id":"art-65-1","article":"65","articleNumber":65,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cine numește anual profesorii diriginți?","options":["administratorul financiar","directorul unității de învățământ","președintele comitetului de părinți","președintele consiliului elevilor"],"answer":1,"term":"directorul unității de învățământ","quote":"Profesorii diriginți sunt numiți, anual, de către directorul unității de învățământ, în baza hotărârii consiliului de administrație.","context":"","source":"Art. 65","unit":1},{"id":"art-66-1","article":"66","articleNumber":66,"block":1,"fromPoint":1,"toPoint":8,"pointCount":12,"prompt":"Unde sunt prevăzute activitățile specifice dirigintelui?","options":["contractul de sponsorizare","fișa postului","registrul de inventar","statul de plată"],"answer":1,"term":"fișa postului","quote":"Activitățile specifice funcției de diriginte sunt prevăzute în fișa postului cadrului didactic.","context":"","source":"Art. 66","unit":1},{"id":"art-66-2","article":"66","articleNumber":66,"block":2,"fromPoint":9,"toPoint":12,"pointCount":12,"prompt":"Cu cine colaborează dirigintele pentru incluziunea elevilor cu CES?","options":["administratorul financiar","profesorul itinerant și de sprijin","reprezentantul furnizorilor","secretarul primăriei"],"answer":1,"term":"profesorul itinerant și de sprijin","quote":"Profesorul diriginte monitorizează activitatea colectivului de elevi, colaborează cu profesorul itinerant și de sprijin și informează consiliul de administrație privind barierele întâmpinate de beneficiarii primari cu dizabilități în ceea ce privește accesul și participarea la activitățile curriculare, extracurriculare și extrașcolare.","context":"","source":"Art. 66","unit":11},{"id":"art-67-1","article":"67","articleNumber":67,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cât de des stabilește dirigintele întâlnirea cu părinții pentru situația școlară?","options":["numai la absolvire","numai la schimbarea directorului","numai o dată la doi ani","pe perioada fiecărui interval de cursuri"],"answer":3,"term":"pe perioada fiecărui interval de cursuri","quote":"Pentru realizarea unei comunicări constante cu părinții / reprezentanții legali, profesorul diriginte stabilește, în acord cu aceștia, pe perioada fiecărui interval de cursuri, o întâlnire pentru prezentarea situației școlare a beneficiarilor primari, pentru discutarea problemelor educaționale sau comportamentale specifice ale acestora. În situații obiective cum ar fi: calamități, intemperii, epidemii, pandemii, alte situații excepționale, aceste întâlniri se pot desfășura, după caz, în format hibrid sau online, prin mijloace electronice de comunicare, în sistem de videoconferință.","context":"","source":"Art. 67","unit":1},{"id":"art-68-1","article":"68","articleNumber":68,"block":1,"fromPoint":1,"toPoint":8,"pointCount":31,"prompt":"Ce acțiuni preventive organizează dirigintele în privința drogurilor?","options":["comercializarea substanțelor","încurajarea experimentării substanțelor","prevenirea consumului de droguri","promovarea consumului de droguri"],"answer":2,"term":"prevenirea consumului de droguri","quote":"acțiuni pentru prevenirea consumului de droguri în rândul beneficiarilor primari, inclusiv cele în colaborare cu centrele de prevenire, evaluare si consiliere antidrog;","context":"organizează și coordonează:","source":"Art. 68","unit":7},{"id":"art-68-2","article":"68","articleNumber":68,"block":2,"fromPoint":9,"toPoint":16,"pointCount":31,"prompt":"Ce monitorizează dirigintele în legătură cu prezența elevilor?","options":["achizițiile furnizorilor","concediile personalului administrativ","frecvența la ore","veniturile părinților"],"answer":2,"term":"frecvența la ore","quote":"frecvența la ore a beneficiarilor primari;","context":"monitorizează:","source":"Art. 68","unit":10},{"id":"art-68-3","article":"68","articleNumber":68,"block":3,"fromPoint":17,"toPoint":24,"pointCount":31,"prompt":"Cu ce instituții colaborează dirigintele pentru orientarea școlară a elevilor cu CES?","options":["AEP","ANAF","ANPC","CJRAE/CMBRAE"],"answer":3,"term":"CJRAE/CMBRAE","quote":"CJRAE/CMBRAE pentru referirea și orientarea școlară a beneficiarilor primari cu CES;","context":"colaborează cu:","source":"Art. 68","unit":20},{"id":"art-68-4","article":"68","articleNumber":68,"block":4,"fromPoint":25,"toPoint":31,"pointCount":31,"prompt":"Despre ce reglementări informează dirigintele elevii și părinții?","options":["achizițiile primăriei","alegerile parlamentare","concediile furnizorilor","evaluări și examene"],"answer":3,"term":"evaluări și examene","quote":"elevii și părinții sau reprezentanții legali cu privire la reglementările referitoare la evaluări și examene și cu privire la alte documente care reglementează activitatea și parcursul școlar al beneficiarilor primari;","context":"informează:","source":"Art. 68","unit":26},{"id":"art-69-1","article":"69","articleNumber":69,"block":1,"fromPoint":1,"toPoint":8,"pointCount":12,"prompt":"Cine motivează absențele elevilor potrivit regulamentului?","options":["Administratorul de patrimoniu","Profesorul diriginte","Reprezentantul părinților","Secretarul-șef"],"answer":1,"term":"Profesorul diriginte","quote":"motivează absențele beneficiarilor primari, în conformitate cu prevederile prezentului regulament și ale regulamentului de organizare și funcționare a unității de învățământ;","context":"Profesorul diriginte mai are și următoarele atribuții:","source":"Art. 69","unit":2},{"id":"art-69-2","article":"69","articleNumber":69,"block":2,"fromPoint":9,"toPoint":12,"pointCount":12,"prompt":"Ce tip de recomandare emit consilierul școlar și dirigintele la final de gimnaziu și liceu?","options":["autorizație de funcționare","certificat fiscal","decizie obligatorie de angajare","recomandare consultativă"],"answer":3,"term":"recomandare consultativă","quote":"la finalizarea învățământului gimnazial și liceal, profesorul consilier școlar și dirigintele emit câte o recomandare consultativă de încadrare într-o formă de învățământ de nivel superior, având caracter de orientare școlară pentru fiecare elev în parte. Pentru absolvenții de învățământ liceal se poate realiza și o recomandare sub forma unei orientări vocaționale de încadrare pe piața forței de muncă;","context":"Profesorul diriginte mai are și următoarele atribuții:","source":"Art. 69","unit":11},{"id":"art-70-1","article":"70","articleNumber":70,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Cărui personal i se aplică adaptat dispozițiile art. 66–69?","options":["numai personalului administrativ","numai personalului financiar","numai personalului medical","personalului didactic din învățământul preșcolar și primar"],"answer":3,"term":"personalului didactic din învățământul preșcolar și primar","quote":"Dispozițiile art. 66 – 69 se adaptează și aplică în mod corespunzător și personalului didactic din învățământul preșcolar și primar.","context":"","source":"Art. 70","unit":1},{"id":"art-71-1","article":"71","articleNumber":71,"block":1,"fromPoint":1,"toPoint":8,"pointCount":11,"prompt":"Ce comisie permanentă privește calitatea educației?","options":["comisia de casare a mobilierului","comisia de evaluare și asigurare a calității","comisia de recepție a lucrărilor","comisia electorală locală"],"answer":1,"term":"comisia de evaluare și asigurare a calității","quote":"comisia de evaluare și asigurare a calității;","context":"Comisiile cu caracter permanent sunt:","source":"Art. 71","unit":5},{"id":"art-71-2","article":"71","articleNumber":71,"block":2,"fromPoint":9,"toPoint":11,"pointCount":11,"prompt":"Cât timp activează comisiile permanente?","options":["numai în prima lună de cursuri","numai în vacanța de vară","numai în ziua constituirii","pe tot parcursul anului școlar"],"answer":3,"term":"pe tot parcursul anului școlar","quote":"Comisiile cu caracter permanent își desfășoară activitatea pe tot parcursul anului școlar, comisiile cu caracter temporar își desfășoară activitatea doar în anumite perioade ale anului școlar, iar comisiile cu caracter ocazional sunt înființate ori de câte ori se impune constituirea unei astfel de comisii, pentru rezolvarea unor probleme specifice apărute la nivelul unității de învățământ.","context":"Comisiile cu caracter permanent sunt:","source":"Art. 71","unit":10},{"id":"art-72-1","article":"72","articleNumber":72,"block":1,"fromPoint":1,"toPoint":8,"pointCount":53,"prompt":"Cine emite decizia de constituire a comisiilor școlii?","options":["administratorul de patrimoniu","administratorul financiar","directorul","secretarul-șef"],"answer":2,"term":"directorul","quote":"Comisia pentru curriculum se constituie la nivelul unităților de învățământ preuniversitar de stat, în baza hotărârii consiliului de administrație, fiind formată din membrii catedrelor/ comisiilor metodice. Directorul unității de învățământ emite decizia de constituire a Comisiei pentru curriculum.","context":"","source":"Art. 72","unit":4},{"id":"art-72-2","article":"72","articleNumber":72,"block":2,"fromPoint":9,"toPoint":16,"pointCount":53,"prompt":"Ce tip de analiză folosește comisia pentru curriculum la analiza nevoilor?","options":["exclusiv contabilă","exclusiv electorală","exclusiv fiscală","SWOT"],"answer":3,"term":"SWOT","quote":"inițierea și realizarea analizei de nevoi, implicând consultarea beneficiarilor educației, privind oferta curriculară a unității de învățământ, inclusiv a curriculumului la decizia elevului din oferta școlii (CDEOȘ), pentru fiecare an școlar, prin utilizarea metodei de analiză de tip SWOT;","context":"Atribuțiile comisiei pentru curriculum vizează activități legate de procesul de proiectare, implementare, monitorizare și evaluare a implementării curriculumului, la nivelul unității de învățământ, precum:","source":"Art. 72","unit":11},{"id":"art-72-3","article":"72","articleNumber":72,"block":3,"fromPoint":17,"toPoint":24,"pointCount":53,"prompt":"Ce program monitorizează comisia pentru curriculum pentru recuperarea achizițiilor?","options":["Învățare remedială","Programul de audit financiar","Programul de investiții publice","Programul de pază al școlii"],"answer":0,"term":"Învățare remedială","quote":"monitorizarea nevoii de recuperare a achizițiilor și a desfășurării programului \"Învățare remedială\" la nivelul unității de învățământ;","context":"Atribuțiile comisiei pentru curriculum vizează activități legate de procesul de proiectare, implementare, monitorizare și evaluare a implementării curriculumului, la nivelul unității de învățământ, precum:","source":"Art. 72","unit":23},{"id":"art-72-4","article":"72","articleNumber":72,"block":4,"fromPoint":25,"toPoint":32,"pointCount":53,"prompt":"Ce identifică CFDCD în privința personalului didactic?","options":["nevoile de formare continuă","opțiunile comerciale","preferințele electorale","veniturile familiilor"],"answer":0,"term":"nevoile de formare continuă","quote":"Comisia pentru formare și dezvoltare în cariera didactică identifică nevoile de formare continuă ale personalului didactic, programele și proiectele destinate formării continue a personalului didactic și monitorizează evoluția în carieră a cadrelor didactice, participarea personalului didactic la programe și proiecte de formare continuă.","context":"","source":"Art. 72","unit":30},{"id":"art-72-5","article":"72","articleNumber":72,"block":5,"fromPoint":33,"toPoint":40,"pointCount":53,"prompt":"Ce sistem gestionează CFDCD pentru formarea profesorilor?","options":["sistemul de achiziții publice","sistemul de acumulare a creditelor","sistemul de burse al elevilor","sistemul de credite bancare"],"answer":1,"term":"sistemul de acumulare a creditelor","quote":"gestionează sistemul de acumulare a creditelor la nivelul unității de învățământ, evaluând anual stadiul de îndeplinire a condiției de formare pentru personalul didactic, prin actualizarea periodică a bazei de date privind numărul creditelor ECTS (obținute inclusiv prin recunoaștere și echivalare a creditelor profesionale transferabile) acumulat de fiecare cadru didactic pe parcursul ultimilor doi ani de activitate didactică, calculați la data de 31 august;","context":"Atribuțiile comisiei pentru formare și dezvoltare în cariera didactică sunt următoarele:","source":"Art. 72","unit":37},{"id":"art-72-6","article":"72","articleNumber":72,"block":6,"fromPoint":41,"toPoint":48,"pointCount":53,"prompt":"Cine emite decizia de constituire a comisiei pentru prevenirea violenței?","options":["administratorul financiar","directorul unității de învățământ","președintele comitetului de părinți","președintele consiliului elevilor"],"answer":1,"term":"directorul unității de învățământ","quote":"Directorul unității de învățământ emite decizia de constituire și componența nominală a Comisiei pentru prevenirea și combaterea violenței, a faptelor de corupție și discriminării în mediul școlar și promovarea interculturalității.","context":"","source":"Art. 72","unit":45},{"id":"art-72-7","article":"72","articleNumber":72,"block":7,"fromPoint":49,"toPoint":53,"pointCount":53,"prompt":"Cu ce statut poate participa un polițist la activitățile comisiei pentru prevenirea violenței?","options":["director adjunct","invitat","președinte obligatoriu","secretar permanent"],"answer":1,"term":"invitat","quote":"La activitățile comisiei poate participa, cu statut de invitat, și un polițist desemnat de către Direcția Generală de Poliție a Municipiului București/Inspectoratele de Poliție Județene.","context":"Atribuțiile comisiei:","source":"Art. 72","unit":53},{"id":"art-73-1","article":"73","articleNumber":73,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cui îi este subordonat secretariatul?","options":["administratorului de patrimoniu","administratorului financiar","directorului","secretarului-șef"],"answer":2,"term":"directorului","quote":"Compartimentul secretariat este subordonat directorului.","context":"","source":"Art. 73","unit":2},{"id":"art-74-1","article":"74","articleNumber":74,"block":1,"fromPoint":1,"toPoint":8,"pointCount":16,"prompt":"Ce compartiment gestionează actele de studii?","options":["administrativ","cabinetul medical","financiar – contabil","secretariat"],"answer":3,"term":"secretariat","quote":"primirea, întocmirea, anularea, eliberarea, arhivarea și casarea actelor de studii și a documentelor școlare, în conformitate cu prevederile regulamentului privind regimul actelor de studii și al documentelor școlare gestionate de unitățile de învățământul preuniversitar, aprobat prin ordin al ministrului educației;","context":"Compartimentul secretariat are următoarele atribuții:","source":"Art. 74","unit":7},{"id":"art-74-2","article":"74","articleNumber":74,"block":2,"fromPoint":9,"toPoint":16,"pointCount":16,"prompt":"Ce gestionează secretariatul pentru angajați?","options":["contractelor de telefonie personale","conturilor bancare personale","dosarelor de personal","dosarelor electorale"],"answer":2,"term":"dosarelor de personal","quote":"întocmirea, actualizarea și gestionarea dosarelor de personal ale angajaților unității de învățământ;","context":"Compartimentul secretariat are următoarele atribuții:","source":"Art. 74","unit":12},{"id":"art-75-1","article":"75","articleNumber":75,"block":1,"fromPoint":1,"toPoint":8,"pointCount":10,"prompt":"Este permisă condiționarea eliberării actelor de studii de beneficii?","options":["interzisă","obligatorie","permisă fără restricții","recomandată"],"answer":0,"term":"interzisă","quote":"Condiționarea de orice beneficii a eliberării actelor de studii, a documentelor școlare sau a caracterizărilor este interzisă.","context":"","source":"Art. 75","unit":5},{"id":"art-75-2","article":"75","articleNumber":75,"block":2,"fromPoint":9,"toPoint":10,"pointCount":10,"prompt":"Ce caracter trebuie să aibă sistemul de sesizare a violenței?","options":["confidențial","exclusiv anonim pe rețele sociale","exclusiv verbal","public pentru toți elevii"],"answer":0,"term":"confidențial","quote":"În fiecare unitate de învățământ va exista un sistem confidențial funcțional pentru sesizările referitoare la posibile acte de violență.","context":"","source":"Art. 75","unit":9},{"id":"art-76-1","article":"76","articleNumber":76,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cui îi este subordonat compartimentul financiar-contabil?","options":["administratorului financiar","directorului unității de învățământ","președintelui comitetului de părinți","președintelui consiliului elevilor"],"answer":1,"term":"directorului unității de învățământ","quote":"Compartimentul financiar – contabil este subordonat directorului unității de învățământ.","context":"","source":"Art. 76","unit":3},{"id":"art-77-1","article":"77","articleNumber":77,"block":1,"fromPoint":1,"toPoint":8,"pointCount":15,"prompt":"Ce compartiment întocmește proiectul de buget?","options":["administrativ","financiar","medical","secretariat"],"answer":1,"term":"financiar","quote":"desfășurarea activității financiar-contabile a unității de învățământ;","context":"Compartimentul financiar – contabil are următoarele atribuții:","source":"Art. 77","unit":1},{"id":"art-77-2","article":"77","articleNumber":77,"block":2,"fromPoint":9,"toPoint":15,"pointCount":15,"prompt":"Ce documente privind cheltuielile întocmește compartimentul financiar-contabil?","options":["angajarea, lichidarea, ordonanțarea și plata cheltuielilor bugetare","numai înscrierea elevilor","numai motivarea absențelor","numai planificarea lecțiilor"],"answer":0,"term":"angajarea, lichidarea, ordonanțarea și plata cheltuielilor bugetare","quote":"întocmirea, cu respectarea normelor legale în vigoare, a documentelor privind angajarea, lichidarea, ordonanțarea și plata cheltuielilor bugetare, realizând operațiunile prevăzute de normele legale în materie;","context":"Compartimentul financiar – contabil are următoarele atribuții:","source":"Art. 77","unit":14},{"id":"art-78-1","article":"78","articleNumber":78,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Pe ce bază se desfășoară activitatea financiară a școlii?","options":["bugetului propriu","cotizațiilor obligatorii ale elevilor","estimărilor verbale ale părinților","promisiunilor furnizorilor"],"answer":0,"term":"bugetului propriu","quote":"Activitatea financiară a unității de învățământ se desfășoară pe baza bugetului propriu.","context":"","source":"Art. 78","unit":2},{"id":"art-79-1","article":"79","articleNumber":79,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce program actualizează directorul și CA pe baza bugetului aprobat?","options":["programul anual de achiziții publice","programul de concedii al primăriei","programul de examene al universității","programul electoral local"],"answer":0,"term":"programul anual de achiziții publice","quote":"Pe baza bugetului aprobat, directorul și consiliul de administrație actualizează programul anual de achiziții publice, stabilind și celelalte măsuri ce se impun pentru asigurarea încadrării tuturor categoriilor de cheltuieli în limitele fondurilor alocate.","context":"","source":"Art. 79","unit":1},{"id":"art-80-1","article":"80","articleNumber":80,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Ce condiție este obligatorie pentru angajarea cheltuielilor?","options":["acordul verbal al elevilor","asigurată sursa de finanțare","cererea unui furnizor","promisiunea unui sponsor"],"answer":1,"term":"asigurată sursa de finanțare","quote":"Este interzisă angajarea de cheltuieli dacă nu este asigurată sursa de finanțare.","context":"","source":"Art. 80","unit":1},{"id":"art-81-1","article":"81","articleNumber":81,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Cine coordonează compartimentul administrativ?","options":["administratorul de patrimoniu","administratorul financiar","profesorul diriginte","secretarul-șef"],"answer":0,"term":"administratorul de patrimoniu","quote":"Compartimentul administrativ este coordonat de administratorul de patrimoniu și cuprinde personalul administrativ al unității de învățământ.","context":"","source":"Art. 81","unit":1},{"id":"art-82-1","article":"82","articleNumber":82,"block":1,"fromPoint":1,"toPoint":8,"pointCount":10,"prompt":"Ce bază gestionează compartimentul administrativ?","options":["bazei materiale","datelor electorale","datelor medicale personale","notelor la examene"],"answer":0,"term":"bazei materiale","quote":"gestionarea bazei materiale;","context":"Compartimentul administrativ are următoarele atribuții:","source":"Art. 82","unit":1},{"id":"art-82-2","article":"82","articleNumber":82,"block":2,"fromPoint":9,"toPoint":10,"pointCount":10,"prompt":"Ce proiect anual întocmește compartimentul administrativ?","options":["proiectului anual de achiziții","proiectului de curriculum național","proiectului de examen național","proiectului de plan-cadru național"],"answer":0,"term":"proiectului anual de achiziții","quote":"întocmirea proiectului anual de achiziții și a documentațiilor de atribuire a contractelor;","context":"Compartimentul administrativ are următoarele atribuții:","source":"Art. 82","unit":9},{"id":"art-83-1","article":"83","articleNumber":83,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Conform căror prevederi se administrează baza didactico-materială?","options":["legislației în vigoare","numai promisiunilor sponsorilor","numai solicitărilor furnizorilor","numai votului elevilor"],"answer":0,"term":"legislației în vigoare","quote":"Evidența, organizarea, actualizarea documentelor contabile, prezentarea situațiilor financiare referitoare la patrimoniu și administrarea bazei didactico-materiale a unităților de învățământ se realizează în conformitate cu prevederile legislației în vigoare.","context":"","source":"Art. 83","unit":1},{"id":"art-84-1","article":"84","articleNumber":84,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Cine numește comisia de inventariere?","options":["administratorului de patrimoniu","administratorului financiar","directorului","secretarului-șef"],"answer":2,"term":"directorului","quote":"Inventarierea bunurilor unității de învățământ se realizează de către comisia de inventariere, numită prin decizia directorului.","context":"","source":"Art. 84","unit":1},{"id":"art-85-1","article":"85","articleNumber":85,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Cine administrează bunurile școlii de stat?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"Bunurile aflate în proprietatea unității de învățământ de stat sunt administrate de către consiliul de administrație.","context":"","source":"Art. 85","unit":1},{"id":"art-86-1","article":"86","articleNumber":86,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"În baza cărei hotărâri pot fi închiriate bunurile temporar disponibile?","options":["hotărârii comitetului de părinți","hotărârii consiliului clasei","hotărârii consiliului de administrație","hotărârii consiliului elevilor"],"answer":2,"term":"hotărârii consiliului de administrație","quote":"Bunurile, care sunt temporar disponibile și care sunt în proprietatea sau administrarea unității de învățământ, pot fi închiriate în baza hotărârii consiliului de administrație.","context":"","source":"Art. 86","unit":1},{"id":"art-87-1","article":"87","articleNumber":87,"block":1,"fromPoint":1,"toPoint":8,"pointCount":8,"prompt":"Cum este accesul elevilor și personalului la Biblioteca Școlară Virtuală?","options":["condiționat de donații","condiționat de sponsorizare","contra cost","gratuit"],"answer":3,"term":"gratuit","quote":"În unitățile de învățământ se asigură accesul gratuit al beneficiarilor primari și al personalului la Biblioteca Școlară Virtuală și la platforme digitale de învățare.","context":"","source":"Art. 87","unit":5},{"id":"art-88-1","article":"88","articleNumber":88,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Pe lângă copii și elevi, cine poate fi beneficiar primar al educației?","options":["persoanele adulte înscrise într-o unitate de învățământ","toți angajații primăriei","toți furnizorii școlii","toți părinții elevilor"],"answer":0,"term":"persoanele adulte înscrise într-o unitate de învățământ","quote":"Beneficiarii primari ai educației sunt antepreșcolarii, preșcolarii și elevii, precum și persoanele adulte înscrise într-o unitate de învățământ.","context":"","source":"Art. 88","unit":1},{"id":"art-89-1","article":"89","articleNumber":89,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cum se dobândește calitatea de beneficiar primar?","options":["aprobarea primarului","înscrierea într-o asociație de părinți","înscrierea într-o unitate de învățământ","plata unei cotizații"],"answer":2,"term":"înscrierea într-o unitate de învățământ","quote":"Dobândirea calității de beneficiar primar al educației se face prin înscrierea într-o unitate de învățământ.","context":"","source":"Art. 89","unit":1},{"id":"art-90-1","article":"90","articleNumber":90,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Ce interes trebuie să respecte decizia privind retragerea copilului?","options":["interesul comercial al furnizorului","interesul educațional al copilului/elevului","interesul electoral al autorității","interesul financiar al asociației"],"answer":1,"term":"interesul educațional al copilului/elevului","quote":"În situația solicitării de retragere, menționate la alin. (2) și (3), unitățile de învățământ vor consilia părinții sau reprezentanții legali privind nevoia de a lua decizii în interesul educațional al copilului/elevului și îi vor informa că solicitarea nu poate fi soluționată decât în situația în care evaluarea nivelului dezvoltării realizată de cadrul didactic de la clasă atestă necesitatea reînscrierii în grupa/clasa anterioară sau în grupa/ clasa corespunzătoare nivelului din care s-a retras.","context":"","source":"Art. 90","unit":4},{"id":"art-91-1","article":"91","articleNumber":91,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Prin ce act sunt aprobate metodologiile înscrierii în clasa a IX-a și anul I postliceal?","options":["decizie a directorului","hotărâre a consiliului clasei","hotărâre a consiliului local","ordin al ministrului educației"],"answer":3,"term":"ordin al ministrului educației","quote":"Înscrierea în clasa a IX-a din învățământul liceal sau din învățământul profesional, respectiv în anul I din învățământul postliceal, inclusiv învățământul profesional și tehnic dual, se face în conformitate cu metodologiile aprobate prin ordin al ministrului educației.","context":"","source":"Art. 91","unit":1},{"id":"art-92-1","article":"92","articleNumber":92,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Cum sunt înscriși elevii promovați în anul următor, ca regulă?","options":["de drept","numai după o nouă taxă","numai după votul părinților","numai prin concurs anual"],"answer":0,"term":"de drept","quote":"Elevii promovați vor fi înscriși de drept în anul următor, dacă nu există prevederi specifice de admitere în clasa respectivă, aprobate prin ordin al ministrului educației.","context":"","source":"Art. 92","unit":1},{"id":"art-93-1","article":"93","articleNumber":93,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Cu ce se dovedește calitatea de elev?","options":["cardul de bibliotecă","carnetul de elev","certificatul de naștere","legitimația unui părinte"],"answer":1,"term":"carnetul de elev","quote":"Calitatea de elev se dovedește cu carnetul de elev, vizat la începutul fiecărui an școlar de către unitatea de învățământ la care este înscris elevul.","context":"","source":"Art. 93","unit":2},{"id":"art-94-1","article":"94","articleNumber":94,"block":1,"fromPoint":1,"toPoint":8,"pointCount":9,"prompt":"Câte ore pe an pot fi motivate prin cererea părintelui, în limita de 20% pe disciplină?","options":["35 de ore de curs","40 de ore de curs","45 de ore de curs","50 de ore de curs"],"answer":1,"term":"40 de ore de curs","quote":"În limita a 40 de ore de curs pe an școlar, fără a depăși 20% din numărul orelor alocate unei discipline, absențele pot fi motivate doar pe baza cererilor scrise ale părintelui sau reprezentantului legal al elevului sau ale elevului major, adresate învățătorului/ institutorului/profesorului pentru învățământul primar/profesorului diriginte al clasei, avizate în prealabil de motivare de către directorul unității de învățământ.","context":"","source":"Art. 94","unit":5},{"id":"art-94-2","article":"94","articleNumber":94,"block":2,"fromPoint":9,"toPoint":9,"pointCount":9,"prompt":"Pe ce bază se motivează absențele elevilor reprezentanți?","options":["acordului verbal al colegilor","actelor justificative","unei promisiuni de recuperare","votului consiliului clasei"],"answer":1,"term":"actelor justificative","quote":"În cazul beneficiarilor primari reprezentanți, absențele se motivează pe baza actelor justificative, conform prevederilor statutului elevului.","context":"","source":"Art. 94","unit":9},{"id":"art-95-1","article":"95","articleNumber":95,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Cine aprobă motivarea absențelor pentru olimpiade și concursuri școlare?","options":["administratorul financiar","directorul unității de învățământ","președintele comitetului de părinți","președintele consiliului elevilor"],"answer":1,"term":"directorul unității de învățământ","quote":"Directorul unității de învățământ aprobă motivarea absențelor beneficiarilor primari care participă la olimpiadele și concursurile școlare și profesionale organizate la nivel local, județean/interjudețean, regional, național și internațional, la cererea scrisă a profesorilor îndrumători/însoțitori.","context":"","source":"Art. 95","unit":2},{"id":"art-96-1","article":"96","articleNumber":96,"block":1,"fromPoint":1,"toPoint":7,"pointCount":7,"prompt":"Când se pot reînmatricula, de regulă, elevii retrași?","options":["la începutul anului școlar","numai după doi ani","numai în ultima zi de cursuri","numai la sfârșitul clasei a VIII-a"],"answer":0,"term":"la începutul anului școlar","quote":"Elevii retrași din învățământul preuniversitar se pot reînmatricula, la cerere, de regulă la începutul anului școlar, la același nivel/ciclu de învățământ și aceeași formă de învățământ, cu susținerea, după caz, a examenelor de diferență, redobândind astfel calitatea de elev.","context":"","source":"Art. 96","unit":1},{"id":"art-97-1","article":"97","articleNumber":97,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Când se desfășoară educația extrașcolară?","options":["exclusiv în timpul evaluărilor","în afara programului școlar","numai în timpul orelor de matematică","numai în timpul tezelor"],"answer":1,"term":"în afara programului școlar","quote":"Educația extrașcolară cuprinde ansamblul activităților educaționale organizate în afara programului școlar, în incinta unităților de învățământ sau în afara acestora, care contribuie la dezvoltarea și exersarea competențelor formate prin intermediul curriculumului național, și care se centrează pe dezvoltarea fizică, cognitivă, emoțională și socială a beneficiarilor primari, în vederea integrării și participării lor active în societate.","context":"","source":"Art. 97","unit":1},{"id":"art-98-1","article":"98","articleNumber":98,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Când se desfășoară activitatea educativă extrașcolară a școlii?","options":["exclusiv în orele de curs","exclusiv în timpul examenelor","în afara orelor de curs","numai în locul disciplinelor obligatorii"],"answer":2,"term":"în afara orelor de curs","quote":"Activitatea educativă extrașcolară din unitățile de învățământ se desfășoară în afara orelor de curs.","context":"","source":"Art. 98","unit":1},{"id":"art-99-1","article":"99","articleNumber":99,"block":1,"fromPoint":1,"toPoint":8,"pointCount":10,"prompt":"Cine aprobă calendarul activităților educaționale extrașcolare?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"Calendarul activităților educaționale extrașcolare este aprobat de consiliul de administrație al unității de învățământ.","context":"","source":"Art. 99","unit":7},{"id":"art-99-2","article":"99","articleNumber":99,"block":2,"fromPoint":9,"toPoint":10,"pointCount":10,"prompt":"Cum trebuie sprijinit accesul elevilor la activitățile extrașcolare?","options":["fără impunerea obligativității și fără nicio discriminare","numai prin contribuții financiare","numai prin participare obligatorie","numai prin selecție după venituri"],"answer":0,"term":"fără impunerea obligativității și fără nicio discriminare","quote":"Cadrele didactice din unitățile de învățământ preuniversitar valorifică rezultatele învățării dobândite de preșcolari/elevi în urma participării acestora la activități educaționale extrașcolare și îi motivează pentru implicarea în activități extrașcolare, sprijinind accesul la aceste activități fără impunerea obligativității și fără nicio discriminare.","context":"","source":"Art. 99","unit":9},{"id":"art-100-1","article":"100","articleNumber":100,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Pe ce bază colaborează școlile de artă și sport cu palatele și cluburile copiilor?","options":["decizii individuale ale elevilor","protocoale de parteneriat","simple înțelegeri verbale","taxe obligatorii ale părinților"],"answer":1,"term":"protocoale de parteneriat","quote":"Colaborarea dintre unitățile care desfășoară învățământul de artă și învățământul sportiv și palatele, cluburile copiilor și cluburile sportive școlare se realizează în baza unor protocoale de parteneriat, care conțin obligațiile și beneficiile reciproce.","context":"","source":"Art. 100","unit":2},{"id":"art-101-1","article":"101","articleNumber":101,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Care este un scop al evaluării?","options":["ierarhizarea veniturilor familiilor","orientarea și optimizarea procesului de predare-învățare","sancționarea financiară a părinților","stabilirea taxelor de școlarizare"],"answer":1,"term":"orientarea și optimizarea procesului de predare-învățare","quote":"Scopurile evaluării sunt orientarea și optimizarea procesului de predare-învățare, precum și gestionarea propriilor rezultate ale învățării.","context":"","source":"Art. 101","unit":1},{"id":"art-102-1","article":"102","articleNumber":102,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Pe ce se centrează evaluarea?","options":["competențe","opțiunile politice","relațiile personale","veniturile familiei"],"answer":0,"term":"competențe","quote":"În sistemul de învățământ preuniversitar evaluarea se centrează pe competențe, oferă feedback real beneficiarilor primari, părinților/reprezentanților legali și cadrelor didactice și stă la baza planurilor individuale de învățare.","context":"","source":"Art. 102","unit":2},{"id":"art-103-1","article":"103","articleNumber":103,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Când se realizează evaluarea rezultatelor la învățătură?","options":["numai în ultima zi de cursuri","numai la examenul final","numai la începutul anului","permanent, pe parcursul anului școlar"],"answer":3,"term":"permanent, pe parcursul anului școlar","quote":"Evaluarea rezultatelor la învățătură se realizează permanent, pe parcursul anului școlar.","context":"","source":"Art. 103","unit":1},{"id":"art-104-1","article":"104","articleNumber":104,"block":1,"fromPoint":1,"toPoint":8,"pointCount":9,"prompt":"Cine aprobă alte instrumente de evaluare stabilite de comisia pentru curriculum?","options":["administratorul de patrimoniu","comitetul de părinți","consiliul elevilor","director"],"answer":3,"term":"director","quote":"alte instrumente stabilite de comisia pentru curriculum și aprobate de director sau elaborate de către Ministerul Educației/inspectoratele școlare.","context":"Instrumentele de evaluare se stabilesc în funcție de vârstă și de particularitățile psihopedagogice ale beneficiarilor primari ai educației și de specificul fiecărei discipline. Acestea sunt:","source":"Art. 104","unit":8},{"id":"art-104-2","article":"104","articleNumber":104,"block":2,"fromPoint":9,"toPoint":9,"pointCount":9,"prompt":"Care este minimul de evaluări scrise anuale pe disciplină, cu excepția celor preponderent practice?","options":["cel puțin două","cel puțin opt","cel puțin șase","cel puțin una"],"answer":0,"term":"cel puțin două","quote":"În învățământul primar, la clasele I-IV, în cel gimnazial, liceal, profesional și în cel postliceal, elevii vor avea la fiecare disciplină/modul, cu excepția celor preponderent practice, cel puțin două evaluări prin lucrare scrisă/test pe an școlar.","context":"Instrumentele de evaluare se stabilesc în funcție de vârstă și de particularitățile psihopedagogice ale beneficiarilor primari ai educației și de specificul fiecărei discipline. Acestea sunt:","source":"Art. 104","unit":9},{"id":"art-105-1","article":"105","articleNumber":105,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Pe ce se bazează testele și subiectele de examen?","options":["opțiunile electorale","preferințele furnizorilor","programele școlare","veniturile familiilor"],"answer":2,"term":"programele școlare","quote":"Testele de evaluare și subiectele de examen de orice tip se elaborează pe baza cerințelor didactico-metodologice stabilite de programele școlare, parte a curriculumului național.","context":"","source":"Art. 105","unit":1},{"id":"art-106-1","article":"106","articleNumber":106,"block":1,"fromPoint":1,"toPoint":8,"pointCount":18,"prompt":"Cum se exprimă rezultatele evaluării în clasele I–IV din învățământul de masă?","options":["calificative","exclusiv note de la 1 la 10","exclusiv procente de prezență","exclusiv punctaje universitare"],"answer":0,"term":"calificative","quote":"calificative la clasele I-IV din învățământul de masă și, respectiv, pentru clasele I-IV și pentru nivelul de învățământ gimnazial din învățământul special care școlarizează elevi cu deficiențe grave, severe, profunde sau asociate;","context":"Rezultatele evaluării se exprimă, după caz, prin:","source":"Art. 106","unit":2},{"id":"art-106-2","article":"106","articleNumber":106,"block":2,"fromPoint":9,"toPoint":16,"pointCount":18,"prompt":"Ce notă se acordă pentru frauda constatată la evaluările scrise?","options":["nota 1","nota 2","nota 3","nota 4"],"answer":0,"term":"nota 1","quote":"Pentru frauda constatată la evaluările scrise, inclusiv la probele scrise din cadrul examenelor/concursurilor organizate la nivelul unității de învățământ, conform prezentului regulament, se acordă nota 1 sau, după caz, calificativul insuficient.","context":"","source":"Art. 106","unit":13},{"id":"art-106-3","article":"106","articleNumber":106,"block":3,"fromPoint":17,"toPoint":18,"pointCount":18,"prompt":"Cine emite recomandarea de încadrare la nivelul următor, la final de gimnaziu și liceu?","options":["administratorul și bibliotecarul","primarul și viceprimarul","profesorul consilier școlar și dirigintele","secretarul și contabilul"],"answer":2,"term":"profesorul consilier școlar și dirigintele","quote":"La finalizarea învățământului gimnazial și liceal, profesorul consilier școlar și dirigintele au obligația să emită câte o recomandare de încadrare într-o formă de învățământ de nivel superior, având caracter de orientare școlară pentru fiecare elev în parte. În cazul absolvenților de învățământ liceal se poate realiza și o recomandare sub forma unei orientări vocaționale de încadrare pe piața forței de muncă. Recomandările sunt consultative și sunt emise în baza metodologiei specifice și sunt incluse în portofoliul educațional.","context":"","source":"Art. 106","unit":17},{"id":"art-107-1","article":"107","articleNumber":107,"block":1,"fromPoint":1,"toPoint":7,"pointCount":7,"prompt":"De regulă, cu cât depășește numărul anual de note numărul de ore săptămânale?","options":["cel puțin cinci","cel puțin șapte","cel puțin trei","cel puțin una"],"answer":2,"term":"cel puțin trei","quote":"Numărul de calificative/note acordate anual fiecărui elev, la fiecare disciplină de studiu, este stabilit de cadrul didactic, în funcție de numărul unităților de învățare și de numărul săptămânal de ore prevăzut în planul-cadru. La fiecare disciplină numărul de calificative/note acordate anual este, de regulă, cu cel puțin trei mai mare decât numărul de ore alocat săptămânal disciplinei în planul-cadru de învățământ, dar nu mai mic de patru note pe an școlar pentru fiecare disciplină. În cazul disciplinelor de studiu cu mai puțin de o oră/săptămână, numărul minim de note acordate pentru un an școlar este de două.","context":"","source":"Art. 107","unit":4},{"id":"art-108-1","article":"108","articleNumber":108,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Cine desemnează alt profesor dacă titularul refuză încheierea situației școlare, deși sunt note suficiente?","options":["consiliul clasei","consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"consiliul de administrație","quote":"La sfârșitul anului școlar, cadrele didactice au obligația să încheie situația școlară a beneficiarilor primari. În situația în care cadrul didactic refuză să încheie situația școlară a beneficiarilor primari și elevii au note suficiente, consiliul de administrație al unității de învățământ va desemna un cadru didactic care să le încheie situația școlară în locul acestuia.","context":"","source":"Art. 108","unit":1},{"id":"art-109-1","article":"109","articleNumber":109,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"În favoarea cui se face rotunjirea mediei la o diferență de 50 de sutimi?","options":["directorului","elevului","părintelui","profesorului"],"answer":1,"term":"elevului","quote":"La fiecare disciplină de studiu/modul, inclusiv la purtare se încheie anual o singură medie, calculată prin rotunjirea mediei aritmetice a notelor la cel mai apropiat număr întreg. La o diferență de 50 de sutimi, rotunjirea se face în favoarea elevului. Media, respectiv calificativul la purtare rezultat la finalul anului școlar ca medie a notelor acordate pentru fiecare interval de învățare, luând în considerare comportamentul elevului, se diminuează în mod corespunzător cu unul sau mai multe puncte, în cazul beneficiarilor primari care au înregistrat un număr de absențe nemotivate, în conformitate cu prevederile prezentului Regulament – cadru, precum și cu prevederile Statutului elevului.","context":"","source":"Art. 109","unit":1},{"id":"art-110-1","article":"110","articleNumber":110,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Ce calificative se aleg inițial pentru stabilirea calificativului anual?","options":["două calificative cu frecvența cea mai mare","două calificative cu frecvența cea mai mică","numai primul calificativ","numai ultimul calificativ"],"answer":0,"term":"două calificative cu frecvența cea mai mare","quote":"Pentru aceste clase, calificativul pe disciplină se stabilește astfel: se aleg două calificative cu frecvența cea mai mare, acordate în timpul anului școlar, după care, în perioadele de recapitulare și de consolidare a materiei, în urma aplicării unor probe de evaluare sumativă, cadrul didactic poate opta pentru unul dintre cele două calificative, în baza următoarelor criterii:","context":"","source":"Art. 110","unit":2},{"id":"art-111-1","article":"111","articleNumber":111,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Cine consemnează calificativele la purtare în primar?","options":["comitetul de părinți","consiliul elevilor","învățători/ institutori/profesorii pentru învățământul primar","secretarul și contabilul"],"answer":2,"term":"învățători/ institutori/profesorii pentru învățământul primar","quote":"În învățământul primar, calificativele anuale la fiecare disciplină se consemnează în catalog de către învățătorul/institutorul/profesorul pentru învățământul primar/profesorul de specialitate. Calificativele la purtare se consemnează în catalog de către învățători/ institutori/profesorii pentru învățământul primar.","context":"","source":"Art. 111","unit":1},{"id":"art-112-1","article":"112","articleNumber":112,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Ce obligație au elevii scutiți de efort fizic?","options":["de a fi prezenți la orele de educație fizică și sport","de a lipsi de la toate orele de sport","de a participa la efort maxim","de a plăti o taxă de scutire"],"answer":0,"term":"de a fi prezenți la orele de educație fizică și sport","quote":"Elevii scutiți de efort fizic au obligația de a fi prezenți la orele de educație fizică și sport. Beneficiarilor primari scutiți medical pe parcursul unui întreg an școlar nu li se acordă calificative/note și nu li se încheie media la această disciplină, respectiv, media anuală se calculează fără media de la această disciplină.","context":"","source":"Art. 112","unit":1},{"id":"art-113-1","article":"113","articleNumber":113,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Unde sunt școlarizați sportivii nominalizați pentru centrele olimpice/de excelență?","options":["exclusiv în străinătate","exclusiv în școli militare","exclusiv la domiciliu","în apropierea acestor structuri sportive"],"answer":3,"term":"în apropierea acestor structuri sportive","quote":"Școlarizarea beneficiarilor primari sportivi nominalizați de federațiile naționale sportive pentru centrele naționale olimpice/de excelență se realizează în unități de învățământ situate în apropierea acestor structuri sportive și respectă dinamica selecției loturilor. Situația școlară, înregistrată în perioadele în care elevii se pregătesc în aceste centre, se transmite unităților de învățământ de care aceștia aparțin. În cazul în care școlarizarea se realizează în unități de învățământ care nu pot asigura pregătirea beneficiarilor primari la unele discipline de învățământ, situația școlară a acestor elevi se poate încheia, la disciplinele respective, la unitățile de învățământ de care elevii aparțin, după întoarcerea acestora, conform prezentului regulament.","context":"","source":"Art. 113","unit":1},{"id":"art-114-1","article":"114","articleNumber":114,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Cum se realizează participarea la ora de religie?","options":["exclusiv după o contribuție financiară","exclusiv prin decizia primarului","exclusiv prin votul clasei","în conformitate cu prevederile legale în vigoare"],"answer":3,"term":"în conformitate cu prevederile legale în vigoare","quote":"Participarea la ora de religie se realizează în conformitate cu prevederile legale în vigoare.","context":"","source":"Art. 114","unit":1},{"id":"art-115-1","article":"115","articleNumber":115,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Care este media anuală minimă la purtare pentru promovare?","options":["4","5","6","7"],"answer":2,"term":"6","quote":"Sunt declarați promovați elevii care, la sfârșitul anului școlar, obțin la fiecare disciplină de studiu/modul cel puțin media anuală 5/calificativul \"Suficient\", iar la purtare, media anuală 6/calificativul \"Suficient\".","context":"","source":"Art. 115","unit":1},{"id":"art-116-1","article":"116","articleNumber":116,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"Ce medie minimă este necesară la disciplina principală de specialitate la profil artistic sau sportiv?","options":["4","5","6","7"],"answer":2,"term":"6","quote":"Elevii de la clasele cu profil artistic sau sportiv trebuie să obțină media cel puțin 6 la disciplina principală de specialitate, pentru aceste profiluri/specializări.","context":"","source":"Art. 116","unit":1},{"id":"art-117-1","article":"117","articleNumber":117,"block":1,"fromPoint":1,"toPoint":8,"pointCount":8,"prompt":"Când se încheie situația școlară a elevilor amânați?","options":["înaintea sesiunii de corigențe","numai după doi ani","numai după începerea anului următor","numai după sesiunea de corigențe"],"answer":0,"term":"înaintea sesiunii de corigențe","quote":"Încheierea situației școlare a beneficiarilor primari amânați se face înaintea sesiunii de corigențe, într-o perioadă stabilită de consiliul de administrație. Elevii amânați care nu promovează la una sau două discipline/module de studiu în sesiunea de examene de încheiere a situației școlare a beneficiarilor primari amânați se pot prezenta la sesiunea de examene de corigențe. Elevii declarați amânați din clasa pregătitoare, respectiv din clasa I care nu se prezintă în sesiunile de examinare sunt reînscriși în clasa pentru care nu s-a încheiat situația școlară. Elevele gravide și elevii părinți declarați amânați în condițiile prevederilor alin. (1), lit.f) care nu se prezintă în sesiunile de examinare sunt reînscriși în clasa pentru care nu s-a încheiat situația școlară.","context":"Sunt declarați amânați elevii cărora nu li se poate definitiva situația școlară la una sau la mai multe discipline de studiu/module din următoarele motive:","source":"Art. 117","unit":7},{"id":"art-118-1","article":"118","articleNumber":118,"block":1,"fromPoint":1,"toPoint":7,"pointCount":7,"prompt":"Ce prag de absențe nemotivate indică risc de abandon școlar?","options":["cel puțin 25%","cel puțin 40%","cel puțin 50%","cel puțin 75%"],"answer":3,"term":"cel puțin 75%","quote":"Elevii care nu frecventează cursurile școlare și care au absentat nemotivat la cel puțin 75% din numărul de ore de curs prevăzut într-un an școlar la disciplinele/modulele respective, sunt considerați în situație de risc de abandon școlar.","context":"","source":"Art. 118","unit":4},{"id":"art-119-1","article":"119","articleNumber":119,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"La câte discipline pot avea medii sub 5 elevii declarați corigenți, ca regulă?","options":["cel mult două discipline de studiu","cel mult patru discipline de studiu","cel mult trei discipline de studiu","oricâte discipline de studiu"],"answer":0,"term":"cel mult două discipline de studiu","quote":"Sunt declarați corigenți elevii care obțin calificativul \"Insuficient'/medii anuale sub 5 la cel mult două discipline de studiu, precum și elevii amânați care nu promovează examenul de încheiere a situației școlare la cel mult două discipline de studiu.","context":"","source":"Art. 119","unit":1},{"id":"art-120-1","article":"120","articleNumber":120,"block":1,"fromPoint":1,"toPoint":7,"pointCount":7,"prompt":"În ce clase elevii nu pot fi lăsați repetenți?","options":["clasei pregătitoare și al clasei I","claselor a II-a și a III-a","claselor a IV-a și a V-a","claselor a VI-a și a VII-a"],"answer":0,"term":"clasei pregătitoare și al clasei I","quote":"La sfârșitul clasei pregătitoare și al clasei I elevii nu pot fi lăsați repetenți. Elevii care, pe parcursul anului școlar, au manifestat dificultăți de învățare, menționate în raportul de evaluare a dezvoltării fizice, socioemoționale, cognitive, a limbajului și a comunicării, precum și a dezvoltării capacităților și atitudinilor față de învățare, rămân în colectivele în care au învățat și intră, pe parcursul anului școlar următor, într-un program de remediere/recuperare școlară, realizat de un învățător/institutor/profesor pentru învățământul primar împreună cu un specialist de la centrul județean de resurse și asistență educațională/Centrul Municipiului București de Resurse și Asistență Educațională.","context":"Sunt declarați repetenți:","source":"Art. 120","unit":6},{"id":"art-121-1","article":"121","articleNumber":121,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"În ce clasă se înscrie, la cerere, elevul repetent în anul următor?","options":["clasa pe care o repetă","numai în clasa superioară","numai într-o clasă de nivel liceal","obligatoriu în prima clasă"],"answer":0,"term":"clasa pe care o repetă","quote":"Elevii declarați repetenți se înscriu, la cerere, în anul școlar următor în clasa pe care o repetă, la aceeași unitate de învățământ, inclusiv cu depășirea numărului maxim de elevi la clasă prevăzut de lege, sau se pot transfera la o altă unitate de învățământ.","context":"","source":"Art. 121","unit":1},{"id":"art-122-1","article":"122","articleNumber":122,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"În ce termen se depune cererea de reexaminare după corigență?","options":["19 de ore","24 de ore","29 de ore","34 de ore"],"answer":1,"term":"24 de ore","quote":"Cererea de reexaminare se depune la secretariatul unității de învățământ, în termen de 24 de ore de la afișarea rezultatelor examenului de corigență.","context":"","source":"Art. 122","unit":2},{"id":"art-123-1","article":"123","articleNumber":123,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Din ce materie sunt examinați elevii corigenți sau amânați?","options":["numai din materia opțională","numai din primul capitol","numai din ultima lecție","toată materia studiată în anul școlar"],"answer":3,"term":"toată materia studiată în anul școlar","quote":"Pentru elevii declarați corigenți sau amânați, examinarea se face din toată materia studiată în anul școlar, conform programei școlare.","context":"","source":"Art. 123","unit":1},{"id":"art-124-1","article":"124","articleNumber":124,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"La ce vârstă poate înceta frecventarea învățământului obligatoriu la forma cu frecvență?","options":["13 ani","18 ani","23 ani","28 ani"],"answer":1,"term":"18 ani","quote":"Frecventarea învățământului obligatoriu poate înceta la forma cu frecvență la 18 ani. Persoanele care nu au finalizat învățământul obligatoriu până la această vârstă și care au depășit cu mai mult de trei ani vârsta clasei își pot continua studiile, la cerere, și la forma de învățământ cu frecvență, cursuri serale sau la forma cu frecvență redusă.","context":"","source":"Art. 124","unit":1},{"id":"art-125-1","article":"125","articleNumber":125,"block":1,"fromPoint":1,"toPoint":8,"pointCount":33,"prompt":"Ce statut au elevii până la finalizarea echivalării studiilor din străinătate?","options":["absolvenți","audienți","exmatriculați","repetenți"],"answer":1,"term":"audienți","quote":"Elevii menționați la alin. (1) vor fi înscriși ca audienți până la finalizarea procedurii de echivalare, indiferent de momentul în care părinții sau reprezentanții legali ai acestora solicită școlarizarea, în unități de învățământ preuniversitar, cu excepția unităților de învățământ din cadrul Ministerului Apărării Naționale. Dosarul pentru echivalare se depune la inspectoratele școlare județene/ Inspectoratul Școlar al Municipiului București/ în termen de maximum 30 de zile de la data înscrierii în calitate de audient.","context":"","source":"Art. 125","unit":2},{"id":"art-125-2","article":"125","articleNumber":125,"block":2,"fromPoint":9,"toPoint":16,"pointCount":33,"prompt":"Cine emite decizia de constituire a comisiei de evaluare pentru studiile fără acte doveditoare?","options":["directorul adjunct","Inspectorul școlar general","profesorul diriginte","secretarul-șef"],"answer":1,"term":"Inspectorul școlar general","quote":"Inspectorul școlar general emite, în termen de 10 de zile de la primirea solicitării adresate unității de învățământ, decizia de constituire a comisiei de evaluare/examinare, formată din cadre didactice din unitatea de învățământ și cel puțin un inspector școlar/ profesor metodist. Evaluarea elevului se realizează în termen de cel mult 20 de zile de la data emiterii deciziei, după ce a beneficiat de activități de sprijin și consiliere psiho- pedagogică din partea unității școlare, după cum urmează:","context":"","source":"Art. 125","unit":12},{"id":"art-125-3","article":"125","articleNumber":125,"block":3,"fromPoint":17,"toPoint":24,"pointCount":33,"prompt":"Ce disciplină este probă obligatorie la echivalarea prevăzută la alin. (13)?","options":["Educație fizică și sport","Educație plastică","Limba și literatura română","Religie"],"answer":2,"term":"Limba și literatura română","quote":"Limba și literatura română;","context":"solicitantul este evaluat din materia prevăzută în programele școlare corespunzătoare anului/anilor de studiu liceal, prin susținerea câte unei probe la fiecare din disciplinele din planul-cadru aferent profilului și specializării solicitate pentru care nu deține documente, astfel:","source":"Art. 125","unit":20},{"id":"art-125-4","article":"125","articleNumber":125,"block":4,"fromPoint":25,"toPoint":32,"pointCount":33,"prompt":"În ce termen se poate solicita reexaminarea probelor nepromovate pentru echivalare?","options":["maximum 10 zile lucrătoare","maximum 15 zile lucrătoare","maximum 20 zile lucrătoare","maximum 5 zile lucrătoare"],"answer":0,"term":"maximum 10 zile lucrătoare","quote":"în cazul nepromovării uneia sau mai multor probe, solicitantul are dreptul de a solicita reexaminarea la disciplinele respective, în termen de maximum 10 zile lucrătoare de la data afișării rezultatelor;","context":"","source":"Art. 125","unit":27},{"id":"art-125-5","article":"125","articleNumber":125,"block":5,"fromPoint":33,"toPoint":33,"pointCount":33,"prompt":"Prin ce procedură sunt echivalate notele elevilor români reintegrați din sistemul școlilor europene?","options":["procedură de exmatriculare","procedură de selecție electorală","procedură disciplinară","procedură simplificată"],"answer":3,"term":"procedură simplificată","quote":"Prin excepție de la prevederile alin. (1) – (12), în temeiul Legii nr. 356/2007 pentru aderarea României la Convenția privind definirea statutului școlilor europene, adoptată la Luxemburg la 21 iunie 1994, beneficiarilor primari români înscriși în sistemul școlilor europene, reintegrați în sistemul educațional național, li se recunosc și li se echivalează în procedură simplificată, pe baza cererii avizate de către Ministerul Educației, prin direcția cu atribuții în domeniul școlilor europene, notele/calificativele obținute, cu încadrarea în clasa corespunzătoare.","context":"","source":"Art. 125","unit":33},{"id":"art-126-1","article":"126","articleNumber":126,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Ce se întâmplă cu locul elevelor gravide și al elevilor părinți în perioada îngrijirii copilului, la cerere?","options":["li se rezervă locul","se condiționează de o taxă","se pierde automat locul","se repartizează definitiv altui elev"],"answer":0,"term":"li se rezervă locul","quote":"Elevelor gravide și beneficiarilor primari părinți, pe perioada de îngrijire a copilului, li se rezervă locul în unitatea de învățământ în care sunt școlarizați, la solicitarea scrisă a părintelui/reprezentantului legal al acestora sau la solicitarea scrisă a beneficiarilor primari majori.","context":"","source":"Art. 126","unit":3},{"id":"art-127-1","article":"127","articleNumber":127,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"În ce termen se comunică situația de corigență, amânare, repetenție sau abandon după încheierea cursurilor?","options":["cel mult 6 zile","cel mult 7 zile","cel mult 8 zile","cel mult 9 zile"],"answer":1,"term":"cel mult 7 zile","quote":"Situația școlară a beneficiarilor primari corigenți, amânați, repetenți sau în situație de abandon școlar se comunică în scris părinților sau reprezentanților legali sau, după caz, beneficiarilor primari majori de către învățător/institutor/profesorul pentru învățământul primar/profesorul diriginte, în cel mult 7 zile de la încheierea cursurilor.","context":"","source":"Art. 127","unit":2},{"id":"art-128-1","article":"128","articleNumber":128,"block":1,"fromPoint":1,"toPoint":8,"pointCount":12,"prompt":"Ca regulă, sunt permise examinări pentru înscrierea în prima clasă din primar?","options":["Se interzice","Sunt impuse de comitetul părinților","Sunt întotdeauna recomandate","Sunt obligatorii"],"answer":0,"term":"Se interzice","quote":"Se interzice organizarea unor examinări în vederea înscrierii beneficiarilor primari în prima clasă a învățământului primar. În clasa pregătitoare sunt înscriși copiii care au împlinit vârsta de 6 ani până la data începerii anului școlar. La solicitarea scrisă a părinților/reprezentanților legali, pot fi înscriși în clasa pregătitoare și copiii care împlinesc vârsta de 6 ani până la sfârșitul anului calendaristic, dacă dezvoltarea lor psihosomatică este corespunzătoare.","context":"","source":"Art. 128","unit":7},{"id":"art-128-2","article":"128","articleNumber":128,"block":2,"fromPoint":9,"toPoint":12,"pointCount":12,"prompt":"Ce trebuie asigurat elevilor cu CES în procesul de învățare și la examene?","options":["condiții de egalizare de șanse","evaluarea exclusiv după prezență","excluderea de la probe","taxe suplimentare obligatorii"],"answer":0,"term":"condiții de egalizare de șanse","quote":"Pentru elevii cu cerințe educaționale speciale se asigură condiții de egalizare de șanse, în funcție de tipul de tulburare/afecțiune/dizabilitate, atât pe parcursul procesului de învățare cât și în cadrul examenelor organizate la nivelul unității de învățământ.","context":"","source":"Art. 128","unit":11},{"id":"art-129-1","article":"129","articleNumber":129,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Când au loc, de regulă, examenele de diferență?","options":["în perioada vacanțelor școlare","numai după absolvirea liceului","numai în prima zi de cursuri","numai în ultima zi de cursuri"],"answer":0,"term":"în perioada vacanțelor școlare","quote":"Desfășurarea examenelor de diferență are loc, de regulă, în perioada vacanțelor școlare.","context":"","source":"Art. 129","unit":1},{"id":"art-130-1","article":"130","articleNumber":130,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Se acordă reexaminare la diferențele pentru transfer?","options":["nu se acordă reexaminare","se acordă automat reexaminare anuală","se acordă obligatoriu două reexaminări","se acordă reexaminare fără limită"],"answer":0,"term":"nu se acordă reexaminare","quote":"La examenele de diferență pentru elevii care solicită transferul de la o unitate de învățământ la alta nu se acordă reexaminare.","context":"","source":"Art. 130","unit":1},{"id":"art-131-1","article":"131","articleNumber":131,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Ce tipuri de probe pot exista la examenele școlii?","options":["numai probe de prezență","numai probe de voluntariat","numai probe sportive","scrise, orale și practice"],"answer":3,"term":"scrise, orale și practice","quote":"Pentru desfășurarea examenelor există trei tipuri de probe: scrise, orale și practice, după caz. La toate examenele se susțin, de regulă, două din cele trei probe – proba scrisă și proba orală.","context":"","source":"Art. 131","unit":1},{"id":"art-132-1","article":"132","articleNumber":132,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"Cât durează proba scrisă pentru învățământul primar?","options":["40 de minute","45 de minute","50 de minute","55 de minute"],"answer":1,"term":"45 de minute","quote":"Proba scrisă a examenelor are o durată de 45 de minute pentru învățământul primar și de 90 de minute pentru învățământul secundar și postliceal, din momentul primirii subiectelor de către elev. Proba scrisă conține două variante de subiecte, dintre care elevul tratează o singură variantă, la alegere.","context":"","source":"Art. 132","unit":1},{"id":"art-133-1","article":"133","articleNumber":133,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"Care este media minimă de promovare la corigență?","options":["3","4","5","6"],"answer":2,"term":"5","quote":"Sunt declarați promovați anual elevii care obțin, la fiecare disciplină/modul la care susțin examenul de corigență, cel puțin calificativul \"Suficient\"/media 5.","context":"","source":"Art. 133","unit":2},{"id":"art-134-1","article":"134","articleNumber":134,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"În ce termen se depun actele care justifică neprezentarea la examen?","options":["cel mult 6 zile lucrătoare","cel mult 7 zile lucrătoare","cel mult 8 zile lucrătoare","cel mult 9 zile lucrătoare"],"answer":1,"term":"cel mult 7 zile lucrătoare","quote":"Elevii corigenți sau amânați care nu se pot prezenta la examene din motive temeinice, dovedite cu acte, depuse în cel mult 7 zile lucrătoare de la data examenului, sunt examinați la o dată ulterioară, stabilită de consiliul de administrație, dar nu mai târziu de începerea cursurilor noului an școlar. Perioada se poate prelungi, în mod excepțional, pentru situații obiective, prin decizie a inspectoratului școlar.","context":"","source":"Art. 134","unit":1},{"id":"art-135-1","article":"135","articleNumber":135,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Când se afișează rezultatele corigențelor și ale examenelor elevilor amânați?","options":["a doua zi după încheierea sesiunii de examen","la o lună după începerea anului","numai după doi ani","numai la sfârșitul mandatului directorului"],"answer":0,"term":"a doua zi după încheierea sesiunii de examen","quote":"Rezultatul la examenele de corigență și la examenele de încheiere a situației pentru elevii amânați, precum și situația școlară anuală a beneficiarilor primari se afișează, la loc vizibil, a doua zi după încheierea sesiunii de examen, cu respectarea legislației în vigoare privind protecția datelor cu caracter personal, și se consemnează în procesul-verbal al primei ședințe a consiliului profesoral.","context":"","source":"Art. 135","unit":6},{"id":"art-136-1","article":"136","articleNumber":136,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Unde consemnează dirigintele situația școlară după examene?","options":["în catalog","numai în condica de prezență","numai în registrul de casă","numai în registrul de inventar"],"answer":0,"term":"în catalog","quote":"După terminarea sesiunii de examen, de încheiere a situației de corigență sau de reexaminare, învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte consemnează în catalog situația școlară a beneficiarilor primari care au participat la aceste examene.","context":"","source":"Art. 136","unit":1},{"id":"art-137-1","article":"137","articleNumber":137,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce drept au elevii în condițiile legii și ale regulamentelor?","options":["să anuleze planul-cadru","să numească directorul","să se transfere","să stabilească taxe de școlarizare"],"answer":2,"term":"să se transfere","quote":"Beneficiarii primari ai educației au dreptul să se transfere de la o unitate de învățământ la alta, de la o formațiune de studiu la alta, de la un profil la altul și de la o filieră la alta, în condițiile stabilite de prevederile legii și ale prezentului regulament și ale regulamentului de organizare și funcționare a unității de învățământ la care se face transferul.","context":"","source":"Art. 137","unit":1},{"id":"art-138-1","article":"138","articleNumber":138,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Al cui acord este necesar pentru transfer?","options":["consiliului de administrație al unității de învățământ primitoare","numai comitetului de părinți","numai consiliului clasei de proveniență","numai consiliului elevilor"],"answer":0,"term":"consiliului de administrație al unității de învățământ primitoare","quote":"Transferul beneficiarilor primari ai educației se face cu acordul consiliului de administrație al unității de învățământ primitoare și cu avizul consultativ al consiliului de administrație al unității de învățământ de la care se transferă. Consiliul de administrație al unității de învățământ la care se solicită transferul motivează, în scris, refuzul de aprobare a cererii.","context":"","source":"Art. 138","unit":1},{"id":"art-139-1","article":"139","articleNumber":139,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cu câți elevi poate ISJ/ISMB aproba depășirea efectivului maxim la transfer, în situații excepționale?","options":["cel mult 1 beneficiari","cel mult 2 beneficiari","cel mult 3 beneficiari","cel mult 4 beneficiari"],"answer":1,"term":"cel mult 2 beneficiari","quote":"În situații excepționale, bine motivate, în care transferul nu se poate face cu încadrarea în numărul maxim de beneficiari primari ai educației la grupă/formațiunea de studiu, ISJ/ISMB poate aproba depășirea efectivului maxim cu cel mult 2 beneficiari peste efectivul maxim, pe baza justificării din partea consiliului de administrație al unității de învățământ. Pentru situațiile excepționale în care se solicită depășirea cu peste 2 beneficiari primari a numărului maxim de antepreșcolari/preșcolari/elevi la grupă/formațiunea de studiu, aprobarea va fi dată de Ministerul Educației, conform metodologiei în vigoare.","context":"","source":"Art. 139","unit":3},{"id":"art-140-1","article":"140","articleNumber":140,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Ce condiție există la transferul liceal/postliceal cu schimbarea profilului sau specializării?","options":["numai acordul colegilor","numai plata unei taxe","numai vechimea în școală","susținerea și promovarea evaluării prin examene de diferență"],"answer":3,"term":"susținerea și promovarea evaluării prin examene de diferență","quote":"În învățământul liceal sau postliceal, inclusiv în învățământul preuniversitar tehnologic în sistem dual, aprobarea transferurilor la care se schimbă filiera, profilul, domeniul de pregătire, specializarea/calificarea profesională este condiționată de susținerea și promovarea evaluării prin examene de diferență.","context":"","source":"Art. 140","unit":1},{"id":"art-141-1","article":"141","articleNumber":141,"block":1,"fromPoint":1,"toPoint":8,"pointCount":9,"prompt":"Cu ce medie se compară, de regulă, media elevului din clasele X–XII/XIII la transfer?","options":["media directorului","media primului admis","media tuturor părinților","media ultimului promovat"],"answer":3,"term":"media ultimului promovat","quote":"în cadrul învățământului liceal, elevii din clasele a X-a – a XII/XIII-a se pot transfera, de regulă, dacă media lor din ultimul an este cel puțin egală cu media ultimului promovat din clasa la care se solicită transferul. Excepțiile de la această prevedere se aprobă de către consiliul de administrație al unității de învățământ la care se solicită transferul;","context":"Elevii din învățământul liceal și din învățământul postliceal, inclusiv în învățământul preuniversitar tehnologic în sistem dual, se pot transfera, păstrând forma de învățământ, cu respectarea următoarelor condiții:","source":"Art. 141","unit":3},{"id":"art-141-2","article":"141","articleNumber":141,"block":2,"fromPoint":9,"toPoint":9,"pointCount":9,"prompt":"Ce condiție nu se aplică elevilor IX–XII școlarizați în spital care solicită transfer?","options":["condiției de domiciliu în străinătate","condiției de medie","condiției de sponsorizare","condiției de vechime în muncă"],"answer":1,"term":"condiției de medie","quote":"Elevii din clasele IX-XII, școlarizați în forma de școlarizare din spital, pot solicita transferul în timpul anului școlar și în vacanțele școlare, fără îndeplinirea condiției de medie menționate la alin. (1) lit. a)-d) și f). Solicitarea trebuie să fie însoțită de scrisoarea medicală emisă de medicul specialist, care atestă internarea, monitorizarea sau recuperarea elevului în anul școlar respectiv, și de adeverința emisă de școala din spital, care atestă că elevul urmează forma de școlarizare din spital.","context":"","source":"Art. 141","unit":9},{"id":"art-142-1","article":"142","articleNumber":142,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"În ce limite se face transferul de la zi/seral la frecvență redusă?","options":["contribuțiilor financiare ale părinților","efectivelor maxime de elevi la clasă","numărului de furnizori","numărului de sponsori"],"answer":1,"term":"efectivelor maxime de elevi la clasă","quote":"elevii de la învățământul cu frecvență zi/seral se pot transfera la forma de învățământ cu frecvență redusă, în limita efectivelor maxime de elevi la clasă;","context":"Elevii din învățământul liceal și din învățământul postliceal se pot transfera de la o formă de învățământ la alta astfel:","source":"Art. 142","unit":2},{"id":"art-143-1","article":"143","articleNumber":143,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Cine desemnează comisia care elaborează testul pentru transferul la clase intensive/bilingve?","options":["administratorul financiar","directorul unității de învățământ","președintele comitetului de părinți","președintele consiliului elevilor"],"answer":1,"term":"directorul unității de învățământ","quote":"testul de aptitudini și cunoștințe va fi elaborat la nivelul unității de învățământ la care elevul se transferă, de către o comisie desemnată în acest sens de directorul unității de învățământ;","context":"Transferul beneficiarilor primari de la o formațiune de studiu cu predarea unei limbi de circulație internațională în regim normal la o formațiune de studiu cu predare intensivă, respectiv bilingvă a unei limbi de circulație internațională se realizează astfel:","source":"Art. 143","unit":3},{"id":"art-144-1","article":"144","articleNumber":144,"block":1,"fromPoint":1,"toPoint":8,"pointCount":12,"prompt":"Când se efectuează transferul de la frecvență redusă la zi/seral?","options":["numai după terminarea liceului","numai în perioada vacanței de vară","numai în ultima zi din decembrie","oricând, fără condiții"],"answer":1,"term":"numai în perioada vacanței de vară","quote":"de la învățământul cu frecvență redusă la cel cu frecvență zi/seral, numai în perioada vacanței de vară.","context":"Transferurile în care se schimbă forma de învățământ se efectuează în următoarele perioade:","source":"Art. 144","unit":3},{"id":"art-144-2","article":"144","articleNumber":144,"block":2,"fromPoint":9,"toPoint":12,"pointCount":12,"prompt":"Cine aprobă transferul în alte situații excepționale, pe acte justificative?","options":["comitetului de părinți","consiliului clasei","consiliului de administrație al inspectoratului școlar","consiliului elevilor"],"answer":2,"term":"consiliului de administrație al inspectoratului școlar","quote":"în alte situații excepționale, pe baza documentelor justificative, cu aprobarea consiliului de administrație al inspectoratului școlar.","context":"Transferul beneficiarilor primari în timpul cursurilor școlare se poate efectua, în mod excepțional, cu respectarea prevederilor prezentului regulament, în următoarele situații:","source":"Art. 144","unit":12},{"id":"art-145-1","article":"145","articleNumber":145,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Cine aprobă transferul gemenilor în aceeași clasă, la cerere?","options":["comitetului de părinți","consiliului clasei","consiliului de administrație al unității de învățământ","consiliului elevilor"],"answer":2,"term":"consiliului de administrație al unității de învățământ","quote":"Gemenii, tripleții etc. se pot transfera în clasa celui cu media mai mare sau invers, la cererea părintelui/reprezentantului legal sau la cererea beneficiarilor primari, dacă aceștia sunt majori, cu aprobarea consiliului de administrație al unității de învățământ","context":"","source":"Art. 145","unit":1},{"id":"art-146-1","article":"146","articleNumber":146,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Când se pot transfera în alte școli elevii declarați inapți pentru cariera militară?","options":["în timpul anului școlar","numai după bacalaureat","numai după doi ani","numai după vârsta de 25 de ani"],"answer":0,"term":"în timpul anului școlar","quote":"Elevii din unitățile de învățământ liceal din sistemul de apărare, ordine publică și securitate națională declarați \"Inapt\"/\"Necorespunzător\" pentru cariera militară, cei care comit abateri grave sau cei care nu doresc să mai urmeze cursurile respectivelor unități de învățământ se pot transfera în alte unități de învățământ, în timpul anului școlar. Transferul se efectuează cu respectarea prevederilor prezentului regulament, precum și a reglementărilor specifice ministerelor de care aparțin unitățile de învățământ unde este înmatriculat elevul.","context":"","source":"Art. 146","unit":1},{"id":"art-147-1","article":"147","articleNumber":147,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Unde se pot transfera elevii din învățământul particular sau confesional, în condițiile regulamentului?","options":["exclusiv în școli militare","numai în școli din străinătate","numai în universități","unități de învățământ de stat"],"answer":3,"term":"unități de învățământ de stat","quote":"Elevii din învățământul preuniversitar particular sau confesional se pot transfera la unități de învățământ de stat, în condițiile prezentului regulament.","context":"","source":"Art. 147","unit":1},{"id":"art-148-1","article":"148","articleNumber":148,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Ce reorientare poate fi propusă pentru copiii cu CES, în funcție de evoluție?","options":["dinspre învățământul special/special integrat spre învățământul de masă și invers","numai din liceu spre universitate","numai din școala de masă spre excludere","numai din școală spre muncă"],"answer":0,"term":"dinspre învățământul special/special integrat spre învățământul de masă și invers","quote":"Pentru copiii/tinerii cu cerințe educaționale speciale, în funcție de evoluția acestora, se pot face propuneri de reorientare dinspre învățământul special/special integrat spre învățământul de masă și invers.","context":"","source":"Art. 148","unit":1},{"id":"art-149-1","article":"149","articleNumber":149,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"De ce prioritate la transfer beneficiază elevele gravide și elevii părinți pentru înscrierea copilului?","options":["exclusiv nivelul liceal militar","exclusiv nivelul postliceal","exclusiv nivelul universitar","nivelul antepreșcolar"],"answer":3,"term":"nivelul antepreșcolar","quote":"prioritate la transfer în cadrul unei unități de învățământ care are în structură nivelul antepreșcolar pentru înscrierea copilului, în cazul transferului între filiere, profiluri, specializări în învățământul liceal, conform prevederilor legale.","context":"Elevele gravide și elevii părinți beneficiază cu prioritate de următoarele facilități:","source":"Art. 149","unit":2},{"id":"art-150-1","article":"150","articleNumber":150,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"În ce termen solicită școala primitoare situația școlară după aprobarea transferului?","options":["4 zile lucrătoare","5 zile lucrătoare","6 zile lucrătoare","7 zile lucrătoare"],"answer":1,"term":"5 zile lucrătoare","quote":"După aprobarea transferului, unitatea de învățământ primitoare este obligată să solicite situația școlară a elevului în termen de 5 zile lucrătoare. Unitatea de învățământ de la care se transferă elevul este obligată să trimită la unitatea de învățământ primitoare situația școlară a celui transferat, în termen de 10 zile lucrătoare de la primirea solicitării. Până la primirea situației școlare de către unitatea de învățământ la care s-a transferat, elevul transferat participă la cursuri în calitate de audient.","context":"","source":"Art. 150","unit":1},{"id":"art-151-1","article":"151","articleNumber":151,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Ce metodă sprijină coordonarea monitorizării elevelor gravide și elevilor părinți?","options":["exmatriculării automate","managementului de caz","selecției după venituri","suspendării definitive a studiilor"],"answer":1,"term":"managementului de caz","quote":"În cadrul managementului de caz, mecanismul de coordonare presupune implicarea specialiștilor care pot contribui la identificarea nevoilor elevelor gravide și ale beneficiarilor primari părinți, la planificarea, implementarea și monitorizarea integrată a intervenției din perspectiva realizării scopului prevăzut la alin. (1).","context":"","source":"Art. 151","unit":3},{"id":"art-152-1","article":"152","articleNumber":152,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Ce calitate au părinții în relația cu școala?","options":["angajatori ai profesorilor","inspectori școlari","ordonatori de credite","parteneri educaționali principali"],"answer":3,"term":"parteneri educaționali principali","quote":"Părinții/reprezentanții legali ai beneficiarului primar sunt parteneri educaționali principali ai unităților de învățământ.","context":"","source":"Art. 152","unit":1},{"id":"art-153-1","article":"153","articleNumber":153,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Despre cine poate obține părintele informații individuale?","options":["despre dosarele tuturor profesorilor","despre toate familiile clasei","despre toți elevii școlii","numai la situația propriului copil"],"answer":3,"term":"numai la situația propriului copil","quote":"Părintele/reprezentantul legal al beneficiarului primar are dreptul să dobândească informații referitoare numai la situația propriului copil.","context":"","source":"Art. 153","unit":2},{"id":"art-154-1","article":"154","articleNumber":154,"block":1,"fromPoint":1,"toPoint":7,"pointCount":7,"prompt":"Cine stabilește procedura de acces a părinților în școală?","options":["consiliul clasei","Consiliul de administrație","consiliul elevilor","consiliul profesoral"],"answer":1,"term":"Consiliul de administrație","quote":"Consiliul de administrație are obligația stabilirii procedurii de acces al părinților/ reprezentanților legali în unitățile de învățământ.","context":"Părintele/reprezentantul legal al beneficiarului primar are acces în incinta unității de învățământ în concordanță cu procedura de acces, dacă:","source":"Art. 154","unit":7},{"id":"art-155-1","article":"155","articleNumber":155,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"În ce tip de asociații au dreptul să se constituie părinții?","options":["asociații cu personalitate juridică","autorități de control fiscal","inspectorate școlare","instanțe judecătorești"],"answer":0,"term":"asociații cu personalitate juridică","quote":"Părinții/reprezentanții legali au dreptul să se constituie în asociații cu personalitate juridică, conform legislației în vigoare.","context":"","source":"Art. 155","unit":1},{"id":"art-156-1","article":"156","articleNumber":156,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Care este prima cale de rezolvare a conflictelor sesizate de părinte?","options":["discuții amiabile","exmatricularea imediată a copilului","publicarea datelor tuturor elevilor","sancționarea automată a clasei"],"answer":0,"term":"discuții amiabile","quote":"Rezolvarea situațiilor conflictuale sesizate de părintele/reprezentantul legal al beneficiarului primar în care este implicat propriul copil se face prin discuții amiabile cu salariatul unității de învățământ implicat, educatorul/educatoarea/ profesorul pentru educație timpurie/învățătorul/institutorul/profesorul pentru învățământ preșcolar/primar/profesorul diriginte;","context":"","source":"Art. 156","unit":1},{"id":"art-157-1","article":"157","articleNumber":157,"block":1,"fromPoint":1,"toPoint":8,"pointCount":16,"prompt":"Cât de des trebuie părintele să ia legătura cu dirigintele/învățătorul?","options":["minimum o dată pe an","minimum o dată pe lună","numai la absolvire","numai la schimbarea directorului"],"answer":1,"term":"minimum o dată pe lună","quote":"Părintele/reprezentantul legal are obligația ca, minimum o dată pe lună, să ia legătura cu profesorul pentru învățământul antepreșcolar/preșcolar/învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte pentru a cunoaște evoluția copilului/elevului, prin mijloace stabilite de comun acord. Prezența părintelui sau a reprezentantului legal va fi consemnată în caietul educatorului/educatoarei/profesorului pentru educație timpurie/ învățătorului/institutorului/profesorului pentru învățământ preșcolar/primar/profesorului diriginte, cu nume, dată și semnătură.","context":"","source":"Art. 157","unit":4},{"id":"art-157-2","article":"157","articleNumber":157,"block":2,"fromPoint":9,"toPoint":16,"pointCount":16,"prompt":"Pe ce bază se returnează sumele pentru hrană plătite anticipat, la retragerea copilului?","options":["numai cererii unui furnizor","numai unei promisiuni verbale","numai votului colegilor","unei cereri scrise"],"answer":3,"term":"unei cereri scrise","quote":"În situația retragerii copilului de la unitatea de educație timpurie cu program prelungit, părintele beneficiază de returnarea sumelor plătite anticipat pentru asigurarea hranei, în baza depunerii unei cereri scrise.","context":"","source":"Art. 157","unit":16},{"id":"art-158-1","article":"158","articleNumber":158,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Față de cine este interzisă agresarea fizică, psihică sau verbală în școală?","options":["copiilor/ beneficiarilor primari și a personalului","numai furnizorilor","numai membrilor comitetului de părinți","numai persoanelor din afara școlii"],"answer":0,"term":"copiilor/ beneficiarilor primari și a personalului","quote":"Se interzice oricăror persoane agresarea fizică, psihică, verbală etc. a copiilor/ beneficiarilor primari și a personalului unității de învățământ.","context":"","source":"Art. 158","unit":1},{"id":"art-159-1","article":"159","articleNumber":159,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Cum este respectarea ROFUIP și a regulamentului școlii pentru părinți?","options":["condiționată de o donație","exclusiv voluntară","facultativă","obligatorie"],"answer":3,"term":"obligatorie","quote":"Respectarea prevederilor prezentului regulament și a regulamentului de organizare și funcționare a unității de învățământ este obligatorie pentru părinții/reprezentanții legali ai beneficiarilor primari.","context":"","source":"Art. 159","unit":1},{"id":"art-160-1","article":"160","articleNumber":160,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cum se discută situația individuală a unui elev cu părintele?","options":["individual, numai în prezența părintelui/ reprezentantului legal","numai în prezența furnizorilor","numai pe rețelele sociale","public, în prezența tuturor părinților"],"answer":0,"term":"individual, numai în prezența părintelui/ reprezentantului legal","quote":"În adunarea generală a părinților/reprezentanților legali se discută problemele generale ale colectivului de beneficiari primari, și nu situația concretă a unui beneficiar primar. Situația unui beneficiar primar se discută individual, numai în prezența părintelui/ reprezentantului legal al beneficiarului primar respectiv.","context":"","source":"Art. 160","unit":3},{"id":"art-161-1","article":"161","articleNumber":161,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Care este cvorumul adunării generale a părinților clasei?","options":["jumătate plus unu din totalul părinților","o treime din totalul părinților","un sfert din totalul părinților","un singur părinte"],"answer":0,"term":"jumătate plus unu din totalul părinților","quote":"Adunarea generală a părinților/reprezentanților legali se convoacă ori de câte ori este nevoie, este valabil întrunită în prezența a jumătate plus unu din totalul părinților/ reprezentanților legali ai copiilor/beneficiarilor primari din grupa/clasa respectivă și adoptă hotărâri cu votul a jumătate plus unu din cei prezenți.","context":"","source":"Art. 161","unit":2},{"id":"art-162-1","article":"162","articleNumber":162,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"În ce termen se convoacă adunarea pentru alegerea comitetului de părinți?","options":["primele 10 zile calendaristice","primele 15 zile calendaristice","primele 20 zile calendaristice","primele 25 zile calendaristice"],"answer":1,"term":"primele 15 zile calendaristice","quote":"Convocarea adunării generale pentru alegerea comitetului de părinți are loc în primele 15 zile calendaristice de la începerea cursurilor anului școlar.","context":"","source":"Art. 162","unit":3},{"id":"art-163-1","article":"163","articleNumber":163,"block":1,"fromPoint":1,"toPoint":7,"pointCount":7,"prompt":"Ale cui decizii le pune în practică comitetul de părinți?","options":["adunarea generală a părinților","numai comisia de inventariere","numai consiliul elevilor","numai operatorii economici"],"answer":0,"term":"adunarea generală a părinților","quote":"pune în practică deciziile luate de către adunarea generală a părinților/reprezentanților legali beneficiarilor primari clasei. Deciziile se iau cu majoritatea simplă a voturilor părinților/reprezentanților legali;","context":"Comitetul de părinți pe grupă/clasă are următoarele atribuții:","source":"Art. 163","unit":1},{"id":"art-164-1","article":"164","articleNumber":164,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce interese reprezintă președintele comitetului clasei?","options":["interesele furnizorilor","interesele operatorilor de jocuri de noroc","interesele partidelor politice","interesele părinților"],"answer":3,"term":"interesele părinților","quote":"Președintele comitetului de părinți pe grupă/clasă reprezintă interesele părinților/ reprezentanților legali în relațiile cu consiliul reprezentativ al părinților/reprezentanților legali și asociația de părinți și, prin acestea, în relație cu conducerea unității de învățământ și alte foruri, organisme și organizații.","context":"","source":"Art. 164","unit":1},{"id":"art-165-1","article":"165","articleNumber":165,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Ce constituie implicarea elevilor sau personalului în strângerea/gestionarea fondurilor părinților?","options":["abatere disciplinară","condiție de promovare","criteriu de admitere","obligație de serviciu"],"answer":0,"term":"abatere disciplinară","quote":"Este interzisă și constituie abatere disciplinară implicarea copiilor/beneficiarilor primari sau a personalului din unitatea de învățământ în strângerea și/sau gestionarea fondurilor.","context":"","source":"Art. 165","unit":3},{"id":"art-166-1","article":"166","articleNumber":166,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Din cine este compus consiliul reprezentativ al părinților?","options":["numai membrii consiliului local","președinții comitetelor de părinți","toți elevii școlii","toți furnizorii școlii"],"answer":1,"term":"președinții comitetelor de părinți","quote":"Consiliul reprezentativ al părinților/reprezentanților legali din unitatea de învățământ este compus din președinții comitetelor de părinți.","context":"","source":"Art. 166","unit":2},{"id":"art-167-1","article":"167","articleNumber":167,"block":1,"fromPoint":1,"toPoint":7,"pointCount":7,"prompt":"Câți vicepreședinți are consiliul reprezentativ al părinților?","options":["1 vicepreședinți","2 vicepreședinți","3 vicepreședinți","4 vicepreședinți"],"answer":1,"term":"2 vicepreședinți","quote":"Consiliul reprezentativ al părinților/reprezentanților legali își desemnează președintele și 2 vicepreședinți ale căror atribuții se stabilesc imediat după desemnare, de comun acord între cei 3, și se consemnează în procesul-verbal al ședinței.","context":"","source":"Art. 167","unit":1},{"id":"art-168-1","article":"168","articleNumber":168,"block":1,"fromPoint":1,"toPoint":8,"pointCount":14,"prompt":"Ce poate propune consiliul reprezentativ al părinților pentru CDEOȘ?","options":["candidați la alegeri","discipline și domenii","funcții de inspector","sancțiuni fiscale"],"answer":1,"term":"discipline și domenii","quote":"propune unităților de învățământ discipline și domenii care să se studieze prin curriculumul la decizia elevului din oferta școlii, inclusiv din oferta națională;","context":"Consiliul reprezentativ al părinților/reprezentanților legali are următoarele atribuții:","source":"Art. 168","unit":1},{"id":"art-168-2","article":"168","articleNumber":168,"block":2,"fromPoint":9,"toPoint":14,"pointCount":14,"prompt":"Ce sprijină consiliul părinților în privința protecției elevilor?","options":["asigurarea sănătății și securității beneficiarilor primari","eliminarea disciplinelor obligatorii","înlocuirea tuturor profesorilor","restrângerea accesului la cursuri"],"answer":0,"term":"asigurarea sănătății și securității beneficiarilor primari","quote":"sprijină conducerea unității de învățământ în asigurarea sănătății și securității beneficiarilor primari;","context":"Consiliul reprezentativ al părinților/reprezentanților legali are următoarele atribuții:","source":"Art. 168","unit":12},{"id":"art-169-1","article":"169","articleNumber":169,"block":1,"fromPoint":1,"toPoint":7,"pointCount":7,"prompt":"Pentru ce pot fi atrase resurse prin demersurile consiliului părinților?","options":["acordarea de avantaje personale","finanțarea campaniilor electorale","modernizarea și întreținerea patrimoniului","plata cotizațiilor politice"],"answer":2,"term":"modernizarea și întreținerea patrimoniului","quote":"modernizarea și întreținerea patrimoniului unității de învățământ, a bazei materiale și sportive;","context":"Consiliul reprezentativ al părinților/reprezentanților legali din unitatea de învățământ poate face demersuri privind atragerea de resurse financiare, care vor fi gestionate de către unitatea de învățământ, constând în contribuții, donații, sponsorizări etc. din partea unor persoane fizice sau juridice din țară și din străinătate care vor fi utilizate pentru:","source":"Art. 169","unit":2},{"id":"art-170-1","article":"170","articleNumber":170,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Când se încheie contractul educațional?","options":["în momentul înscrierii","numai după doi ani","numai după primul examen","numai la absolvire"],"answer":0,"term":"în momentul înscrierii","quote":"Unitățile de învățământ încheie cu părinții sau reprezentanții legali/elevii majori, în momentul înscrierii beneficiarilor primari în registrul unic matricol, un contract educațional, în care sunt înscrise drepturile și obligațiile reciproce ale părților, conform prevederilor legale în vigoare. Contractul educațional are caracterul juridic al unui contract de adeziune.","context":"","source":"Art. 170","unit":1},{"id":"art-171-1","article":"171","articleNumber":171,"block":1,"fromPoint":1,"toPoint":5,"pointCount":5,"prompt":"Cât timp este valabil contractul educațional?","options":["numai o lună","numai o săptămână","numai până la prima vacanță","pe toată perioada de școlarizare"],"answer":3,"term":"pe toată perioada de școlarizare","quote":"Contractul educațional este valabil pe toată perioada de școlarizare în cadrul unității de învățământ.","context":"","source":"Art. 171","unit":1},{"id":"art-172-1","article":"172","articleNumber":172,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Ce amendă sancționează refuzul directorului de a semna contractul educațional?","options":["de la 1.000 de lei la 5.000 de lei","de la 10.000 de lei la 20.000 de lei","de la 100 de lei la 500 de lei","de la 500 de lei la 900 de lei"],"answer":0,"term":"de la 1.000 de lei la 5.000 de lei","quote":"refuzul semnării contractului educațional de către directorul unității de învățământ, se sancționează cu amendă de la 1.000 de lei la 5.000 de lei, sau cu prestarea unei activități în folosul comunității.","context":"Următoarele fapte constituie contravenții, în măsura în care nu constituie infracțiuni, și se sancționează după cum urmează:","source":"Art. 172","unit":2},{"id":"art-173-1","article":"173","articleNumber":173,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce cuprinde contractul educațional din școlile de apărare și ordine publică?","options":["drepturile și obligațiile reciproce ale părților","numai calendarul vacanțelor","numai obligațiile elevului","numai obligațiile părinților"],"answer":0,"term":"drepturile și obligațiile reciproce ale părților","quote":"În unitățile de învățământ preuniversitar din sistemul de apărare, ordine publică și securitate națională, elevii și, în cazul celor minori, împreună cu părinții sau reprezentanții legali ai acestora, încheie un contract educațional, al cărui conținut se stabilește prin ordin al conducătorului ministerului de resort, în care sunt înscrise drepturile și obligațiile reciproce ale părților.","context":"","source":"Art. 173","unit":1},{"id":"art-174-1","article":"174","articleNumber":174,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Cu cine colaborează autoritățile locale pentru obiectivele școlii?","options":["consiliul de administrație și cu directorul","numai comisia electorală","numai furnizorii comerciali","numai reprezentanții altor localități"],"answer":0,"term":"consiliul de administrație și cu directorul","quote":"Autoritățile administrației publice locale, precum și reprezentanți ai comunității locale colaborează cu consiliul de administrație și cu directorul, în vederea atingerii obiectivelor unității de învățământ.","context":"","source":"Art. 174","unit":1},{"id":"art-175-1","article":"175","articleNumber":175,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"În interesul cui se realizează parteneriatele educaționale?","options":["beneficiarilor direcți ai educației","exclusiv furnizorilor comerciali","exclusiv partidelor politice","exclusiv sponsorilor"],"answer":0,"term":"beneficiarilor direcți ai educației","quote":"Unitățile de învățământ pot realiza parteneriate cu asociații, fundații, instituții de educație și cultură, organisme economice/agenți economici și organizații guvernamentale și nonguvernamentale sau alte tipuri de organizații, în interesul beneficiarilor direcți ai educației.","context":"","source":"Art. 175","unit":1},{"id":"art-176-1","article":"176","articleNumber":176,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce centre pot organiza școlile la nivel local, singure sau în parteneriat?","options":["centre comunitare de învățare permanentă","centre de control vamal","centre de jocuri de noroc","centre de propagandă electorală"],"answer":0,"term":"centre comunitare de învățare permanentă","quote":"Unitățile de învățământ, de sine stătător sau în parteneriat cu autoritățile administrației publice locale și cu alte instituții și organisme publice și private: case de cultură, furnizori de formare continuă, parteneri sociali, organizații nonguvernamentale și altele asemenea, pot organiza la nivel local centre comunitare de învățare permanentă, pe baza unor oferte de servicii educaționale adaptate nevoilor specifice diferitelor grupuri-țintă interesate.","context":"","source":"Art. 176","unit":1},{"id":"art-177-1","article":"177","articleNumber":177,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"În baza cărei hotărâri poate școala iniția programe remediale și „Școala după școală”?","options":["hotărârii comitetului de părinți","hotărârii consiliului clasei","hotărârii consiliului de administrație","hotărârii consiliului elevilor"],"answer":2,"term":"hotărârii consiliului de administrație","quote":"Unitățile de învățământ, în conformitate cu legislația în vigoare și cu prevederile prezentului regulament, pot iniția, în parteneriat cu autoritățile administrației publice locale și cu organizațiile de părinți, în baza hotărârii consiliului de administrație, activități educative, recreative, de timp liber, pentru consolidarea competențelor dobândite sau pentru accelerarea învățării, precum și activități de recuperare cu elevii, prin programele \"Învățare remedială\" sau \"Școala după școală\".","context":"","source":"Art. 177","unit":1},{"id":"art-178-1","article":"178","articleNumber":178,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Cine asigură condițiile și fondurile pentru sănătate și securitate în perimetrul școlii?","options":["autoritățile administrației publice locale","Comitetul clasei","Consiliul elevilor","Furnizorii de manuale"],"answer":0,"term":"autoritățile administrației publice locale","quote":"Autoritățile administrației publice locale asigură condițiile și fondurile necesare pentru implementarea și respectarea normelor de sănătate și securitate în muncă și pentru asigurarea securității copiilor/beneficiarilor primari și a personalului în perimetrul unității de învățământ.","context":"","source":"Art. 178","unit":3},{"id":"art-179-1","article":"179","articleNumber":179,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"Ce trebuie să precizeze protocolul cu operatorii economici?","options":["numai calendarul vacanțelor","numai preferințele elevilor","numai veniturile familiilor","responsabilitățile părților"],"answer":3,"term":"responsabilitățile părților","quote":"Protocolul conține prevederi clare cu privire la responsabilitățile părților, referitoare la asigurarea securității beneficiarilor primari și a personalului unității de învățământ, respectarea normelor de sănătate și securitate în muncă, asigurarea transportului la și de la operatorul economic, durata activităților, drepturile și îndatoririle beneficiarilor primari, utilizarea fondurilor realizate, cu respectarea prevederilor legale în vigoare. De asemenea, unitățile de învățământ profesional și tehnic încheie parteneriate și protocoale de colaborare cu operatorii economici, în vederea derulării orelor de instruire practică. Unitățile de învățământ preuniversitar cu personalitate juridică ce școlarizează în învățământ profesional și tehnic dual încheie contracte de parteneriat cu unul sau mai mulți operatori economici sau cu o asociație/un consorțiu de operatori economici și cu unitatea administrativ-teritorială pe raza căreia se află unitatea școlară. Pentru pregătirea profesională, fiecare elev major, respectiv părintele sau reprezentantul legal al elevului minor din aceste unități de învățământ prevăzute încheie un contract de pregătire practică individual cu operatorul economic și unitatea de învățământ. Contractele prevăzute se reglementează prin metodologii specifice aprobate prin ordin al ministrului educației.","context":"","source":"Art. 179","unit":2},{"id":"art-180-1","article":"180","articleNumber":180,"block":1,"fromPoint":1,"toPoint":6,"pointCount":6,"prompt":"Ce responsabilitate trebuie precizată în protocol pentru activitățile din afara școlii?","options":["alegerii profesorilor prin votul elevilor","asigurării securității copiilor/beneficiarilor primari","numirii inspectorului școlar","stabilirii impozitelor locale"],"answer":1,"term":"asigurării securității copiilor/beneficiarilor primari","quote":"În cazul derulării unor activități în afara perimetrului unității de învățământ, în protocol se va specifica concret cărei părți îi revine responsabilitatea asigurării securității copiilor/beneficiarilor primari.","context":"","source":"Art. 180","unit":3},{"id":"art-181-1","article":"181","articleNumber":181,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce fonduri sunt interzise pentru examenele/evaluările naționale?","options":["fonduri de investiții aprobate","fonduri de protocol","fonduri pentru burse legale","fonduri pentru manuale gratuite"],"answer":1,"term":"fonduri de protocol","quote":"Se interzice constituirea de fonduri de protocol sau a oricărui alt fond destinat derulării examenelor/evaluărilor naționale.","context":"","source":"Art. 181","unit":1},{"id":"art-182-1","article":"182","articleNumber":182,"block":1,"fromPoint":1,"toPoint":7,"pointCount":7,"prompt":"Comercializarea și oferirea gratuită a energizantelor în școală sunt:","options":["interzise","obligatorii","permise fără condiții","recomandate"],"answer":0,"term":"interzise","quote":"În unitățile de învățământ comercializarea sau oferirea cu titlu gratuit, inclusiv prin automate comerciale, a băuturilor energizante sunt interzise, conform prevederilor Legii nr. 61/1991 pentru sancționarea faptelor de încălcare a unor norme de conviețuire socială, a ordinii și liniștii publice, republicată, cu modificările și completările ulterioare.","context":"","source":"Art. 182","unit":5},{"id":"art-183-1","article":"183","articleNumber":183,"block":1,"fromPoint":1,"toPoint":4,"pointCount":4,"prompt":"Ce este interzis în raport cu accesul la educație?","options":["activitățile de prevenire a abandonului","consilierea școlară","măsurile care pot limita accesul la educație","sprijinul pentru elevii vulnerabili"],"answer":2,"term":"măsurile care pot limita accesul la educație","quote":"În unitățile de învățământ sunt interzise măsurile care pot limita accesul la educație al beneficiarilor primari, cum ar fi, de exemplu, efectuarea de către aceștia a serviciului pe școală, interzicerea participării la cursuri sau sancționarea beneficiarilor primari care nu poartă uniforma unității de învățământ sau altele asemenea.","context":"","source":"Art. 183","unit":2},{"id":"art-184-1","article":"184","articleNumber":184,"block":1,"fromPoint":1,"toPoint":3,"pointCount":3,"prompt":"Despre existența cărui act pentru clădirile școlii trebuie informat publicul?","options":["autorizației de securitate la incendiu","dosarele medicale ale elevilor","parolele cataloagelor electronice","veniturile personale ale părinților"],"answer":0,"term":"autorizației de securitate la incendiu","quote":"Unitățile de învățământ preuniversitar și unitățile de educație extrașcolară au obligația publicării pe site-urile proprii și prin orice altă formă de comunicare publică existentă la nivelul unității școlare, a autorizației de securitate la incendiu pentru fiecare clădire de învățământ, precum și a autorizației sanitare de funcționare.","context":"","source":"Art. 184","unit":1},{"id":"art-185-1","article":"185","articleNumber":185,"block":1,"fromPoint":1,"toPoint":1,"pointCount":1,"prompt":"Ce include învățământul profesional și tehnic, până la reorganizarea prevăzută?","options":["exclusiv învățământul preșcolar","exclusiv învățământul primar","exclusiv învățământul universitar","învățământul liceal tehnologic, învățământul postliceal și, respectiv învățământul profesional"],"answer":3,"term":"învățământul liceal tehnologic, învățământul postliceal și, respectiv învățământul profesional","quote":"În sensul prezentului regulament, prin învățământ profesional și tehnic se înțelege învățământul liceal tehnologic, învățământul postliceal și, respectiv învățământul profesional, până la reorganizarea acestuia în cadrul învățământului liceal tehnologic.","context":"","source":"Art. 185","unit":1},{"id":"art-186-1","article":"186","articleNumber":186,"block":1,"fromPoint":1,"toPoint":2,"pointCount":2,"prompt":"În ce termen de la intrarea în vigoare se aprobă regulamentele proprii?","options":["40 de zile","45 de zile","50 de zile","55 de zile"],"answer":1,"term":"45 de zile","quote":"În termen de 45 de zile de la data intrării în vigoare a prezentului regulament, consiliile de administrație ale unităților de învățământ sunt obligate ca, pe baza acestuia și a dispozițiilor legale în vigoare, să aprobe propriile regulamente de organizare și funcționare.","context":"","source":"Art. 186","unit":1}],"modules":[{"id":1,"title":"Dispoziții generale","startArticle":1,"endArticle":4,"articles":"art. 1–4"},{"id":2,"title":"Organizarea școlii","startArticle":5,"endArticle":15,"articles":"art. 5–15"},{"id":3,"title":"Managementul școlii","startArticle":16,"endArticle":37,"articles":"art. 16–37"},{"id":4,"title":"Personalul școlii","startArticle":38,"endArticle":53,"articles":"art. 38–53"},{"id":5,"title":"Consilii, diriginți și comisii","startArticle":54,"endArticle":72,"articles":"art. 54–72"},{"id":6,"title":"Compartimente și patrimoniu","startArticle":73,"endArticle":87,"articles":"art. 73–87"},{"id":7,"title":"Elevii, evaluarea și transferul","startArticle":88,"endArticle":151,"articles":"art. 88–151"},{"id":8,"title":"Părinții și parteneriatele","startArticle":152,"endArticle":180,"articles":"art. 152–180"},{"id":9,"title":"Dispoziții finale","startArticle":181,"endArticle":186,"articles":"art. 181–186"}],"sourceVersion":"textul ROFUIP din materialul integral al platformei","articles":[{"article":"1","articleNumber":1,"legalText":"(1) Regulamentul-cadru de organizare și funcționare a unităților de învățământ preuniversitar, denumit în continuare regulament, reglementează organizarea și funcționarea unităților de învățământ preuniversitar, denumite în continuare unități de învățământ, în cadrul sistemului de învățământ din România, în conformitate cu prevederile legale în vigoare, și se aplică în toate unitățile de învățământ.\n(2) Unitatea de învățământ se organizează și funcționează în conformitate cu prevederile legislației în vigoare, ale prezentului regulament, ale propriului regulament de organizare și funcționare și ale regulamentului de ordine interioară.\n(3) În baza legislației în vigoare și a prezentului regulament, Ministerul Apărării Naționale, Ministerul Afacerilor Interne, Ministerul Justiției și alte instituții cu atribuții în domeniile apărării, informațiilor, ordinii publice și securității emit reglementări specifice privind organizarea și funcționarea unităților de învățământ liceal și postliceal din domeniul respectiv.\n(4) În unitățile de învățământ-pilot și de aplicație se respectă prevederile regulamentelor specifice de organizare și funcționare a unităților de învățământ-pilot și de aplicație.\n(5) Pentru unitățile de învățământ alternativ, de învățământ liceal vocațional teologic, de învățământ liceal vocațional pedagogic, de învățământ de artă și, respectiv, de învățământ sportiv integrat se aplică în mod corespunzător și prevederile regulamentelor specifice de organizare și funcționare, aprobate prin ordin al ministrului educației."},{"article":"2","articleNumber":2,"legalText":"(1) În baza prezentului regulament, a actelor normative și/sau administrative cu caracter normativ care reglementează drepturile și obligațiile beneficiarilor primari și secundari ai educației și ale personalului din unitățile de învățământ, precum și a contractelor colective de muncă aplicabile, unitățile de învățământ își elaborează propriul regulament de organizare și funcționare.\n(2) Regulamentul de organizare și funcționare a unității de învățământ conține reglementări cu caracter general, în funcție de tipul acesteia, precum și reglementări specifice fiecărei unități de învățământ, în conformitate cu prevederile legale în vigoare.\n(3) Proiectul regulamentului de organizare și funcționare a unității de învățământ se elaborează de către un colectiv de lucru, coordonat de un cadru didactic, membru al Consiliului de Administrație, numit de către directorul unității de învățământ. Din colectivul de lucru, numit prin hotărâre a consiliului de administrație, fac parte și reprezentanți ai organizațiilor sindicale afiliate federațiilor sindicale reprezentative la nivel de sector de negociere colectivă învățământ preuniversitar care au membri în unitatea de învățământ, ai părinților/reprezentanților legali și ai beneficiarilor primari, desemnați de către consiliul reprezentativ al părinților/reprezentanților legali și asociația părinților/reprezentanților legali, acolo unde există, respectiv de consiliul școlar al elevilor.\n(4) Proiectul regulamentului de organizare și funcționare a unității de învățământ, precum și modificările ulterioare ale acestuia se supun spre dezbatere în consiliul reprezentativ al părinților/reprezentanților legali și asociației părinților/reprezentanților legali, acolo unde există, în consiliul școlar al elevilor și în consiliul profesoral, la care participă cu drept de vot și personalul didactic auxiliar și administrativ.\n(5) Regulamentul de organizare și funcționare a unității de învățământ, precum și modificările ulterioare ale acestuia se aprobă, prin hotărâre, de către consiliul de administrație.\n(6) După aprobare, regulamentul de organizare și funcționare a unității de învățământ se înregistrează la secretariatul unității. Pentru aducerea la cunoștința personalului unității de învățământ, a părinților/reprezentanților legali și a beneficiarilor primari, regulamentul de organizare și funcționare a unității de învățământ se afișează pe site-ul unității de învățământ și prin orice altă formă de comunicare publică existentă la nivelul unității de învățământ.\n(7) Educatorii/educatoarele/profesorii de educație timpurie/învățătorii/institutorii/profesorii pentru învățământul preșcolar/primar/profesorii diriginți au obligația de a prezenta regulamentul beneficiarilor primari și părinților/reprezentanților legali, la începutul fiecărui an școlar și ori de câte ori există o revizuire a acestuia.\n(8) Regulamentul de organizare și funcționare a unității de învățământ poate fi revizuit anual sau ori de câte ori este nevoie.\n(9) Respectarea prevederilor regulamentului de organizare și funcționare a unității de învățământ de către personalul didactic, didactic auxiliar, administrativ, elevi și părinți/reprezentanți legali este obligatorie. Nerespectarea regulamentului de organizare și funcționare a unității de învățământ constituie abatere și se sancționează conform prevederilor legale.\n(10) Regulamentul de ordine interioară al unității de învățământ conține dispozițiile obligatorii prevăzute la art. 65 alin. (4) din Legea învățământului preuniversitar nr 198/2023, cu modificările și completările ulterioare, și cele prevăzute la art. 242 din Legea nr. 53/2003 – Codul muncii, republicată, cu modificările și completările ulterioare, și în contractele colective de muncă aplicabile.\n(11) Regulamentul de ordine interioară se aprobă prin hotărâre a consiliului de administrație, după consultarea consiliului profesoral, a consiliului școlar al beneficiarilor primari, a consiliului reprezentativ al părinților/reprezentanților legali și asociației de părinți, acolo unde există, a reprezentanților organizațiilor sindicale care au membri în unitatea de învățământ, afiliate la federațiile sindicale reprezentative la nivel de sector de activitate negociere colectivă învățământ preuniversitar și se aduce la cunoștință prin afișare pe site sau punerea la dispoziția autorităților prevăzute la art. 63 alin. (1) din Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare.\n(12) Regulamentul de ordine interioară se aduce la cunoștința publicului, prin intermediul site-urilor proprii, într-o secțiune specială, și prin orice altă formă de comunicare publică existentă la nivelul unității de învățământ."},{"article":"3","articleNumber":3,"legalText":"(1) Unitățile de învățământ se organizează și funcționează pe baza principiilor stabilite în conformitate cu Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare.\n(2) Conducerile unităților de învățământ își fundamentează deciziile pe dialog și consultare, promovând participarea părinților/reprezentanților legali la viața școlii, respectând dreptul la opinie al elevului și asigurând transparența deciziilor și a rezultatelor, printr-o comunicare periodică, adecvată a acestora, în conformitate cu Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare."},{"article":"4","articleNumber":4,"legalText":"Unitățile de învățământ se organizează și funcționează independent de orice ingerințe politice sau religioase, în incinta acestora fiind interzise crearea și funcționarea oricăror formațiuni politice, organizarea și desfășurarea activităților de natură politică și prozelitism religios, precum și orice formă de activitate care încalcă normele de conduită morală și conviețuire socială, care pun în pericol sănătatea, integritatea fizică sau psihică a beneficiarilor primari sau a personalului din unitatea de învățământ."},{"article":"5","articleNumber":5,"legalText":"Unitățile de învățământ autorizate să funcționeze provizoriu/acreditate fac parte din rețeaua școlară națională, care se constituie în conformitate cu prevederile legale.\nUnitățile de învățământ care fac parte din rețeaua școlară națională au obligația de a include în Sistemul Informatic Integrat al Învățământului din România (SIIIR), datele referitoare la beneficiarii primari școlarizați."},{"article":"6","articleNumber":6,"legalText":"În sistemul național de învățământ, unitățile de învățământ autorizate să funcționeze provizoriu/acreditate dobândesc personalitate juridică, în conformitate cu prevederile legislației în vigoare.\nUnitatea de învățământ preuniversitar cu personalitate juridică (PJ) este orice unitate de învățământ autorizată să funcționeze provizoriu/acreditată din sistemul național de învățământ preuniversitar, care are următoarele elemente definitorii:\nact de înființare – ordin al ministrului/hotărâre a autorităților administrației publice locale sau județene (după caz)/hotărâre judecătorească/orice alt act emis în acest sens, cu respectarea prevederilor legislației în vigoare la data emiterii acestuia;\ndispune de patrimoniu, în proprietate publică/privată sau prin administrare/comodat/ închiriere (sediu, dotări corespunzătoare, adresă);\ncod de identificare fiscală (CIF);\ncont în Trezoreria Statului/bancă (pentru unitățile de învățământ particular);\nsigiliu cu stema României și cu denumirea actualizată a Ministerului Educației, precum și cu denumirea exactă/completă a unității de învățământ corespunzătoare, de regulă, nivelului maxim de învățământ școlarizat.\nFiecare unitate de învățământ cu personalitate juridică are personal de conducere, personal didactic, didactic auxiliar și administrativ și buget, proprii, întocmește situațiile financiare, dispunând, în limitele și condițiile prevăzute de legislația în vigoare, de autonomie instituțională și decizională.\nO unitate de învățământ cu personalitate juridică poate avea în componența sa una sau mai multe structuri școlare arondate, fără personalitate juridică, în care se desfășoară doar activitate didactică și/sau alte locații în care se desfășoară activitate didactică și/sau\nadministrativă."},{"article":"7","articleNumber":7,"legalText":"În vederea creșterii calității educației și a optimizării gestionării resurselor, unitățile de învățământ și autoritățile administrației publice locale pot decide înființarea consorțiilor școlare, în conformitate cu metodologia pentru înființarea consorțiilor școlare."},{"article":"8","articleNumber":8,"legalText":"Inspectoratele școlare stabilesc, pentru fiecare unitate administrativ-teritorială, după consultarea reprezentanților unităților de învățământ și a autorităților administrației publice locale, circumscripțiile unităților de învățământ care școlarizează grupe și/sau clase de nivel antepreșcolar, preșcolar, primar și gimnazial, cu respectarea prevederilor legale.\nCircumscripția școlară este formată din totalitatea străzilor aflate în apropierea unității de învățământ și arondate acesteia, în vederea școlarizării beneficiarilor primari.\nUnitățile de învățământ școlarizează în învățământul antepreșcolar, preșcolar, primar și gimnazial, cu prioritate, în limita planului de școlarizare aprobat, copiii/elevii care au domiciliul în circumscripția școlară a unității de învățământ respective. Înscrierea se face în urma unei solicitări scrise din partea părintelui sau a reprezentantului legal.\nPărintele/reprezentantul legal are dreptul de a solicita școlarizarea copilului la o altă unitate de învățământ decât aceea la care domiciliul său este arondat. Înscrierea se face în urma unei solicitări scrise din partea părintelui, a tutorelui sau a reprezentantului legal și se aprobă de către consiliul de administrație al unității de învățământ la care se solicită înscrierea, în limita planului de școlarizare aprobat, după asigurarea școlarizării beneficiarilor primari din circumscripția școlară a unității de învățământ respective.\nPrin excepție de la prevederile alin. (4), înscrierea în unitățile de învățământ cu nivel antepreșcolar sau preșcolar sau în serviciile complementare de educație timpurie, respectiv în clasa pregătitoare, se face conform metodologiilor specifice, elaborate de Ministerul Educației.\nÎn cazul în care părinții se află în proces de divorț, până la soluționarea litigiului prevalează interesul superior al copilului în ceea ce privește asigurarea accesului la educație al acestuia, iar părintele care exercită autoritatea părintească, respectiv persoana în grija căreia se află minorul are obligația de a-l înscrie la o unitate de învățământ, de regulă, din proximitatea domiciliului.\n(la 12-09-2025, Articolul 8 , Capitolul I , Titlul II a fost completat de Articolul I din ORDINUL nr. 6.226 din 5 septembrie 2025, publicat în MONITORUL OFICIAL nr. 842 din 12\nseptembrie 2025 )"},{"article":"9","articleNumber":9,"legalText":"Anul școlar începe la 1 septembrie și se încheie la 31 august din anul calendaristic următor.\nStructura anului școlar, respectiv perioadele de desfășurare a cursurilor, a vacanțelor și a sesiunilor de evaluări, examene și concursuri naționale se stabilesc prin ordin al ministrului educației. În unitățile de educație timpurie, care oferă servicii esențiale în societate, atât pentru copiii cărora li se adresează, cât și pentru familiile acestora și angajatori, vacanța școlară se raportează, cu prioritate, la interesul beneficiarilor primari pentru care, în timpul acesteia, se organizează, la cererea părinților/reprezentanților legali, activități educative recreative în unitățile de educație timpurie.\nPentru elevele gravide și elevii părinți, pe perioada de îngrijire a copilului, precum și în situații obiective, cum ar fi epidemii, intemperii, calamități, alte situații excepționale, cursurile școlare față în față pot fi suspendate pe o perioadă determinată, potrivit reglementărilor în vigoare.\nSuspendarea cursurilor cu prezență fizică se poate face, după caz:\nla nivel individual, la cererea părintelui/ reprezentantului legal, cu avizul și recomandările specifice ale medicului curant, în cazul în care elevul suferă de boli care afectează capacitatea de oxigenare, boli respiratorii cronice severe, boli cardiovasculare, obezitate severă, diabet zaharat tip I, boli inflamatorii, boli imune/autoimune, boli rare, boli ereditare de metabolism, tratament imunosupresiv, alte afecțiuni cronice, afecțiuni asociate cu imunodepresie moderată sau severă cum ar fi: transplant, afecțiuni oncologice în tratament imunosupresor, imunodeficiențe primare sau dobândite, alte tipuri de tratamente imunosupresoare. În această situație activitatea didactică se va desfășura în sistem hibrid sau online;\nla nivel individual, la cererea elevelor gravide sau a beneficiarilor primari părinți majori sau la cererea părintelui/reprezentantului legal al acestora în cazul beneficiarilor primari minori, activitatea didactică desfășurându-se în format hibrid sau online;\nla nivel individual, la cererea elevului major sau a părintelui/reprezentantului legal al acestuia, pentru beneficiarii primari aflați în arest la domiciliu, în limitele hotărârii judecătorești; în această situație activitatea didactică se va desfășura în sistem hibrid sau online, în limitele hotărârii judecătorești;\nla nivelul unor formațiuni de studiu – grupe/clase din cadrul unității de învățământ, precum și la nivelul unității de învățământ – la cererea directorului, în baza hotărârii consiliului de administrație al unității, cu informarea ISJ/ISMB, respectiv cu aprobarea inspectorului școlar general și informarea Ministerului Educației;\nla nivelul grupurilor de unități de învățământ din același județ/municipiul București – la cererea inspectorului școlar general, cu aprobarea ministerului educației;\nla nivel regional sau național, prin ordin al ministrului educației, ca urmare a hotărârii comitetului județean/al municipiului București pentru situații de urgență, respectiv Comitetului Național pentru Situații de Urgență (CJSU/CNSU), după caz.\nSuspendarea cursurilor cu prezență fizică la nivel individual, conform alin. (4) lit.a) și lit.b), se realizează cu avizul, motivat în scris, al consiliului de administrație al unității de învățământ. Suspendarea cursurilor cu prezență fizică în cazul elevelor gravide și a beneficiarilor primari părinți, precum și revenirea acestora cu prezență fizică în unitatea de învățământ se va realiza cu informarea ISJ/ISMB.\nÎn situațiile prevăzute la alin. (4), activitatea didactică se poate desfășura în format online sau hibrid.\nÎn situațiile prevăzute la alin. (4) în care activitatea nu s-a putut desfășura în format online sau hibrid, suspendarea cursurilor este urmată de măsuri privind parcurgerea integrală a programei școlare prin modalități alternative stabilite de consiliul de administrație al unității de învățământ.\nÎn situații excepționale, inclusiv pe perioada declarării stării de urgență/alertă, desfășurarea activităților în sistem online sau hibrid se realizează în conformitate cu prevederile Anexei nr. 1 la prezentul regulament, Metodologia-cadru de organizare și desfășurare a activităților în sistem online sau hibrid.\nReluarea activităților didactice care presupun prezența fizică a beneficiarilor primari în unitățile de învățământ preuniversitar se realizează cu respectarea prevederilor legale în vigoare."},{"article":"10","articleNumber":10,"legalText":"În funcție de programul de activitate, unitățile de educație timpurie funcționează astfel:\ncu program normal – 5 ore pe zi, activitate cu copiii;\ncu program prelungit – 10 ore pe zi, activitate cu copiii.\nÎn aceeași unitate de învățământ, educația timpurie poate fi organizată în grupe cu program normal și/sau cu program prelungit, cu respectarea prevederilor legale în vigoare\nÎn educația timpurie, programul zilnic al copilului nu poate depăși 10 ore zilnic.\nPentru toate tipurile de program menționate la alin. (1), se aplică același curriculum aprobat prin ordin de ministru.\nProgramul de funcționare al unității de educație timpurie, particularizat la nevoile beneficiarilor primari și/sau ale zonei în care se află unitatea, se stabilește pornind de la prevederile din Curriculumul pentru educație timpurie în vigoare și se aprobă prin hotărâre a consiliului de administrație, în baza rezultatului consultărilor părinților/reprezentanților legali ai copiilor.\nÎn perioada vacanțelor, în unitățile de învățământ cu nivel antepreșcolar și preșcolar se pot organiza, la nivelul unității sau în asociere cu alte unități, activități educativ- recreative cu copiii. Activitățile se pot organiza cu minimum 10 copii înscriși la program prelungit, ai căror părinți au solicitat acest tip de program.\nPerioada din vacanță în care se organizează activități educativ-recreative se aprobă de către Consiliul de administrație al unității de învățământ, în concordanță cu programarea concediilor de odihnă ale salariaților și se aduce la cunoștință părinților/reprezentanților legali ai beneficiarilor primari.\nÎn vederea participării la activitățile educativ-recreative menționate la alin. (6), părinții și unitatea de învățământ încheie pentru perioada respectivă contract educațional, conform reglementărilor legale în vigoare.\nActivitățile menționate la alin. (6) se vor desfășura cu respectarea următoarelor condiții specifice :\nstabilirea locației potrivite pentru activități de vacanță;\nplanificarea personalului didactic și administrativ în activitate;\nplanificarea activităților de educativ-recreative;\nasigurarea condițiilor de microclimat;\nasigurarea hranei conform prevederilor aplicabile;\nasigurarea efectuării concediului de odihnă pentru personalul unității de educație timpurie;\nasigurarea timpului necesar pentru efectuarea lucrărilor necesare de reparație și de igienizare ale clădirilor și terenurilor."},{"article":"11","articleNumber":11,"legalText":"În unitățile de învățământ, cursurile se pot organiza în forma de învățământ cu frecvență zi, învățământ cu frecvență seral sau în forma de învățământ cu frecvență redusă.\nÎnvățământul primar funcționează, de regulă, în programul de dimineață. Pentru unitățile de învățământ care funcționează în cel puțin două schimburi, programul este stabilit de consiliul de administrație al unității de învățământ.\nCursurile pentru elevii din clasa pregătitoare și din clasele I și a II-a nu vor începe înainte de ora 8.00 și nu se vor termina mai târziu de ora 14.00.\nÎn învățământul primar, ora de curs este de 45 de minute, cu o pauză de 15 minute după fiecare oră și o pauză de 20 de minute după cea de-a doua oră de curs. La clasa pregătitoare și la clasa I, activitățile de predare-învățare-evaluare acoperă 30 – 35 de minute, restul de timp fiind destinat activităților liber alese, recreative.\nÎn situațiile în care clasele din învățământul primar funcționează împreună cu alte clase din nivelurile superioare de învățământ, ora de curs este de 50 de minute, iar în ultimele\ncinci minute se organizează activități de tip recreativ.\nPentru clasele din învățământul gimnazial, liceal, profesional și din învățământul postliceal, ora de curs este de 50 de minute, cu o pauză de 10 minute după fiecare oră; după a treia oră de curs se poate stabili o pauză de 15 – 20 de minute.\nÎn învățământul special, durata orei de curs și a activităților de terapii specifice este de 45 de minute, cu o pauză de 15 minute după fiecare oră și o pauză de 30 de minute după cea de-a doua oră de curs.\nÎn educația timpurie – nivel antepreșcolar și nivel preșcolar, durata activităților poate varia, în funcție de particularitățile copiilor și, implicit, de interesul manifestat de grupul de copii/copil pentru acestea, de conținutul activităților, precum și în funcție de maniera de desfășurare. Recomandat este ca, pentru primul interval de vârstă (de la 3 luni la 1 an), durata unei activități să fie de cel mult 5-10 minute, după care, pentru intervalele următoare, durata activității poate crește progresiv, până la 35 minute (5 – 6 ani), respectând prevederile din planul de învățământ din cadrul Curriculumului pentru educație timpurie.\nÎn situații speciale, cum ar fi epidemii, intemperii, calamități, alte situații excepționale, pe o perioadă determinată, durata orelor de curs și a pauzelor poate fi modificată, la propunerea motivată a directorului, în baza hotărârii consiliului de administrație al unității de învățământ, cu aprobarea inspectoratului școlar.\nElevele gravide și elevii părinți pot beneficia de un program școlar flexibil, în vederea prevenirii și combaterii abandonului școlar. Programul flexibil se stabilește, prin consultare cu părinții/tutorii/reprezentanții legali ai beneficiarilor primari minori, de către o comisie care include și consilierul școlar. Programul poată să prevadă atât un plan individualizat de învățare, cât și un orar școlar adaptat nevoilor acestora, precum și alte măsuri stabilite de către comisie.\nÎn unitățile de învățământ preuniversitar se asigură condiții de igienă necesare apărării, păstrării și promovării stării de sănătate, dezvoltării fizice și neuropsihice armonioase și prevenirii apariției unor îmbolnăviri. În acest sens, în unitățile de educație timpurie se va avea în vedere și expunerea limitată a copiilor la tehnologie, conform recomandărilor Organizației Mondiale a Sănătății.\nÎn vederea respectării opțiunilor pentru Curriculum la decizia elevului din oferta școlii (CDEOȘ) exprimate de elevi/părinți, stabilirea listei de opționale va lua în calcul inclusiv posibilitatea de organizare a unui bloc orar pentru CDEOȘ, care să permită participarea la un opțional comun a beneficiarilor primari din clase diferite, de la același nivel de studiu."},{"article":"12","articleNumber":12,"legalText":"Durata și structura anului de studiu, alcătuirea schemei orare, precum și organizarea procesului de învățământ în cadrul programului \"A doua șansă\" sunt reglementate prin metodologie specifică, aprobată prin ordin al ministrului educației.\nÎn urma analizei de nevoi întreprinse la nivelul unității de învățământ în funcție de resursele existente (umane, financiare și materiale), prin decizia consiliului de administrație al unității de învățământ și, după caz, cu avizul inspectoratului școlar, se pot organiza programe care au drept scop creșterea calității educației oferite tuturor beneficiarilor primari sau se pot întreprinde demersuri pentru dobândirea unui statut special, precum:\nProgramul \"Școala după școală\";\nProgramul de \"Învățare remedială\";\nStatutul de școală verde;\nStatutul de școală – pilot sau de aplicație;\nProgramul \"Zone de investiții prioritare în educație\".\nOrganizarea programelor și, respectiv, dobândirea statutului menționat la alin. (2) se face în conformitate cu reglementările specifice, aprobate prin ordin al ministrului educației."},{"article":"13","articleNumber":13,"legalText":"În unitățile de învățământ, formațiunile de studiu cuprind grupe, clase sau ani de studiu\nși se constituie în conformitate cu prevederile Art. 23 alin. (1), (2), (3) și Art. 248 alin.\n(16) din Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare, la propunerea directorului, prin hotărâre a consiliului de administrație.\nÎn unitățile de educație timpurie se recomandă următoarea modalitate de organizare a efectivelor de copii:\nla nivel antepreșcolar: grupa mică – copii de la 3 la 12 luni, grupa mijlocie – copii de la\n13 la 24 de luni, grupa mare – copii de la 25 la 36 de luni;\nla nivel preșcolar: grupa mică – copii de la 3 la 4 ani, grupa mijlocie – copii de la 4 la\n5 ani, grupa mare – copii de la 5 la 6 ani.\nÎn cazul în care numărul total al copiilor este sub minimul prevăzut la art. 23, alin. (1) din Legea învățământului preuniversitar nr.198/2023, cu modificările și completările ulterioare, pentru fiecare grupă de vârstă sau, în cazul existenței fraților de vârste diferite, se pot constitui și grupe eterogene.\nÎn situații excepționale, formațiunile de antepreșcolari, preșcolari sau de elevi pot funcționa cu cel mult 2 beneficiari sub efectivul minim și, respectiv, cu cel mult 4 beneficiari peste efectivul maxim prevăzut la art. 23 alin. (1) din Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare, după caz, cu\naprobarea inspectoratului școlar, pe baza unei justificări din partea consiliului de administrație al unității de învățământ care solicită exceptarea de la prevederilealin. (1). (la 04-09-2025, Alineatul (4), Articolul 13, Capitolul III, Titlul II a fost modificat de Punctul 1., Articolul I din ORDINUL nr. 6.055 din 29 august 2025, publicat în MONITORUL OFICIAL nr. 819 din 4 septembrie 2025 )\nÎn localitățile în care există cerere pentru forma de învățământ în limba maternă a unei minorități naționale, formațiunile de studiu pot funcționa sub efectivul minim sau peste efectivul maxim, în conformitate cu prevederile legale în vigoare.\nPrevederile alin. (5) se aplică și formațiunilor de studiu în limba română, atunci când acestea funcționează în zone unde ponderea unei minorități etnice este majoritară. În aceste situații, aprobarea se realizează de Ministerul Educației la propunerea ISJ/ISMB sau a consiliului de administrație al unității de învățământ.\nActivitatea de învățământ în regim simultan se reglementează prin ordin al ministrului educației.\nMinisterul stabilește, prin proceduri specifice, disciplinele de învățământ/modulele la care predarea se face individual sau pe grupe de elevi.\nÎn situații temeinic motivate, în unitățile de învățământ liceal și, după caz, profesional în care numărul de elevi de la o specializare/calificare profesională/un domeniu de pregătire profesională este insuficient pentru alcătuirea unei clase, se pot organiza clase cu dublu profil sau dublă specializare/calificare. În unitățile de învățământ care școlarizează elevi în învățământ profesional și tehnic, inclusiv dual, în care numărul de elevi de la o calificare profesională este sub efectivele prevăzute în Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare, se pot organiza clase cu maximum trei grupe cu calificări diferite.\nClasele menționate la alin. (9) se organizează pentru profiluri/domenii de pregătire profesională/specializări/calificări la care disciplinele generale sunt comune, la solicitarea consiliului de administrație al unității de învățământ, cu avizul inspectoratului școlar și aprobarea ministerului.\nLa disciplinele comune pentru toți elevii claselor menționate la alin. (9), activitatea se desfășoară cu toată clasa, iar la disciplinele/modulele de specialitate activitatea se desfășoară pe grupe.\nConsiliul de administrație poate decide constituirea de grupe pentru elevi din formațiuni de studiu diferite care aleg să studieze aceleași discipline opționale, în conformitate cu prevederile statutului elevului, cu încadrarea în numărul de norme aprobat.\nÎn vederea asigurării și respectării principiului desegregării școlare și al combaterii oricăror forme de discriminare asumat la nivelul sistemului național de învățământ, la începutul nivelului de învățământ, formațiunile de studiu se constituie prin distribuția aleatorie a beneficiarilor primari, acolo unde există mai multe clase pe an de studiu, conform procedurii în vigoare, aprobate prin ordin al ministrului educației."},{"article":"14","articleNumber":14,"legalText":"Învățământul special și special integrat pentru preșcolarii/elevii cu deficiențe ușoare și moderate sau grave/profunde/severe/asociate se organizează individual, pe grupe sau clase cu efective stabilite prin lege, în funcție de tipul și de gradul deficienței."},{"article":"15","articleNumber":15,"legalText":"La înscrierea în învățământul gimnazial, liceal, profesional, inclusiv dual, se asigură, de regulă, continuitatea studiului limbilor moderne, ținând cont de oferta educațională a unității de învățământ.\nConducerea unității de învățământ constituie, de regulă, formațiunile de studiu astfel încât elevii să studieze aceleași limbi străine.\nÎn unitățile de învățământ în care constituirea formațiunilor de studiu nu se poate face cu respectarea prevederilor alin. (2), conducerile unităților de învățământ asigură în program un interval orar care să permită asocierea beneficiarilor primari pentru studiul limbilor moderne.\nÎn situații temeinic motivate, la solicitarea scrisă a părinților/reprezentanților legali sau a beneficiarilor primari majori, consiliul de administrație poate hotărî ordinea studierii limbilor moderne sau schimbarea lor.\nÎn cazurile menționate la alin. (4), conducerea unității de învățământ, în interesul superior al elevului, poate să asigure un program de sprijin pentru elevii care nu au studiat limba modernă respectivă sau nu se află la același nivel de studiu cu ceilalți elevi din clasă/grupă, cu încadrarea în bugetul unității de învățământ."},{"article":"16","articleNumber":16,"legalText":"(1) Managementul unităților de învățământ cu personalitate juridică este asigurat în conformitate cu prevederile legale.\n(2) Unitatea de învățământ cu personalitate juridică, cu excepția celor din sistemul de apărare, ordine publică și securitate națională, este condusă de consiliul de administrație, de director și, după caz, de directori adjuncți, unde este cazul.\n(3) În exercitarea atribuțiilor ce le revin, consiliile de administrație și directorii se\nconsultă, după caz, cu toate organismele interesate: consiliul profesoral, personalul didactic auxiliar, personalul administrativ, Comisia pentru Evaluarea și Asigurarea Calității (CEAC), Comisia pentru Formare și Dezvoltare în Cariera Didactică (CFDCD) și alte comisii constituite la nivelul unității de învățământ, consiliul școlar al elevilor, consiliul reprezentativ al părinților/reprezentanților legali și asociația de părinți, acolo unde există, cu autoritățile administrației publice locale și organizațiile sindicale afiliate federațiilor sindicale reprezentative la nivel de sector de negociere colectivă învățământ preuniversitar, precum și cu reprezentanții operatorilor economici implicați în susținerea învățământului profesional și tehnic, inclusiv dual, respectiv a învățământului tehnologic în sistem dual și/sau în desfășurarea instruirii practice a elevilor.\n(4) În unitățile de învățământ preuniversitar particular și confesional, persoana juridică fondatoare stabilește, prin hotărâre, structura consiliului de administrație, funcțiile de conducere, precum și atribuțiile acestora, cu respectarea prevederilor prezentului regulament."},{"article":"17","articleNumber":17,"legalText":"(1) Pentru toate litigiile în care este implicată unitatea de învățământ de stat, directorul, în calitate de reprezentant legal, este obligat să asigure dreptul la apărare și reprezentarea unității în fața instanțelor de judecată sau a altor organe de specialitate.\n(2) La solicitarea scrisă a directorului, inspectoratele școlare asigură, prin consilierul juridic, consultanță de specialitate pentru unitățile de învățământ de stat. Aceasta constă în analiza documentelor, explicarea legislației și a procedurilor, evaluarea riscurilor și oferirea de soluții punctuale, precum și îndrumare în redactarea cererilor, notificărilor, întâmpinărilor sau a altor documente cu specific juridic.\n(3) Nerespectarea obligațiilor prevăzute la alin. (1) constituie abatere disciplinară și se sancționează conform prevederilor Legii învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare."},{"article":"18","articleNumber":18,"legalText":"(1) Consiliul de administrație este organul deliberativ de conducere al unităților de învățământ preuniversitar de stat.\n(2) Consiliul de administrație se organizează și funcționează conform Metodologiei-cadru de organizare și funcționare a consiliului de administrație din unitățile de învățământ preuniversitar, aprobate prin ordin al ministrului educației.\n(3) Președintele consiliului de administrație al unităților de învățământ de stat este directorul unității de învățământ, cu excepția unităților de învățământ de stat care organizează, cu o pondere majoritară, învățământ profesional în sistem dual, respectiv învățământ tehnologic în sistem dual, caz în care președintele poate fi directorul sau un reprezentant al operatorului economic.\n(4) Pentru unitățile de învățământ particular și confesional, conducerea consiliului de administrație este asigurată de persoana desemnată de fondatori.\n(5) În situația în care tematica ședinței vizează activitatea directorului sau eliberarea din funcție a directorului numit în urma concursului național, iar directorul este președinte, de drept sau ales, ședința este condusă de un alt membru al consiliului de administrație ales prin votul membrilor.\n(6) Incompatibilitățile privind calitatea de membru al consiliului de administrație sunt cele prevăzute în Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare și în Metodologia-cadru de organizare și funcționare a consiliilor de administrație din unitățile de învățământ preuniversitar, aprobată prin ordin al ministrului educației.\n(7) Ședințele consiliului de administrație se pot desfășura fizic, on-line sau hibrid, conform prevederilor Metodologiei-cadru de organizare și funcționare a consiliilor de administrație din unitățile de învățământ preuniversitar, aprobată prin ordin al ministrului educației.\n(8) Pentru asigurarea transparenței în procesul decizional, tematica de ședință a Consiliului de administrație, precum și deciziile luate vor fi afișate la avizierul instituției și/ sau pe adresa/ pagina web a instituției."},{"article":"19","articleNumber":19,"legalText":"(1) La ședințele consiliului de administrație participă de drept, cu statut de observator, reprezentanții federațiilor sindicale reprezentative la nivel de sector de negociere colectivă învățământ preuniversitar care au membri în unitatea de învățământ și ai asociației de părinți membre a federațiilor părinților/reprezentanților legali cu activitate relevantă la nivel național. În cazul unităților de învățământ gimnazial, liceal sau profesional, după caz, participă cu statut de observator și președintele consiliului școlar al beneficiarilor primari.\n(2) În unitățile de învățământ care organizează exclusiv învățământ tehnologic, președintele consiliului școlar al beneficiarilor primari participă obligatoriu, cu statut de observator, la toate ședințele consiliului de administrație.\n(3) În funcție de problematica abordată, la ședințele consiliului de administrație pot participa și alte persoane/sunt invitați și alți observatori, conform prevederilor Metodologiei-cadru de organizare și funcționare a consiliilor de administrație din unitățile\nde învățământ preuniversitar, aprobată prin ordin al ministrului educației.\n(4) Președintele consiliului de administrație convoacă observatorii la toate ședințele consiliului de administrație.\n(5) În consiliile de administrație ale unităților de învățământ preuniversitar de nivel liceal/ postliceal și profesional, după caz, cu excepția unităților de învățământ cu personalitate juridică care organizează exclusiv învățământ tehnologic, din cota rezervată părinților/reprezentanților legali un loc este repartizat, cu drept de vot, unui reprezentant al beneficiarilor primari care a împlinit vârsta de 18 ani.\n(6) În consiliile de administrație ale unităților de învățământ care școlarizează doar nivel postliceal cota aferentă părinților/reprezentanților legali revine reprezentanților beneficiarilor primari.\n(7) Reprezentanții consiliului de administrație organizează, cel puțin o dată pe an, întâlniri consultative cu reprezentanții părinților/reprezentanților legali ai beneficiarilor primari cu cerințe educaționale speciale, respectiv ale părinților/reprezentanților legali fiecărui grup etnic din care fac parte beneficiarii primari.\n(8) Consiliul de administrație, cu sprijinul autorităților publice locale, identifică și aprobă măsurile necesare pentru accesibilizarea mediului fizic, informațional, comunicațional și educațional conform nevoilor beneficiarilor primari, părinților/reprezentanților legali și personalului cu dizabilități.\n(9) Consiliul de administrație, cu sprijinul educatorilor/profesorilor pentru învățământ primar/ diriginților, monitorizează nevoia de sprijin și solicită CJRAE/CMBRAE să aloce profesori consilieri școlari, profesori logopezi, profesori itineranți și de sprijin, respectiv mediatori școlari necesari, în funcție de nevoile unității de învățământ.\n(10) Consiliul de administrație poate decide aprobarea unor acțiuni/măsuri cu caracter financiar/bugetar doar cu încadrarea în prevederile bugetare aprobate. (la 07-07-2026, Articolul 19, Capitolul II, Titlul III a fost completat de Punctul 2., Articolul I din ORDINUL nr. 4.261 din 26 iunie 2026, publicat în MONITORUL OFICIAL nr. 556 din 7 iulie 2026 )"},{"article":"20","articleNumber":20,"legalText":"(1) Directorul exercită conducerea executivă a unității de învățământ de stat, în conformitate cu legislația în vigoare.\n(2) Recrutarea pentru ocuparea funcțiilor de director din unitățile de învățământ de stat se realizează prin concurs național, organizat prin inspectoratele școlare, sub coordonarea Ministerului Educației, potrivit metodologiei aprobate prin ordin al ministrului educației.\n(3) La concursul pentru ocuparea funcțiilor de director participă personalul didactic de predare titular în învățământul preuniversitar.\n(4) Directorul, după promovarea concursului, încheie contract de management educațional cu inspectorul școlar general al ISJ/ISMB. Modelul contractului de management educațional este aprobat prin ordin al ministrului educației. Contractul de management educațional poate fi modificat exclusiv prin act adițional, cu acordul părților semnatare.\n(5) Contractul de management educațional poate fi încheiat numai după prezentarea unei evaluări medicale care atestă faptul că persoana este aptă pentru funcția vizată.\n(6) Pentru asigurarea finanțării de bază, a finanțării complementare și a finanțării suplimentare, după promovarea concursului, directorul încheie contract de management administrativ-financiar cu primarul unității administrativ-teritoriale în a cărei rază teritorială se află unitatea de învățământ, respectiv cu președintele consiliului județean, pentru unitățile de învățământ special și special integrat. Modelul contractului de management administrativ-financiar este aprobat prin ordin al ministrului educației. Contractul de management administrativ-financiar poate fi modificat exclusiv prin act adițional, cu acordul părților semnatare.\n(7) Pe perioada exercitării mandatului, directorul nu poate deține, conform legii, funcția de președinte sau vicepreședinte în structurile de conducere ale partidelor politice, la nivel local, județean/al municipiului București sau național, funcția de primar, viceprimar, președinte sau vicepreședinte de consiliu județean/al Consiliului General al Municipiului București sau orice funcție de conducere în organizațiile sindicale.\n(8) Nu poate ocupa/exercita o funcție de conducere la nivelul unităților de învățământ preuniversitar persoana care a fost condamnată penal definitiv pentru săvârșirea cu intenție a unei infracțiuni contra vieții, integrității corporale sau sănătății, contra libertății persoanei, rele tratamente aplicate minorului, hărțuire, trafic de minori, proxenetism, infracțiuni contra libertății și integrității sexuale, luare și dare de mită, trafic de influență, fals și uz de fals, furt calificat, pentru care nu a intervenit reabilitarea.\n(9) În cazul unităților de învățământ cu predare integrală în limbile minorităților naționale, directorul are obligația cunoașterii limbii respective. În cazul unităților de învățământ cu secții de predare în limbile minorităților naționale/studiul limbii minorității naționale, unul dintre directori are obligația cunoașterii limbii respective. În aceste cazuri, numirea directorului se face cu consultarea organizației care reprezintă minoritatea respectivă în Parlamentul României sau, dacă minoritatea nu are reprezentare parlamentară, cu consultarea Grupului parlamentar al minorităților naționale. Respectarea criteriilor de competență profesională este obligatorie.\n(10) În unitățile de învățământ cu predare în limbile minorităților naționale, în care există și clase cu predare în limba română, unul dintre directori este un cadru didactic care nu aparține minorităților și care predă în limba română.\n(11) Directorii unităților de învățământ particular și confesional sunt numiți de conducerea\npersoanei juridice fondatoare, cu respectarea criteriilor de competență. Actul de numire se aduce la cunoștința ISJ/ISMB pe raza căreia își desfășoară activitatea unitatea respectivă.\n(12) Directorul unității de învățământ de stat, numit în urma concursului național, poate fi eliberat din funcție:\na) la propunerea motivată a inspectorului școlar general al ISJ/ISMB, cu avizul consiliului de administrație al ISJ/ISMB;\nb) la propunerea motivată a 2/3 dintre membrii consiliului de administrație al unității de învățământ, urmată de un raport de evaluare a activității directorului, realizat de către o comisie constituită la nivelul ISJ/ISMB, decizia finală aparținând consiliului de administrație al inspectoratului școlar;\nc) la propunerea consiliului profesoral, cu votul secret a 2/3 dintre membri. În această situație, este obligatorie realizarea unui audit de către ISJ/ISMB. Rezultatele auditului se analizează în consiliul de administrație al ISJ/ISMB. În funcție de hotărârea consiliului de administrație al ISJ/ISMB, inspectorul școlar general emite decizia de eliberare din funcție a directorului unității de învățământ;\nd) pentru încălcarea cu vinovăție a obligațiilor stabilite prin contractul de management, cu respectarea procedurii de cercetare disciplinară prevăzută de Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare;\ne) de către consiliul de administrație al ISJ/ISMB la propunerea motivată a autorității publice locale care anual evaluează respectarea contractului și a planului de management administrativ-financiar; hotărârea finală aparține ISJ/ISMB.\n(13) Directorul unității de învățământ particular și confesional poate fi eliberat din funcție, la propunerea consiliului de administrație, cu votul a 2/3 din membrii săi, prin decizia persoanei juridice fondatoare.\n(14) În funcțiile de director rămase vacante în urma organizării concursului sau în cazul vacantării funcției de director din unitățile de învățământ preuniversitar de stat, conducerea interimară este asigurată, până la organizarea concursului, dar nu mai târziu de sfârșitul anului școlar, de un cadru didactic titular, numit prin detașare în interesul învățământului, prin decizia inspectorului școlar general, cu avizul consiliului de administrație al ISJ/ISMB și cu acordul scris al persoanei solicitate.\n(15) Anterior solicitării avizului consiliului de administrație al ISJ/ISMB, potrivit alin.\n(14), inspectorul școlar general consultă consiliul profesoral al unității de învățământ, de regulă până la încheierea cursurilor anului școlar, în perioada de activitate a cadrelor didactice.\n(16) În cazul în care nu se poate asigura numirea prin detașare în interesul învățământului, conducerea interimară va fi asigurată de un cadru didactic membru al consiliului de administrație din unitatea de învățământ, cu acordul acestuia, căruia i se deleagă atribuțiile specifice funcției de conducere, până la organizarea concursului, dar nu mai mult de 60 de zile calendaristice și fără a depăși sfârșitul anului școlar. În această ultimă situație, în baza avizului consiliului de administrație al ISJ/ISMB, inspectorul școlar general emite decizie de delegare a atribuțiilor specifice funcției.\n(17) Pentru învățământul particular și confesional, directorul unității de învățământ este numit de conducerea persoanei juridice fondatoare, iar actul de numire se comunică/ se aduce la cunoștința inspectoratului școlar/ ISMB, pe raza căruia își desfășoară activitatea unitatea de învățământ respectivă.\n(18) Structurile și funcțiile de conducere ale unităților de învățământ particular și confesional, atribuțiile, modul de constituire, precum și durata mandatelor sunt stabilite prin regulamentele de organizare și funcționare ale acestora, în concordanță cu prevederile legale."},{"article":"21","articleNumber":21,"legalText":"(1) În exercitarea funcției de conducere executivă, directorul are următoarele atribuții:\na) este reprezentantul legal al unității de învățământ și realizează conducerea executivă a acesteia;\nb) organizează întreaga activitate educațională;\nc) răspunde de aplicarea legislației în vigoare, la nivelul unității de învățământ;\nd) asigură corelarea obiectivelor specifice unității de învățământ cu cele stabilite la nivel național și local;\ne) propune spre aprobare consiliului de administrație obiectivele unității de învățământ preuniversitar privind asigurarea calității și echității în educație, prin raportare la cadrul general privind politicile educaționale, scopurile, obiectivele și standardele stabilite de Ministerul Educației. Îndeplinirea obiectivelor unității de învățământ privind asigurarea calității și echității în educație reprezintă criteriu în evaluarea managerială realizată de inspectorul școlar general al ISJ/ISMB și este verificată periodic de ARACIP;\nf) răspunde de implicarea unității de învățământ în programele Uniunii Europene în domeniul educației și formării profesionale, ca instrument de dezvoltare instituțională și de creștere a calității educației furnizate de unitatea de învățământ;\ng) coordonează și notifică administratorii patrimoniului în vederea obținerii autorizațiilor și avizelor legale necesare funcționării unității de învățământ, conform atribuțiilor care le revin;\nh) reprezintă unitatea de învățământ în cadrul consorțiilor școlare constituite în parteneriat cu alte unități de învățământ de stat, particulare și confesionale și autorități ale administrației publice locale în vederea asigurării calității educației și a optimizării gestionării resurselor;\ni) colaborează cu consiliul școlaral al elevilor, structurile asociative ale părinților/ reprezentanților legali și organizațiilor sindicale afiliate federațiilor sindicale\nreprezentative la nivel de sector de negociere colectivă învățământ preuniversitar care au membrii în unitatea de învățământ, pentru identificarea celor mai bune metode privind dezvoltarea sistemului educațional;\nj) asigură aplicarea și respectarea normelor de sănătate și de securitate în muncă;\nk) încheie parteneriate cu operatorii economici pentru asigurarea instruirii practice a beneficiarilor primari;\nl) prezintă anual un raport asupra calității educației în unitatea de învățământ; raportul este prezentat în fața consiliului de administrație, a consiliului profesoral, în fața consiliului reprezentativ al părinților/reprezentanților legali și a conducerii asociației de părinți, acolo unde există; raportul este adus la cunoștința autorităților administrației publice locale și a ISJ/ISMB și postat pe site-ul unității de învățământ și prin orice altă formă de comunicare publică existentă la nivelul unității școlare, în termen de maximum 30 de zile de la data începerii anului școlar.\n(2) Directorul are calitatea de ordonator de credite și are responsabilitățile prevăzute de legislația în vigoare pentru această calitate. În exercitarea funcției de ordonator de credite, directorul are următoarele atribuții:\na) propune consiliului de administrație spre aprobare proiectul de buget și raportul de execuție bugetară;\nb) răspunde de încadrarea în bugetul aprobat al unității de învățământ; în acest sens, are obligația de a angaja și de a utiliza creditele bugetare numai în limita prevederilor și destinațiilor aprobate prin buget, pentru cheltuieli strict legate de activitatea instituției publice respective și cu respectarea dispozițiilor legale;\nc) face demersuri pentru atragerea de resurse extrabugetare, cu respectarea prevederilor legale;\nd) răspunde de gestionarea bazei materiale a unității de învățământ;\ne) răspunde de angajarea, lichidarea și ordonanțarea cheltuielilor, în limita creditelor bugetare aprobate;\nf) are responsabilitatea organizării și ținerii la zi a contabilității și prezentării la termen a situațiilor financiare asupra situației patrimoniului aflat în administrare și a execuției bugetare;\ng) răspunde de asigurarea cadrului organizatoric în vederea efectuării raportării și declarării sumelor către organele fiscale și teritoriale de muncă, precum și de verificarea periodică a declarării și concordanței dintre evidențele contabile și sumele raportate/ declarate. (la 07-07-2026, Alineatul (2), Articolul 21, Capitolul III, Titlul III a fost modificat de Punctul 3., Articolul I din ORDINUL nr. 4.261 din 26 iunie 2026, publicat în MONITORUL OFICIAL nr. 556 din 7 iulie 2026 )\n(3) În exercitarea funcției de angajator, directorul are următoarele atribuții:\na) angajează personalul din unitate prin încheierea contractului individual de muncă;\na^1) actualizează, prin act adițional, contractele individuale de muncă ori de câte ori intervin modificări ale clauzelor contractuale; (la 07-07-2026, Alineatul (3), Articolul 21, Capitolul III, Titlul III a fost completat de Punctul 4., Articolul I din ORDINUL nr. 4.261 din 26 iunie 2026, publicat în MONITORUL OFICIAL nr. 556 din 7 iulie 2026 )\na^2) desemnează, prin decizie scrisă, persoana responsabilă de înregistrarea informațiilor din contractele individuale de muncă ale fiecărui angajat în Registrul general de evidență a salariaților (REGES-online), precum și a informațiilor specifice în aplicația informatică de salarizare EDUSAL; (la 07-07-2026, Alineatul (3) , Articolul 21 , Capitolul III , Titlul III a fost completat de Punctul 4. , Articolul I din ORDINUL nr. 4.261 din 26 iunie 2026, publicat în MONITORUL OFICIAL nr. 556 din 7 iulie 2026 )\nb) întocmește, conform legii, fișele posturilor pentru personalul din subordine;\nc) răspunde de evaluarea periodică, formarea, motivarea personalului din unitate;\nd) propune consiliului de administrație vacantarea posturilor, organizarea concursurilor pe post și angajarea personalului;\ne) aplică prevederile metodologiei-cadru privind mobilitatea personalului didactic din învățământul preuniversitar, precum și prevederile altor acte normative, elaborate de minister.\n(4) Alte atribuții ale directorului sunt:\na) propune ISJ/ISMB, spre aprobare, proiectul planului de școlarizare, avizat de consiliul de administrație;\nb) coordonează activitatea de elaborare a ofertei educaționale a unității de învățământ și o propune spre aprobare consiliului de administrație; prin excepție, în unitățile de învățământ preuniversitar care școlarizează elevi exclusiv în învățământ profesional și tehnic cu o pondere majoritară a învățământului dual, directorul aprobă curriculumul la decizia elevului din oferta școlii cu obligativitatea consultării, în prealabil, a reprezentanților operatorilor economici implicați în instruirea practică și pregătirea de specialitate a beneficiarilor primari în calificarea respectivă;\nc) coordonează activitatea de colectare a datelor statistice pentru sistemul național de indicatori pentru educație, pe care le transmite ISJ/ISMB, și răspunde de introducerea datelor în Sistemul informatic integrat al învățământului din România (SIIIR);\nd) propune consiliului de administrație, spre aprobare, regulamentul de ordine interioară și regulamentul de organizare și funcționare a unității de învățământ;\ne) stabilește componența nominală a formațiunilor de studiu, în baza hotărârii consiliului de administrație;\nf) elaborează proiectul de încadrare cu personal didactic de predare, precum și statul de personal didactic auxiliar și administrativ și le supune, spre aprobare, consiliului de\nadministrație;\ng) numește, după consultarea consiliului profesoral, în baza hotărârii consiliului de administrație, profesorii diriginți, educatorii/profesorii pentru educație timpurie de la grupele pentru educație timpurie, în cazul în care unitatea de învățământ are și acest nivel de educație, învățătorii/profesorii pentru învățământul primar la clase, precum și coordonatorul pentru proiecte și programe educative școlare și extrașcolare, respectiv coordonatorul pentru proiecte educaționale europene;\nh) răspunde de implementarea programelor naționale inițiate de Ministerul Educației și a proiectelor europene din cadrul programelor UE în domeniul educației și formării profesionale și coordonează activitatea echipelor de proiect din unitatea de învățământ;\ni) emite, în baza hotărârii consiliului de administrație, decizia de numire a cadrului didactic, membru al consiliului clasei, care preia atribuțiile profesorului diriginte, în situațiile în care acesta este indisponibil pentru o perioadă de timp, din motive obiective;\nj) emite, în baza hotărârii consiliului de administrație, decizia de numire a coordonatorilor structurilor arondate, din rândul cadrelor didactice – de regulă, titulare – care își desfășoară activitatea în structurile respective;\nk) emite, în baza hotărârii consiliului de administrație, decizia de constituire a comisiilor din cadrul unității de învățământ;\nl) coordonează comisia de întocmire a orarului cursurilor unității de învățământ și îl propune spre aprobare consiliului de administrație;\nm) propune consiliului de administrație, spre aprobare, strategiile unității de învățământ pentru implementarea și respectiv, pentru valorizarea activităților din proiectele naționale inițiate de Ministerul Educației și din proiectele europene din cadrul programelor UE în domeniul educației și formării profesionale, precum și calendarul activităților educative al unității de învățământ;\nn) emite, în baza hotărârii consiliului de administrație, decizia de aprobare a regulamentelor de funcționare ale cercurilor, asociațiilor științifice, tehnice, sportive și cultural- artistice ale beneficiarilor primari din unitatea de învățământ, precum și a programului activităților remediale și a programului \"Școală după școală\" desfășurat la nivelul unității;\no) elaborează instrumente interne de lucru, utilizate în activitatea de îndrumare, control și evaluare a tuturor activităților care se desfășoară în unitatea de învățământ și le supune spre aprobare consiliului de administrație;\np) asigură, prin responsabilul comisiei pentru curriculum, aplicarea planului de învățământ, a programelor școlare și a metodologiei privind evaluarea rezultatelor școlare pe baza standardelor naționale de evaluare;\nq) controlează, cu sprijinul responsabilului comisiei pentru curriculum, calitatea procesului instructiv-educativ, atât prin asistențe la ore, astfel ca fiecare cadru didactic să fie asistat cel puțin o dată într-un an școlar, cât și prin evaluarea impactului participării cadrelor didactice la mobilități cu scop de învățare și la diverse activități educative extracurriculare și extrașcolare;\nr) monitorizează activitatea de formare continuă a personalului din unitate;\ns) monitorizează activitatea cadrelor didactice debutante și sprijină integrarea acestora în colectivul unității de învățământ;\nt) consemnează zilnic în condica de prezență absențele și întârzierile personalului didactic și administrativ de la programul de lucru;\nu) își asumă, alături de consiliul de administrație, răspunderea publică pentru performanțele unității de învățământ pe care o conduce;\nv) numește și controlează personalul care răspunde de sigiliul unității de învățământ;\nw) răspunde de arhivarea documentelor unității de învățământ;\nx) răspunde de primirea, întocmirea, anularea, eliberarea, arhivarea și casarea actelor de studii și a documentelor școlare;\ny) supune, spre aprobare, consiliului de administrație, procedura de acces în unitatea de învățământ al persoanelor din afara acesteia, inclusiv al reprezentanților mass-mediei, precum și procedura de acces a părinților/reprezentanților legali ai beneficiarilor primari, în condițiile stabilite prin regulamentul de organizare și funcționare a unității de învățământ și regulamentul de ordine interioară a unității de învățământ; procedura de acces în unitatea de învățământ se afișează, la loc vizibil, la intrarea în unitatea de învățământ. Reprezentanții instituțiilor cu drept de îndrumare și control asupra unităților de învățământ, precum și persoanele care participă la procesul de monitorizare și evaluare a calității sistemului de învățământ au acces neîngrădit în unitatea de învățământ;\nz) supune, spre aprobare, consiliului de administrație, procedura de sesizare a suspiciunilor și faptelor de violență la nivelul unității de învățământ precum și metoda de sesizare confidențială a suspiciunilor și cazurilor de violență la nivelul unității de învățământ, în condițiile stabilite prin regulamentul de ordine interioară a unității de învățământ; procedura și metoda de sesizare a suspiciunilor și cazurilor de violență se afișează, la loc vizibil, la intrarea în unitatea de învățământ; aa) asigură implementarea hotărârilor consiliului de administrație; bb) propune spre aprobare consiliului de administrație suspendarea cursurilor la nivelul unor formațiuni de studiu – grupe/clase sau la nivelul unității de învățământ, în situații obiective, cum ar fi epidemii, intemperii, calamități, alte situații excepționale; cc) coordonează activitățile realizate prin intermediul tehnologiei și al internetului la nivelul unității de învățământ și stabilește, în acord cu profesorii diriginți și cadrele didactice, modalitatea de valorificare a acestora; dd) asigură implementarea sarcinilor legate de proiectele cu finanțare nerambursabilă în cadrul cărora unitatea de învățământ este aplicant/lider/coordonator sau partener, desemnând,\nprin decizii interne, componența echipelor de implementare; ee) sprijină participarea cadrelor didactice la mobilități cu scop de învățare, desfășurate în cadrul programelor UE de educație și formare profesională, prin asigurarea suplinirii pe perioada mobilității, utilizând resurse financiare din finanțarea complementară; ff) sprijină participarea beneficiarilor primari la mobilități cu scop de învățare, desfășurate în cadrul programelor UE de educație și formare profesională și asigură recunoașterea rezultatelor învățării dobândite în timpul stagiului sau perioadei petrecute în străinătate ca fiind echivalentă cu perioada de prezență la activitățile obișnuite ale unității de învățământ; întreprinde măsurile necesare pentru a motiva absențele beneficiarilor primari care participă la astfel de mobilități și pentru a permite recuperarea materiei pierdute, în conformitate cu legislația în vigoare; gg) coordonează managementul cazurilor de violență asupra beneficiarilor primari și asupra personalului la nivelul unității de învățământ; hh) analizează nevoile de accesibilizare a mediului școlar și sesizează autoritățile administrației publice locale privind investițiile necesare asigurării accesului și participării beneficiarilor primari cu dizabilități la procesul educațional; ii) recrutează, cu acordul consiliului de administrație și cu sprijinul CJRAE/CMBRAE, elevi de la liceele pedagogice, clasele a XI-a și a XII-a, aflați în practică individuală sau comasată și studenți de la facultățile de psihologie acreditate, aflați în practică, în vederea asistării în timpul orelor de curs a beneficiarilor primari cu cerințe educaționale speciale (CES) și/sau dizabilități;\njj) inițiază și coordonează colaborarea personalului unității de învățământ cu școlile speciale, centrele școlare de educație incluzivă, instituțiile de protecție socială, furnizorii licențiați și acreditați din domeniul serviciilor sociale și de sănătate, CJRAE/ CMBRAE, instituțiile de protecție socială, furnizorii licențiați și acreditați din domeniul serviciilor sociale și de sănătate, în vederea asigurării nevoilor beneficiarilor primari cu cerințe educaționale speciale integrați; kk) inițiază și coordonează colaborarea personalului unității de învățământ cu organizațiile neguvernamentale, în vederea asigurării nevoilor educaționale specifice beneficiarilor primari cu statut social, economic sau cultural scăzut, remigranți, refugiați, cu cerințe educaționale speciale, cu dizabilități, separați temporar sau definitiv de părinți, din comunități de romi vulnerabile, implicați în migrație sezonieră și alte categorii dezavantajate; ll) poate achiziționa, cu acordul consiliului de administrație, serviciile necesare îndeplinirii obligațiilor legale privind integrarea beneficiarilor primari cu cerințe educaționale speciale în învățământul de masă, costurile fiind acoperite din finanțarea de bază.\n(5) Directorul îndeplinește alte atribuții precizate explicit în fișa postului, stabilite de către consiliul de administrație, potrivit legii, și orice alte atribuții rezultând din prevederile legale în vigoare și contractele colective de muncă aplicabile.\n(6) Pentru realizarea atribuțiilor sale, directorul se consultă cu reprezentanții organizațiilor sindicale reprezentative la nivel de sector de negociere colectivă învățământ preuniversitar care au membri în unitatea de învățământ sau, după caz, cu reprezentanții salariaților din unitatea de învățământ, în conformitate cu prevederile legale.\n(7) Pentru perioada în care directorul nu își poate exercita atribuțiile (concediu de odihnă, delegații și altele asemenea), acesta are obligația de a delega, prin decizie, atribuțiile către directorul adjunct sau, în cazul în care nu există funcția de director adjunct, către un alt cadru didactic titular, de regulă membru al consiliului de administrație.\n(8) Pentru situațiile excepționale (accident, boală și altele asemenea) în care directorul nu poate delega atribuțiile, acesta emite la începutul anului școlar decizia de delegare a atribuțiilor către directorul adjunct sau, în cazul în care nu există funcția de director adjunct, către un cadru didactic membru al consiliului de administrație. Decizia va conține și un supleant, cadru didactic titular. Neîndeplinirea acestor obligații constituie abatere disciplinară și se sancționează conform legii.\n(9) În situațiile în care directorul are calitate procesuală în dosarele aflate pe rolul instanțelor, în contradictoriu cu unitatea la care exercită funcția, acesta își deleagă atribuțiile specifice funcției de conducere directorului adjunct/membrului consiliului de administrație, care asigură reprezentarea intereselor unității de învățământ, precum și semnarea tuturor actelor de procedură necesare, până la finalizarea definitivă a acestor dosare.\n(10) Prin derogare de la prevederile alin. (1) – (5), (7) și (8) în învățământul particular și confesional, persoana juridică fondatoare stabilește structura funcțiilor de conducere, atribuțiile acestora, precum și procedurile de delegare a atribuțiilor."},{"article":"22","articleNumber":22,"legalText":"În exercitarea atribuțiilor și a responsabilităților stabilite în conformitate cu prevederile art. 21, directorul emite decizii, și note de serviciu."},{"article":"23","articleNumber":23,"legalText":"(1) Drepturile și obligațiile directorului unității de învățământ sunt cele prevăzute de legislația în vigoare, de prezentul regulament, de regulamentul de organizare și funcționare a unității de învățământ, de regulamentul de ordine interioară și de contractele colective de muncă aplicabile.\n(2) Perioada concediului anual de odihnă al directorului se aprobă de către inspectorul școlar general.\n(3) Rechemarea din concediul de odihnă a directorilor din unitățile de învățământ preuniversitar se face în caz de forță majoră sau pentru interese urgente care impun prezența acestora la locul de muncă, cu respectarea obligațiilor legale de către angajator, și se dispune prin decizie a inspectorului școlar general."},{"article":"24","articleNumber":24,"legalText":"(1) În activitatea sa, directorul poate fi ajutat de unul, doi sau trei directori adjuncți.\n(2) Se poate norma o funcție de director adjunct pentru:\na) unitățile de învățământ care au peste 30 de formațiuni de studiu;\nb) unitățile de învățământ care au între 20 și 30 de clase și îndeplinesc una dintre condițiile: au cel puțin 10 clase inclusiv din învățământul primar și/sau grupe din învățământul antepreșcolar/preșcolar sau au secții cu predare în limbile minorităților într-o unitate școlară cu predare în limba română sau au secții cu predare în limba română într-o unitate școlară cu predare într-o limbă a minorităților;\nc) unitățile de învățământ care au între 20 și 30 de clase și au internat și cantină;\nd) unitățile de învățământ liceal/postliceal care au peste 25 de clase;\ne) unitățile de învățământ liceal/postliceal care au între 20 și 25 de clase și îndeplinesc una din condițiile: au cel puțin 10 clase din învățământul primar și/sau grupe din învățământul antepreșcolar/preșcolar sau au secții cu predare în limbile minorităților într-o unitate școlară cu predare în limba română sau au secții cu predare în limba română într-o unitate școlară cu predare într-o limbă a minorităților;\nf) unitățile de învățământ liceal/postliceal care au între 20 și 25 de clase și au internat și cantină;\ng) unitățile de învățământ special cu cel puțin 16 clase.\n(3) Se pot norma două funcții de director adjunct pentru unitățile de învățământ de nivel gimnazial, liceal sau postliceal care funcționează cu peste 50 de formațiuni de studiu.\n(4) Se pot norma trei funcții de director adjunct pentru unitățile de învățământ de nivel gimnazial, liceal sau postliceal care funcționează cu peste 70 de formațiuni de studiu sau cu peste 70 de formațiuni de studiu din învățământul antepreșcolar și preșcolar."},{"article":"25","articleNumber":25,"legalText":"(1) Recrutarea pentru ocuparea funcțiilor de director adjunct din unitățile de învățământ de stat se realizează prin concurs național, organizat prin ISJ/ISMB, sub coordonarea Ministerului Educației, potrivit metodologiei aprobate prin ordin al ministrului educației.\n(2) La concursul pentru ocuparea funcțiilor de director adjunct participă personalul didactic de predare titular în învățământul preuniversitar.\n(3) Directorul adjunct, după promovarea concursului, încheie contract de management educațional cu inspectorul școlar general al ISJ/ISMB. Modelul contractului de management educațional este aprobat prin ordin al ministrului educației. Contractul de management educațional poate fi modificat exclusiv prin act adițional, cu acordul părților semnatare.\n(4) Contractul de management educațional poate fi încheiat numai după prezentarea unei evaluări medicale care atestă faptul că persoana este aptă pentru funcția vizată.\n(5) Pe perioada exercitării mandatului, directorul adjunct nu poate deține, conform legii, funcția de președinte sau vicepreședinte în structurile de conducere ale partidelor politice, la nivel local, județean/al municipiului București sau național, funcția de primar, viceprimar, președinte sau vicepreședinte de consiliu județean/al Consiliului General al Municipiului București sau orice funcție de conducere în organizațiile sindicale.\n(6) Nu poate ocupa/exercita o funcție de conducere la nivelul unităților de învățământ preuniversitar persoana care a fost condamnată penal definitiv pentru săvârșirea cu intenție a unei infracțiuni contra vieții, integrității corporale sau sănătății, contra libertății persoanei, rele tratamente aplicate minorului, hărțuire, trafic de minori, proxenetism, infracțiuni contra libertății și integrității sexuale, luare și dare de mită, trafic de influență, fals și uz de fals, furt calificat, pentru care nu a intervenit reabilitarea.\n(7) Directorul adjunct al unității de învățământ de stat, numit în urma concursului național, poate fi eliberat din funcție:\na) la propunerea motivată a inspectorului școlar general al ISJ/ISMB, cu avizul consiliului de administrație al ISJ/ISMB;\nb) la propunerea motivată a 2/3 dintre membrii consiliului de administrație al unității de învățământ urmată de un raport de evaluare a activității directorului adjunct, realizat de către o comisie constituită la nivelul ISJ/ISMB, decizia finală aparținând consiliului de administrație al inspectoratului școlar;\nc) la propunerea consiliului profesoral, cu votul secret a 2/3 dintre membri. În această situație, este obligatorie realizarea unui audit de către ISJ/ISMB. Rezultatele auditului se analizează în consiliul de administrație al ISJ/ISMB. În funcție de hotărârea consiliului de administrație al ISJ/ISMB, inspectorul școlar general emite decizia de eliberare din funcție a directorului adjunct al unității de învățământ;\nd) pentru încălcarea cu vinovăție a obligațiilor stabilite prin contractul de management, cu respectarea procedurii de cercetare disciplinară prevăzută de Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare.\n(8) Eliberarea din funcție a directorului adjunct al unității de învățământ liceal militar se face cu respectarea legislației în vigoare și cu avizul Ministerului Apărării Naționale.\n(9) În funcțiile de director adjunct rămase vacante în urma organizării concursului sau în cazul vacantării funcției de director adjunct din unitățile de învățământ preuniversitar de\nstat, conducerea interimară este asigurată, până la organizarea concursului, dar nu mai târziu de sfârșitul anului școlar, de un cadru didactic titular, numit prin detașare în interesul învățământului, prin decizia inspectorului școlar general, cu avizul consiliului de administrație al ISJ/ISMB și cu acordul scris al persoanei solicitate.\n(10) Anterior solicitării avizului consiliului de administrație al ISJ/ISMB, potrivit alin.\n(9), inspectorul școlar general consultă consiliul profesoral al unității de învățământ, de regulă până la încheierea cursurilor anului școlar, în perioada de activitate a cadrelor didactice.\n(11) În cazul în care nu se poate asigura numirea prin detașare în interesul învățământului, conducerea interimară va fi asigurată de un cadru didactic membru al consiliului de administrație din unitatea de învățământ, cu acordul acestuia, căruia i se deleagă atribuțiile specifice funcției de conducere, până la organizarea concursului, dar nu mai mult de 60 de zile calendaristice și fără a depăși sfârșitul anului școlar. În această ultimă situație, în baza avizului consiliului de administrație al ISJ/ISMB, inspectorul școlar general emite decizie de delegare a atribuțiilor specifice funcției.\n(12) Asigurarea conducerii unei unități de învățământ preuniversitar particular, până la organizarea concursului, dar nu mai mult de sfârșitul anului școlar, se poate realiza de personalul didactic de predare care se distinge prin calități profesionale, manageriale și morale, după cum urmează:\na) prin numirea în funcția de conducere de către persoana juridică finanțatoare, la propunerea consiliului de administrație al unității de învățământ particular, a unui cadru didactic din cadrul respectivei unități de învățământ sau a unui cadru didactic pensionat; actul de numire se aduce la cunoștința ISJ/ISMB pe raza căruia își desfășoară activitatea unitatea școlară;\nb) prin detașarea în interesul învățământului a cadrelor didactice titulare în învățământul preuniversitar de stat sau a cadrelor didactice titulare în alte unități de învățământ particular, la propunerea conducerii persoanei juridice finanțatoare și cu acordul scris al persoanelor solicitate, prin decizie a ISJ/ISMB.\n(13) Directorul adjunct al unității de învățământ particular poate fi eliberat din funcție prin decizia persoanei juridice fondatoare."},{"article":"26","articleNumber":26,"legalText":"(1) Directorul adjunct își desfășoară activitatea în baza contractului de management încheiat și îndeplinește atribuțiile stabilite prin fișa postului, anexă la contractul de management, precum și atribuțiile delegate de director pe perioade determinate.\n(2) Directorul adjunct exercită, prin delegare, în condițiile art. 21 alin. (7) și (8), toate atribuțiile directorului, în lipsa acestuia."},{"article":"27","articleNumber":27,"legalText":"(1) Perioada concediului anual de odihnă al directorului adjunct se aprobă de către directorul unității de învățământ.\n(2) Rechemarea din concediu a directorului adjunct se poate realiza de către directorul unității de învățământ sau de către inspectorul școlar general al ISJ/ISMB, cu respectarea obligațiilor legale de către angajator."},{"article":"28","articleNumber":28,"legalText":"(1) Pentru optimizarea managementului unității de învățământ, conducerea acesteia elaborează documente manageriale, astfel:\na) documente de diagnoză;\nb) documente de prognoză;\nc) documente de evidență.\n(2) În funcție de resursele existente la nivelul unității de învățământ, documentele manageriale menționate la alin. (1), precum și alte documente elaborate de comisiile constituite la nivelul unității de învățământ vor fi stocate în format digital. Validarea acestor documente se poate face și prin semnătură electronică."},{"article":"29","articleNumber":29,"legalText":"(1) Documentele de diagnoză ale unității de învățământ sunt:\na) rapoartele anuale ale comisiilor și compartimentelor din unitatea de învățământ;\nb) raportul anual asupra calității educației din unitatea de învățământ;\nc) raportul anual de evaluare internă a calității.\n(2) Conducerea unității de învățământ poate elabora și alte documente de diagnoză privind domenii specifice de interes, care să contribuie la dezvoltarea instituțională și la atingerea obiectivelor educaționale."},{"article":"30","articleNumber":30,"legalText":"(1) Raportul anual asupra calității educației se întocmește de către director și directorul adjunct/directorii adjuncți, după caz.\n(2) Raportul anual asupra calității educației se analizează, se dezbate și se validează de către consiliul profesoral și se aprobă de către consiliul de administrație, la propunerea directorului, în primele patru săptămâni de la începutul anului școlar.\n(3) Raportul se prezintă de către director în fața consiliului profesoral, a consiliului școlar al beneficiarilor primari, a consiliului reprezentativ al părinților/reprezentanților legali și a conducerii asociației de părinți, acolo unde există."},{"article":"31","articleNumber":31,"legalText":"Raportul anual asupra calității educației este adus la cunoștința autorităților administrației publice locale și a ISJ/ISMB și postat pe site-ul unității de învățământ și prin orice altă formă de comunicare publică existentă la nivelul unității școlare."},{"article":"32","articleNumber":32,"legalText":"(1) Raportul anual de evaluare internă (RAEI) se întocmește de către comisia pentru evaluarea și asigurarea calității educației, se prezintă, spre analiză și validare consiliului profesoral și se aprobă de către consiliul de administrație, la propunerea coordonatorului comisiei, și se prezintă, spre analiză, consiliului profesoral.\n(2) Raportul anual de evaluare internă este adus la cunoștință tuturor beneficiarilor prin afișare sau publicare."},{"article":"33","articleNumber":33,"legalText":"(1) Documentele de prognoză ale unității de învățământ realizate pe baza documentelor de diagnoză ale perioadei anterioare sunt:\na) planul de dezvoltare instituțională, respectiv planul de acțiune al școlii (PAS) pentru învățământul profesional și tehnic/ învățământul preuniversitar tehnologic, inclusiv în sistem dual;\nb) planul managerial;\nc) programul de dezvoltare a sistemului de control intern managerial.\n(2) Directorul poate elabora și alte documente de prognoză, în scopul optimizării managementului unității de învățământ.\n(3) Documentele de prognoză se postează pe site-ul unității de învățământ și se transmit, în format electronic, consiliului reprezentativ al părinților/reprezentanților legali și conducerii asociației de părinți, acolo unde există, fiind documente care conțin informații de interes public."},{"article":"34","articleNumber":34,"legalText":"(1) Planul de dezvoltare instituțională constituie documentul de prognoză pe termen lung și se elaborează de către o echipă coordonată de către director, pentru o perioadă de 3 – 5 ani. Acesta conține:\na) prezentarea unității: istoric și starea actuală a resurselor umane, materiale și financiare, relația cu comunitatea locală și organigramă;\nb) analiza de nevoi, alcătuită din analiza de tip SWOT și analiza de tip PESTE;\nc) viziunea, misiunea și obiectivele strategice ale unității;\nd) planificarea tuturor activităților unității de învățământ, respectiv activități manageriale, obiective, termene, stadii de realizare, resurse necesare, responsabilități, indicatori de performanță și evaluare.\n(2) Planul de acțiune al școlii (PAS) pentru unitățile de învățământ profesional și tehnic/ învățământul preuniversitar tehnologic în sistem dual corelează oferta educațională și de formare profesională cu nevoile de dezvoltare socioeconomică la nivel local, județean și regional, stabilite prin Planul regional de acțiune pentru învățământ (PRAI) și Planul local de acțiune pentru învățământ (PLAI).\n(3) Planul de acțiune al școlii (PAS) se realizează în baza ghidului de elaborare emis de către Centrul Național de Dezvoltare a Învățământului Profesional și Tehnic.\n(4) Planul de dezvoltare instituțională, respectiv planul de acțiune al școlii se dezbate și se avizează de către consiliul profesoral și se aprobă de către consiliul de administrație. Planificarea strategică, respectiv planul de acțiune al școlii, pentru unitățile de învățământ preuniversitar cu personalitate juridică care școlarizează în învățământ profesional și tehnic/învățământul preuniversitar tehnologic, inclusiv în sistem dual este elaborat, pentru o perioadă de 3 – 5 ani, de către o echipă coordonată de către director, în colaborare cu partenerii unității de învățământ, și se aprobă de către consiliul de administrație.\n(5) Stadiul atingerii obiectivelor strategice incluse în cadrul documentelor de prognoză pe termen lung (PDI/PAS) este evaluat anual și, după caz, echipa coordonată de către director care a elaborat aceste documente poate propune revizuirea/reactualizarea activităților corespunzătoare acestora;\n(6) În cazul în care se propune o revizuire a activităților, aceasta este corelată cu propunerea de revizuire corespunzătoare a celorlalte componente PDI/PAS.\n(7) Propunerea de revizuire se dezbate și se avizează de către consiliul profesoral și se aprobă de către consiliul de administrație, devenind anexă la PDI/PAS."},{"article":"35","articleNumber":35,"legalText":"(1) Planul managerial constituie documentul de acțiune pe termen scurt și se elaborează de către director pentru o perioadă de un an școlar.\n(2) Planul managerial conține adaptarea direcțiilor de acțiune ale ministerului și inspectoratului școlar la specificul unității, precum și a obiectivelor strategice ale planului de dezvoltare instituțională la perioada anului școlar respectiv.\n(3) Planul managerial conține toate activitățile din cadrul proiectelor naționale inițiate de Ministerul Educației și din proiectele europene din cadrul programelor UE în domeniul educației și formării profesionale pe care unitatea de învățământ le derulează în acel an.\n(4) Planul managerial se dezbate și se avizează de către consiliul profesoral și se aprobă de către consiliul de administrație.\n(5) Directorul adjunct întocmește propriul plan managerial conform fișei postului, în concordanță cu planul managerial al directorului și cu planul de dezvoltare instituțională/ planul de acțiunii al școlii, care se aprobă de către consiliul de administrație."},{"article":"36","articleNumber":36,"legalText":"Directorul ia măsurile necesare, în conformitate cu legislația în vigoare, pentru elaborarea și/sau dezvoltarea sistemului de control intern managerial, inclusiv a procedurilor formalizate pe activități. Planul de dezvoltare a sistemului de control intern managerial va cuprinde obiectivele, acțiunile, responsabilitățile, termenele, precum și alte componente."},{"article":"37","articleNumber":37,"legalText":"Documentele manageriale de evidență sunt:\na) statul de funcții;\nb) organigrama unității de învățământ;\nc) schema orară a unității de învățământ/programul zilnic al unității de învățământ antepreșcolar/preșcolar;\nd) planul de școlarizare."},{"article":"38","articleNumber":38,"legalText":"(1) În unitățile de învățământ, personalul este format din personal didactic de conducere, didactic de predare și de instruire practică, didactic auxiliar și personal administrativ.\n(2) Selecția personalului didactic, a celui didactic auxiliar și a celui administrativ din unitățile de învățământ se face conform normelor specifice fiecărei categorii de personal.\n(3) Angajarea personalului didactic de predare, didactic auxiliar și administrativ în unitățile de învățământ cu personalitate juridică se realizează prin încheierea contractului individual de muncă cu unitatea de învățământ, prin reprezentantul său legal."},{"article":"39","articleNumber":39,"legalText":"(1) Drepturile și obligațiile personalului din învățământ sunt cele prevăzute de reglementările legale în vigoare.\n(2) Personalul din învățământul preuniversitar trebuie să îndeplinească condițiile de studii cerute pentru postul ocupat și să fie apt din punct de vedere medical.\n(3) Personalul din învățământul preuniversitar trebuie să aibă o ținută morală demnă, în concordanță cu valorile pe care trebuie să le transmită beneficiarilor primari, o vestimentație decentă și un comportament responsabil.\n(4) Personalului din învățământul preuniversitar îi este interzis să desfășoare și să încurajeze acțiuni de natură să afecteze imaginea publică a beneficiarului primar și viața intimă, privată sau familială a acestuia sau ale celorlalți salariați din unitate.\n(5) Personalului din învățământul preuniversitar îi este interzis să aplice pedepse corporale, precum și să agreseze verbal, fizic sau emoțional beneficiarii primari și/sau colegii.\n(6) Personalului didactic de predare din învățământul preuniversitar îi este interzis să desfășoare activități de pregătire suplimentară/meditații contracost cu beneficiarii primari de la clasa/clasele la care este încadrat în anul școlar în curs, conform procedurii pentru completarea declarațiilor de interese de către personalul didactic de predare, aprobată prin ordin al ministrului educației.\n(7) Personalul din învățământul preuniversitar are obligația de a veghea la siguranța beneficiarilor primari, pe parcursul desfășurării programului școlar și a activităților școlare, extracurriculare/ extrașcolare.\n(8) Personalul din învățământul preuniversitar are obligația să sesizeze, după caz, instituțiile publice de asistență socială/educațională specializată, direcția generală de asistență socială și protecția copilului în legătură cu orice încălcări ale drepturilor beneficiarilor primari, inclusiv în legătură cu aspecte care le afectează demnitatea, integritatea fizică și psihică."},{"article":"40","articleNumber":40,"legalText":"(1) Structura de personal și organizarea acestuia se stabilesc prin organigramă, prin statele de funcții și prin proiectul de încadrare ale fiecărei unități de învățământ.\n(2) Prin organigrama unității se stabilesc: structura de conducere și ierarhia internă, organismele consultative, comisiile și celelalte colective de lucru, compartimentele de specialitate sau alte structuri funcționale prevăzute de legislația în vigoare.\n(3) Organigrama se propune de către director la începutul fiecărui an școlar, se aprobă de către consiliul de administrație și se înregistrează la secretariatul unității de învățământ."},{"article":"41","articleNumber":41,"legalText":"Coordonarea activității structurilor unităților de învățământ se realizează de către un coordonator numit, de regulă, dintre cadrele didactice titulare, prin hotărâre a consiliului de administrație, la propunerea directorului."},{"article":"42","articleNumber":42,"legalText":"Personalul didactic auxiliar și administrativ este organizat în compartimente de specialitate care se află în subordinea directorului/directorului adjunct, în conformitate cu organigrama unității de învățământ."},{"article":"43","articleNumber":43,"legalText":"La nivelul fiecărei unități de învățământ funcționează, de regulă, următoarele compartimente: secretariat, financiar, administrativ, precum și alte compartimente sau servicii, potrivit legislației în vigoare."},{"article":"44","articleNumber":44,"legalText":"Personalul didactic are drepturile și obligațiile prevăzute de legislația în vigoare și de contractele colective de muncă aplicabile."},{"article":"45","articleNumber":45,"legalText":"Pentru încadrarea și menținerea în funcție, personalul didactic are obligația să prezinte un certificat medical, eliberat de medicul specializat de medicina muncii, care atestă că este apt pentru prestarea activității în învățământ, precum și cazierul judiciar și certificatul de integritate comportamentală."},{"article":"46","articleNumber":46,"legalText":"Personalul didactic are obligația de a participa la activități de formare continuă, în condițiile legii."},{"article":"47","articleNumber":47,"legalText":"(1) În unitățile de învățământ, cu excepția nivelului antepreșcolar/preșcolar, se organizează serviciul pe școală, pe durata desfășurării cursurilor. Atribuțiile personalului didactic de predare în timpul efectuării serviciului pe școală sunt stabilite prin regulamentul de organizare și funcționare a unității de învățământ.\n(2) În cazul în care un cadru didactic își desfășoară activitatea în mai multe unități de învățământ, acesta va efectua serviciul pe școală într-o singură unitate de învățământ, la alegere, cu acordul conducerii acesteia.\n(3) Pentru asigurarea incluziunii beneficiarilor primari cu cerințe educaționale speciale, personalul didactic colaborează în activitatea didactică la clasă cu profesori itineranți și de sprijin, profesori consilieri școlari, profesori logopezi."},{"article":"48","articleNumber":48,"legalText":"(1) Personalul administrativ are drepturile și obligațiile prevăzute de legislația în vigoare și de contractele colective de muncă aplicabile.\n(2) Organizarea și desfășurarea concursului de ocupare a posturilor administrative dintr-o unitate de învățământ sunt coordonate de director. Consiliul de administrație al unității de învățământ aprobă comisiile de concurs și validează rezultatele concursului.\n(3) Angajarea personalului administrativ în unitățile de învățământ cu personalitate juridică se face de către director, cu aprobarea consiliului de administrație, prin încheierea contractului individual de muncă.\n(4) Pentru încadrarea și menținerea în funcție, personalul administrativ are obligația să prezinte un certificat medical, eliberat de medicul specializat de medicina muncii, care atestă că este apt pentru prestarea activității în domeniul vizat, precum și cazierul judiciar și certificatul de integritate comportamentală."},{"article":"49","articleNumber":49,"legalText":"(1) Activitatea personalului administrativ este coordonată, de regulă, de administratorul de patrimoniu.\n(2) Programul personalului administrativ se stabilește de către administratorul de patrimoniu potrivit nevoilor unității de învățământ și se aprobă de către directorul/directorul adjunct al unității de învățământ.\n(3) Administratorul de patrimoniu stabilește sectoarele de lucru ale personalului de îngrijire. În funcție de nevoile unității, directorul poate solicita administratorului de patrimoniu schimbarea acestor sectoare.\n(4) Administratorul de patrimoniu nu poate folosi personalul subordonat în alte activități decât cele necesare unității de învățământ.\n(5) Administratorul de patrimoniu sau, în lipsa acestuia, altă persoană din cadrul compartimentului administrativ, desemnată de către director, verifică periodic, în limita competențelor, elementele bazei materiale a unității de învățământ, în vederea asigurării securității beneficiarilor primari/personalului din unitate."},{"article":"50","articleNumber":50,"legalText":"Evaluarea personalului se face conform legislației în vigoare și contractelor colective de muncă aplicabile."},{"article":"51","articleNumber":51,"legalText":"(1) Evaluarea personalului didactic și didactic auxiliar se realizează în baza fișelor de evaluare aduse la cunoștință la începutul anului școlar.\n(2) Evaluarea personalului administrativ se realizează în perioada 1 – 31 ianuarie a fiecărui an, pentru anul calendaristic anterior.\n(3) Conducerea unității de învățământ va comunica în scris personalului didactic/didactic auxiliar/administrativ rezultatul evaluării conform fișei specifice."},{"article":"52","articleNumber":52,"legalText":"Personalul didactic răspunde disciplinar conform legii."},{"article":"53","articleNumber":53,"legalText":"Personalul administrativ răspunde disciplinar în conformitate cu prevederile Legii nr. 53/2003 – Codul muncii, republicată, cu modificările și completările ulterioare."},{"article":"54","articleNumber":54,"legalText":"Consiliul profesoral este format din totalitatea cadrelor didactice dintr-o unitate de învățământ. Președintele consiliului profesoral este directorul.\nConsiliul profesoral se întrunește lunar sau de câte ori este nevoie, la propunerea directorului sau la solicitarea a minimum 1/3 din numărul cadrelor didactice.\nCadrele didactice au dreptul să participe la toate ședințele consiliilor profesorale din unitățile de învățământ unde își desfășoară activitatea și au obligația de a participa la ședințele consiliului profesoral din unitatea de învățământ unde declară, în scris, la începutul fiecărui an școlar, că au norma de bază. Absența nemotivată de la ședințele consiliului profesoral din unitatea de învățământ unde are norma de bază se consideră abatere disciplinară și se sancționează conform legii.\nCvorumul necesar pentru întrunirea în ședință a consiliului profesoral este de 2/3 din numărul total al membrilor, cadre didactice cu norma de bază în unitatea de învățământ.\nHotărârile se adoptă prin vot deschis sau secret, cu cel puțin jumătate plus unu din numărul total al membrilor consiliului profesoral cu norma de bază în unitate, și sunt obligatorii pentru personalul unității de învățământ, precum și pentru beneficiarii primari, părinți/reprezentanți legali. Modalitatea de vot se stabilește la începutul ședinței.\nDirectorul unității de învățământ numește, prin decizie, atât componența consiliului profesoral, cât și secretarul acestuia, ales de consiliul profesoral. Secretarul are atribuția de a redacta lizibil și inteligibil procesele-verbale ale ședințelor consiliului profesoral.\nLa ședințele consiliului profesoral, directorul poate invita, în funcție de tematica dezbătută, personalul didactic auxiliar și/sau personalul administrativ din unitatea de învățământ, reprezentanți desemnați ai părinților/reprezentanților legali, ai consiliului beneficiarilor primari, ai autorităților administrației publice locale și ai operatorilor economici și ai altor parteneri educaționali. La ședințele consiliului profesoral pot participa și reprezentanții organizațiilor sindicale afiliate federațiilor sindicale reprezentative la nivel de sector de negociere colectivă învățământ preuniversitar care au membrii în unitatea de învățământ.\nÎn procesele-verbale ale ședințelor consiliului profesoral, secretarul acestuia consemnează:\nprezența membrilor consiliului profesoral la ședințe;\nprezentarea ordinii de zi a ședințelor de către președintele consiliului profesoral, respectiv aprobarea ordinii de zi de către membrii consiliului profesoral;\nrezultatul votului privind aprobarea/respingerea celor propuse, prin indicarea numărului de voturi \"pentru\", numărului de voturi \"împotrivă\" și a numărului de abțineri;\nintervențiile pe care le au membrii consiliului profesoral și invitații în timpul ședinței\nrespective;\nasigurarea cvorumului.\nNumele și semnăturile olografe ale participanților la ședințe sunt consemnate la sfârșitul procesului-verbal al fiecărei ședințe; președintele consiliului profesoral semnează, după membri, pentru certificarea celor consemnate în procesele-verbale.\nProcesele-verbale se scriu în registrul de procese-verbale al consiliului profesoral. Registrul de procese-verbale se numerotează pe fiecare pagină și se înregistrează. Pe ultima pagină, directorul unității de învățământ semnează pentru certificarea numărului paginilor registrului și aplică sigiliul unității de învățământ.\nRegistrul de procese-verbale al consiliului profesoral este însoțit de un dosar care conține anexele proceselor-verbale (rapoarte, programe, informări, tabele, liste, solicitări, memorii, sesizări etc.), numerotate și îndosariate pentru fiecare ședință. Registrul și dosarul se păstrează într-un fișet securizat, ale cărui chei se găsesc la secretarul și la directorul unității de învățământ.\nȘedințele consiliului profesoral se pot desfășura, după caz, în format hibrid sau online, prin mijloace electronice de comunicare, în sistem de videoconferință, conform unei proceduri stabilite la nivelul unității de învățământ."},{"article":"55","articleNumber":55,"legalText":"Consiliul profesoral are următoarele atribuții:\nanalizează, dezbate și validează raportul privind calitatea învățământului din unitatea de învățământ, care se face public;\nalege, prin vot secret, reprezentanții personalului didactic în consiliul de administrație;\ngestionează și asigură calitatea actului didactic;\nstabilește și monitorizează aplicarea Codului de etică profesională elaborat în conformitate cu Codul-cadru de etică profesională aprobat prin ordin al ministrului educației;\npropune consiliului de administrație premierea și acordarea titlului de \"Profesorul anului\" personalului didactic de predare cu rezultate deosebite la catedră;\npropune consiliului de administrație inițierea procedurii legale pentru încălcări ale eticii profesionale de către cadrele didactice, personalul didactic auxiliar și personalul de conducere, după caz;\ndezbate, avizează și propune consiliului de administrație, spre aprobare, planul de dezvoltare instituțională al unității de învățământ;\ndezbate și aprobă rapoartele de activitate anuale, precum și eventuale completări sau modificări ale acestora;\naprobă raportul privind situația școlară anuală prezentată de fiecare învățător/institutor/ profesor pentru învățământ primar/profesor-diriginte, precum și situația școlară după încheierea sesiunilor de amânări, diferențe și corigențe;\naprobă sancțiunile disciplinare aplicate beneficiarilor primari care săvârșesc abateri, potrivit prevederilor statutului elevului, ale prezentului regulament și ale regulamentului de organizare și funcționare a unității de învățământ;\npropune acordarea recompenselor pentru elevi și pentru personalul didactic din unitatea de învățământ, conform reglementărilor în vigoare;\npropune consiliului de administrație programe de formare și dezvoltare profesională continuă pentru cadrele didactice;\nvalidează mediile la purtare mai mici de 7, respectiv mai mici de 8, în cazul unităților de învățământ cu profil pedagogic, teologic și militar, precum și calificativele la purtare mai mici de \"bine\", pentru elevii din învățământul primar; propune sancțiunile disciplinare ale beneficiarilor primari, în conformitate cu atribuțiile care i-au fost stabilite prin legislația în vigoare;\navizează oferta de curriculumul la decizia elevului din oferta școlii (CDEOȘ) pentru anul școlar următor și o propune spre aprobare consiliului de administrație. În stabilirea listei de opționale, consiliul profesoral va ține cont de numărul și ordinea opțiunilor pentru CDEOȘ exprimate de către preșcolari/elevi și părinți/reprezentanții legali ai acestora;\navizează proiectul planului de școlarizare;\nvalidează, la începutul anului școlar, fișele de autoevaluare ale personalului didactic și didactic auxiliar din unitatea de învățământ, în baza cărora se stabilește calificativul anual;\ndezbate și avizează regulamentul de organizare și funcționare a unității de învățământ și regulamentul de ordine interioară;\ndezbate, la solicitarea ministerului, a inspectoratului școlar sau din proprie inițiativă, proiecte de acte normative și/sau administrative cu caracter normativ, care reglementează activitatea la nivelul sistemului național de învățământ, formulează propuneri de modificare sau de completare a acestora;\ndezbate probleme legate de conținutul sau organizarea procesului educațional din unitatea de învățământ și propune consiliului de administrație măsuri de optimizare a acestuia;\npropune și alege, cadrele didactice membre ale comisiei pentru evaluarea și asigurarea calității, precum și ale altor comisii constituite la nivelul unității de învățământ , în condițiile legii;\nîndeplinește, în limitele legii, alte atribuții stabilite de consiliul de administrație, precum și orice alte atribuții potrivit legislației în vigoare și contractelor colective de muncă aplicabile;\npropune eliberarea din funcție a directorului unității de învățământ, conform legii."},{"article":"56","articleNumber":56,"legalText":"Documentele consiliului profesoral sunt:\ntematica și graficul ședințelor consiliului profesoral;\nconvocatoarele consiliului profesoral/dovezi ale convocării prin mijloace electronice;\nregistrul de procese-verbale al consiliului profesoral, însoțit de dosarul cu anexele proceselor- verbale."},{"article":"57","articleNumber":57,"legalText":"Consiliul clasei funcționează în învățământul primar, gimnazial, liceal, profesional și postliceal și este constituit din totalitatea personalului didactic care predă la clasa respectivă, din cel puțin un părinte delegat al comitetului de părinți al clasei, cu excepția claselor din învățământul postliceal, și, pentru toate clasele, cu excepția celor din învățământul primar, reprezentantul beneficiarilor primari clasei respective, desemnat prin vot secret de către elevii clasei.\nPreședintele consiliului clasei este învățătorul/institutorul/profesorul pentru învățământul primar, respectiv profesorul diriginte, în cazul învățământului gimnazial, liceal, profesional și postliceal.\nConsiliul clasei se întrunește cel puțin o dată, în fiecare interval de cursuri sau ori de câte ori este necesar, la solicitarea învățătorului/institutorului/profesorului pentru învățământul primar, respectiv a profesorului diriginte, a reprezentanților părinților/ reprezentanților legali și ai beneficiarilor primari.\nÎn situații obiective, cum ar fi calamități, intemperii, epidemii, pandemii, alte situații excepționale, ședințele consiliului clasei se pot desfășura, după caz, în format hibrid sau online, prin mijloace electronice de comunicare în sistem de videoconferință."},{"article":"58","articleNumber":58,"legalText":"Consiliul clasei are următoarele atribuții:\nanalizează de cel puțin două ori pe an progresul în învățare și comportamentul fiecărui elev;\nstabilește măsuri de sprijin atât pentru elevii cu dificultăți de învățare sau de comportament, cât și pentru elevii cu rezultate deosebite, contribuind la realizarea și adaptarea periodică a planurilor individualizate de învățare ale beneficiarilor primari;\nstabilește notele/calificativele, respectiv mediile la purtare pentru fiecare elev al clasei, în funcție de frecvența și comportamentul acestora în activitatea școlară și extrașcolară; propune consiliului profesoral validarea notelor mai mici de 7, respectiv mai mici de 8, pentru unitățile de învățământ cu profil pedagogic, teologic și militar, sau a calificativelor mai mici de \"bine\", pentru învățământul primar;\npropune recompense pentru elevii cu rezultate deosebite;\nparticipă la întâlniri cu părinții și elevii ori de câte ori este nevoie, la solicitarea învățătorului/institutorului/profesorului pentru învățământul primar/profesorului diriginte sau a cel puțin 1/3 dintre părinții/ reprezentanții legali ai beneficiarilor primari ai clasei;\nanalizează abaterile disciplinare ale beneficiarilor primari și propune sancțiuni sau soluționează contestațiile unor sancțiuni, în conformitate cu prevederile Statutului elevului, ale prezentului regulament și ale regulamentului de organizare și funcționare a unității de învățământ."},{"article":"59","articleNumber":59,"legalText":"Consiliul clasei se întrunește în prezența a cel puțin 2/3 din totalul membrilor și adoptă hotărâri cu votul a jumătate plus unu din totalul membrilor săi.\nLa sfârșitul fiecărei ședințe a consiliului clasei, toți membrii au obligația să semneze procesul- verbal de ședință. Procesele-verbale se scriu în registrul de procese-verbale ale consiliilor clasei, constituit pe fiecare clasă sau nivel de învățământ. Registrul de procese- verbale se numerotează pe fiecare pagină și se înregistrează. Registrul de procese-verbale al consiliului clasei este însoțit de un dosar care conține anexele proceselor, numerotate și îndosariate pentru fiecare ședință."},{"article":"60","articleNumber":60,"legalText":"Coordonatorul pentru proiecte și programe educative școlare și extrașcolare este, de regulă, un cadru didactic titular, propus de consiliul profesoral și aprobat de către consiliul de administrație, în baza unor criterii specifice aprobate de către consiliul de administrație al unității de învățământ.\nCoordonatorul pentru proiecte și programe educative școlare și extrașcolare coordonează activitatea educativă din unitatea de învățământ, inițiază, organizează și desfășoară activități extracurriculare și extrașcolare la nivelul unității de învățământ, cu diriginții, cu responsabilul comisiei de învățământ primar, cu consiliul reprezentativ al părinților/\nreprezentanților legali și asociația de părinți, acolo unde aceasta există, cu reprezentanți ai consiliului beneficiarilor primari, cu consilierul școlar și cu partenerii guvernamentali și neguvernamentali.\nCoordonatorul pentru proiecte și programe educative școlare și extrașcolare își desfășoară activitatea în baza prevederilor strategiilor Ministerului Educației privind educația formală și nonformală.\nDirectorul unității de învățământ stabilește atribuțiile coordonatorului pentru proiecte și programe educative școlare și extrașcolare, în funcție de prioritățile și specificul unității.\nCoordonatorul pentru proiecte și programe educative școlare și extrașcolare poate fi remunerat suplimentar din fonduri extrabugetare, conform legislației în vigoare.\nÎn unitățile de învățământ preuniversitar care au obținut acreditare Erasmus+ sau, în lipsa acreditării, în unitățile de învățământ în care se derulează mai mult de trei proiecte din cadrul unor programe ale UE în domeniul educației sau formării profesionale, directorul poate numi, după consultarea consiliului profesoral, în baza hotărârii consiliului de administrație, un coordonator pentru proiecte educaționale europene. În cazul in care unitatea de învățământ nu este acreditată sau derulează mai puțin de trei proiecte din cadrul unor programe ale UE în domeniul educației sau formării profesionale, atribuțiile coordonatorului pentru proiecte educaționale europene sunt îndeplinite de coordonatorul pentru proiecte și programe educative școlare și extrașcolare."},{"article":"61","articleNumber":61,"legalText":"Coordonatorul pentru proiecte și programe educative școlare și extrașcolare are următoarele atribuții:\ncoordonează, monitorizează și evaluează activitatea educativă nonformală din unitatea de învățământ;\navizează planificarea activităților din cadrul programului activităților educative ale clasei/grupei;\nelaborează proiectul programului/calendarului activităților educative școlare și extrașcolare ale unității de învățământ, în conformitate cu planul de dezvoltare instituțională, cu direcțiile stabilite de către inspectoratul școlar și minister, cu nevoile și interesele beneficiarilor primari, în urma consultării consiliului reprezentativ al părinților/reprezentanților legali, asociației de părinți, acolo unde există, și a beneficiarilor primari, și îl supune spre aprobare consiliului de administrație;\nelaborează, propune și implementează proiecte de programe educative;\nidentifică tipurile de activități educative extrașcolare care corespund nevoilor și intereselor beneficiarilor primari, precum și posibilitățile de realizare a acestora, prin consultarea beneficiarilor primari, a consiliului reprezentativ al părinților/reprezentanților legali și asociației de părinți, acolo unde există;\nprezintă consiliului de administrație rapoarte anuale privind activitatea educativă și rezultatele acesteia;\ndiseminează informațiile privind activitățile educative derulate în unitatea de învățământ;\nfacilitează implicarea consiliului reprezentativ al părinților/reprezentanților legali și asociației de părinți, acolo unde există, și a partenerilor educaționali în activitățile educative;\nelaborează tematici și propune forme de desfășurare a consultațiilor cu părinții sau reprezentanții legali pe teme educative;\npropune/elaborează instrumente de evaluare a activității educative nonformale desfășurate la nivelul unității de învățământ;\nfacilitează, alături de cadrele didactice coordonatoare de proiecte, mobilitățile cu scop de învățare pentru elevi și cadre didactice, în țară sau în străinătate, în programele UE de educație și formare profesională sau în cadrul unor programe ale partenerilor educaționali, în cazul în care unitatea de învățământ preuniversitar nu are un coordonator pentru proiecte educaționale europene;\nanalizează oferta furnizorilor de educație extrașcolară și înaintează consiliului de administrație propuneri de parteneriat în funcție de resursele existente umane, materiale și financiare existente la nivelul unității de învățământ;\ninițiază și susține colaborarea unității de învățământ cu unitățile de educație extrașcolară din localitate/județ;\nse asigură că rezultatele învățării dobândite de preșcolari/elevi prin participarea la programe și proiecte școlare și extrașcolare sunt recunoscute prin adeverințe, diplome sau certificate acordate de unitățile de învățământ preuniversitar sau partenerii acestora, respectiv sunt incluse în portofoliul educațional al beneficiarului primar.\nsusține cadrele didactice în adaptarea proiectelor și programelor educative școlare și extrașcolare la nevoile beneficiarilor primari cu cerințe educaționale speciale.\norice alte atribuții rezultând din legislația în vigoare.\nPortofoliul coordonatorului pentru proiecte și programe educative școlare și extrașcolare conține:\noferta educațională a unității de învățământ în domeniul activității educative extrașcolare;\nplanul anual al activității educative extrașcolare;\nprograme de parteneriat pentru realizarea de activități educative extrașcolare;\nprograme educative de prevenire și intervenție;\nmodalități de monitorizare și evaluare a activității educative extrașcolare;\nmăsuri de optimizare a ofertei educaționale extrașcolare;\nrapoarte de activitate anuale;\ndocumente care reglementează activitatea extrașcolară, în format letric/electronic, transmise de inspectoratul școlar și minister, privind activitatea educativă extrașcolară.\nPortofoliul menționat la alin. (2) poate fi realizat și stocat și în format electronic."},{"article":"62","articleNumber":62,"legalText":"Coordonatorul pentru proiecte educaționale europene este un cadru didactic titular, propus de consiliul profesoral și aprobat de către consiliul de administrație, în baza unor criterii specifice aprobate de către consiliul de administrație al unității de învățământ.\nCoordonatorul pentru proiecte educaționale europene coordonează activitatea de identificare a surselor de finanțare, informează instituția cu privire la apelurile lansate, participă la scrierea cererilor de finanțare, sprijină implementarea, monitorizează aspecte ale proiectelor implementate la nivelul unității de învățământ.\nCoordonatorul pentru proiecte educaționale europene își desfășoară activitatea în baza prevederilor strategiilor Ministerului Educației privind absorbția fondurilor europene prin Programele finanțate extern – Erasmus +, PNRR, FSE+, alte finanțări.\nDirectorul unității de învățământ stabilește atribuțiile coordonatorului pentru proiecte educaționale europene, în funcție de specificul unității.\nCoordonatorul pentru proiecte educaționale europene are următoarele atribuții:\ncontribuie la realizarea analizei de nevoi instituționale, în corelație cu oportunitățile de finanțare europeană lansate de Comisia Europeana, Ministerul Educației sau alte autorități abilitate – Ministerul Investițiilor și Proiectelor Europene (MIPE), Ministerul Mediului, Agenția Națională pentru Programe Comunitare în Domeniul Educației și Formării Profesionale (ANPCDEFP) etc.;\nstabilește un grafic al accesării fondurilor europene în funcție de documentele oficiale lansate de Comisia Europeană, Ministerul Educației sau alte autorități abilitate – MIPE, Ministerul Mediului, ANPCDEFP, etc.;\nidentifică oportunități de finanțare, elaborează, propune și monitorizează proiecte cu finanțare europeană;\nidentifică tipurile de proiecte europene care corespund nevoilor beneficiarilor primari/ părinților/reprezentanților legali ai acestora/personalului unității de învățământ/comunității școlare, precum și posibilitățile de realizare a acestora, prin consultarea conducerii și personalului unității de învățământ, a beneficiarilor primari ai educației, a consiliului reprezentativ al părinților și asociației de părinți, acolo unde există;\nfacilitează, la nivelul unității de învățământ, organizarea concursurilor și competițiilor cu tematică europeană;\nfacilitează mobilități cu scop de învățare pentru elevi și cadre didactice în țară și în străinătate, desfășurate în cadrul proiectelor educaționale europene;\ndiseminează la nivel local, județean, regional, național rezultatele proiectelor educaționale europene derulate în unitatea de învățământ;\npropune/elaborează instrumente de monitorizare, evaluare și raportare a proiectelor desfășurate la nivelul unității de învățământ;\nparticipă la activități organizate de ISJ/ISMB/ANPCDEFP/alte instituții în domeniul programelor educaționale europene;\nprezintă consiliului de administrație rapoarte anuale privind implementarea proiectelor europene, rezultatele și impactul acestora;\nîndeplinește orice alte atribuții rezultând din legislația în vigoare.\nPortofoliul coordonatorului pentru proiecte educaționale europene conține:\nanaliza de nevoi a unității de învățământ;\ndocumentația specifică pentru scrierea și implementarea proiectelor care pot fi accesate pentru unitățile de învățământ și coordonatele de accesare a platformelor IT corespunzătoare;\napeluri, ghiduri pentru finanțare relevante pentru tipurile de proiecte care pot fi accesate pentru unitățile de învățământ și alte documente care reglementează accesarea fondurilor europene/implementarea proiectelor, în format letric/electronic, transmise de ISJ/ ISMB/ME/MIPE/ANPCDEFP/Biroul de Legătură al Parlamentului European/Reprezentanța Comisiei Europene în România, alte instituții/organizații;\nschițe de proiect și cereri de finanțare depuse;\nmodalități și instrumente de monitorizare și evaluare a proiectelor implementate;\nrapoarte de activitate anuale.\nPortofoliul menționat la alin. (6) poate fi realizat și stocat și în format electronic."},{"article":"63","articleNumber":63,"legalText":"Inspectoratul școlar stabilește o zi metodică pentru coordonatorii pentru proiecte și programe educative școlare și extrașcolare și pentru coordonatorul pentru proiecte educaționale europene.\nActivitatea desfășurată de coordonatorul pentru proiecte și programe educative școlare și extrașcolare, respectiv activitatea desfășurată de coordonatorul pentru proiecte educaționale europene se regăsește în raportul anual de activitate, prezentat în consiliul de administrație. Activitatea educativă școlară și extrașcolară și activitatea de gestionare a proiectelor educaționale europene sunt părți ale planului de dezvoltare instituțională a unității de învățământ."},{"article":"64","articleNumber":64,"legalText":"Profesorul diriginte coordonează activitatea clasei din învățământul gimnazial, liceal, profesional și postliceal.\nUn cadru didactic poate îndeplini atribuțiile de profesor diriginte la o singură formațiune de studiu.\nÎn cazul învățământului primar, atribuțiile dirigintelui revin învățătorului/ institutorului/ profesorului pentru învățământul primar.\n(3) În cazul învățământului antepreșcolar și preșcolar, atribuțiile dirigintelui revin educatorului/profesorului pentru educație timpurie."},{"article":"65","articleNumber":65,"legalText":"Profesorii diriginți sunt numiți, anual, de către directorul unității de învățământ, în baza hotărârii consiliului de administrație.\nLa numirea profesorilor diriginți se are în vedere, în măsura posibilităților, principiul continuității, astfel încât clasa să aibă același diriginte pe parcursul unui nivel de învățământ.\nDe regulă, poate fi numit profesor diriginte un cadru didactic titular sau suplinitor care a dobândit definitivarea/licențierea în învățământ, are cel puțin o jumătate din norma didactică în unitatea de învățământ și predă la clasa respectivă."},{"article":"66","articleNumber":66,"legalText":"Activitățile specifice funcției de diriginte sunt prevăzute în fișa postului cadrului didactic.\nProfesorul diriginte realizează anual planificarea activităților conform proiectului de dezvoltare instituțională și nevoilor educaționale ale colectivului de elevi pe care îl coordonează. Planificarea se avizează de către directorul unității de învățământ.\nActivitățile de suport educațional, consiliere și orientare profesională sunt obligatorii\nși sunt desfășurate de profesorul diriginte astfel:\nîn cadrul orelor din aria curriculară consiliere și orientare;\nîn afara orelor de curs, în situația în care în planul-cadru nu este prevăzută ora de consiliere și orientare. În această situație, dirigintele stabilește, consultând colectivul de elevi, un interval orar în care se vor desfășura activitățile de suport educațional, consiliere și orientare profesională, care va fi adus la cunoștință beneficiarilor primari, părinților/reprezentanților legali și celorlalte cadre didactice. Planificarea orei destinate acestor activități se realizează cu aprobarea directorului unității de învățământ, iar ora respectivă se consemnează în condica de prezență.\nProfesorul diriginte desfășoară activități de suport educațional, consiliere și orientare profesională pentru elevii clasei, atât la nivelul întregii clase, pe grupuri, cât și individual. Activitățile se referă la:\nteme stabilite în concordanță cu specificul vârstei, cu interesele sau solicitările beneficiarilor primari, pe baza programelor școlare în vigoare elaborate pentru aria curriculară \"Consiliere și orientare\";\nteme de educație în conformitate cu prevederile actelor normative și ale strategiilor naționale, precum și în baza parteneriatelor încheiate de Ministerul Educației cu alte ministere, instituții și organizații.\nProfesorul diriginte desfășoară, în colaborare cu consilierul școlar și partenerii educaționali, comunitatea locală, activități de consiliere vocațională și de orientare școlară și profesională, pe tot parcursul învățământului gimnazial, vizând aspecte referitoare la:–\nautocunoașterea, autoevaluarea,– lumea muncii: producție, salariu, șomaj, antreprenoriat,– aspecte psiho-sociale, juridice ale muncii,– muncă și comunicare,– explorarea diversității\nprofesiilor, meseriilor etc. din mediul de viață imediat, cel comunitar, regional,– exemple de aplicare a cunoștințelor școlare în viața practică,– luarea deciziilor legate de continuarea studiilor și carieră prin valorificarea informațiilor despre sine, educație și ocupații,–\nimplicarea părinților/reprezentanților legali în consilierea vocațională a beneficiarilor primari,\nProfesorul diriginte, în colaborare cu consilierul școlar și parteneri educaționali, urmărește dezvoltarea și perfecționarea abilităților personale și academice ale beneficiarilor primari prin utilizarea adecvată a portofoliilor acestora, în propria activitate, conectându-i la trasee academice și de carieră prin facilitarea accesului la întreaga ofertă de educație și formare profesională și sprijinirea/susținerea inserției socio-profesionale viitoare a beneficiarilor primari.\nProfesorul diriginte desfășoară activități educative extrașcolare, pe care le stabilește după consultarea beneficiarilor primari și a părinților/reprezentanților legali, în concordanță cu specificul vârstei și nevoilor identificate pentru colectivul de elevi.\nProfesorul diriginte colaborează cu consilierul școlar, mediatorul școlar și mediatorul sanitar pentru consilierea școlară și psihologică a elevelor gravide și a beneficiarilor primari părinți cu privire la drepturile educaționale și la cele privind starea de sănătate.\nProfesorul diriginte monitorizează activitatea colectivului de elevi, colaborează cu profesorul itinerant și de sprijin și informează consiliul de administrație privind barierele întâmpinate de beneficiarii primari cu dizabilități în ceea ce privește accesul și participarea la activitățile curriculare, extracurriculare și extrașcolare.\nLa începutul anului școlar și ori de câte ori se impune, profesorul diriginte informează elevii și părinții/reprezentanții legali privind serviciile (consiliere școlară, logopedie, sprijin educațional, mediere școlară etc.), programele (Burse școlare, Tichete pentru rechizite, Euro 200, Masă sănătoasă, Învățare remedială, Școala la domiciliu etc.) disponibile la nivelul unității de învățământ."},{"article":"67","articleNumber":67,"legalText":"Pentru realizarea unei comunicări constante cu părinții / reprezentanții legali, profesorul diriginte stabilește, în acord cu aceștia, pe perioada fiecărui interval de cursuri, o întâlnire pentru prezentarea situației școlare a beneficiarilor primari, pentru discutarea problemelor educaționale sau comportamentale specifice ale acestora. În situații obiective cum ar fi: calamități, intemperii, epidemii, pandemii, alte situații excepționale, aceste întâlniri se pot desfășura, după caz, în format hibrid sau online, prin mijloace electronice de comunicare, în sistem de videoconferință.\nPlanificarea orelor dedicate întâlnirilor diriginților cu părinții sau reprezentanții legali de la fiecare formațiune de studiu se comunică beneficiarilor primari și părinților/ reprezentanților legali ai acestora și se afișează la avizier sau pe site-ul unității de învățământ.\nÎntâlnirea cu părinții/reprezentanții legali se recomandă a fi individuală, în conformitate cu o programare stabilită în prealabil. La această întâlnire, la solicitarea părintelui/reprezentantului legal sau a dirigintelui, poate participa și elevul."},{"article":"68","articleNumber":68,"legalText":"Profesorul diriginte are următoarele atribuții:\norganizează și coordonează:\nactivitatea colectivului de elevi;\nactivitatea consiliului clasei;\nîntâlniri la care sunt convocați părinții sau reprezentanții legali la începutul și la sfârșitul anului școlar și ori de câte ori este cazul;\nacțiuni de orientare școlară și profesională pentru elevii clasei;\nactivități educative și de consiliere;\nactivități extracurriculare și extrașcolare în unitatea de învățământ și în afara acesteia, inclusiv activitățile realizate prin intermediul tehnologiei și al internetului;\nacțiuni pentru prevenirea consumului de droguri în rândul beneficiarilor primari, inclusiv cele în colaborare cu centrele de prevenire, evaluare si consiliere antidrog;\nactivități de cunoaștere, intercunoaștere și teambuilding/dezvoltare a coeziunii de grup în vederea formării unei culturi bazate pe respect, încredere și susținere reciprocă la nivelul clasei.\nmonitorizează:\nsituația la învățătură a beneficiarilor primari;\nfrecvența la ore a beneficiarilor primari;\nparticiparea și rezultatele beneficiarilor primari la concursurile și competițiile școlare și extrașcolare;\nparticiparea și comportamentul beneficiarilor primari în timpul activităților școlare, extrașcolare și extracurriculare;\nparticiparea beneficiarilor primari la programe sau proiecte și implicarea acestora în activități de voluntariat;\ncolaborează cu:\nprofesorii clasei și coordonatorul pentru proiecte și programe educative școlare și extrașcolare pentru informarea privind activitatea beneficiarilor primari, pentru soluționarea unor situații specifice activităților școlare și pentru toate aspectele care vizează procesul instructiv-educativ, care îi implică pe elevi;\ncabinetele de consiliere școlară, în activități de consiliere și orientare a beneficiarilor primari clasei;\ndirectorul unității de învățământ, pentru organizarea unor activități ale colectivului de elevi, pentru inițierea unor proiecte educaționale cu elevii, pentru rezolvarea unor probleme administrative referitoare la întreținerea și dotarea sălii de clasă, inclusiv în scopul păstrării bazei materiale, pentru soluționarea unor probleme sau situații deosebite, apărute în legătură cu colectivul de elevi;\nasociația și comitetul de părinți, părinții sau reprezentanții legali pentru toate aspectele care vizează activitatea beneficiarilor primari și evenimentele importante la care aceștia participă și cu alți parteneri implicați în activitatea educativă școlară și extrașcolară;\nprofesorii logopezi, pentru referirea și susținerea participării beneficiarilor primari la activități de logopedie;\nprofesorii itineranți și de sprijin pentru incluziunea beneficiarilor primari cu CES în colectivul clasei și pentru organizarea activităților de stimulare, compensare, recuperare și consolidare a competențelor acestora la grupă/clasă sau în afara ei;\nCJRAE/CMBRAE pentru referirea și orientarea școlară a beneficiarilor primari cu CES;\nasistenții sociali/psihologii din cadrul SPAS/DAS/DGASPC pentru referirea cazurilor de violență asupra minorilor, abandon școlar și alte situații care constituie o încălcare a drepturilor copiilor;\nalți parteneri implicați în activitatea educativă școlară și extrașcolară;\ncompartimentul secretariat, pentru acordarea burselor și întocmirea documentelor școlare și a actelor de studii ale beneficiarilor primari clasei;\npersoana desemnată pentru gestionarea SIIIR, în vederea completării și actualizării datelor referitoare la elevi;\ninformează:\nelevii și părinții sau reprezentanții legali despre prevederile regulamentului de\norganizare și funcționare a unităților de învățământ;\nelevii și părinții sau reprezentanții legali cu privire la reglementările referitoare la evaluări și examene și cu privire la alte documente care reglementează activitatea și parcursul școlar al beneficiarilor primari;\npărinții sau reprezentanții legali despre situația școlară, comportamentul beneficiarilor primari, frecvența acestora la ore; informarea se realizează în cadrul întâlnirilor cu părinții sau reprezentanții legali, precum și în scris, ori de câte ori este nevoie;\npărinții sau reprezentanții legali, în cazul în care elevul înregistrează absențe nemotivate; informarea se face în scris; numărul absențelor se stabilește prin regulamentul de organizare și funcționare a fiecărei unități de învățământ;\npărinții sau reprezentanții legali, în scris, referitor la sancționările disciplinare, neîncheierea situației școlare, situațiile de corigență sau repetenție;\nelevii și părinții sau reprezentanții legali cu privire la prevederile procedurii de management a cazurilor de violență.\nîndeplinește alte atribuții stabilite de către conducerea unității de învățământ, în conformitate cu legislația în vigoare sau fișa postului."},{"article":"69","articleNumber":69,"legalText":"Profesorul diriginte mai are și următoarele atribuții:\ncompletează catalogul clasei cu datele de identificare școlară ale beneficiarilor primari (nume, inițiala tatălui, prenume, număr matricol);\nmotivează absențele beneficiarilor primari, în conformitate cu prevederile prezentului regulament și ale regulamentului de organizare și funcționare a unității de învățământ;\npropune, în cadrul consiliului clasei și în consiliul profesoral, nota, respectiv media la purtare a fiecărui elev, în conformitate cu reglementările prezentului regulament;\naduce la cunoștința consiliului profesoral, pentru aprobare, sancțiunile beneficiarilor primari propuse de către consiliul clasei;\npropune/pune în aplicare sancțiunile beneficiarilor primari stabilite în conformitate cu prevederile prezentului regulament și ale statutului elevului;\nîncheie situația școlară a fiecărui elev la sfârșitul anului școlar și o consemnează în catalog și în carnetul de elev;\nrealizează ierarhizarea beneficiarilor primari la sfârșit de an școlar pe baza rezultatelor acestora;\nsprijină elevii majori, părinții/reprezentanții legali ai beneficiarilor primari minori, prin activități de informare și consiliere în procesul de depunere a documentelor necesare pentru acordarea burselor.\ncompletează documentele specifice colectivului de elevi și monitorizează completarea portofoliului educațional al beneficiarilor primari;\nîntocmește calendarul activităților educative extrașcolare ale clasei;\nla finalizarea învățământului gimnazial și liceal, profesorul consilier școlar și dirigintele emit câte o recomandare consultativă de încadrare într-o formă de învățământ de nivel superior, având caracter de orientare școlară pentru fiecare elev în parte. Pentru absolvenții de învățământ liceal se poate realiza și o recomandare sub forma unei orientări vocaționale de încadrare pe piața forței de muncă;\ncentralizează opțiunile pentru CDEOȘ exprimate de către elevi și părinți/reprezentanții legali ai acestora la nivelul fiecărei clase."},{"article":"70","articleNumber":70,"legalText":"Dispozițiile art. 66 – 69 se adaptează și aplică în mod corespunzător și personalului didactic din învățământul preșcolar și primar."},{"article":"71","articleNumber":71,"legalText":"La nivelul fiecărei unități de învățământ funcționează comisii:\ncu caracter permanent;\ncu caracter temporar;\ncu caracter ocazional.\nComisiile cu caracter permanent sunt:\ncomisia pentru curriculum;\ncomisia de evaluare și asigurare a calității;\ncomisia de securitate și sănătate în muncă și pentru situații de urgență;\ncomisia pentru controlul managerial intern, numai pentru unitățile de învățământ de stat;\ncomisia pentru prevenirea și combaterea violenței, a faptelor de corupție și discriminării în mediul școlar și promovarea interculturalității;\ncomisia pentru formare și dezvoltare în cariera didactică.\nComisiile cu caracter permanent își desfășoară activitatea pe tot parcursul anului școlar, comisiile cu caracter temporar își desfășoară activitatea doar în anumite perioade ale anului școlar, iar comisiile cu caracter ocazional sunt înființate ori de câte ori se impune constituirea unei astfel de comisii, pentru rezolvarea unor probleme specifice apărute la nivelul unității de învățământ.\nComisiile cu caracter temporar și ocazional vor fi stabilite de fiecare unitate de învățământ, prin regulamentul de organizare și funcționare a unității de învățământ."},{"article":"72","articleNumber":72,"legalText":"Comisiile de la nivelul unității de învățământ își desfășoară activitatea pe baza deciziei de constituire emise de directorul unității de învățământ. În cadrul comisiilor prevăzute la art. 71 alin. (2) lit. b) și e) sunt cuprinși: reprezentanți ai beneficiarilor primari din învățământul gimnazial cu statut de observatori/ reprezentanți ai beneficiarilor primari din învățământul liceal și postliceal cu statut de membru, reprezentanți ai părinților/ reprezentanților legali, nominalizați de consiliul școlar al elevilor, respectiv consiliul reprezentativ al părinților/reprezentanților legali și asociația de părinți, acolo unde există.\nActivitatea comisiilor din unitatea de învățământ și documentele elaborate de membrii comisiei sunt reglementate prin acte normative sau prin regulamentul de organizare și funcționare a unității de învățământ.\nFiecare unitate de învățământ își elaborează proceduri privind funcționarea comisiilor în funcție de nevoile proprii.\nComisia pentru curriculum se constituie la nivelul unităților de învățământ preuniversitar de stat, în baza hotărârii consiliului de administrație, fiind formată din membrii catedrelor/ comisiilor metodice. Directorul unității de învățământ emite decizia de constituire a Comisiei pentru curriculum.\nActivitatea Comisiei pentru curriculum este coordonată de un responsabil, propus prin vot, de către consiliul profesoral, din rândul personalului didactic de predare titular, cu rezultate deosebite obținute în activitatea didactică.\nNumirea responsabilului comisiei pentru curriculum se face prin decizie a directorului, emisă în baza unei hotărâri a consiliului de administrație, în urma propunerii primite din partea consiliului profesoral.\nÎn cadrul aceleiași unități de învățământ catedrele/comisiile metodice de la nivelul Comisiei pentru curriculum se constituie din cel puțin 4 cadre didactice care își desfășoară activitatea în unitatea de învățământ, după caz, pe arii curriculare, pe discipline de studiu sau pe discipline înrudite.\nÎn unitățile de învățământ de educație timpurie și în învățământul primar catedrele/ comisiile metodice se constituie din cel puțin 4 cadre didactice care își desfășoară activitatea în unitatea de învățământ, după caz, pe grupe, pe ani de studiu, pe grupe de clase sau pe ciclu de învățământ. Catedrele/comisiile metodice se pot constitui și cu 2 sau 3 cadre didactice, în unitățile de învățământ cu un număr mic de cadre didactice care își desfășoară activitatea pe ciclul de învățământ.\nFiecare unitate de învățământ elaborează o procedură privind funcționarea Comisiei pentru curriculum, care include și modul de constituire și funcționare a catedrelelor/comisiilor metodice, în funcție de nevoile proprii.\nAtribuțiile comisiei pentru curriculum vizează activități legate de procesul de proiectare, implementare, monitorizare și evaluare a implementării curriculumului, la nivelul unității de învățământ, precum:\ninițierea și realizarea analizei de nevoi, implicând consultarea beneficiarilor educației, privind oferta curriculară a unității de învățământ, inclusiv a curriculumului la decizia elevului din oferta școlii (CDEOȘ), pentru fiecare an școlar, prin utilizarea metodei de analiză de tip SWOT;\nconsilierea cadrelor didactice în procesul de elaborare a planificării și proiectării didactice;\nmonitorizarea de către responsabilul comisiei pentru curriculum, a modului de aplicare a planurilor – cadru și a programelor școlare, inclusiv prin realizarea de asistențe la ore;\nanalizarea periodică a performanțelor școlare ale beneficiarilor primari și propunerea, după caz, a unor activități remediale care să fie realizate la clasele de elevi;\ncoordonarea organizării de activități de pregătire pentru elevi în vederea participării acestora la examene și concursuri școlare;\nrealizarea la nivelul catedrelor/comisiilor metodice a unor instrumente și resurse educaționale, inclusiv a unor resurse educaționale deschise și a unor instrumente de evaluare și notare;\ncentralizarea, prin responsabilul comisiei, a cursurilor opționale propuse de catedrele/ comisiile metodice, sub forma unei liste care este prezentată pentru a fi dezbătută și avizată de consiliul profesoral și ulterior propusă, spre aprobare, consiliului de administrație al unității de învățământ;\ncoordonarea activităților de prezentare a ofertei de CDEOȘ părinților/reprezentanților legali și beneficiarilor primari;\nanalizarea proiectelor de programă, în vederea acordării de către inspectoratul școlar a avizului de specialitate, pentru disciplinele care fac parte din CDEOȘ, elaborate la nivelul unității de învățământ;\nelaborarea anuală a unui raport privind calitatea ofertei curriculare a unității de învățământ, inclusiv a cursurilor opționale, implementate la nivelul unității de învățământ, prin prelucrarea și interpretarea informațiilor obținute din procesul de monitorizare;\nprezentarea de către responsabilul comisiei pentru curriculum, în consiliul profesoral, a raportului de activitate al comisiei și valorificarea concluziilor și recomandărilor raportului în fundamentarea analizei de nevoi pentru proiectarea ofertei curriculare, inclusiv a CDEOȘ, din anul școlar următor;\nsusținerea cadrelor didactice în ceea ce privește adaptarea planificării școlare și a predării la nivelul de performanță al beneficiarilor primari și la realizarea planurilor individualizate de învățare;\nmonitorizarea nevoii de recuperare a achizițiilor și a desfășurării programului \"Învățare remedială\" la nivelul unității de învățământ;\nmonitorizarea interesului beneficiarilor primari de a studia limba maternă, respectiv\nistoria și cultura minorității căreia îi aparțin și întreprinderea demersurilor necesare pentru a le oferi posibilitatea să le studieze, la cererea acestora sau a reprezentanților legali;\nconstituirea și actualizarea periodică a unei arhive electronice care să cuprindă documente, studii, cercetări, resurse educaționale realizate/avizate de Ministerul Educației, care sprijină aplicarea curriculumului;\nconstituirea și actualizarea periodică a arhivei electronice privind documentele care privesc curriculumul, atât cele elaborate și aprobate la nivel național, cât și cele elaborate și aprobate la nivelul unității de învățământ (planuri-cadru și programe școlare utilizate, inclusiv pentru CDEOȘ).\nComisia pentru formare și dezvoltare în cariera didactică (CFDCD) se constituie la nivelul unităților de învățământ preuniversitar de stat, prin decizie a directorului, fiind formată din 3-7 membri, dintre care unul este responsabilul/coordonatorul comisiei, în baza hotărârii consiliului profesoral.\nMembrii și responsabilii Comisiei pentru formare și dezvoltare în cariera didactică se aleg din rândul personalului didactic de predare titular, prin vot secret, de către consiliul profesoral. Responsabilul nu poate ocupa funcția de director sau director adjunct.\nComponența CFDCD este stabilită anual, prin decizie a conducerii unității de învățământ.\nComisia pentru formare și dezvoltare în cariera didactică identifică nevoile de formare continuă ale personalului didactic, programele și proiectele destinate formării continue a personalului didactic și monitorizează evoluția în carieră a cadrelor didactice, participarea personalului didactic la programe și proiecte de formare continuă.\nAtribuțiile comisiei pentru formare și dezvoltare în cariera didactică sunt următoarele:\nrealizează cartografierea nevoilor de formare continuă ale personalului didactic la nivelul unității de învățământ și le raportează Caselor Corpului Didactic;\nidentifică și informează personalul didactic privind programele și proiectele destinate formării continue;\nelaborează și propune anual consiliului profesoral, spre avizare, planificarea activităților din domeniul formării în cariera didactică, în acord cu nevoile de formare identificate la nivelul unității de învățământ/ local, cu prioritățile stabilite în planul național de formare continuă în cariera didactică și cu profilul profesional al cadrelor didactice;\nplanifică, organizează și desfășoară ateliere, seminarii, lecții predate colaborativ, interasistențe, studii de caz, schimburi de experiență etc, la nivelul unității de învățământ;\norganizează activități specifice de mentorat didactic pentru cadrele didactice debutante, în vederea susținerii examenului național pentru definitivare în învățământul preuniversitar/ de licențiere în cariera didactică;\nsprijină cadrele didactice în dobândirea recunoașterii rezultatelor învățării nonformale, inclusiv a celor dobândite ca urmare a participării la mobilități cu scop de învățare în proiectele finanțate prin programele UE în domeniul educației;\ngestionează sistemul de acumulare a creditelor la nivelul unității de învățământ, evaluând anual stadiul de îndeplinire a condiției de formare pentru personalul didactic, prin actualizarea periodică a bazei de date privind numărul creditelor ECTS (obținute inclusiv prin recunoaștere și echivalare a creditelor profesionale transferabile) acumulat de fiecare cadru didactic pe parcursul ultimilor doi ani de activitate didactică, calculați la data de 31 august;\nmonitorizează impactul formării cadrelor didactice asupra calității procesului de predare- învățare-evaluare și a progresului școlar al beneficiarilor primari, la nivelul unității de învățământ;\ninformează și sprijină personalul didactic în ceea ce privește evoluția în carieră;\nconsiliază personalul didactic în ceea ce privește elaborarea și gestionarea portofoliului profesional;\ncolaborează cu ISJ/ISMB, cu CCD, cu consiliul de administrație și cu consiliul profesoral al unității de învățământ;\nîn baza unor analize de nevoi, colaborează cu celelalte comisii din unitatea de învățământ pentru a elabora programe de formare adaptate și actualizate;\norice alte atribuții rezultând din legislația în vigoare.\nComisia pentru prevenirea și combaterea violenței, a faptelor de corupție și discriminării în mediul școlar și promovarea interculturalității se constituie la nivelul unităților de învățământ preuniversitar de stat, în baza hotărârii consiliului de administrație prin care se aprobă și componența sa nominală. Comisia este formată din:– un director adjunct sau, după caz, coordonatorul pentru proiecte și programe educative școlare și extrașcolare;– 4-6 reprezentanți ai cadrelor didactice, desemnați de Consiliul profesoral;–\n1-3 reprezentanți ai părinților/reprezentanților legali desemnați de consiliul reprezentativ al părinților/reprezentanților legali și asociația de părinți, acolo unde există;– 1-3 elevi desemnați de Consiliul școlar al elevilor;– 1 reprezentant al primarului și 1 reprezentant al consiliului local, membri în Consiliul de administrație al unității de învățământ, cu statut de invitați;– profesorul-consilier școlar și mediatorul școlar, după caz.\nDirectorul unității de învățământ emite decizia de constituire și componența nominală a Comisiei pentru prevenirea și combaterea violenței, a faptelor de corupție și discriminării în mediul școlar și promovarea interculturalității.\nFiecare unitate de învățământ elaborează o procedură privind funcționarea Comisiei pentru prevenirea și combaterea violenței, a faptelor de corupție și discriminării în mediul școlar și promovarea interculturalității, în funcție de nevoile proprii.\nActivitatea comisiei se desfășoară prin raportarea și punerea în aplicare a ansamblului prevederilor legale în vigoare care vizează prevenirea și combaterea violenței, a faptelor de corupție și discriminării și, respectiv, afirmă promovarea interculturalității, în mediul\nșcolar.\nComisia pentru prevenirea și combaterea violenței, a faptelor de corupție și discriminării în mediul școlar și promovarea interculturalității analizează abaterile disciplinare ale beneficiarilor primari care săvârșesc abateri și propune sancțiunile disciplinare aplicate acestora, potrivit prevederilor statutului elevului, prezentului regulament și ale regulamentului de organizare și funcționare a unității de învățământ.\nAtribuțiile comisiei:\nprevenirea și combaterea violenței:– înregistrarea și raportarea la Inspectoratul Școlar Județean/al Municipiului București a cazurilor de violență săvârșite în mediul școlar;–\nanalizarea factorilor școlari care au condus la săvârșirea faptelor de violență, elaborarea, revizuirea și aplicarea Planului de prevenire și reducere a violenței în mediul școlar al unității de învățământ preuniversitar;– realizarea unui raport privind incidența, respectiv prevenirea violenței, pe care îl comunică Comisiei pentru evaluarea și asigurarea calității (CEAC), în vederea includerii acestuia în raportul general privind starea și calitatea învățământului în anul școlar respectiv;– colaborarea cu autoritățile și instituțiile cu atribuții legale în prevenirea, combaterea și managementul cazurilor de violență școlară, inclusiv cu reprezentanții serviciilor publice de asistență socială, ai poliției și ai jandarmeriei;– propunerea unor măsuri specifice, rezultate după analiza factorilor de risc, care să aibă drept consecință creșterea gradului de siguranță a preșcolarilor/beneficiarilor primari și a personalului din unitatea școlară și prevenirea delincvenței juvenile în incinta și în zonele adiacente unității de învățământ;– propunerea, aplicarea și/sau monitorizarea unor măsuri specifice pentru promovarea stării de bine, a unui climat școlar pozitiv și a coeziunii școlare la nivelul unității de învățământ.\nprevenirea și combaterea faptelor de corupție:– îmbunătățirea strategiilor de comunicare pe teme anticorupție, care să ia în calcul potențialele riscuri și vulnerabilități;– asigurarea transparenței în procesul decizional la nivel de unitate de învățământ, inclusiv a modului de utilizare a resurselor bugetare și extrabugetare;– promovarea standardelor etice profesionale și stimularea comportamentului etic;– desfășurarea de acțiuni de promovare a Codului de etică pentru învățământul preuniversitar;– monitorizarea aplicării procedurilor specifice referitoare la conflictul de interese, inclusiv aplicarea ordinului privind completarea declarațiilor de interese de către personalul didactic de predare;– diseminarea de materiale cu rol informativ privind riscurile și consecințele faptelor de corupție sau a incidentelor de integritate;– derularea de programe și campanii de informare și responsabilizare a beneficiarilor primari cu privire la riscurile și consecințele negative ale corupției.\npromovarea principiilor școlii incluzive:– monitorizarea respectării politicilor de promovare a incluziunii, diversității, combaterea discriminării și a segregării școlare;–\nasigurarea faptului că materialele expuse în unitatea de învățământ(ex. tablourile expuse pe pereții unității de învățământ) respectă, recunosc și reflectă cultura, istoria și limba minorităților etnice, naționale și lingvistice ale beneficiarilor primari, părinților/ reprezentanților legali și ale comunității locale;– asigurarea faptului că tradițiile, sărbătorile, evenimentele respectă, recunosc și reflectă diversitatea etnică, lingvistică, religioasă a beneficiarilor primari, a părinților/reprezentanților legali și a comunității locale;– identificarea și analiza cazurilor de discriminare și înaintarea de propuneri pentru soluționarea acestora, consiliului de administrație, directorului unității de învățământ sau consiliului profesoral, după caz;– medierea, după caz, a conflictelor apărute ca urmare a nerespectării principiilor școlii incluzive;– propunerea unor acțiuni specifice, la nivelul claselor sau al unității de învățământ, care să contribuie la cunoașterea și valorizarea celuilalt, la promovarea interculturalității;– consilierea cadrelor didactice în ceea ce privește adaptarea curriculumului la diversitatea etnică, lingvistică, culturală a beneficiarilor primari și a comunității locale.– sesizarea autorităților competente în cazul identificării formelor grave de discriminare;– monitorizarea și evaluarea acțiunilor întreprinse pentru prevenirea și combaterea discriminării și promovarea interculturalității;–\nmonitorizarea respectării legislației privind desegregarea școlară și, după caz, colaborarea la realizarea Planului de desegregare școlară la nivelul unității de învățământ.\noricare alte atribuții care sunt stipulate ca fiind de competența comisiei, incluse în cadrul prevederilor legale în vigoare.\nLa activitățile comisiei poate participa, cu statut de invitat, și un polițist desemnat de către Direcția Generală de Poliție a Municipiului București/Inspectoratele de Poliție Județene."},{"article":"73","articleNumber":73,"legalText":"Compartimentul secretariat cuprinde, după caz, posturile de secretar-șef, secretar și informatician, analist programator.\nCompartimentul secretariat este subordonat directorului.\nSecretariatul funcționează în program de lucru cu elevii, părinții sau reprezentanții legali sau alte persoane interesate din afara unității, aprobat de director, în baza hotărârii consiliului de administrație."},{"article":"74","articleNumber":74,"legalText":"Compartimentul secretariat are următoarele atribuții:\ntransmiterea informațiilor la nivelul unității de învățământ;\nîntocmirea, actualizarea și gestionarea bazelor de date;\nîntocmirea și transmiterea situațiilor statistice și a celorlalte categorii de documente solicitate de către autorități, precum și a corespondenței unității;\nînscrierea copiilor/beneficiarilor primari pe baza dosarelor personale, păstrarea, organizarea și actualizarea permanentă a evidenței acestora și rezolvarea problemelor privind mișcarea beneficiarilor primari, în baza hotărârilor consiliului de administrație;\nrezolvarea problemelor specifice pregătirii și desfășurării examenelor și evaluărilor naționale, ale concursurilor de ocupare a posturilor vacante, conform atribuțiilor prevăzute de legislația în vigoare sau de fișa postului;\ncompletarea, verificarea, păstrarea în condiții de securitate și arhivarea documentelor referitoare la situația școlară a beneficiarilor primari și a statelor de funcții;\nprimirea, întocmirea, anularea, eliberarea, arhivarea și casarea actelor de studii și a documentelor școlare, în conformitate cu prevederile regulamentului privind regimul actelor de studii și al documentelor școlare gestionate de unitățile de învățământul preuniversitar, aprobat prin ordin al ministrului educației;\nselecția, evidența și depunerea documentelor la Arhivele Naționale, după expirarea termenelor de păstrare, stabilite prin \"Indicatorul termenelor de păstrare\", aprobat prin ordin al ministrului educației;\npăstrarea și aplicarea sigiliului unității pe documentele avizate și semnate de persoanele competente, în situația existenței deciziei directorului în acest sens;\nîntocmirea și/sau verificarea, respectiv avizarea documentelor/documentațiilor, potrivit legislației în vigoare sau fișei postului;\nîntocmirea statelor de personal;\nîntocmirea, actualizarea și gestionarea dosarelor de personal ale angajaților unității de învățământ;\ncalcularea drepturilor salariale sau de altă natură în colaborare cu compartimentul financiar – contabil;\ngestionarea corespondenței unității de învățământ; înregistrarea tuturor sesizărilor, petițiilor sau memoriilor primite de la elevi, părinți/reprezentanți legali, alte persoane;\nîntocmirea și actualizarea procedurilor activităților desfășurate la nivelul compartimentului, în conformitate cu legislația în vigoare;\norice alte atribuții specifice compartimentului, rezultând din legislația în vigoare, contractele colective de muncă aplicabile, regulamentul de organizare și funcționare al unității, regulamentul de ordine interioară, hotărârile consiliului de administrație și deciziile directorului, stabilite în sarcina sa."},{"article":"75","articleNumber":75,"legalText":"Secretarul-șef/Secretarul unității de învățământ pune la dispoziția personalului condicile de prezență, fiind responsabil cu siguranța acestora.\nSecretarul-șef/Secretarul răspunde de securitatea cataloagelor și verifică, la sfârșitul orelor de curs, împreună cu profesorul de serviciu, existența tuturor cataloagelor, încheind un proces-verbal în acest sens.\nÎn perioada cursurilor, cataloagele se păstrează în cancelarie, într-un fișet securizat, iar în perioada vacanțelor școlare, la secretariat, în aceleași condiții de siguranță.\nÎn situații speciale, atribuțiile prevăzute la alin. (1) și (2) pot fi îndeplinite, prin delegare de sarcini, și de către cadre didactice sau personal didactic auxiliar, din cadrul unității de învățământ, cu acordul prealabil al personalului solicitat.\nCondiționarea de orice beneficii a eliberării actelor de studii, a documentelor școlare sau a caracterizărilor este interzisă.\nSecretarul-șef/Secretarul răspunde de gestionarea actelor de studii și a documentelor școlare în conformitate cu prevederile regulamentului privind regimul actelor de studii și al documentelor școlare gestionate de unitățile de învățământ preuniversitar.\nUnitatea de învățământ va pune la dispoziția părinților/reprezentanților legali ai beneficiarilor primari și a altor persoane interesate o adresă de e-mail la care pot fi transmise solicitări, petiții, cereri, memorii, sesizări etc.\nConducerea unității de învățământ se va asigura că termenul de răspuns prevăzut de lege pentru memorii, petiții, cereri etc., va fi respectat.\nÎn fiecare unitate de învățământ va exista un sistem confidențial funcțional pentru sesizările referitoare la posibile acte de violență.\nPentru a asigura legătura părinților/reprezentanților legali ai beneficiarilor primari cu unitatea de învățământ, directorul și consiliul de administrație decid un program flexibil al compartimentului secretariat, astfel încât să asigure activitatea cu părinții/reprezentanții legali al acestuia în intervalul orar 8-9, respectiv 16-18, cel puțin două zile pe săptămână."},{"article":"76","articleNumber":76,"legalText":"Compartimentul financiar – contabil reprezintă structura organizatorică din cadrul unității de învățământ în care sunt realizate: fundamentarea și execuția bugetului, evidența contabilă, întocmirea și transmiterea situațiilor financiare, precum și orice alte activități cu privire la finanțarea și contabilitatea instituțiilor, prevăzute de legislația în vigoare, de contractele colective de muncă aplicabile, de regulamentul de organizare și funcționare a\nunității și de regulamentul de ordine interioară.\nCompartimentul financiar – contabil cuprinde, după caz, administratorul financiar, precum și ceilalți angajați asimilați funcției prevăzute de legislația în vigoare, denumită generic \"contabil\".\nCompartimentul financiar – contabil este subordonat directorului unității de învățământ."},{"article":"77","articleNumber":77,"legalText":"Compartimentul financiar – contabil are următoarele atribuții:\ndesfășurarea activității financiar-contabile a unității de învățământ;\ngestionarea, din punct de vedere financiar, a întregului patrimoniu al unității de învățământ, în conformitate cu dispozițiile legale în vigoare și cu hotărârile consiliului de administrație;\nîntocmirea proiectului de buget și a raportului de execuție bugetară, conform legislației în vigoare și contractelor colective de muncă aplicabile;\ninformarea periodică a consiliului de administrație cu privire la execuția bugetară;\norganizarea contabilității veniturilor și cheltuielilor;\nconsemnarea în documente justificative a oricărei operațiuni care afectează patrimoniul unității de învățământ și înregistrarea în evidența contabilă a documentelor;\nîntocmirea și verificarea statelor de plată în colaborare cu compartimentul secretariat;\nvalorificarea rezultatelor procesului de inventariere a patrimoniului, în situațiile prevăzute de lege și ori de câte ori consiliul de administrație consideră necesar;\nîntocmirea lucrărilor de închidere a exercițiului financiar;\nîndeplinirea obligațiilor patrimoniale ale unității de învățământ față de bugetul de stat, bugetul asigurărilor sociale de stat, bugetul local și față de terți;\nimplementarea procedurilor de contabilitate;\navizarea, în condițiile legii, a proiectelor de contracte sau de hotărâri ale consiliului de administrație, prin care se angajează fondurile unității;\nasigurarea și gestionarea documentelor și a instrumentelor financiare cu regim special;\nîntocmirea, cu respectarea normelor legale în vigoare, a documentelor privind angajarea, lichidarea, ordonanțarea și plata cheltuielilor bugetare, realizând operațiunile prevăzute de normele legale în materie;\norice alte atribuții specifice compartimentului, rezultând din legislația în vigoare și hotărârile consiliului de administrație și deciziile directorului, stabilite în sarcina sa, precizate explicit în fișa postului."},{"article":"78","articleNumber":78,"legalText":"Întreaga activitate financiară a unităților de învățământ se organizează și se desfășoară cu respectarea legislației în vigoare.\nActivitatea financiară a unității de învățământ se desfășoară pe baza bugetului propriu."},{"article":"79","articleNumber":79,"legalText":"Pe baza bugetului aprobat, directorul și consiliul de administrație actualizează programul anual de achiziții publice, stabilind și celelalte măsuri ce se impun pentru asigurarea încadrării tuturor categoriilor de cheltuieli în limitele fondurilor alocate."},{"article":"80","articleNumber":80,"legalText":"Este interzisă angajarea de cheltuieli dacă nu este asigurată sursa de finanțare.\nResursele extrabugetare ale unității pot fi folosite exclusiv de aceasta, conform hotărârii consiliului de administrație."},{"article":"81","articleNumber":81,"legalText":"Compartimentul administrativ este coordonat de administratorul de patrimoniu și cuprinde personalul administrativ al unității de învățământ.\nCompartimentul administrativ este subordonat directorului unității de învățământ."},{"article":"82","articleNumber":82,"legalText":"Compartimentul administrativ are următoarele atribuții:\ngestionarea bazei materiale;\nrealizarea reparațiilor, care sunt în sarcina unității, și a lucrărilor de întreținere, igienizare, curățenie și gospodărire a unității de învățământ;\nîntreținerea terenurilor, a clădirilor și a tuturor componentelor bazei didactico- materiale;\nrealizarea demersurilor necesare obținerii autorizațiilor de funcționare a unității de învățământ, care intră în atribuțiile unității de învățământ;\nrecepția bunurilor, serviciilor și a lucrărilor, printr-o comisie constituită la nivelul compartimentului;\nînregistrarea modificărilor produse cu privire la existența, utilizarea și mișcarea bunurilor din gestiune și prezentarea actelor corespunzătoare Compartimentul financiar- contabil;\nevidența consumului de materiale;\npunerea în aplicare a măsurilor stabilite de către conducerea unității de învățământ privind sănătatea și securitatea în muncă, situațiile de urgență și P.S.I.;\nîntocmirea proiectului anual de achiziții și a documentațiilor de atribuire a contractelor;\norice alte atribuții specifice compartimentului, rezultând din legislația în vigoare, hotărârile consiliului de administrație și deciziile directorului, stabilite în sarcina sa, precizate explicit în fișa postului."},{"article":"83","articleNumber":83,"legalText":"Evidența, organizarea, actualizarea documentelor contabile, prezentarea situațiilor financiare referitoare la patrimoniu și administrarea bazei didactico-materiale a unităților de învățământ se realizează în conformitate cu prevederile legislației în vigoare."},{"article":"84","articleNumber":84,"legalText":"Inventarierea bunurilor unității de învățământ se realizează de către comisia de inventariere, numită prin decizia directorului.\nModificările care se operează în listele ce cuprind bunurile aflate în proprietatea unității de învățământ se supun aprobării consiliului de administrație de către director, la propunerea administratorului de patrimoniu, în baza solicitării compartimentelor funcționale."},{"article":"85","articleNumber":85,"legalText":"Bunurile aflate în proprietatea unității de învățământ de stat sunt administrate de către consiliul de administrație.\nBunurile aflate în proprietatea unității de învățământ particular sunt supuse regimului juridic al proprietății private."},{"article":"86","articleNumber":86,"legalText":"Bunurile, care sunt temporar disponibile și care sunt în proprietatea sau administrarea unității de învățământ, pot fi închiriate în baza hotărârii consiliului de administrație."},{"article":"87","articleNumber":87,"legalText":"În unitățile de învățământ se organizează și funcționează, atât în format fizic, cât și digital, biblioteca școlară, inclusiv biblioteca școlară virtuală, sau centrul de documentare și informare.\nAcestea se organizează și funcționează în baza Legii bibliotecilor nr. 334/2002, republicată, cu modificările și completările ulterioare, și a regulamentului aprobat prin ordin al ministrului educației.\nCentrele de documentare și informare se pot înființa și pot funcționa în orice unitate de învățământ din învățământul de stat, particular și confesional, în conformitate cu prevederile regulamentului aprobat prin ordin al ministrului educației.\nÎntr-un centru de documentare și informare pot activa, în condițiile legii, atât profesorul documentarist, cât și bibliotecarul, documentaristul, redactorul.\nÎn unitățile de învățământ se asigură accesul gratuit al beneficiarilor primari și al personalului la Biblioteca Școlară Virtuală și la platforme digitale de învățare.\nPrin platformele digitale de învățare, unitatea de învățământ asigură suportul digital pentru elevi, inclusiv pentru elevele gravide și elevii părinți, în procesul de învățare, în timpul sau în afara programului școlar, în perioadele de suspendare a cursurilor școlare, în perioada de îngrijire a copilului, în perioadele în care, din motive medicale sau de altă natură, se află în imposibilitate de participare fizică la cursuri, pentru participarea la mobilități naționale și internaționale.\nÎn unitățile de învățământ de aplicație sau în consorțiile școlare coordonate de acestea, platformele digitale de învățare asigură suportul pentru desfășurarea practicii pedagogice a beneficiarilor primari și studenților în sistem blended-learning.\nBibliotecile școlare, respectiv centrele de documentare și informare sunt dotate și cu materiale, cărți, periodice, resurse educaționale în limbile minorităților naționale și care reflectă nevoile, interesele, cultura, istoria și identitatea minorităților naționale/ grupurilor etnice/persoanelor cu dizabilități."},{"article":"88","articleNumber":88,"legalText":"Beneficiarii primari ai educației sunt antepreșcolarii, preșcolarii și elevii, precum și persoanele adulte înscrise într-o unitate de învățământ."},{"article":"89","articleNumber":89,"legalText":"Dobândirea calității de beneficiar primar al educației se face prin înscrierea într-o unitate de învățământ.\nÎnscrierea se aprobă de către consiliul de administrație, cu respectarea legislației în vigoare, a prezentului regulament, a regulamentelor specifice aprobate prin ordin al ministrului educației și a regulamentului de organizare și funcționare a unității, ca urmare a solicitării scrise a părinților/ reprezentanților legali.\nÎn vederea asigurării accesului la învățământul obligatoriu, unitățile de învățământ preuniversitar au obligația de a înscrie persoanele care nu dețin un cod numeric personal, în conformitate cu prevederile art. 105 alin. (11) din Legea învățământului preuniversitar nr. 198/2023, cu modificările ulterioare. Normele metodologice pentru înmatricularea persoanelor care nu dețin un cod numeric personal, sunt prevăzute în Anexa nr. 2 la prezentul regulament."},{"article":"90","articleNumber":90,"legalText":"Înscrierea în unitățile de învățământ cu grupe de nivel antepreșcolar și preșcolar, în serviciile de educație timpurie complementare și, respectiv, în învățământul primar se face conform metodologiilor aprobate prin ordin al ministrului educației.\nÎn situația în care, pe durata clasei pregătitoare ori a clasei I, elevul acumulează absențe ca urmare a unor probleme medicale sau se observă manifestări de oboseală sau de neadaptare școlară, părinții sau reprezentanții legali pot depune la unitatea de învățământ o solicitare de retragere a elevului în vederea reînscrierii în anul școlar următor, în clasa corespunzătoare nivelului din care s-a retras; la cererea motivată a părintelui, reînscrierea se poate face și în anul școlar în care s-a solicitat retragerea, în clasa anterioară nivelului din care s-a retras elevul.\nÎn situația în care copiii din învățământul preșcolar, din grupele mijlocii și mari, înregistrează absențe ca urmare a unor probleme medicale sau se observă manifestări de oboseală sau de neadaptare la regimul grădiniței, părinții sau reprezentanții legali pot depune la unitatea de învățământ o solicitare de retragere a copilului, în vederea reînscrierii în anul școlar următor sau a înscrierii într-un serviciu complementar.\nÎn situația solicitării de retragere, menționate la alin. (2) și (3), unitățile de învățământ vor consilia părinții sau reprezentanții legali privind nevoia de a lua decizii în interesul educațional al copilului/elevului și îi vor informa că solicitarea nu poate fi soluționată decât în situația în care evaluarea nivelului dezvoltării realizată de cadrul didactic de la clasă atestă necesitatea reînscrierii în grupa/clasa anterioară sau în grupa/ clasa corespunzătoare nivelului din care s-a retras."},{"article":"91","articleNumber":91,"legalText":"Înscrierea în clasa a IX-a din învățământul liceal sau din învățământul profesional, respectiv în anul I din învățământul postliceal, inclusiv învățământul profesional și tehnic dual, se face în conformitate cu metodologiile aprobate prin ordin al ministrului educației."},{"article":"92","articleNumber":92,"legalText":"Elevii promovați vor fi înscriși de drept în anul următor, dacă nu există prevederi specifice de admitere în clasa respectivă, aprobate prin ordin al ministrului educației."},{"article":"93","articleNumber":93,"legalText":"Calitatea de antepreșcolar/preșcolar/elev se exercită prin frecventarea cursurilor și prin participarea la activitățile existente în programul fiecărei unități de învățământ.\nCalitatea de elev se dovedește cu carnetul de elev, vizat la începutul fiecărui an școlar de către unitatea de învățământ la care este înscris elevul."},{"article":"94","articleNumber":94,"legalText":"Prezența beneficiarilor primari la fiecare oră de curs se verifică de către cadrul didactic, care consemnează, în mod obligatoriu, fiecare absență. Absența se consemnează în catalog doar în cazul în care elevul nu este prezent la ora de curs și nu poate fi folosită drept mijloc de coerciție.\nMotivarea absențelor se face de către educatorul/învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte în ziua prezentării actelor justificative.\nÎn cazul beneficiarilor primari minori, părinții sau reprezentanții legali au obligația de a prezenta personal învățătorului/institutorului/profesorului pentru învățământul primar/ profesorului diriginte actele justificative pentru absențele copilului său.\nActele medicale pe baza cărora se face motivarea absențelor sunt, după caz: adeverință eliberată de medicul cabinetului școlar, de medicul de familie sau medicul de specialitate, adeverință/certificat medical/foaie de externare/scrisoare medicală eliberat(ă) de unitatea sanitară în care elevul a fost internat. Actele medicale trebuie să aibă viza cabinetului școlar sau a medicului de familie care are în evidență fișele medicale/carnetele de sănătate ale beneficiarilor primari.\nÎn limita a 40 de ore de curs pe an școlar, fără a depăși 20% din numărul orelor alocate\nunei discipline, absențele pot fi motivate doar pe baza cererilor scrise ale părintelui sau reprezentantului legal al elevului sau ale elevului major, adresate învățătorului/ institutorului/profesorului pentru învățământul primar/profesorului diriginte al clasei, avizate în prealabil de motivare de către directorul unității de învățământ.\nPrin excepție de la prevederile alin. (5), pentru elevele gravide și elevii părinți absențele pot fi motivate pentru un număr de ore de curs, în limita a 100 de ore de curs pe an școlar, fără a depăși 40% din numărul orelor alocate unei discipline.\nEducatorul/educatoarele/profesorul pentru educație timpurie/învățătorul/institutorul/ profesorul pentru învățământul primar/profesorul diriginte păstrează la sediul unității de învățământ, pe tot parcursul anului școlar, actele pe baza cărora se face motivarea absențelor, prezentate în termen de 7 zile calendaristice de la reluarea activității elevului.\nNerespectarea termenului prevăzut la alin. (7) atrage declararea absențelor ca nemotivate.\nÎn cazul beneficiarilor primari reprezentanți, absențele se motivează pe baza actelor justificative, conform prevederilor statutului elevului."},{"article":"95","articleNumber":95,"legalText":"La cererea scrisă a directorilor unităților de învățământ cu program sportiv suplimentar, a profesorilor-antrenori din unitățile de învățământ cu program sportiv integrat, a directorilor cluburilor sportive școlare/asociațiilor sportive școlare sau a conducerilor structurilor sportive, directorul unității de învățământ aprobă motivarea absențelor beneficiarilor primari care participă la cantonamente și la competiții de nivel local, județean, regional, național și internațional.\nDirectorul unității de învățământ aprobă motivarea absențelor beneficiarilor primari care participă la olimpiadele și concursurile școlare și profesionale organizate la nivel local, județean/interjudețean, regional, național și internațional, la cererea scrisă a profesorilor îndrumători/însoțitori.\nDirectorul unității de învățământ aprobă motivarea absențelor beneficiarilor primari care participă la mobilități cu scop educațional, în conformitate cu prevederile art. 131, alin.\n(5) din Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare.\n(4) Directorul unității de învățământ are obligația să anunțe serviciile de asistență socială (SPAS/DAS) și să contribuie la stabilirea unor măsuri de prevenire a abandonului școlar, în cazul beneficiarilor primari care înregistrează absențe la cel puțin 75% din numărul de ore de curs prevăzut într-un an școlar la disciplinele/modulele respective."},{"article":"96","articleNumber":96,"legalText":"Elevii retrași din învățământul preuniversitar se pot reînmatricula, la cerere, de regulă la începutul anului școlar, la același nivel/ciclu de învățământ și aceeași formă de învățământ, cu susținerea, după caz, a examenelor de diferență, redobândind astfel calitatea de elev.\nÎn situația beneficiarilor primari retrași din învățământul preuniversitar, părinții/ reprezentanții legali au obligația de a depune o declarație pe propria răspundere prin care își asumă că, în termen de cel mult 60 de zile, prezintă dovada continuării studiilor și acte doveditoare privind domiciliul/rezidența elevului în vederea asigurării dreptului la educație al copilului. În caz contrar, directorul unității de învățământ va informa Serviciul de Siguranța Școlară de pe raza căruia își desfășoară activitatea.\nPrin excepție de la prevederile alin. (1) elevele gravide și elevii părinți aflați în perioada de îngrijire a copilului, retrași, se pot reînmatricula la același an de studiu, în unitatea de învățământ la care au fost școlarizați, oricând în timpul anului școlar.\nÎncheierea situației școlare pentru elevele gravide și pentru elevii părinți aflați în perioada de îngrijire a copilului, reînmatriculați la același an de studiu, corespunzător anului de studiu la care a avut loc retragerea, se face, în cazul în care aceștia au un număr suficient de note, conform prevederilor prezentului regulament. În cazul în care acest fapt nu este posibil, elevii sunt declarați amânați, fiind aplicabile prevederile prezentului regulament, referitoare la situația beneficiarilor primari amânați.\nÎn cadrul rețelei școlare se pot înființa grupe de acomodare pentru elevii români reîntorși în țară.\nLa cererea părintelui sau a reprezentantului legal al elevului care nu a fost înscris în sistemul de învățământ din România în ultimii doi ani, inspectoratul școlar organizează în cadrul unităților de învățământ grupe de acomodare, în conformitate cu Metodologia pentru organizarea grupelor de acomodare, prevăzută în Anexa nr. 3 la prezentul regulament.\nGrupele de acomodare au ca obiectiv sprijinirea elevului în dobândirea unui nivel corespunzător de limbă română și în recuperarea decalajelor de orice fel, precum și integrarea facilă în sistemul național de învățământ preuniversitar, prin activități extrașcolare."},{"article":"97","articleNumber":97,"legalText":"Educația extrașcolară cuprinde ansamblul activităților educaționale organizate în afara programului școlar, în incinta unităților de învățământ sau în afara acestora, care contribuie la dezvoltarea și exersarea competențelor formate prin intermediul curriculumului național, și care se centrează pe dezvoltarea fizică, cognitivă, emoțională și socială a beneficiarilor primari, în vederea integrării și participării lor active în societate.\nOferta activităților de educație extrașcolară la nivelul unităților de învățământ\npreuniversitar este elaborată în urma unei consultări a beneficiarilor primari și părinților/ reprezentanților legali, în raport cu nevoile și perspectivele acestora în vederea participării lor la inițierea și implementarea activităților de educație extrașcolară.\nParticiparea beneficiarilor primari la activități educaționale extrașcolare realizate de organizații publice sau private din afara sistemului național de învățământ se realizează în baza unui acord/protocol de parteneriat cu unitățile de învățământ preuniversitar sau cu unitățile de educație extrașcolară."},{"article":"98","articleNumber":98,"legalText":"Activitatea educativă extrașcolară din unitățile de învățământ se desfășoară în afara orelor de curs.\nActivitățile educaționale extrașcolare sunt realizate în cadrul unităților de învățământ preuniversitar, al unităților de educație extrașcolară, în baze sportive, turistice și centre de agrement, în tabere școlare, muzee și galerii de artă, centre comunitare, case de cultură, centre de tineret, grădini botanice, parcuri naționale, biblioteci și în alte spații educaționale care îndeplinesc condițiile de siguranță a beneficiarilor primari."},{"article":"99","articleNumber":99,"legalText":"Activitățile educaționale extrașcolare desfășurate în unitățile de învățământ pot fi: culturale, civice, artistice, tehnice, științifice, recreative, turistice, ecologice, sportive, jurnalistice, de robotică, de voluntariat, de educație rutieră, financiară, juridică, antreprenorială, pentru sănătate și alte categorii specifice.\nActivitățile educaționale extrașcolare se pot desfășura sub formă de proiecte și programe educative, concursuri, festivaluri, expoziții, campanii, schimburi culturale, excursii, serbări, expediții, școli de vară, tabere și caravane tematice, dezbateri, sesiuni de formare, simpozioane, vizite de studiu, vizite, ateliere deschise etc.\nActivitatea educațională extrașcolară poate fi proiectată atât la nivelul fiecărei grupe/ clase de beneficiari primari, de către educator/educatoare/învățător/institutor/profesor pentru învățământul preșcolar sau primar/profesor diriginte, cât și la nivelul unității de învățământ, de către coordonatorul pentru proiecte și programe educative școlare și extrașcolare.\nActivitățile educaționale extrașcolare sunt stabilite în consiliul profesoral al unității de învățământ, împreună cu consiliul beneficiarilor primari, în conformitate cu opțiunile beneficiarilor primari, ale consiliului reprezentativ al părinților/reprezentanților legali și ale asociațiilor părinților/reprezentanților legali, acolo unde acestea există, precum și cu resursele de care dispune unitatea de învățământ.\nOrganizarea activităților educaționale extrașcolare de către unitățile de învățământ preuniversitar/comitetele de părinți/asociațiile de părinți în parteneriat cu autorități publice locale, organizații neguvernamentale și alți parteneri educaționali, sub forma excursiilor, taberelor, expedițiilor și a altor activități de timp liber care necesită deplasarea din localitatea de domiciliu se face în conformitate cu regulamentul aprobat prin ordin al ministrului educației.\nActivitățile educaționale extrașcolare de timp liber care nu necesită deplasarea din localitate, precum și activitățile extracurriculare și extrașcolare organizate în incinta unității de învățământ se derulează conform prevederilor prezentului regulament și, după caz, cu acordul de principiu al părintelui/ reprezentantului legal al beneficiarului primar, exprimat în scris, la începutul anului școlar.\nCalendarul activităților educaționale extrașcolare este aprobat de consiliul de administrație al unității de învățământ.\nRezultatele învățării dobândite de preșcolari/elevi prin participarea la activități educaționale extrașcolare se înscriu în portofoliul educațional al elevului și sunt recunoscute prin adeverințe, diplome sau certificate acordate de unitățile de educație extrașcolară, unitățile de învățământ preuniversitar sau partenerii acestora.\nCadrele didactice din unitățile de învățământ preuniversitar valorifică rezultatele învățării dobândite de preșcolari/elevi în urma participării acestora la activități educaționale extrașcolare și îi motivează pentru implicarea în activități extrașcolare, sprijinind accesul la aceste activități fără impunerea obligativității și fără nicio discriminare.\nEvaluarea activității educaționale extrașcolare derulate la nivelul unității de învățământ este parte a evaluării instituționale a respectivei unități de învățământ."},{"article":"100","articleNumber":100,"legalText":"Unitățile de învățământ care desfășoară învățământul de artă și învățământul sportiv colaborează cu unitățile de educație extrașcolară cu activități de profil în vederea susținerii reciproce.\nColaborarea dintre unitățile care desfășoară învățământul de artă și învățământul sportiv și palatele, cluburile copiilor și cluburile sportive școlare se realizează în baza unor protocoale de parteneriat, care conțin obligațiile și beneficiile reciproce.\nUnitățile de învățământ care desfășoară învățământul de artă pot colabora atât cu secțiile artistice din palatele și cluburile copiilor cât și cu alte secții, în proiecte interdisciplinare.\nUnitățile de învățământ care desfășoară învățământul sportiv pot colabora atât cu cluburile sportive școlare cât și cu secțiile de sport din palatele și cluburile copiilor, cu sau fără\ncertificat de identitate sportivă. Capitolul III Evaluarea copiilor/elevilor"},{"article":"101","articleNumber":101,"legalText":"Scopurile evaluării sunt orientarea și optimizarea procesului de predare-învățare, precum și gestionarea propriilor rezultate ale învățării."},{"article":"102","articleNumber":102,"legalText":"Conform legii, evaluările în sistemul de învățământ preuniversitar se realizează la nivel de disciplină, domeniu de studiu sau modul de pregătire.\nÎn sistemul de învățământ preuniversitar evaluarea se centrează pe competențe, oferă feedback real beneficiarilor primari, părinților/reprezentanților legali și cadrelor didactice și stă la baza planurilor individuale de învățare.\nÎncepând cu anul școlar 2025-2026, toate evaluările se realizează pe baza standardelor naționale de evaluare pentru fiecare disciplină, domeniu de studiu și modul de pregătire. Pentru toate disciplinele din învățământul primar, gimnazial și liceal, filierele teoretică, vocațională, precum și tehnologică, pentru disciplinele din trunchiul comun, standardele naționale de evaluare se elaborează de către Centrul Național pentru Curriculum și Evaluare. Pentru învățământul tehnologic, pentru fiecare disciplină/domeniu de studiu/modul de pregătire care nu este în trunchiul comun, standardele naționale de evaluare se realizează de Centrul Național de Învățământ Tehnologic și Tehnologic Dual.\nRezultatul evaluării, exprimat prin calificativ, notă, punctaj etc., nu poate fi folosit ca mijloc de coerciție, acesta reflectând strict rezultatele învățării, conform prevederilor legale."},{"article":"103","articleNumber":103,"legalText":"Evaluarea rezultatelor la învățătură se realizează permanent, pe parcursul anului școlar.\nLa sfârșitul clasei pregătitoare și clasei I, evaluarea dezvoltării fizice, socioemoționale, cognitive, a limbajului și a comunicării, precum și a dezvoltării capacităților și atitudinilor față de învățare ale copilului, realizată pe parcursul întregului an școlar, se finalizează prin completarea unui raport, de către cadrul didactic responsabil împreună cu consilierul școlar, în baza unei metodologii aprobate prin ordin al ministrului educației.\nLa sfârșitul învățământului antepreșcolar, evaluarea longitudinală a dezvoltării copilului și a nivelului de pregătire al acestuia pentru următorul nivel de învățământ – nivel preșcolar, se finalizează prin completarea, de către educator/educatoare, a Fișei de apreciere a progresului individual al copilului, al cărei model se regăsește în Curriculumul pentru educație timpurie. Fișa de apreciere a progresului individual al copilului este discutată cu părintele și este asumată prin semnătură de către acesta, care are obligația de a o transmite mai departe cadrului didactic care preia copilul, atunci când acesta trece la nivelul următor.\nLa sfârșitul grupei mari din învățământul preșcolar, cadrul didactic, în colaborare cu consilierul școlar, completează raportul descriptiv de evaluare privind dezvoltarea fizică și formarea competențelor cognitive și socio-emoționale ale copilului, conform modelului prezentat în metodologia specifică. Raportul este discutat cu părintele și este asumat prin semnătură de către acesta, care are obligația de a-l transmite mai departe cadrului didactic care preia copilul, atunci când acesta trece la nivelul următor.\nPortofoliul educațional este obligatoriu începând cu generația de preșcolari care intră în grupa mijlocie și generația de elevi din clasa pregătitoare, în anul școlar 2024-2025. Formatul portofoliului educațional, modalitatea de înscriere a datelor și alte detalii sunt cuprinse în metodologia specifică aprobată prin ordin al ministrului educației.\nPortofoliul educațional poate fi realizat și în format digital."},{"article":"104","articleNumber":104,"legalText":"Instrumentele de evaluare se stabilesc în funcție de vârstă și de particularitățile psihopedagogice ale beneficiarilor primari ai educației și de specificul fiecărei discipline. Acestea sunt:\nevaluări orale;\nteste, lucrări scrise;\nexperimente și activități practice;\nreferate;\nproiecte;\nprobe practice;\nalte instrumente stabilite de comisia pentru curriculum și aprobate de director sau elaborate de către Ministerul Educației/inspectoratele școlare.\nÎn învățământul primar, la clasele I-IV, în cel gimnazial, liceal, profesional și în cel postliceal, elevii vor avea la fiecare disciplină/modul, cu excepția celor preponderent practice, cel puțin două evaluări prin lucrare scrisă/test pe an școlar."},{"article":"105","articleNumber":105,"legalText":"Testele de evaluare și subiectele de examen de orice tip se elaborează pe baza cerințelor didactico-metodologice stabilite de programele școlare, parte a curriculumului național."},{"article":"106","articleNumber":106,"legalText":"Rezultatele evaluării se exprimă, după caz, prin:\naprecieri descriptive privind dezvoltarea copilului – la nivelurile antepreșcolar, preșcolar și clasa pregătitoare;\ncalificative la clasele I-IV din învățământul de masă și, respectiv, pentru clasele I-IV și pentru nivelul de învățământ gimnazial din învățământul special care școlarizează elevi cu deficiențe grave, severe, profunde sau asociate;\nnote de la 1 la 10 în învățământul gimnazial, liceal, profesional și în învățământul postliceal;\nprin punctaje/coduri specifice, în cazul testelor standardizate aplicate în afara evaluărilor externe prevăzute de lege;\nprin rapoarte anuale de evaluare a dezvoltării fizice, socioemoționale, cognitive, a limbajului și a comunicării, precum și a dezvoltării capacităților și atitudinilor de învățare, pentru clasa pregătitoare și clasa I.\nRezultatele evaluării se consemnează în catalog, cu cerneală albastră, sub forma:\n«Calificativul/data», respectiv «Nota/data», și/sau în catalogul electronic, cu obligativitatea tipăririi, înregistrării și arhivării acestuia la sfârșitul anului școlar, prin compartimentul secretariat, în conformitate cu prevederile cuprinse în Standardele tehnice minime necesare pentru utilizarea catalogului electronic, aprobate prin ordin al ministrului educației și cercetării.\n(la 15-07-2025, Alineatul (2), Articolul 106, Sectiunea 1, Capitolul III, Titlul VII a fost modificat de Punctul 1., Articolul I din ORDINUL nr. 4.498 din 8 iulie 2025, publicat în MONITORUL OFICIAL nr. 663 din 15 iulie 2025 )\nPrin excepție de la prevederile alin. (2), la nivelurile antepreșcolar și preșcolar (grupa mică și mijlocie), rezultatele evaluării sunt consemnate în caietul de observații, iar pentru grupa mare din învățământul preșcolar și clasa pregătitoare din învățământul primar, în raportul anual de evaluare.\nControlul utilizării și al respectării standardelor naționale de evaluare de către cadrele didactice se realizează prin inspecția școlară.\nDin momentul aprobării standardelor naționale de evaluare, evaluarea copiilor/ beneficiarilor primari fără respectarea acestora și/sau evaluarea fără respectarea metodologiilor de evaluare, realizată de personalul didactic, constituie abatere disciplinară și se sancționează în conformitate cu prevederile art. 210 alin. (1) din Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare.\nPentru filiera teoretică, evaluarea continuă se face în spațiul școlar, prin aplicarea instrumentelor de evaluare, cu accent pe caracterul formativ al acesteia.\nPentru filierele tehnologice, evaluarea continuă se realizează în spațiul școlar, prin aplicarea instrumentelor de evaluare, și la angajatori/locurile de practică, prin probe practice. Competențele profesionale pot fi evaluate integral la angajatori/locurile de practică.\nEvaluarea realizată pe baza standardelor naționale de evaluare, ca niveluri de performanță a competențelor specifice din programele școlare, stă la baza planurilor individuale de învățare realizate de către profesorul de la clasă.\nPentru frauda constatată la evaluările scrise, inclusiv la probele scrise din cadrul examenelor/concursurilor organizate la nivelul unității de învățământ, conform prezentului regulament, se acordă nota 1 sau, după caz, calificativul insuficient.\nElevii vor beneficia pe parcursul unui an școlar de cel puțin un plan individualizat de învățare, elaborat în urma evaluărilor susținute și după interpretarea rezultatelor de către cadrul didactic, care va fi folosit pentru consolidarea cunoștințelor, pentru întreprinderea unor acțiuni de învățare remedială și pentru stimularea beneficiarilor primari capabili de performanțe superioare.\nPortofoliul educațional cuprinde documente relevante pentru rezultatele învățării beneficiarilor primari: certificări care prezintă rezultate la disciplinele de studiu, pe ani de studiu/niveluri de școlarizare, rezultate la evaluările naționale și recomandări de recuperare a pierderilor de învățare, produse sau rezultate ale activităților desfășurate, diplome, certificate sau alte înscrisuri obținute în urma evaluării competențelor dobândite în diferite contexte, formale, nonformale și informale.\nPortofoliul educațional se utilizează începând cu debutul învățământului obligatoriu și este utilizat pe tot parcursul învățământului preuniversitar. Informații din portofoliul educațional pot fi utilizate pentru identificarea decalajelor educaționale și fundamentarea intervențiilor de sprijin.\nLa finalizarea învățământului gimnazial și liceal, profesorul consilier școlar și dirigintele au obligația să emită câte o recomandare de încadrare într-o formă de învățământ de nivel superior, având caracter de orientare școlară pentru fiecare elev în parte. În cazul absolvenților de învățământ liceal se poate realiza și o recomandare sub forma unei orientări vocaționale de încadrare pe piața forței de muncă. Recomandările sunt consultative și sunt emise în baza metodologiei specifice și sunt incluse în portofoliul educațional.\nDupă finalizarea învățământului obligatoriu, portofoliul educațional poate fi completat cu rezultate ale activităților de învățare pe tot parcursul vieții."},{"article":"107","articleNumber":107,"legalText":"Pentru nivelurile antepreșcolar și preșcolar, rezultatele evaluării se comunică și se discută individual cu părinții sau reprezentanții legali.\nCalificativele/Notele acordate se comunică în mod obligatoriu beneficiarilor primari și părinților/reprezentanților legali și se trec în catalog și în carnetul de elev de către cadrul didactic care le acordă.\nÎn învățământul primar cu predare în limbile minorităților naționale, calificativele se pot comunica și în limba de predare de către cadrul didactic.\nNumărul de calificative/note acordate anual fiecărui elev, la fiecare disciplină de studiu, este stabilit de cadrul didactic, în funcție de numărul unităților de învățare și de numărul săptămânal de ore prevăzut în planul-cadru. La fiecare disciplină numărul de calificative/note acordate anual este, de regulă, cu cel puțin trei mai mare decât numărul de ore alocat săptămânal disciplinei în planul-cadru de învățământ, dar nu mai mic de patru note pe an școlar pentru fiecare disciplină. În cazul disciplinelor de studiu cu mai puțin de o oră/săptămână, numărul minim de note acordate pentru un an școlar este de două.\nÎn cazul curriculumului organizat modular, numărul de note acordate trebuie să fie corelat cu numărul de ore alocate fiecărui modul în planul de învățământ, precum și cu structura modulului, de regulă, o notă la un număr de 25 de ore. Numărul minim de note acordate elevului la un modul este de două.\nElevii aflați în situație de corigență vor avea cu cel puțin un calificativ/o notă în plus față de numărul de calificative/note prevăzut la alin. (4), ultimul calificativ/ultima notă fiind acordat/ă, de regulă, în ultimele trei săptămâni ale anului școlar.\nLa finalul fiecărui interval de cursuri din structura anului școlar, se acordă câte o notă/un calificativ la purtare, luând în considerare comportamentul elevului."},{"article":"108","articleNumber":108,"legalText":"La sfârșitul anului școlar, cadrele didactice au obligația să încheie situația școlară a beneficiarilor primari. În situația în care cadrul didactic refuză să încheie situația școlară a beneficiarilor primari și elevii au note suficiente, consiliul de administrație al unității de învățământ va desemna un cadru didactic care să le încheie situația școlară în locul acestuia.\nLa sfârșitul fiecărui interval de cursuri, învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte consultă consiliul clasei pentru acordarea notei la purtare pentru intervalul respectiv, prin care este evaluat comportamentul elevului, precum și respectarea de către acesta a reglementărilor adoptate de unitatea de învățământ.\nLa sfârșitul anului școlar, învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte consultă consiliul clasei pentru elaborarea aprecierii asupra situației școlare a fiecărui elev.\nÎn cazul secțiilor/școlilor speciale germane din România, ale căror cursuri sunt finalizate cu diplomă de acces general în învățământul superior german și diplomă de bacalaureat, structura anului școlar și modalitatea de încheiere a situației școlare se adaptează la sistemul educațional german de către consiliul de administrație al unității de învățământ."},{"article":"109","articleNumber":109,"legalText":"La fiecare disciplină de studiu/modul, inclusiv la purtare se încheie anual o singură medie, calculată prin rotunjirea mediei aritmetice a notelor la cel mai apropiat număr întreg. La o diferență de 50 de sutimi, rotunjirea se face în favoarea elevului. Media, respectiv calificativul la purtare rezultat la finalul anului școlar ca medie a notelor acordate pentru fiecare interval de învățare, luând în considerare comportamentul elevului, se diminuează în mod corespunzător cu unul sau mai multe puncte, în cazul beneficiarilor primari care au înregistrat un număr de absențe nemotivate, în conformitate cu prevederile prezentului Regulament – cadru, precum și cu prevederile Statutului elevului.\nMediile se consemnează în catalog cu cerneală roșie.\nÎn cazul în care curriculumul este organizat modular, fiecare modul se dezvoltă ca o unitate autonomă de instruire. Media unui modul se calculează din notele obținute pe parcursul desfășurării modulului, conform prevederilor alin. (1). Încheierea mediei unui modul care se termină pe parcursul anului se face în momentul finalizării acestuia.\nMedia anuală generală se calculează ca medie aritmetică, cu două zecimale, prin rotunjire, a mediilor anuale de la toate disciplinele/modulele și de la purtare."},{"article":"110","articleNumber":110,"legalText":"La clasele I-IV se stabilesc calificative anuale la fiecare disciplină de studiu.\nPentru aceste clase, calificativul pe disciplină se stabilește astfel: se aleg două calificative cu frecvența cea mai mare, acordate în timpul anului școlar, după care, în perioadele de recapitulare și de consolidare a materiei, în urma aplicării unor probe de evaluare sumativă, cadrul didactic poate opta pentru unul dintre cele două calificative, în baza următoarelor criterii:\nprogresul sau regresul elevului;\nraportul efort-performanță realizată;\ncreșterea sau descreșterea motivației elevului;\nrealizarea unor sarcini din programul suplimentar de pregătire sau de recuperare, stabilite de cadrul didactic și care au fost aduse la cunoștința părintelui/reprezentantului legal."},{"article":"111","articleNumber":111,"legalText":"În învățământul primar, calificativele anuale la fiecare disciplină se consemnează în\ncatalog de către învățătorul/institutorul/profesorul pentru învățământul primar/profesorul de specialitate. Calificativele la purtare se consemnează în catalog de către învățători/ institutori/profesorii pentru învățământul primar.\nÎn învățământul gimnazial, liceal, profesional și postliceal, mediile anuale pe disciplină/modul se consemnează în catalog de către cadrul didactic care a predat disciplina/ modulul. Mediile la purtare se consemnează în catalog de profesorii diriginți ai claselor."},{"article":"112","articleNumber":112,"legalText":"Elevii scutiți de efort fizic au obligația de a fi prezenți la orele de educație fizică și sport. Beneficiarilor primari scutiți medical pe parcursul unui întreg an școlar nu li se acordă calificative/note și nu li se încheie media la această disciplină, respectiv, media anuală se calculează fără media de la această disciplină.\nPentru elevii scutiți medical pe parcursul unui întreg an școlar, profesorul de educație fizică și sport consemnează în catalog, la rubrica respectivă, \"scutit medical în anul școlar\", specificând totodată documentul medical, numărul și data eliberării acestuia. Documentul medical va fi atașat la dosarul personal al elevului, aflat la secretariat.\nPentru elevii scutiți medical, pe o perioadă determinată în timpul anului școlar, profesorul de educație fizică și sport consemnează în catalog, la rubrica respectivă, \"scutit medical în anul școlar, începând cu data de:…până la…\", specificând totodată documentul medical, numărul și data eliberării acestuia. Documentul medical va fi atașat la dosarul personal al elevului, aflat la secretariat.\nBeneficiarilor primari scutiți de efort fizic la orele de educație fizică și sport, pe o perioadă determinată în timpul anului școlar, li se încheie media la această disciplină, pentru anul școlar respectiv, numai dacă au obținut cel puțin 2 calificative/note. În caz contrar, acestor elevi nu li se încheie media la această disciplină și, respectiv, media anuală se calculează fără media de la această disciplină.\n(la 15-07-2025, Alineatul (4), Articolul 112, Sectiunea 1, Capitolul III, Titlul VII a fost modificat de Punctul 2., Articolul I din ORDINUL nr. 4.498 din 8 iulie 2025, publicat în MONITORUL OFICIAL nr. 663 din 15 iulie 2025 )\nElevii scutiți medical nu sunt obligați să vină în echipament sportiv la orele de educație fizică și sport, dar trebuie să aibă încălțăminte adecvată pentru sălile de sport. Absențele la aceste ore se consemnează în catalog.\nPentru integrarea în colectiv a beneficiarilor primari scutiți medical, în timpul orei de educație fizică și sport, cadrul didactic le poate atribui sarcini organizatorice care vor avea în vedere recomandările medicale, de exemplu: arbitraj, cronometrare, măsurare, înregistrarea unor elemente tehnice, ținerea scorului etc."},{"article":"113","articleNumber":113,"legalText":"Școlarizarea beneficiarilor primari sportivi nominalizați de federațiile naționale sportive pentru centrele naționale olimpice/de excelență se realizează în unități de învățământ situate în apropierea acestor structuri sportive și respectă dinamica selecției loturilor. Situația școlară, înregistrată în perioadele în care elevii se pregătesc în aceste centre, se transmite unităților de învățământ de care aceștia aparțin. În cazul în care școlarizarea se realizează în unități de învățământ care nu pot asigura pregătirea beneficiarilor primari la unele discipline de învățământ, situația școlară a acestor elevi se poate încheia, la disciplinele respective, la unitățile de învățământ de care elevii aparțin, după întoarcerea acestora, conform prezentului regulament."},{"article":"114","articleNumber":114,"legalText":"Participarea la ora de religie se realizează în conformitate cu prevederile legale în vigoare."},{"article":"115","articleNumber":115,"legalText":"Sunt declarați promovați elevii care, la sfârșitul anului școlar, obțin la fiecare disciplină de studiu/modul cel puțin media anuală 5/calificativul \"Suficient\", iar la purtare, media anuală 6/calificativul \"Suficient\".\nElevii liceelor pedagogice, ai liceelor teologice și ai liceelor militare care obțin la purtare media anuală mai mică de 8 nu mai pot continua studiile la aceste profiluri. Acești elevi sunt obligați să se transfere, pentru anul școlar următor, la alte profiluri/licee, cu respectarea legislației în vigoare și a regulamentelor de organizare și funcționare a unităților în cauză."},{"article":"116","articleNumber":116,"legalText":"Elevii de la clasele cu profil artistic sau sportiv trebuie să obțină media cel puțin 6 la disciplina principală de specialitate, pentru aceste profiluri/specializări.\nElevii de la clasele cu specializările muzică, coregrafie și arta actorului trebuie să obțină cel puțin nota 6 pentru specializarea respectivă la examenul de sfârșit de an școlar.\nElevii de la clasele cu specializările arte vizuale, arte plastice, arte decorative, arhitectură, arte ambientale, design, conservare-restaurare bunuri culturale trebuie să obțină la toate disciplinele practice de specialitate media anuală cel puțin 6.\nElevii de la clasele cu profil pedagogic trebuie să obțină la sfârșitul anului școlar medii anuale de cel puțin 6 la disciplinele limba și literatura română/limba și literatura maternă, matematică/aritmetică și la disciplinele pedagogice de profil.\nElevii care nu îndeplinesc condițiile de la alin. (1)-(4) se vor transfera, pentru anul școlar următor, la alte profiluri/specializări, cu respectarea legislației în vigoare și a regulamentelor de organizare și funcționare a unităților în cauză.\n(la 15-07-2025, Alineatul (5), Articolul 116, Sectiunea 1, Capitolul III, Titlul VII a fost modificat de Punctul 3., Articolul I din ORDINUL nr. 4.498 din 8 iulie 2025, publicat în MONITORUL OFICIAL nr. 663 din 15 iulie 2025 )"},{"article":"117","articleNumber":117,"legalText":"Sunt declarați amânați elevii cărora nu li se poate definitiva situația școlară la una sau la mai multe discipline de studiu/module din următoarele motive:\nau absentat, motivat și nemotivat, la cel puțin 50% din numărul de ore de curs prevăzut într-un an școlar la disciplinele/modulele respective și nu au numărul minim de calificative/ note prevăzut de prezentul regulament;\nau fost scutiți de frecvență de către directorul unității de învățământ în urma unor solicitări oficiale, pentru perioada participării la festivaluri și concursuri profesionale, cultural-artistice și sportive, interne și internaționale, cantonamente și pregătire specializată;\nau beneficiat de bursă de studiu în străinătate, recunoscută de Ministerul Educației;\nau urmat studiile, pentru o perioadă determinată de timp, în alte țări;\nnu au un număr suficient de calificative/note necesar pentru încheierea mediei/mediilor sau nu au calificativele/mediile anuale la disciplinele/modulele respective consemnate în catalog de către cadrul didactic din alte motive decât cele de mai sus, neimputabile personalului didactic de predare.\nperioada examenelor coincide cu perioada de naștere în cazul elevelor gravide sau cu perioada de îngrijire a copilului în cazul beneficiarilor primari părinți, dovedită prin documente medicale.\nÎncheierea situației școlare a beneficiarilor primari amânați se face înaintea sesiunii de corigențe, într-o perioadă stabilită de consiliul de administrație. Elevii amânați care nu promovează la una sau două discipline/module de studiu în sesiunea de examene de încheiere a situației școlare a beneficiarilor primari amânați se pot prezenta la sesiunea de examene de corigențe. Elevii declarați amânați din clasa pregătitoare, respectiv din clasa I care nu se prezintă în sesiunile de examinare sunt reînscriși în clasa pentru care nu s-a încheiat situația școlară. Elevele gravide și elevii părinți declarați amânați în condițiile prevederilor alin. (1), lit.f) care nu se prezintă în sesiunile de examinare sunt reînscriși în clasa pentru care nu s-a încheiat situația școlară.\nÎn situația în care un cadru didactic refuză să participe la examenul pentru încheierea situației școlare sau la examenul de corigență, consiliul de administrație al unității de învățământ, cu avizul inspectorului școlar de specialitate, va desemna un alt cadru didactic care să facă parte din comisia de examinare."},{"article":"118","articleNumber":118,"legalText":"Elevii din învățământul obligatoriu care au acumulat un număr de absențe nemotivate ce au condus la imposibilitatea finalizării a 2 ani școlari succesivi sunt considerați în situație de abandon școlar.\nElevii aflați în situație de abandon școlar în doi ani școlari consecutivi, sunt radiați din evidențele școlare.\nElevii considerați în situație de abandon școlar pot fi reînscriși, la cerere, la nivelul clasei pe care au abandonat-o.\nElevii care nu frecventează cursurile școlare și care au absentat nemotivat la cel puțin 75% din numărul de ore de curs prevăzut într-un an școlar la disciplinele/modulele respective, sunt considerați în situație de risc de abandon școlar.\nÎn cazul beneficiarilor primari din învățământul obligatoriu aflați în situație de risc și de abandon școlar, unitatea de învățământ are obligația de a informa instituțiile responsabile cu privire la neîndeplinirea de către părinții, tutorii, reprezentanții legali ai elevului a obligațiilor legale privind asigurarea frecventării cu regularitate și conform programului de către acesta a cursurilor școlare.\nÎn învățământul antepreșcolar și preșcolar (grupa mică), în situația neprezentării copilului la începutul anului școlar, după înscrierea acestuia în unitatea de învățământ, precum și în cazul unei absențe prelungite a copilului, mai mare de 15 zile lucrătoare consecutive, fără o justificare medicală sau fără a anunța conducerea unității cu privire la motivul absenței, părintele primește o notificare cu privire la posibilitatea vacantării locului. Dacă în termen de 5 zile părintele nu transmite, în scris, un răspuns la notificarea primită, copilul este considerat retras și locul acestuia este declarat liber/vacant.\nPentru copiii preșcolari din grupele mijlocii și mari care se află în situația prezentată la alin.\nunitatea de învățământ este obligată să prezinte părinților/reprezentanților legali opțiunile pe care aceștia le au în cazul retragerii copilului: reînscrierea acestuia în anul școlar următor sau, după caz, înscrierea într-un serviciu complementar."},{"article":"119","articleNumber":119,"legalText":"Sunt declarați corigenți elevii care obțin calificativul \"Insuficient'/medii anuale sub 5 la cel mult două discipline de studiu, precum și elevii amânați care nu promovează examenul de încheiere a situației școlare la cel mult două discipline de studiu.\nÎn cazul în care curriculumul este organizat modular, sunt declarați corigenți:\nelevii care obțin medii sub 5 la modulele ce se finalizează pe parcursul anului școlar, indiferent de numărul modulelor nepromovate;\nelevii care obțin medii sub 5 la cel mult două module care se finalizează la sfârșitul anului școlar, precum și elevii amânați care nu promovează examenul de încheiere a situației școlare la cel mult două module.\nPentru elevii corigenți se organizează anual o singură sesiune de examene de corigență, într-o perioadă stabilită prin ordin de ministru.\nPentru elevii corigenți menționați la alin. (2) lit.a) se organizează și o sesiune specială de examene de corigență, în ultima săptămână de cursuri a anului școlar. Media fiecărui modul, obținută în cadrul sesiunii speciale de corigență, este și media anuală a modulului."},{"article":"120","articleNumber":120,"legalText":"Sunt declarați repetenți:\nelevii care au obținut calificativul \"Insuficient'/medii anuale sub 5 la mai mult de două discipline de învățământ/module care se finalizează la sfârșitul anului școlar. Prevederile se aplică și beneficiarilor primari care nu au promovat examenele de corigență în sesiunea specială, organizată în conformitate cu art. 119 alin. (4) din prezentul regulament;\nelevii care au obținut la purtare calificativul anual \"Insuficient'/media anuală mai mică de 6;\nelevii corigenți care nu se prezintă la sesiunea de examen de corigență sau, după caz, la sesiunea specială prevăzută la art. 119 alin. (4) sau care nu promovează examenul la toate disciplinele/modulele la care se află în situație de corigență, cu excepția elevelor gravide dacă perioada examenelor coincide cu perioada de naștere și a beneficiarilor primari părinți dacă perioada examenelor coincide cu perioada de îngrijire a copilului, dovedită prin documente medicale;\nelevii amânați care nu se prezintă la sesiunea de încheiere a situației școlare la cel puțin o disciplină/un modul, cu excepția elevelor gravide dacă perioada examenelor coincide cu perioada de naștere și a beneficiarilor primari părinți dacă perioada examenelor coincide cu perioada de îngrijire a copilului, dovedită cu documente medicale;\nelevii exmatriculați din învățământul postliceal, cu drept de reînscriere; acestora li se înscrie în documentele școlare \"Repetent prin exmatriculare, cu drept de reînscriere în aceeași unitate de învățământ sau în altă unitate de învățământ\".\nLa sfârșitul clasei pregătitoare și al clasei I elevii nu pot fi lăsați repetenți. Elevii care, pe parcursul anului școlar, au manifestat dificultăți de învățare, menționate în raportul de evaluare a dezvoltării fizice, socioemoționale, cognitive, a limbajului și a comunicării, precum și a dezvoltării capacităților și atitudinilor față de învățare, rămân în colectivele în care au învățat și intră, pe parcursul anului școlar următor, într-un program de remediere/recuperare școlară, realizat de un învățător/institutor/profesor pentru învățământul primar împreună cu un specialist de la centrul județean de resurse și asistență educațională/Centrul Municipiului București de Resurse și Asistență Educațională.\nCopiii din grupa mare a învățământului preșcolar care pe parcursul anului școlar au manifestat dificultăți de învățare, menționate în raportul de evaluare a dezvoltării fizice, cognitive și socio- emoționale, rămân în colectivele în care au învățat și intră, pe parcursul anului școlar următor, într-un program de învățare personalizat pe care educatorul/ educatoarea/ profesorul de educație timpurie îl realizează împreună cu un specialist de la centrul județean de resurse și asistență educațională/Centrul Municipiului București de Resurse și Asistență Educațională."},{"article":"121","articleNumber":121,"legalText":"Elevii declarați repetenți se înscriu, la cerere, în anul școlar următor în clasa pe care o repetă, la aceeași unitate de învățământ, inclusiv cu depășirea numărului maxim de elevi la clasă prevăzut de lege, sau se pot transfera la o altă unitate de învățământ.\nPentru elevii din învățământul obligatoriu și din învățământul postliceal declarați repetenți la sfârșitul primului an de studii, reînscrierea se poate face și peste numărul de locuri aprobat prin planul de școlarizare.\n(la 07-07-2026, Alineatul (2), Articolul 121, Sectiunea 1, Capitolul III, Titlul VII a fost modificat de Punctul 5., Articolul I din ORDINUL nr. 4.261 din 26 iunie 2026, publicat în MONITORUL OFICIAL nr. 556 din 7 iulie 2026 )\nÎn învățământul postliceal cu frecvență, elevii se pot afla în situația de repetenție de cel mult două ori. Anul de studiu nepromovat se poate repeta o singură dată.\nElevii de la nivelul ciclului liceal din clasa a XI-a sau a XII-a, precum și cei din învățământul postliceal care repetă a doua oară un an școlar nepromovat sau care se află în stare de repetenție pentru a treia oară, pot continua studiile în învățământul cu frecvență redusă."},{"article":"122","articleNumber":122,"legalText":"După încheierea sesiunii de corigență, elevii care nu au promovat la o singură disciplină de învățământ/un singur modul au dreptul să solicite reexaminarea. Aceasta se aprobă de către director, în cazuri justificate, o singură dată pe an școlar.\nCererea de reexaminare se depune la secretariatul unității de învățământ, în termen de 24 de ore de la afișarea rezultatelor examenului de corigență.\nReexaminarea se desfășoară în termen de două zile de la data depunerii cererii, dar nu mai târziu de data începerii cursurilor noului an școlar.\nComisia de reexaminare se numește prin decizie a directorului și este formată din alte cadre didactice decât cele care au făcut examinarea anterioară. În situația în care în unitatea de învățământ nu există alte cadre didactice decât cele care au făcut examinarea anterioară, în comisie pot fi numite și cadre didactice din alte unități de învățământ, la decizia inspectoratului școlar.\nÎn cazul beneficiarilor primari amânați, în situația în care profesorul clasei refuză nemotivat să susțină examenul de încheiere a situației școlare a beneficiarilor primari amânați sau corigenți, sau din motive obiective dovedite/ justificate cu documente, atunci Consiliul de administrație poate desemna o comisie în vederea încheierii situației școlare a beneficiarilor primari amânați sau corigenți."},{"article":"123","articleNumber":123,"legalText":"Pentru elevii declarați corigenți sau amânați, examinarea se face din toată materia studiată în anul școlar, conform programei școlare.\nPentru elevii care susțin examene de diferență, examinarea se face din toată materia studiată în anul școlar respectiv sau dintr-o parte a acesteia, în funcție de situație.\nDisciplinele/Modulele la care se dau examene de diferență sunt cele prevăzute în trunchiul comun și în curriculumul diferențiat al specializării/calificării profesionale a clasei la care se face transferul și care nu au fost studiate de candidat. Se susține examen separat pentru fiecare clasă/an de studiu. Notele obținute la examenele de diferență din curriculumul diferențiat se consemnează în registrul matricol, fără a fi luate în calcul pentru media anuală a elevului pentru fiecare an de studiu încheiat.\nNu se susțin examene de diferență pentru disciplinele din curriculumul la decizia elevului din oferta școlii.\nÎn cazul beneficiarilor primari transferați în timpul anului școlar, aceștia preiau disciplinele opționale ale clasei în care se transferă.\nÎn cazul transferului beneficiarilor primari corigenți la cel mult două discipline/module, cu schimbarea profilului/specializării/calificării profesionale, și care nu vor mai studia la unitatea de învățământ primitoare disciplinele/modulele respective, se vor susține doar examenele de diferență. Prevederea se aplică și în cazul beneficiarilor primari declarați amânați."},{"article":"124","articleNumber":124,"legalText":"Frecventarea învățământului obligatoriu poate înceta la forma cu frecvență la 18 ani. Persoanele care nu au finalizat învățământul obligatoriu până la această vârstă și care au depășit cu mai mult de trei ani vârsta clasei își pot continua studiile, la cerere, și la forma de învățământ cu frecvență, cursuri serale sau la forma cu frecvență redusă.\nPentru persoanele care au depășit cu mai mult de 3 ani vârsta clasei în învățământul primar, cu mai mult de 4 ani vârsta clasei în învățământul gimnazial, respectiv cu mai mult de\n5 ani vârsta clasei în învățământul liceal, învățământul obligatoriu se poate organiza și în forma de învățământ cu frecvență redusă, în conformitate cu prevederile metodologiei aprobate prin ordin al ministrului educației sau prin programul \"A doua șansă\"."},{"article":"125","articleNumber":125,"legalText":"Elevii care dețin acte de studii și care, indiferent de cetățenie sau statut, au urmat cursurile într- o unitate de învățământ din altă țară sau la organizații furnizoare de educație care organizează și desfășoară pe teritoriul României activități corespunzătoare unor sisteme educaționale din alte țări, pot dobândi calitatea de elev în România după echivalarea studiilor de către inspectoratele școlare județene/ Inspectoratul Școlar al Municipiului București. Echivalarea se realizează la nivelul ultimei clase absolvite.\nElevii menționați la alin. (1) vor fi înscriși ca audienți până la finalizarea procedurii de echivalare, indiferent de momentul în care părinții sau reprezentanții legali ai acestora solicită școlarizarea, în unități de învățământ preuniversitar, cu excepția unităților de învățământ din cadrul Ministerului Apărării Naționale. Dosarul pentru echivalare se depune la inspectoratele școlare județene/ Inspectoratul Școlar al Municipiului București/ în termen de maximum 30 de zile de la data înscrierii în calitate de audient.\nElevii audienți vor fi înscriși într-un registru de evidență similar registrului matricol. Înscrierea, completarea și arhivarea se realizează în conformitate cu prevederile regulamentului privind regimul actelor de studii și al documentelor școlare gestionate de unitățile de învățământ preuniversitar referitoare la întocmirea, completarea și arhivarea registrului matricol.\nActivitatea beneficiarilor primari audienți va fi înregistrată în cataloage provizorii, toate mențiunile privind evaluările și frecvența urmând a fi trecute în cataloagele claselor după încetarea calității de audienți.\nAlegerea nivelului clasei în care va fi înscris elevul ca audient se face, prin decizie, de către directorul unității de învățământ, în baza hotărârii consiliului de administrație adoptate în urma analizării raportului întocmit de o comisie formată din cadre didactice care predau la nivelul de studiu pentru care se solicită înscrierea, stabilită la nivelul unității de învățământ, din care fac parte și directorul/directorul adjunct și un psiholog/consilier școlar.\nEvaluarea situației elevului și decizia menționată la alin. (5) vor ține cont de vârsta și nivelul dezvoltării psihocomportamentale a elevului, de recomandarea părinților/ reprezentanților legali, de nivelul obținut în urma unei evaluări orale sumare, de perspectivele de evoluție școlară.\nÎn cazul în care părinții sau reprezentanții legali nu sunt de acord cu recomandarea comisiei privind nivelul clasei în care va fi înscris elevul audient, elevul va fi înscris la clasa pentru care optează părinții, pe răspunderea acestora asumată prin semnătură.\nÎn termen de maximum 15 zile de la primirea atestatului de echivalare emis de inspectoratele școlare județene/ Inspectoratului Școlar al Municipiului București, elevul audient este înscris în catalogul clasei și i se transferă din catalogul provizoriu toate mențiunile cu privire la activitatea desfășurată – note, absențe etc.\nElevii străini care au acte de studii, au depus documentele în vederea echivalării studiilor și care cunosc limba română, sunt școlarizați, conform prevederilor legale în vigoare, după finalizarea procedurii de echivalare. Școlarizarea și înmatricularea acestora se fac în anul de studiu corespunzător documentului de echivalare emis.\nElevii care nu dețin acte de studii și au urmat cursurile într-o unitate de învățământ din altă țară, sunt înscriși ca audienți, cu respectarea prevederilor alin. (3) – (7). Această procedură se aplică și în cazul persoanelor, indiferent de cetățenie sau statut, care solicită continuarea studiilor și înscrierea în sistemul românesc, fără a prezenta documente care să ateste studiile efectuate în străinătate sau la organizații furnizoare de educație care organizează și desfășoară pe teritoriul României activități corespunzătoare unor sisteme educaționale din alte țări, care nu sunt înscrise în Registrul special al Agenției Române pentru Asigurarea Calității în Învățământul Preuniversitar. Această procedură se aplică și persoanelor care urmează o altă formă de școlarizare nefinalizată cu diplomă.\nÎn vederea școlarizării și înmatriculării, în cazul în care nu sunt deținute și prezentate documentele școlare care atestă perioadele sau anii de studii din străinătate, părinții/reprezentanții legali ai beneficiarilor primari/elevii majori depun o cerere scrisă, adresată conducerii unității de învățământ în vederea evaluării/examinării beneficiarilor primari, precizând ultimul an de studiu pentru care se solicită evaluarea/examinarea. Cererea este înaintată de către conducerea unității de învățământ inspectoratului școlar.\nInspectorul școlar general emite, în termen de 10 de zile de la primirea solicitării adresate unității de învățământ, decizia de constituire a comisiei de evaluare/examinare, formată din cadre didactice din unitatea de învățământ și cel puțin un inspector școlar/ profesor metodist. Evaluarea elevului se realizează în termen de cel mult 20 de zile de la data emiterii deciziei, după ce a beneficiat de activități de sprijin și consiliere psiho- pedagogică din partea unității școlare, după cum urmează:\nevaluarea se realizează la disciplinele din ariile curriculare Comunicare în limba română/ Limba și literatura română, Matematică și științe ale naturii, respectiv Om și societate, cu excepția disciplinei Religie, conform planurilor-cadru de învățământ în vigoare. Elevul este examinat pentru fiecare an de studiu pentru care nu prezintă documente școlare justificative, începând, în ordine inversă, cu ultimul an de studiu realizat în străinătate, stabilit de comisia constituită prin decizia inspectorului școlar general;\n(la 04-09-2025, Litera a), Alineatul (12), Articolul 125, Sectiunea 1, Capitolul III, Titlul\nVII a fost modificată de Punctul 2., Articolul I din ORDINUL nr. 6.055 din 29 august 2025, publicat în MONITORUL OFICIAL nr. 819 din 4 septembrie 2025 )\nîn cazul în care elevul promovează examenele din ultimul an de studii, acesta este înscris în clasa următoare; în această situație nu se mai impune evaluarea celorlalți ani de studii;\nîn situația în care elevul nu promovează examenele din ultimul an de studii la 3 sau mai multe discipline/module, acesta este examinat pentru înscrierea în clasa inferioară. Părintele sau reprezentantul legal, respectiv elevul major poate solicita reexaminarea în termen de 24 de ore de la afișarea rezultatelor;\nmodul de desfășurare și rezultatele evaluării/examinării vor fi consemnate într-un proces- verbal și ulterior în registrul matricol.\nÎn cazul persoanelor care au urmat o altă formă de organizare a învățământului obligatoriu, finalizată cu diplomă obținută la o instituție acreditată în statul emitent, și care dețin documente școlare care atestă parcurgerea tuturor claselor din ciclul liceal, Ministerul Educației și Cercetării poate recunoaște și echivala diploma, cu respectarea prevederilor legale în vigoare. În cazul persoanelor care au urmat o altă formă de organizare a învățământului obligatoriu, finalizată cu diplomă obținută la o instituție acreditată în statul emitent, dar care nu dețin documente școlare care să ateste parcurgerea tuturor claselor din ciclul liceal, Ministerul Educației și Cercetării poate recunoaște și echivala diploma numai în urma promovării unui proces de evaluare inițiat de către inspectoratul școlar județean/al municipiului București, cu respectarea următoarelor prevederi:\nevaluarea se realizează în baza comunicării transmise de către Centrul Național de Recunoaștere și Echivalare a Diplomelor (CNRED), de către o comisie desemnată prin decizie a inspectorului școlar general;\nsolicitantul este evaluat din materia prevăzută în programele școlare corespunzătoare anului/anilor de studiu liceal, prin susținerea câte unei probe la fiecare din disciplinele din planul-cadru aferent profilului și specializării solicitate pentru care nu deține documente, astfel:\nLimba și literatura română;\nLimba modernă (la alegerea solicitantului);\nInformatică/TIC;\no disciplină, la alegere, din aria curriculară Matematică și științe ale naturii;\no disciplină, la alegere, din aria curriculară Om și societate;\nnota minimă de promovare pentru fiecare disciplină este 5 (cinci);\nechivalarea este posibilă doar dacă solicitantul promovează toate probele stabilite pentru evaluare;\nîn cazul nepromovării uneia sau mai multor probe, solicitantul are dreptul de a solicita reexaminarea la disciplinele respective, în termen de maximum 10 zile lucrătoare de la data\nafișării rezultatelor;\nmodul de desfășurare a evaluării și rezultatele obținute se consemnează într-un proces- verbal, care se transmite către CNRED pentru finalizarea procedurii de recunoaștere și echivalare a diplomei.\n(la 04-09-2025, Alineatul (13), Articolul 125, Sectiunea 1, Capitolul III, Titlul VII a fost modificat de Punctul 3., Articolul I din ORDINUL nr. 6.055 din 29 august 2025, publicat în MONITORUL OFICIAL nr. 819 din 4 septembrie 2025 )\nȘcolarizarea și înmatricularea într-un an de studiu a beneficiarilor primari străini care nu au acte de studiu se face în conformitate cu prevederile Metodologiei privind școlarizarea și organizarea și desfășurarea cursului de inițiere în limba română pentru minorii care au dobândit o formă de protecție internațională sau un drept de ședere în România, precum și pentru minorii cetățeni ai statelor membre ale Uniunii Europene și ale Spațiului Economic European și ai Confederației Elvețiene, aprobată prin ordin al ministrului educației.\nPentru elevii străini care nu cunosc limba română, înscrierea și participarea la cursul de inițiere în limba română se fac conform reglementărilor aprobate prin ordin al ministrului educației. Beneficiarilor primari care au promovat cursul de inițiere în limba română li se eliberează certificate de competențe lingvistice. Acestea sunt înregistrate într-un registru unic de evidență a actelor de studii care atestă nivelul de cunoaștere a limbii române și care se întocmește, se completează și se arhivează în conformitate cu prevederile regulamentului privind regimul actelor de studii și al documentelor școlare gestionate de unitățile de învățământ preuniversitar.\nPrin programul \"A doua șansă\" – învățământ primar și programul \"A doua șansă\" – învățământ secundar pot fi școlarizați și minorii și tinerii care au depășit vârsta de 18 ani, care au dobândit protecție internațională sau un drept de ședere în România, precum și cetățeni ai statelor membre ale Uniunii Europene, Spațiului Economic European și cetățeni ai Confederației Elvețiene, cu sau fără acte de studiu.\nElevii străini școlarizați prin programul \"A doua șansă\", care nu cunosc limba română, simultan cu frecventarea programului au dreptul să participe, la cerere, și la cursul de inițiere în limba română.\nPrin excepție de la prevederile alin. (1) – (12), în temeiul Legii nr. 356/2007 pentru aderarea României la Convenția privind definirea statutului școlilor europene, adoptată la Luxemburg la 21 iunie 1994, beneficiarilor primari români înscriși în sistemul școlilor europene, reintegrați în sistemul educațional național, li se recunosc și li se echivalează în procedură simplificată, pe baza cererii avizate de către Ministerul Educației, prin direcția cu atribuții în domeniul școlilor europene, notele/calificativele obținute, cu încadrarea în clasa corespunzătoare."},{"article":"126","articleNumber":126,"legalText":"Beneficiarilor primari dintr-o unitate de învățământ de stat, particular sau confesional din România, care urmează să continue studiile în alte țări pentru o perioadă determinată de timp, li se rezervă locul în unitatea de învățământ de unde pleacă, la solicitarea scrisă a părintelui/reprezentantului legal. Rezervarea locului nu rămâne valabilă la trecerea de la nivelul de învățământ gimnazial la nivelul de învățământ liceal.\nÎn cazul în care o persoană, indiferent de cetățenie sau statut, solicită înscrierea în sistemul de învățământ românesc după începerea cursurilor noului an școlar, se aplică procedura referitoare la recunoaștere și echivalare și, după caz, cea prevăzută la articolele precedente, dacă nu i se poate echivala anul școlar parcurs în străinătate.\nElevelor gravide și beneficiarilor primari părinți, pe perioada de îngrijire a copilului, li se rezervă locul în unitatea de învățământ în care sunt școlarizați, la solicitarea scrisă a părintelui/reprezentantului legal al acestora sau la solicitarea scrisă a beneficiarilor primari majori."},{"article":"127","articleNumber":127,"legalText":"Consiliile profesorale din unitățile de învățământ de stat, particular sau confesional validează situația școlară a beneficiarilor primari, pe clase, în ședința de încheiere a cursurilor, iar secretarul consiliului consemnează în procesul-verbal numărul beneficiarilor primari promovați, numărul și numele beneficiarilor primari corigenți, repetenți, amânați, exmatriculați, în situație de abandon școlar, precum și numele beneficiarilor primari cu note la purtare mai mici de 7, respectiv 8 pentru profilul pedagogic și unitățile de învățământ teologic și militar/calificative mai puțin de \"Bine\".\nSituația școlară a beneficiarilor primari corigenți, amânați, repetenți sau în situație de abandon școlar se comunică în scris părinților sau reprezentanților legali sau, după caz, beneficiarilor primari majori de către învățător/institutor/profesorul pentru învățământul primar/profesorul diriginte, în cel mult 7 zile de la încheierea cursurilor.\nPentru elevii amânați sau corigenți, învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte comunică în scris părinților/reprezentantului legal programul de desfășurare a examenelor de corigență și perioada de încheiere a situației școlare.\nNu pot fi făcute publice, fără acordul părintelui/reprezentantului legal sau al elevului/ absolventului major, documentele elevului, cu excepția situației prevăzute de Legea nr. 272/2004 privind protecția și promovarea drepturilor copilului, republicată, cu modificările și completările ulterioare."},{"article":"128","articleNumber":128,"legalText":"Examenele organizate de unitățile de învățământ sunt:\nexamen de corigență;\nexamen de încheiere a situației școlare pentru elevii declarați amânați;\nexamen de diferențe pentru elevii a căror înscriere în unitatea de învățământ este condiționată de promovarea unor astfel de examene/evaluări;\nexaminări/testări organizate în vederea înscrierii beneficiarilor primari în clasa a V-a.\nunitățile de învățământ liceal pot organiza concurs de admitere în clasa a IX-a, pentru anumite specializări sau pentru toate specializările, pentru maximum 50% din numărul de locuri atribuite prin planul de școlarizare, raportat la numărul de formațiuni de studiu după susținerea de către elevi a evaluării naționale.\nOrganizarea în unitățile de învățământ a examenelor de admitere în învățământul liceal sau profesional, inclusiv învățământ profesional și tehnic dual, precum și a examenelor și evaluărilor naționale se face conform metodologiilor aprobate prin ordin al ministrului educației.\nSe interzice organizarea unor examinări în vederea înscrierii beneficiarilor primari în prima clasă a învățământului primar. În clasa pregătitoare sunt înscriși copiii care au împlinit vârsta de 6 ani până la data începerii anului școlar. La solicitarea scrisă a părinților/reprezentanților legali, pot fi înscriși în clasa pregătitoare și copiii care împlinesc vârsta de 6 ani până la sfârșitul anului calendaristic, dacă dezvoltarea lor psihosomatică este corespunzătoare.\nFac excepție de la prevederile alin. (3) unitățile de învățământ cu predare în limbile minorităților naționale, care pot organiza testări ale nivelului cunoașterii limbii de predare, în cazul în care numărul candidaților la înscrierea în clasa pregătitoare depășește numărul de locuri, în baza metodologiei de înscriere în învățământul primar aprobate prin ordin al ministrului educației.\nOrganizarea unor examinări în vederea înscrierii beneficiarilor primari în clasa pregătitoare este permisă pentru unitățile de învățământ cu profil artistic și cu profil sportiv, în vederea testării aptitudinilor specifice, în baza metodologiei de înscriere în învățământul primar aprobate prin ordin al ministrului educației.\nOrganizarea unor examinări în vederea înscrierii beneficiarilor primari în clasa a V-a se realizează conform Metodologiei de înscriere a beneficiarilor primari în clasa a V- a la unitățile de învățământ care nu dețin clase de nivel primar prevăzute în Anexa nr. 4, la prezentul regulament.\nPentru elevii cu cerințe educaționale speciale se asigură condiții de egalizare de șanse, în funcție de tipul de tulburare/afecțiune/dizabilitate, atât pe parcursul procesului de învățare cât și în cadrul examenelor organizate la nivelul unității de învățământ.\nÎn unitățile de învățământ din domeniile apărării, informațiilor, ordinii publice și securității pot fi organizate și alte examene decât cele prevăzute la alin.(1), prevăzute în regulamentele specifice elaborate de către Ministerul Apărării Naționale, Ministerul Afacerilor Interne, Ministerul Justiției și alte instituții cu atribuții în domeniile respective."},{"article":"129","articleNumber":129,"legalText":"Desfășurarea examenelor de diferență are loc, de regulă, în perioada vacanțelor școlare."},{"article":"130","articleNumber":130,"legalText":"\nLa examenele de diferență pentru elevii care solicită transferul de la o unitate de învățământ la alta nu se acordă reexaminare."},{"article":"131","articleNumber":131,"legalText":"Pentru desfășurarea examenelor există trei tipuri de probe: scrise, orale și practice, după caz. La toate examenele se susțin, de regulă, două din cele trei probe – proba scrisă și proba orală.\nPentru disciplinele/modulele de studiu la care, datorită profilului sau/și specializării/ calificării profesionale, este necesară și proba practică, modalitățile de susținere a acesteia, precum și cea de-a doua probă de examen sunt stabilite de directorul unității de învățământ împreună cu membrii comisiei pentru curriculum.\nProba practică se susține la disciplinele/modulele care au, preponderent, astfel de activități.\nDirectorul unității de învățământ stabilește, prin decizie, în baza hotărârii consiliului de administrație, componența comisiilor și datele de desfășurare a examenelor. Comisia de corigențe are în componență un președinte și câte două cadre didactice examinatoare pentru fiecare comisie pe disciplină. Comisia este responsabilă de realizarea subiectelor.\nLa toate examenele, evaluarea beneficiarilor primari se face de cadre didactice de aceeași specialitate sau, după caz, specialități înrudite/din aceeași arie curriculară.\nPentru examinarea beneficiarilor primari corigenți, unul dintre cadrele didactice este cel care a predat elevului disciplina/modulul de învățământ în timpul anului școlar. În mod excepțional, în situația în care între elev și profesor există un conflict care ar putea vicia rezultatul evaluării, în comisia de examen este numit un alt cadru didactic de aceeași specialitate sau, după caz, de specialități înrudite din aceeași arie curriculară."},{"article":"132","articleNumber":132,"legalText":"Proba scrisă a examenelor are o durată de 45 de minute pentru învățământul primar și de 90 de minute pentru învățământul secundar și postliceal, din momentul primirii subiectelor de către elev. Proba scrisă conține două variante de subiecte, dintre care elevul tratează o singură variantă, la alegere.\nProba orală a examenelor se desfășoară prin dialog cadru didactic – elev, pe baza biletelor de examen. Numărul biletelor de examen este de două ori mai mare decât numărul beneficiarilor primari care susțin examenul la disciplina/modulul respectivă/respectiv. Fiecare bilet conține două subiecte. Elevul poate schimba biletul de examen cel mult o dată.\nFiecare cadru didactic examinator acordă elevului câte o/un notă/calificativ la fiecare probă susținută de acesta. Notele de la probele orale sau practice sunt întregi. Notele de la probele scrise pot fi și fracționare. Media aritmetică a notelor acordate la cele două sau trei probe, rotunjită la nota întreagă cea mai apropiată, reprezintă nota finală la examenul de corigență, fracțiunile de 50 de sutimi rotunjindu- se în favoarea elevului.\nMedia obținută de elev la examenul de corigență este media aritmetică, calculată cu două zecimale, fără rotunjire, a notelor finale acordate de cei doi examinatori. Între notele finale acordate de cei doi examinatori nu se acceptă o diferență mai mare de un punct. În caz contrar, medierea o face președintele comisiei de examen.\nLa clasele la care evaluarea cunoștințelor se face prin calificative se procedează astfel: după corectarea lucrărilor scrise și după susținerea examenului oral, fiecare examinator acordă propriul calificativ; calificativul final al elevului la examenul de corigență se stabilește de comun acord între cei doi examinatori."},{"article":"133","articleNumber":133,"legalText":"Elevul corigent este declarat promovat la disciplina/modulul de examen dacă obține cel puțin calificativul \"Suficient\"/media 5.\nSunt declarați promovați anual elevii care obțin, la fiecare disciplină/modul la care susțin examenul de corigență, cel puțin calificativul \"Suficient\"/media 5.\nMedia obținută la examenul de corigență, la cel de încheiere a situației școlare pentru elevii amânați pentru un an și la examenul de diferență care echivalează o disciplină studiată timp de un an școlar constituie media anuală a disciplinei respective și intră în calculul mediei generale anuale.\nLa examenul de încheiere a situației școlare pentru elevii amânați media obținută constituie media anuală a elevului la disciplina respectivă.\nFac excepție de la prevederile alin. (1), (2) și (4) elevii din învățământul vocațional în cazul cărora media de promovare a examenelor de corigență la disciplinele de specialitate este cea prevăzută la art.116, alin.(1) – (4)."},{"article":"134","articleNumber":134,"legalText":"Elevii corigenți sau amânați care nu se pot prezenta la examene din motive temeinice, dovedite cu acte, depuse în cel mult 7 zile lucrătoare de la data examenului, sunt examinați la o dată ulterioară, stabilită de consiliul de administrație, dar nu mai târziu de începerea cursurilor noului an școlar. Perioada se poate prelungi, în mod excepțional, pentru situații obiective, prin decizie a inspectoratului școlar.\nPentru elevele gravide și elevii părinți aflați în perioada de îngrijire a copilului, precum și în situații excepționale, respectiv internări în spital, imobilizări la pat etc., dovedite cu acte, inspectoratul școlar poate aproba susținerea examenului și după începerea cursurilor noului an școlar."},{"article":"135","articleNumber":135,"legalText":"Rezultatele obținute la examenele de încheiere a situației școlare, la examenele pentru elevii amânați și la examenele de corigență, inclusiv la cele de reexaminare, se consemnează în catalogul de examen de către cadrele didactice examinatoare și se trec în catalogul clasei de către secretarul- șef/secretarul unității de învățământ, în termen de maximum 5 zile de la afișarea rezultatelor, dar nu mai târziu de data începerii cursurilor noului an școlar, cu excepția situațiilor prevăzute la art. 134 alin. (2), când rezultatele se consemnează în catalogul clasei în termen de 5 zile de la afișare.\nRezultatele obținute de elevi la examenele de diferență se consemnează în catalogul de examen de către cadrele didactice examinatoare, iar în registrul matricol și în catalogul clasei de către secretarul- șef/secretarul unității de învățământ.\nÎn catalogul de examen se consemnează calificativele/notele acordate la fiecare probă, nota finală acordată de fiecare cadru didactic examinator sau calificativul, precum și media obținută de elev la examen, respectiv calificativul final. Catalogul de examen se semnează de către examinatori și de către președintele comisiei, imediat după terminarea examenului.\nPreședintele comisiei de examen predă secretarului unității de învățământ toate documentele specifice acestor examene: cataloagele de examen, lucrările scrise și însemnările beneficiarilor primari la proba orală/practică. Aceste documente se predau imediat după finalizarea examenelor, dar nu mai târziu de data începerii cursurilor noului an școlar, cu excepția situațiilor prevăzute la art. 134 alin. (2).\nLucrările scrise și foile cu însemnările elevului la proba orală a examenului se păstrează în arhiva unității de învățământ timp de un an.\nRezultatul la examenele de corigență și la examenele de încheiere a situației pentru elevii amânați, precum și situația școlară anuală a beneficiarilor primari se afișează, la loc vizibil, a doua zi după încheierea sesiunii de examen, cu respectarea legislației în vigoare\nprivind protecția datelor cu caracter personal, și se consemnează în procesul-verbal al primei\nședințe a consiliului profesoral."},{"article":"136","articleNumber":136,"legalText":"După terminarea sesiunii de examen, de încheiere a situației de corigență sau de reexaminare, învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte consemnează în catalog situația școlară a beneficiarilor primari care au participat la aceste examene."},{"article":"137","articleNumber":137,"legalText":"Beneficiarii primari ai educației au dreptul să se transfere de la o unitate de învățământ la alta, de la o formațiune de studiu la alta, de la un profil la altul și de la o filieră la alta, în condițiile stabilite de prevederile legii și ale prezentului regulament și ale regulamentului de organizare și funcționare a unității de învățământ la care se face transferul."},{"article":"138","articleNumber":138,"legalText":"Transferul beneficiarilor primari ai educației se face cu acordul consiliului de administrație al unității de învățământ primitoare și cu avizul consultativ al consiliului de administrație al unității de învățământ de la care se transferă. Consiliul de administrație al unității de învățământ la care se solicită transferul motivează, în scris, refuzul de aprobare a cererii.\n(la 18-10-2024, sintagma: Transferul beneficiarilor primari ai educației antepreșcolare face a fost înlocuită de RECTIFICAREA nr. 5.726 din 6 august 2024, publicată în MONITORUL OFICIAL nr. 1046 din 18 octombrie 2024 )\nÎn cazul copiilor victime sau martori ai violenței domestice, inspectoratele școlare aprobă transferul urgent, cu caracter temporar, la unitățile școlare recomandate de către instituțiile care oferă servicii sociale pentru prevenirea și combaterea violenței domestice, conform procedurii stabilite de către Ministerul Educației."},{"article":"139","articleNumber":139,"legalText":"În învățământul antepreșcolar/preșcolar, primar, gimnazial, învățământul liceal, postliceal, precum și în învățământul preuniversitar tehnologic în sistem dual, elevii se pot transfera de la o grupă/formațiune de studiu la alta, în aceeași unitate de învățământ, sau de la o unitate de învățământ la alta, cu încadrarea în numărul maxim de beneficiari primari ai educației pe formațiune de studiu și în limita cifrei de școlarizare aprobate/repartizate de ISJ/ISMB.\nÎn învățământul preuniversitar tehnologic în sistem dual, transferul beneficiarilor primari de la o grupă/formațiune de studiu la alta, în aceeași unitate de învățământ, sau de la o unitate de învățământ la alta, se face și prin consultarea operatorului economic, partener al unității de învățământ la care se solicită transferul.\nÎn situații excepționale, bine motivate, în care transferul nu se poate face cu încadrarea în numărul maxim de beneficiari primari ai educației la grupă/formațiunea de studiu, ISJ/ISMB poate aproba depășirea efectivului maxim cu cel mult 2 beneficiari peste efectivul maxim, pe baza justificării din partea consiliului de administrație al unității de învățământ. Pentru situațiile excepționale în care se solicită depășirea cu peste 2 beneficiari primari a numărului maxim de antepreșcolari/preșcolari/elevi la grupă/formațiunea de studiu, aprobarea va fi dată de Ministerul Educației, conform metodologiei în vigoare."},{"article":"140","articleNumber":140,"legalText":"În învățământul liceal sau postliceal, inclusiv în învățământul preuniversitar tehnologic în sistem dual, aprobarea transferurilor la care se schimbă filiera, profilul, domeniul de pregătire, specializarea/calificarea profesională este condiționată de susținerea și promovarea evaluării prin examene de diferență.\nDisciplinele/Modulele la care se susțin examene de diferență se stabilesc prin compararea celor două planuri-cadru. Modalitățile de susținere a acestor diferențe se stabilesc de către consiliul de administrație al unității de învățământ, la propunerea membrilor comisiei pentru curriculum."},{"article":"141","articleNumber":141,"legalText":"Elevii din învățământul liceal și din învățământul postliceal, inclusiv în învățământul preuniversitar tehnologic în sistem dual, se pot transfera, păstrând forma de învățământ, cu respectarea următoarelor condiții:\nîn cadrul învățământului liceal, elevii din clasa a IX-a se pot transfera, cu păstrarea filierei, profilului și specializării, în timpul anului școlar, în vacanțele școlare, dacă media lor de admitere, fără a lua în considerație elevii admiși pe locurile speciale pentru elevii romi și pentru cei cu cerințe educaționale speciale (CES), este cel puțin egală cu media ultimului admis prin procesul de repartizare computerizată la specializarea la care se solicită transferul, doar în situații medicale deosebite, pe baza avizului comisiei medicale\njudețene/a municipiului București, acolo unde există, sau a documentelor medicale justificative, și în situațiile excepționale prevăzute la art. 144 alin. (5), cu încadrarea în numărul maxim de elevi pe formațiune de studiu, stabilit de lege;\nîn cadrul învățământului liceal, elevii din clasele a X-a – a XII/XIII-a se pot transfera, de regulă, dacă media lor din ultimul an este cel puțin egală cu media ultimului promovat din clasa la care se solicită transferul. Excepțiile de la această prevedere se aprobă de către consiliul de administrație al unității de învățământ la care se solicită transferul;\nîn cadrul învățământului profesional și tehnic cu durata de 3 ani, reglementat de Legea nr. 1/2011, cu modificările și completările ulterioare, elevii din clasa a IX-a se pot transfera în timpul anului școlar numai dacă media lor de admitere este cel puțin egală cu media ultimului admis la calificarea profesională la care se solicită transferul, doar în situații medicale deosebite, pe baza avizului comisiei medicale județene/a municipiului București, acolo unde există, sau a documentelor medicale justificative, și în situațiile excepționale prevăzute la art. 144 alin. (5), în limita efectivelor maxime la clasă, stabilite de lege;\nîn cadrul învățământului profesional și tehnic cu durata de 3 ani, reglementat de Legea nr. 1/2011, cu modificările și completările ulterioare, elevii din clasele a X-a și a XI-a se pot transfera, de regulă, dacă media lor din ultimul an este cel puțin egală cu media ultimului promovat din clasa la care se solicită transferul. Excepțiile de la această prevedere se aprobă de către consiliul de administrație al unității de învățământ la care se solicită transferul;\nelevii din clasele a IX-a, a X-a și a XI-a din învățământul liceal se pot transfera în aceeași clasă în învățământul profesional și tehnic cu durata de 3 ani, reglementat de Legea nr. 1/2011, cu modificările și completările ulterioare, până la reorganizarea acestor clase în cadrul liceelor tehnologice, după susținerea examenelor de diferență, în limita efectivelor maxime la clasă, stabilite de lege și în baza criteriilor prevăzute de regulamentul de organizare și funcționare a unității de învățământ la care se solicită transferul;\nelevii care au finalizat clasa a IX-a a învățământului profesional și tehnic cu durata de 3 ani, reglementat de Legea nr. 1/2011, cu modificările și completările ulterioare, se pot transfera doar în clasa a IX-a a învățământului liceal, cu respectarea mediei de admitere la profilul și specializarea la care solicită transferul. Elevii care au finalizat clasa a X-a din învățământul profesional și tehnic cu durata de 3 ani, reglementat de Legea nr. 1/2011, cu modificările și completările ulterioare, se pot transfera în clasa a X- a din învățământul liceal, cu respectarea condiției de medie a clasei la care solicită transferul și după promovarea examenelor de diferență;\nPrevederile alin. (1) lit.c) – f) se aplică și în cazul învățământului profesional și tehnic dual cu durata de 3 ani reglementat de Legea nr. 1/2011, cu modificările și completările ulterioare, până la reorganizarea claselor în cadrul liceelor tehnologice.\nElevii din clasele IX-XII, școlarizați în forma de școlarizare din spital, pot solicita transferul în timpul anului școlar și în vacanțele școlare, fără îndeplinirea condiției de medie menționate la alin. (1) lit. a)-d) și f). Solicitarea trebuie să fie însoțită de scrisoarea medicală emisă de medicul specialist, care atestă internarea, monitorizarea sau recuperarea elevului în anul școlar respectiv, și de adeverința emisă de școala din spital, care atestă că elevul urmează forma de școlarizare din spital.\n(la 07-07-2026, Articolul 141, Capitolul IV, Titlul VII a fost completat de Punctul 6., Articolul I din ORDINUL nr. 4.261 din 26 iunie 2026, publicat în MONITORUL OFICIAL nr. 556 din\n7 iulie 2026 )"},{"article":"142","articleNumber":142,"legalText":"Elevii din învățământul liceal și din învățământul postliceal se pot transfera de la o formă de învățământ la alta astfel:\nelevii de la învățământul cu frecvență redusă se pot transfera la forma de învățământ cu frecvență zi/seral, după caz, după susținerea și promovarea examenelor de diferență, dacă au media anuală cel puțin 7 la fiecare disciplină/modul de studiu, în limita efectivelor maxime de elevi la clasă/ și potrivit criteriilor prevăzute în regulamentul de organizare și funcționare a unității de învățământ; transferul se face, de regulă, în aceeași clasă, cu excepția beneficiarilor primari din clasa terminală de la învățământul cu frecvență redusă, pentru care durata studiilor este mai mare cu un an, care se pot transfera, cu păstrarea filierei, profilului și specializării, în clasa terminală din învățământul cu frecvență zi/ seral;\nelevii de la învățământul cu frecvență zi/seral se pot transfera la forma de învățământ cu frecvență redusă, în limita efectivelor maxime de elevi la clasă;\nelevii din clasele terminale ale învățământului liceal se pot transfera, cu păstrarea filierei, profilului și specializării, de la învățământul cu frecvență zi/seral la învățământul cu frecvență redusă, în anul terminal.\nElevii din învățământul preuniversitar tehnologic în sistem dual se pot transfera în învățământul care nu are caracteristicile acestei forme de organizare, după susținerea, dacă este cazul, a examenelor de diferență, în limita efectivelor maxime de elevi la clasă și potrivit criteriilor prevăzute în regulamentul de organizare și funcționare a unității de învățământ; elevii din învățământul liceal și postliceal se pot transfera în învățământul preuniversitar tehnologic în sistem dual, după susținerea, dacă este cazul, a examenelor de diferență, cu respectarea prevederilor legale privind efectivele de elevi la clasă.\nprevederile lit.d) se aplică și în cazul transferului de la/la învățământul profesional și tehnic dual cu durata de 3 ani reglementat de Legea nr. 1/2011, cu modificările și completările ulterioare, până la reorganizarea claselor în cadrul liceelor tehnologice.\nelevii din clasele terminale ale învățământului liceal se pot transfera, cu păstrarea\nfilierei, profilului și specializării, de la învățământul cu frecvență cursuri de zi la învățământul cu frecvență cursuri serale, în anul terminal, pe parcursul vacanțelor școlare."},{"article":"143","articleNumber":143,"legalText":"Transferul beneficiarilor primari de la o formațiune de studiu cu predarea unei limbi de circulație internațională în regim normal la o formațiune de studiu cu predare intensivă, respectiv bilingvă a unei limbi de circulație internațională se realizează astfel:\nla nivel gimnazial, începând cu clasa a V-a, elevii care se transferă de la o unitate de învățământ la alta, de la o formațiune de studiu cu predarea unei limbi de circulație internațională în regim normal la o formațiune de studiu cu predarea intensivă a unei limbi de circulație internațională vor susține un test de aptitudini și cunoștințe la limba modernă;\ntestul de aptitudini și cunoștințe va fi elaborat la nivelul unității de învățământ la care elevul se transferă, de către o comisie desemnată în acest sens de directorul unității de învățământ;\nla nivel liceal, începând cu clasa a IX-a, elevii care se transferă la clasele cu predare intensivă, respectiv bilingvă a unei limbi de circulație internațională vor susține examene de diferență (după caz) și un test de verificare a competențelor lingvistice în unitatea de învățământ la care se transferă.\nSubiectele aferente testelor/probelor vor fi elaborate la nivelul unității de învățământ de către o comisie desemnată în acest sens de directorul unității de învățământ.\nElevii din secțiile bilingve francofone care solicită schimbarea disciplinei nonlingvistice vor susține examen de diferență în vacanțele școlare."},{"article":"144","articleNumber":144,"legalText":"Transferurile în care se păstrează forma de învățământ, filiera, profilul și specializarea se efectuează, de regulă, în perioada vacanțelor școlare. Prin excepție, transferurile de la nivelurile antepreșcolar și preșcolar se pot face oricând în timpul anului școlar, în limita numărului de locuri și ținând cont de interesul superior al copilului.\nTransferurile în care se schimbă forma de învățământ se efectuează în următoarele perioade:\nde la învățământul cu frecvență zi/seral la cel cu frecvență redusă, de regulă în vacanțele școlare; în aceleași perioade se efectuează și transferul la/de la învățământul preuniversitar liceal și postliceal tehnologic și de la/la învățământul preuniversitar tehnologic în sistem dual la învățământul liceal și postliceal tehnologic. Transferurile în cursul anului școlar se pot aproba în mod excepțional în cazurile precizate la alin. (5);\nde la învățământul cu frecvență redusă la cel cu frecvență zi/seral, numai în perioada vacanței de vară.\nTransferurile în învățământul liceal, inclusiv în sistem dual, cu schimbarea filierei/ profilului/specializării/calificării, se efectuează, de regulă, în perioada vacanței de vară, pentru anul școlar următor.\nPrin excepție de la prevederile alin. (3), unitățile de învățământ liceal militar pot efectua transferuri la clasa a IX-a, în primele 30 de zile de la începerea anului școlar, în condițiile prevăzute prin reglementări emise de Ministerul Apărării Naționale.\nTransferul beneficiarilor primari în timpul cursurilor școlare se poate efectua, în mod excepțional, cu respectarea prevederilor prezentului regulament, în următoarele situații:\nla schimbarea domiciliului părinților/reprezentanților legali într-o altă localitate, respectiv într- un alt sector al municipiului București;\nîn cazul unei recomandări medicale, eliberată pe baza expertizei medicale efectuate de comisia medicală județeană/a municipiului București;\nde la clasele de învățământ liceal la clasele de învățământ profesional cu durata de 3 ani reglementat de Legea nr. 1/2011, cu modificările și completările ulterioare, până la reorganizarea claselor în cadrul liceelor tehnologice;\nla/de la învățământul de artă, sportiv și militar;\nde la clasele cu program de predare intensivă a unei limbi străine sau cu program de predare bilingv la celelalte clase;\nîn alte situații excepționale, pe baza documentelor justificative, cu aprobarea consiliului de administrație al inspectoratului școlar."},{"article":"145","articleNumber":145,"legalText":"Gemenii, tripleții etc. se pot transfera în clasa celui cu media mai mare sau invers, la cererea părintelui/reprezentantului legal sau la cererea beneficiarilor primari, dacă aceștia sunt majori, cu aprobarea consiliului de administrație al unității de învățământ"},{"article":"146","articleNumber":146,"legalText":"Elevii din unitățile de învățământ liceal din sistemul de apărare, ordine publică și securitate națională declarați \"Inapt\"/\"Necorespunzător\" pentru cariera militară, cei care comit abateri grave sau cei care nu doresc să mai urmeze cursurile respectivelor unități de învățământ se pot transfera în alte unități de învățământ, în timpul anului școlar. Transferul se efectuează cu respectarea prevederilor prezentului regulament, precum și a reglementărilor specifice ministerelor de care aparțin unitățile de învățământ unde este înmatriculat elevul.\nÎn mod excepțional, elevii din unitățile de învățământ postliceal din sistemul de apărare, ordine publică și securitate națională declarați \"Inapt\"/\"Necorespunzător\" pentru cariera militară, cei care comit abateri grave sau cei care nu doresc să mai urmeze cursurile respectivelor unități de învățământ se pot transfera în alte unități de învățământ în unități\nde învățământ din rețeaua Ministerului Educației, în timpul anului școlar. Transferul se efectuează cu respectarea prevederilor prezentului regulament, precum și a reglementărilor specifice ministerelor de care aparțin unitățile de învățământ unde este înmatriculat elevul.\n(3) Copiii personalului, prevăzut la art. 16 alin. (1) lit. a și art. 18 alin. (1) lit. b) din Legea nr. 168/2020 pentru recunoașterea meritelor personalului participant la acțiuni militare, misiuni și operații pe teritoriul sau în afara teritoriului statului român și acordarea unor drepturi acestuia, familiei acestuia și urmașilor celui decedat, cu modificările și completările ulterioare și la art. 25 alin. (2) din Legea nr. 80/1995 privind statutul cadrelor militare, cu modificările și completările ulterioare, se pot transfera, la cerere, din unitățile de învățământ liceal, cu respectarea prevederilor art. 144, alin. (4), sau postliceal din rețeaua Ministerului Educației și în unitățile de învățământ liceal și postliceal din sistemul de apărare, ordine publică și securitate națională, dacă îndeplinesc criteriile de recrutare și au fost declarați \"Admis\" la probele de selecție, în baza dosarului de candidat, conform reglementărilor specifice ministerului respectiv."},{"article":"147","articleNumber":147,"legalText":"Elevii din învățământul preuniversitar particular sau confesional se pot transfera la unități de învățământ de stat, în condițiile prezentului regulament.\nElevii din învățământul preuniversitar de stat se pot transfera în învățământul particular, cu acordul unității primitoare și în condițiile stabilite de propriul regulament de organizare și funcționare.\nElevii din învățământul liceal preuniversitar cu profil pedagogic se pot transfera în condițiile stabilite de prezentul regulament, precum și de regulamentul specific de organizare și funcționare."},{"article":"148","articleNumber":148,"legalText":"Pentru copiii/tinerii cu cerințe educaționale speciale, în funcție de evoluția acestora, se pot face propuneri de reorientare dinspre învățământul special/special integrat spre învățământul de masă și invers.\nPropunerea de reorientare se face de către cadrul didactic care a lucrat cu copilul în cauză sau de către părinții sau reprezentanții legali ai copilului și de către consilierul școlar. Decizia de reorientare se ia de către comisia de orientare școlară și profesională din cadrul centrului județean de resurse și asistență educațională/Centrului Municipiului București de Resurse și Asistență Educațională, cu acordul părinților sau al reprezentanților legali."},{"article":"149","articleNumber":149,"legalText":"Elevele gravide și elevii părinți beneficiază cu prioritate de următoarele facilități:\ntransferul în cadrul unor formațiuni de studiu în care sunt școlarizați și elevi beneficiari ai unui program flexibil, pentru prevenirea și combaterea abandonului școlar.\nprioritate la transfer în cadrul unei unități de învățământ care are în structură nivelul antepreșcolar pentru înscrierea copilului, în cazul transferului între filiere, profiluri, specializări în învățământul liceal, conform prevederilor legale."},{"article":"150","articleNumber":150,"legalText":"După aprobarea transferului, unitatea de învățământ primitoare este obligată să solicite situația școlară a elevului în termen de 5 zile lucrătoare. Unitatea de învățământ de la care se transferă elevul este obligată să trimită la unitatea de învățământ primitoare situația școlară a celui transferat, în termen de 10 zile lucrătoare de la primirea solicitării. Până la primirea situației școlare de către unitatea de învățământ la care s-a transferat, elevul transferat participă la cursuri în calitate de audient."},{"article":"151","articleNumber":151,"legalText":"În scopul protejării dreptului la educație și combaterea abandonului școlar al elevelor gravide și al beneficiarilor primari părinți pe perioada școlarizării se realizează monitorizarea integrată a acestora.\nInspectoratul școlar sprijină coordonarea, prin metoda managementului de caz, a activității de monitorizare integrată realizată de către Direcția Generală de Asistență și Protecția Copilului.\nÎn cadrul managementului de caz, mecanismul de coordonare presupune implicarea specialiștilor care pot contribui la identificarea nevoilor elevelor gravide și ale beneficiarilor primari părinți, la planificarea, implementarea și monitorizarea integrată a intervenției din perspectiva realizării scopului prevăzut la alin. (1).\nÎn cadrul managementului de caz al elevelor gravide și al beneficiarilor primari părinți vor fi implicați, ca membri în echipă, inclusiv:\nun cadru didactic desemnat din cadrul CJRAE/CMBRAE pentru supravegherea parcursului educațional, pentru a ține în permanență legătura cu unitatea de învățământ la care aceștia sunt înmatriculați și pentru a propune măsuri educaționale în interesul acestora;\nun inspector școlar desemnat de către inspectoratul școlar cu rol în monitorizarea\nprogresului și parcursului școlar, din perspectiva asigurării continuării studiilor. De asemenea, inspectorul școlar realizează consilierea administrativă privind drepturile educaționale, precum și întocmirea dosarului cu documentele școlare ale elevului prin colaborarea cu unitatea de învățământ de bază.\nmediatorul școlar și mediatorul sanitar, pentru consilierea școlară și cea privind starea de sănătate."},{"article":"152","articleNumber":152,"legalText":"Părinții/reprezentanții legali ai beneficiarului primar sunt parteneri educaționali principali ai unităților de învățământ.\nPărinții/reprezentanții legali ai beneficiarului primar au acces la toate informațiile legate de sistemul de învățământ care privesc educația copiilor lor.\nPărinții/reprezentanții legali ai beneficiarului primar au dreptul de a fi susținuți de sistemul de învățământ, pentru a se educa și a-și îmbunătăți aptitudinile ca parteneri în relația familie-școală.\nStatul sprijină părinții/reprezentanții legali în vederea exercitării responsabilităților privind creșterea, îngrijirea, dezvoltarea și educarea beneficiarilor primari. În acest scop, în unitățile de învățământ se organizează cursuri de educație parentală pentru formarea și dezvoltarea abilităților parentale pentru părinți/reprezentanți legali ai beneficiarilor primari sau viitori părinți."},{"article":"153","articleNumber":153,"legalText":"Părintele/reprezentantul legal al beneficiarului primar are dreptul să fie informat periodic referitor la situația școlară și la comportamentul propriului copil și colaborează cu cadrele didactice în vederea îmbunătățirii situației școlare.\nPărintele/reprezentantul legal al beneficiarului primar are dreptul să dobândească informații referitoare numai la situația propriului copil."},{"article":"154","articleNumber":154,"legalText":"Părintele/reprezentantul legal al beneficiarului primar are acces în incinta unității de învățământ în concordanță cu procedura de acces, dacă:\na fost solicitat/a fost programat pentru o discuție cu un cadru didactic sau cu directorul/ directorul adjunct al unității de învățământ;\ndesfășoară activități în comun cu cadrele didactice;\ndepune o cerere/alt document la secretariatul unității de învățământ;\nparticipă la întâlnirile programate cu educatorul/educatoarea/ profesorul pentru educație timpurie/învățătorul/institutorul/profesorul pentru învățământ preșcolar/primar/profesorul diriginte;\nparticipă la acțiuni organizate de asociația de părinți;\nîn alte situații speciale prevăzute de regulamentul de organizare și funcționare a unității.\nConsiliul de administrație are obligația stabilirii procedurii de acces al părinților/ reprezentanților legali în unitățile de învățământ."},{"article":"155","articleNumber":155,"legalText":"Părinții/reprezentanții legali au dreptul să se constituie în asociații cu personalitate juridică, conform legislației în vigoare."},{"article":"156","articleNumber":156,"legalText":"Rezolvarea situațiilor conflictuale sesizate de părintele/reprezentantul legal al beneficiarului primar în care este implicat propriul copil se face prin discuții amiabile cu salariatul unității de învățământ implicat, educatorul/educatoarea/ profesorul pentru educație timpurie/învățătorul/institutorul/profesorul pentru învățământ preșcolar/primar/profesorul diriginte;\nPărintele/reprezentantul legal al beneficiarului primar are dreptul de a solicita ca la discuții să participe și reprezentantul părinților/reprezentanților legali. În situația în care discuțiile amiabile nu conduc la rezolvarea conflictului, părintele/reprezentantul legal are dreptul de a se adresa conducerii unității de învățământ, printr-o cerere scrisă, în vederea rezolvării problemei.\nÎn cazul în care părintele/reprezentantul legal consideră că starea conflictuală nu a fost rezolvată la nivelul unității de învățământ, acesta are dreptul de a se adresa, în scris, inspectoratului școlar pentru a media și rezolva starea conflictuală."},{"article":"157","articleNumber":157,"legalText":"Potrivit prevederilor legale, părintele/reprezentantul legal are obligația de a asigura\nfrecvența școlară a beneficiarului primar în învățământul obligatoriu și de a lua măsuri pentru școlarizarea acestuia până la finalizarea studiilor.\nPărinții/reprezentantul legal au obligația să asigure participarea la cursuri a beneficiarului primar minor pe întreaga perioadă a învățământului obligatoriu. Nerespectarea acestei obligații constituie contravenție și se sancționează conform prevederilor legale în vigoare.\nConform legislației în vigoare, la înscrierea beneficiarului primar în unitatea de învățământ, părintele/reprezentantul legal are obligația de a prezenta documentele medicale solicitate, în vederea menținerii unui climat sănătos la nivel de grupă/formațiune de studiu, pentru evitarea degradării stării de sănătate a celorlalți beneficiari primari din colectivitate/unitatea de învățământ.\nPărintele/reprezentantul legal are obligația ca, minimum o dată pe lună, să ia legătura cu profesorul pentru învățământul antepreșcolar/preșcolar/învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte pentru a cunoaște evoluția copilului/elevului, prin mijloace stabilite de comun acord. Prezența părintelui sau a reprezentantului legal va fi consemnată în caietul educatorului/educatoarei/profesorului pentru educație timpurie/ învățătorului/institutorului/profesorului pentru învățământ preșcolar/primar/profesorului diriginte, cu nume, dată și semnătură.\nPărintele/reprezentantul legal răspunde material pentru distrugerile bunurilor din patrimoniul unității de învățământ, cauzate de beneficiarul primar.\nPărintele/reprezentantul legal al antepreșcolarului/preșcolarului sau al elevului din învățământul primar are obligația să îl însoțească până la intrarea în unitatea de învățământ, iar la terminarea activităților educative/orelor de curs să îl preia. În cazul în care părintele/reprezentantul legal nu poate să desfășoare o astfel de activitate, împuternicește un alt adult.\nPărintele/reprezentantul legal al elevului din învățământul primar, gimnazial și liceal are obligația de a solicita, în scris, retragerea elevului în vederea înscrierii acestuia într-o unitate de învățământ din străinătate.\nDispozițiile alin. (6) nu se aplică în situațiile în care transportul copiilor la și de la unitatea de învățământ se realizează cu microbuzele școlare. Asigurarea securității și siguranței în incinta unității de învățământ la venirea și părăsirea acesteia, în special pentru elevii din clasa pregătitoare, se stabilește prin regulamentul de organizare și funcționare a unității de învățământ.\nPărintele/reprezentantul legal al antepreșcolarului/preșcolarului sau al elevului din învățământul obligatoriu are obligația de a-l susține pe acesta în activitatea de învățare desfășurată, inclusiv în activitatea de învățare realizată prin intermediul tehnologiei și al internetului, și de a colabora cu personalul unității de învățământ pentru desfășurarea în condiții optime a acestei activități.\nPărinții/reprezentanții legali ai căror copii frecventează grupele cu program prelungit din unitățile de educație timpurie publice plătesc o contribuție lunară de hrană, stabilită prin decizia consiliului de administrație al unității de învățământ, cu consultarea consiliului reprezentativ al părinților/reprezentanților legali. Aceasta nu poate depăși contribuția de hrană stabilită prin art. 129 alin. (6) din Legea nr. 272/2004 privind protecția și promovarea drepturilor copilului și pentru stabilirea unor măsuri de asistență socială, cu modificările și completările ulterioare.\nAutoritățile administrației publice, din fonduri proprii, pot suporta integral sau parțial, contribuția lunară de hrană.\nContribuția lunară de hrană pentru copiii înscriși în unitățile de educație timpurie se stabilește în funcție de numărul efectiv de zile de prezență a copilului la programul zilnic.\nNumărul de zile în care copiii au frecventat unitatea în care se oferă servicii de educație timpurie este monitorizat prin registrul de prezență, completat de cadrele didactice.\nContribuția părinților/reprezentanților legali la suportarea cheltuielilor lunare de hrană pentru copiii înscriși în unitatea de educație timpurie cu program prelungit se realizează cu plata în avans pentru o lună calendaristică.\nContribuția lunară de hrană pentru copiii care au achitat taxa și nu au frecventat programul unității de educație timpurie este reportată pentru luna următoare, pentru zilele în care au absentat.\nÎn situația retragerii copilului de la unitatea de educație timpurie cu program prelungit, părintele beneficiază de returnarea sumelor plătite anticipat pentru asigurarea hranei, în baza depunerii unei cereri scrise."},{"article":"158","articleNumber":158,"legalText":"Se interzice oricăror persoane agresarea fizică, psihică, verbală etc. a copiilor/ beneficiarilor primari și a personalului unității de învățământ."},{"article":"159","articleNumber":159,"legalText":"Respectarea prevederilor prezentului regulament și a regulamentului de organizare și funcționare a unității de învățământ este obligatorie pentru părinții/reprezentanții legali ai beneficiarilor primari."},{"article":"160","articleNumber":160,"legalText":"Adunarea generală a părinților/reprezentanților legali este constituită din toți părinții\nsau reprezentanții legali ai copiilor/beneficiarilor primari de la o grupă/formațiune de studiu.\nAdunarea generală a părinților/reprezentanților legali hotărăște cu privire la susținerea cadrelor didactice și a echipei manageriale a unității de învățământ privind activitățile și auxiliarele didactice și mijloacele de învățământ utilizate în demersul de asigurare a condițiilor necesare educării copiilor/beneficiarilor primari.\nÎn adunarea generală a părinților/reprezentanților legali se discută problemele generale ale colectivului de beneficiari primari, și nu situația concretă a unui beneficiar primar. Situația unui beneficiar primar se discută individual, numai în prezența părintelui/ reprezentantului legal al beneficiarului primar respectiv."},{"article":"161","articleNumber":161,"legalText":"Adunarea generală a părinților/reprezentanților legali se convoacă de către educator/ educatoare/profesor pentru educație timpurie/învățător/învățătoare/institutor/profesorul pentru învățământul preșcolar/primar/profesorul diriginte, de către președintele comitetului de părinți al clasei sau de către 1/3 din numărul total al membrilor săi.\nAdunarea generală a părinților/reprezentanților legali se convoacă ori de câte ori este nevoie, este valabil întrunită în prezența a jumătate plus unu din totalul părinților/ reprezentanților legali ai copiilor/beneficiarilor primari din grupa/clasa respectivă și adoptă hotărâri cu votul a jumătate plus unu din cei prezenți."},{"article":"162","articleNumber":162,"legalText":"În unitățile de învățământ, la nivelul fiecărei grupe/clase, se înființează și funcționează comitetul de părinți.\nComitetul de părinți se alege, prin majoritate simplă a voturilor, în fiecare an, în adunarea generală a părinților/reprezentanților legali, convocată de educatoare/învățător/ institutor/profesorul pentru învățământul preșcolar sau primar/profesorul diriginte care prezidează ședința.\nConvocarea adunării generale pentru alegerea comitetului de părinți are loc în primele 15 zile calendaristice de la începerea cursurilor anului școlar.\nComitetul de părinți pe grupă/clasă se compune din 3 persoane: un președinte și 2 membri. În prima ședință după alegere, membrii comitetului decid responsabilitățile fiecăruia, pe care le comunică educatorului/educatoarei/profesorului pentru educație timpurie/profesorului pentru învățământ preșcolar/profesorului pentru învățământ primar/profesorului diriginte.\nComitetul de părinți pe grupă/clasă reprezintă interesele părinților sau ale reprezentanților legali ai beneficiarilor primari ai clasei în adunarea generală a părinților/ reprezentanților legali, în consiliul profesoral, în consiliul clasei și în relațiile cu echipa managerială."},{"article":"163","articleNumber":163,"legalText":"Comitetul de părinți pe grupă/clasă are următoarele atribuții:\npune în practică deciziile luate de către adunarea generală a părinților/reprezentanților legali beneficiarilor primari clasei. Deciziile se iau cu majoritatea simplă a voturilor părinților/reprezentanților legali;\nsusține organizarea și desfășurarea de proiecte, programe și activități educative extrașcolare la nivelul grupei/clasei și al unității de învățământ;\nsusține organizarea și desfășurarea de programe de prevenire și combatere a violenței, de asigurare a siguranței și securității, de combatere a discriminării și de reducere a absenteismului în mediul școlar;\npoate susține activitățile dedicate întreținerii, dezvoltării și modernizării bazei materiale a grupei/clasei și a unității de învățământ prin acțiuni de voluntariat;\nsprijină conducerea unității de învățământ și educatorul/educatoarea/profesorul pentru educație timpurie/învățătorul/ institutorul/profesorul pentru învățământ antepreșcolar/ preșcolar/primar/profesorul diriginte și se implică activ în întreținerea, dezvoltarea și modernizarea bazei materiale a grupei/clasei și a unității de învățământ, conform hotărârii adunării generale;\nsusține organizarea și desfășurarea de activități de consiliere și orientare socioprofesionale;\nse implică în asigurarea securității copiilor/beneficiarilor primari în cadrul activităților educative, extrașcolare și extracurriculare."},{"article":"164","articleNumber":164,"legalText":"Președintele comitetului de părinți pe grupă/clasă reprezintă interesele părinților/ reprezentanților legali în relațiile cu consiliul reprezentativ al părinților/reprezentanților legali și asociația de părinți și, prin acestea, în relație cu conducerea unității de învățământ și alte foruri, organisme și organizații."},{"article":"165","articleNumber":165,"legalText":"În baza hotărârii adunării generale, comitetul de părinți poate decide să susțină, inclusiv financiar prin asociația de părinți cu personalitate juridică, cu respectarea\nprevederilor legale în domeniul financiar, întreținerea, dezvoltarea și modernizarea bazei materiale a unității de învățământ și a grupei/clasei. Hotărârea comitetului de părinți nu este obligatorie.\nSponsorizarea unei grupe/clase de către un operator economic/persoane fizice se face cunoscută comitetului de părinți. Sponsorizarea nu atrage după sine drepturi suplimentare pentru copii/elevi/părinți sau reprezentanți legali.\nEste interzisă și constituie abatere disciplinară implicarea copiilor/beneficiarilor primari sau a personalului din unitatea de învățământ în strângerea și/sau gestionarea fondurilor."},{"article":"166","articleNumber":166,"legalText":"La nivelul fiecărei unități de învățământ funcționează consiliul reprezentativ al părinților/reprezentanților legali.\nConsiliul reprezentativ al părinților/reprezentanților legali din unitatea de învățământ este compus din președinții comitetelor de părinți.\nConsiliul reprezentativ al părinților/reprezentanților legali este o structură fără personalitate juridică a cărei activitate este reglementată printr-un regulament adoptat prin hotărârea adunării generale a președinților comitetelor de părinți pe grupă/clasă din unitatea de învățământ, care nu are patrimoniu, nu are buget de venituri și cheltuieli, nu are dreptul de a colecta cotizații, donații și a primi finanțări de orice fel de la persoane fizice sau juridice. Se poate implica în activitățile unității de învățământ prin acțiuni cu caracter logistic – voluntariat.\nLa nivelul fiecărei unități de învățământ se poate constitui asociația de părinți, în conformitate cu legislația în vigoare privind asociațiile și fundațiile, care reprezintă drepturile și interesele părinților/reprezentanților legali din unitatea de învățământ, membri ai acesteia."},{"article":"167","articleNumber":167,"legalText":"Consiliul reprezentativ al părinților/reprezentanților legali își desemnează președintele și 2 vicepreședinți ale căror atribuții se stabilesc imediat după desemnare, de comun acord între cei 3, și se consemnează în procesul-verbal al ședinței.\nConsiliul reprezentativ al părinților/reprezentanților legali se întrunește în ședințe ori de câte ori este necesar. Convocarea ședințelor consiliului reprezentativ al părinților/ reprezentanților legali se face de către președintele acestuia sau, după caz, de unul dintre vicepreședinți.\nConsiliul reprezentativ al părinților/reprezentanților legali desemnează reprezentanții părinților/reprezentanților legali în organismele de conducere și comisiile unității de învățământ.\nConsiliul reprezentativ al părinților/reprezentanților legali este întrunit statutar în prezența a două treimi din numărul total al membrilor, iar hotărârile se adoptă prin vot deschis, cu majoritatea simplă a voturilor celor prezenți. În situația în care nu se întrunește cvorumul, ședința se reconvoacă pentru o dată ulterioară, fiind statutară în prezența a jumătate plus 1 din totalul membrilor.\nPreședintele reprezintă consiliul reprezentativ al părinților/reprezentanților legali în relația cu alte persoane fizice și juridice.\nPreședintele prezintă, anual, raportul de activitate al consiliului reprezentativ al părinților/reprezentanților legali.\nÎn situații obiective, cum ar fi calamități, intemperii, epidemii, pandemii, alte situații excepționale, ședințele consiliului reprezentativ al părinților/reprezentanților legali se pot desfășura online, prin mijloace electronice de comunicare, în sistem de videoconferință."},{"article":"168","articleNumber":168,"legalText":"Consiliul reprezentativ al părinților/reprezentanților legali are următoarele atribuții:\npropune unităților de învățământ discipline și domenii care să se studieze prin curriculumul la decizia elevului din oferta școlii, inclusiv din oferta națională;\nsprijină parteneriatele educaționale între unitățile de învățământ și instituțiile/ organizațiile cu rol educativ din comunitatea locală;\nsusține unitățile de învățământ în derularea programelor de prevenire și de combatere a absenteismului și a violenței în mediul școlar;\npromovează imaginea unității de învățământ în comunitatea locală;\nse ocupă de conservarea, promovarea și cunoașterea tradițiilor culturale specifice minorităților în plan local, de dezvoltarea multiculturalității și a dialogului cultural;\nsusține unitatea de învățământ în organizarea și desfășurarea tuturor activităților;\nsusține conducerea unității de învățământ în organizarea și în desfășurarea consultațiilor cu părinții sau reprezentanții legali, pe teme educaționale;\ncolaborează cu instituțiile publice de asistență socială/educațională specializată, direcțiile generale de asistență socială și protecția copilului, cu organele de autoritate tutelară sau cu organizațiile nonguvernamentale cu atribuții în acest sens, în vederea soluționării situației beneficiarilor primari care au nevoie de ocrotire;\nsusține unitatea de învățământ în activitatea de consiliere și orientare socioprofesională sau de integrare socială a absolvenților;\npropune măsuri pentru școlarizarea beneficiarilor primari din învățământul obligatoriu și încadrarea în muncă a absolvenților;\nse implică direct în implementarea activităților din cadrul parteneriatelor ce se derulează în unitatea de învățământ, la solicitarea cadrelor didactice;\nsprijină conducerea unității de învățământ în asigurarea sănătății și securității beneficiarilor primari;\nare inițiative și se implică în îmbunătățirea calității vieții copiilor/beneficiarilor primari, în buna desfășurare a activității în internate și în cantine;\nsusține conducerea unității de învățământ în organizarea și desfășurarea programului \"Școala după școală\"."},{"article":"169","articleNumber":169,"legalText":"Consiliul reprezentativ al părinților/reprezentanților legali din unitatea de învățământ poate face demersuri privind atragerea de resurse financiare, care vor fi gestionate de către unitatea de învățământ, constând în contribuții, donații, sponsorizări etc. din partea unor persoane fizice sau juridice din țară și din străinătate care vor fi utilizate pentru:\nmodernizarea și întreținerea patrimoniului unității de învățământ, a bazei materiale și sportive;\nacordarea de premii și de burse beneficiarilor primari;\nsprijinirea financiară a unor activități extrașcolare;\nacordarea de sprijin financiar sau material copiilor care provin din familii cu situație materială precară;\nalte activități care privesc bunul mers al unității de învățământ sau care sunt aprobate prin hotărâre de către adunarea generală a părinților/reprezentanților legali pe care îi reprezintă.\nConsiliul reprezentativ al părinților/reprezentanților legali colaborează cu structurile asociative ale părinților/reprezentanților legali la nivel local, județean, regional și național."},{"article":"170","articleNumber":170,"legalText":"Unitățile de învățământ încheie cu părinții sau reprezentanții legali/elevii majori, în momentul înscrierii beneficiarilor primari în registrul unic matricol, un contract educațional, în care sunt înscrise drepturile și obligațiile reciproce ale părților, conform prevederilor legale în vigoare. Contractul educațional are caracterul juridic al unui contract de adeziune.\nModelul contractului educațional este prezentat în Anexa nr. 5 la prezentul regulament.\nPrin hotărâre a consiliului de administrație, la contractul educațional pot fi adăugate și alte clauze, a căror natură nu poate afecta interesul superior al beneficiarului primar în funcție de specificul fiecărei unități și după consultarea consiliului reprezentativ al părinților/reprezentanților legali, prin act adițional semnat de ambele părți."},{"article":"171","articleNumber":171,"legalText":"Contractul educațional este valabil pe toată perioada de școlarizare în cadrul unității de învățământ.\nContractul educațional se încheie în două exemplare originale, unul pentru părinte sau reprezentant legal/elev major, altul pentru unitatea de învățământ, și își produce efectele de la data semnării. Unitatea de învățământ arhivează exemplarul contractului educațional pe toată perioada de școlarizare a elevului și pentru încă doi ani din momentul în care elevul părăsește unitatea de învățământ.\nConsiliul de administrație al unității de învățământ preuniversitar monitorizează modul de îndeplinire a obligațiilor prevăzute în contractul educațional.\nVerificarea modului de respectare a prevederilor contractului educațional de către părți se realizează din oficiu sau la sesizarea părintelui/reprezentantului legal/elevului major sau a directorului unității de învățământ preuniversitar.\nÎn cazul nerespectării prevederilor contractului educațional, inspectoratele școlare/ inspectoratul școlar al municipiului București pot dispune aplicarea măsurilor sau sancțiunilor, conform prevederilor legale."},{"article":"172","articleNumber":172,"legalText":"Următoarele fapte constituie contravenții, în măsura în care nu constituie infracțiuni, și se sancționează după cum urmează:\nrefuzul semnării contractului educațional de către părinte sau reprezentantul legal, se sancționează cu amendă de la 1.000 de lei la 5.000 de lei;\nrefuzul semnării contractului educațional de către directorul unității de învățământ, se sancționează cu amendă de la 1.000 de lei la 5.000 de lei, sau cu prestarea unei activități în folosul comunității.\nContravențiile prevăzute la punctul 1) lit. a) și b) sunt sesizate de directorul, consiliul de administrație al unității de învățământ sau de către beneficiarii primari ori părinții/reprezentanții legali ai acestora.\nAplicarea sancțiunilor se realizează în conformitate cu prevederile art. 148, alin. (2)-\ndin Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare."},{"article":"173","articleNumber":173,"legalText":"În unitățile de învățământ preuniversitar din sistemul de apărare, ordine publică și securitate națională, elevii și, în cazul celor minori, împreună cu părinții sau reprezentanții legali ai acestora, încheie un contract educațional, al cărui conținut se stabilește prin ordin al conducătorului ministerului de resort, în care sunt înscrise drepturile și obligațiile reciproce ale părților."},{"article":"174","articleNumber":174,"legalText":"Autoritățile administrației publice locale, precum și reprezentanți ai comunității locale colaborează cu consiliul de administrație și cu directorul, în vederea atingerii obiectivelor unității de învățământ."},{"article":"175","articleNumber":175,"legalText":"Unitățile de învățământ pot realiza parteneriate cu asociații, fundații, instituții de educație și cultură, organisme economice/agenți economici și organizații guvernamentale și nonguvernamentale sau alte tipuri de organizații, în interesul beneficiarilor direcți ai educației."},{"article":"176","articleNumber":176,"legalText":"Unitățile de învățământ, de sine stătător sau în parteneriat cu autoritățile administrației publice locale și cu alte instituții și organisme publice și private: case de cultură, furnizori de formare continuă, parteneri sociali, organizații nonguvernamentale și altele asemenea, pot organiza la nivel local centre comunitare de învățare permanentă, pe baza unor oferte de servicii educaționale adaptate nevoilor specifice diferitelor grupuri-țintă interesate."},{"article":"177","articleNumber":177,"legalText":"Unitățile de învățământ, în conformitate cu legislația în vigoare și cu prevederile prezentului regulament, pot iniția, în parteneriat cu autoritățile administrației publice locale și cu organizațiile de părinți, în baza hotărârii consiliului de administrație, activități educative, recreative, de timp liber, pentru consolidarea competențelor dobândite sau pentru accelerarea învățării, precum și activități de recuperare cu elevii, prin programele \"Învățare remedială\" sau \"Școala după școală\"."},{"article":"178","articleNumber":178,"legalText":"Parteneriatul cu autoritățile administrației publice locale are ca scop derularea unor activități/programe educaționale în vederea atingerii obiectivelor educaționale stabilite de unitatea de învățământ.\nActivitățile derulate în parteneriat nu pot avea conotații politice, de propagandă electorală, de prozelitism religios, nu pot fi contrare moralei sau legilor statului, iar în cazul parteneriatelor cu agenții economici nu se poate face publicitate la produsele sau serviciile acestora.\nAutoritățile administrației publice locale asigură condițiile și fondurile necesare pentru implementarea și respectarea normelor de sănătate și securitate în muncă și pentru asigurarea securității copiilor/beneficiarilor primari și a personalului în perimetrul unității de învățământ."},{"article":"179","articleNumber":179,"legalText":"Unitățile de învățământ încheie parteneriate și protocoale de colaborare cu operatorii economici în vederea derulării orelor de instruire practică.\nProtocolul conține prevederi clare cu privire la responsabilitățile părților, referitoare la asigurarea securității beneficiarilor primari și a personalului unității de învățământ, respectarea normelor de sănătate și securitate în muncă, asigurarea transportului la și de la operatorul economic, durata activităților, drepturile și îndatoririle beneficiarilor primari, utilizarea fondurilor realizate, cu respectarea prevederilor legale în vigoare. De asemenea, unitățile de învățământ profesional și tehnic încheie parteneriate și protocoale de colaborare cu operatorii economici, în vederea derulării orelor de instruire practică. Unitățile de învățământ preuniversitar cu personalitate juridică ce școlarizează în învățământ profesional și tehnic dual încheie contracte de parteneriat cu unul sau mai mulți operatori economici sau cu o asociație/un consorțiu de operatori economici și cu unitatea administrativ-teritorială pe raza căreia se află unitatea școlară. Pentru pregătirea profesională, fiecare elev major, respectiv părintele sau reprezentantul legal al elevului minor din aceste unități de învățământ prevăzute încheie un contract de pregătire practică individual cu operatorul economic și unitatea de învățământ. Contractele prevăzute se reglementează prin metodologii specifice aprobate prin ordin al ministrului educației."},{"article":"180","articleNumber":180,"legalText":"Unitățile de învățământ încheie protocoale de parteneriat cu organizații nonguvernamentale, unități medicale, poliție, jandarmerie, instituții de cultură, asociații confesionale, alte organisme, în vederea atingerii obiectivelor educaționale stabilite prin proiectul de dezvoltare instituțională/planul de acțiune al unității de învățământ.\nProtocolul conține prevederi cu privire la responsabilitățile părților implicate, cu respectarea prevederilor legale în vigoare.\nÎn cazul derulării unor activități în afara perimetrului unității de învățământ, în protocol se va specifica concret cărei părți îi revine responsabilitatea asigurării securității copiilor/beneficiarilor primari.\nRezultatul activităților realizate va fi făcut public, prin afișare la sediul unității, pe site-ul școlii, prin comunicate de presă și prin alte mijloace de informare.\nUnitățile de învățământ pot încheia protocoale de parteneriat și pot derula activități comune cu unități de învățământ din străinătate, având ca obiectiv principal dezvoltarea personalității copiilor și a tinerilor, respectându-se legislația în vigoare din statele din care provin instituțiile respective.\nReprezentanții părinților/reprezentanților legali se vor implica direct în buna derulare a activităților din cadrul parteneriatelor ce se derulează în unitatea de învățământ."},{"article":"181","articleNumber":181,"legalText":"Se interzice constituirea de fonduri de protocol sau a oricărui alt fond destinat derulării examenelor/evaluărilor naționale."},{"article":"182","articleNumber":182,"legalText":"În unitățile de învățământ sunt interzise fumatul, precum și utilizarea tuturor categoriilor de produse care conțin tutun sau a țigaretelor electronice, conform Legii nr. 349/2002 pentru prevenirea și combaterea efectelor consumului produselor din tutun, cu modificările și completările ulterioare.\nÎn unitățile de învățământ sunt interzise deținerea, consumul sau comercializarea de droguri, băuturi alcoolice, substanțe etnobotanice sau alte substanțe.\nÎn unitățile de învățământ este interzisă organizarea sau participarea/promovarea participării la jocuri de noroc.\nInterdicțiile stipulate la alin. (1), (2) și (3) sunt valabile și pe perioada organizării de către cadrele didactice a diferitelor tipuri de activități extrașcolare și extracurriculare la care participă elevii unităților de învățământ preuniversitar.\nÎn unitățile de învățământ comercializarea sau oferirea cu titlu gratuit, inclusiv prin automate comerciale, a băuturilor energizante sunt interzise, conform prevederilor Legii nr. 61/1991 pentru sancționarea faptelor de încălcare a unor norme de conviețuire socială, a ordinii și liniștii publice, republicată, cu modificările și completările ulterioare.\nUtilizarea telefoanelor mobile sau a oricăror alte echipamente de comunicații electronice de către elevi se realizează conform prevederilor legale stipulate în Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare; utilizarea acestora în timpul orelor de curs se poate face numai la solicitarea cadrului didactic, în situația folosirii lor în procesul educativ. Prevederile nu se aplică echipamentelor pe care elevii cu CES sunt autorizați să le folosească.\nNerespectarea prevederilor referitoare la utilizarea telefoanelor/a altor echipamente de comunicații electronice poate duce la preluarea echipamentului de către personalul unității de învățământ în vederea predării, după caz, către părinți/reprezentanți legali ai beneficiarilor primari minori sau beneficiarilor primari majori conform regulamentului de organizare și funcționare al unității de învățământ."},{"article":"183","articleNumber":183,"legalText":"În unitățile de învățământ se asigură dreptul fundamental la învățătură și este interzisă orice formă de discriminare a copiilor/beneficiarilor primari și a personalului din unitate.\nÎn unitățile de învățământ sunt interzise măsurile care pot limita accesul la educație al beneficiarilor primari, cum ar fi, de exemplu, efectuarea de către aceștia a serviciului pe școală, interzicerea participării la cursuri sau sancționarea beneficiarilor primari care nu poartă uniforma unității de învățământ sau altele asemenea.\nÎn scopul protejării beneficiarilor primari și prevenirii traficului de minori, fiecare unitate de învățământ va implementa măsuri proactive de identificare și prevenire a cazurilor de trafic de persoane.\nÎn organizarea activităților de informare și educare pentru elevi și părinți/reprezentanți legali cu scopul de a crește gradul de conștientizare privind pericolele traficului de persoane, precum și modalitățile de prevenire ale acestuia, unitățile de învățământ vor colabora cu autoritățile locale, organizațiile non-guvernamentale și alte instituții relevante pentru a oferi suport și protecție beneficiarilor primari vulnerabili la riscul de trafic de persoane."},{"article":"184","articleNumber":184,"legalText":"Unitățile de învățământ preuniversitar și unitățile de educație extrașcolară au obligația\npublicării pe site-urile proprii și prin orice altă formă de comunicare publică existentă la nivelul unității școlare, a autorizației de securitate la incendiu pentru fiecare clădire de învățământ, precum și a autorizației sanitare de funcționare.\nPentru clădirile care nu dețin autorizație de securitate la incendiu, entitățile prevăzute la alin. (1) au obligația aducerii la cunoștința publicului, prin intermediul site-urilor proprii și prin orice altă formă de comunicare publică existentă la nivelul unității școlare, dacă se impune sau nu obținerea acestui act administrativ pentru fiecare clădire de învățământ.\nÎn cazul inexistenței autorizației sanitare de funcționare, entitățile prevăzute la alin.\nau obligația aducerii la cunoștința publicului, prin intermediul site-urilor proprii și prin orice altă formă de comunicare publică existentă la nivelul unității școlare, a acestui fapt."},{"article":"185","articleNumber":185,"legalText":"În sensul prezentului regulament, prin învățământ profesional și tehnic se înțelege învățământul liceal tehnologic, învățământul postliceal și, respectiv învățământul profesional, până la reorganizarea acestuia în cadrul învățământului liceal tehnologic."},{"article":"186","articleNumber":186,"legalText":"În termen de 45 de zile de la data intrării în vigoare a prezentului regulament, consiliile de administrație ale unităților de învățământ sunt obligate ca, pe baza acestuia și a dispozițiilor legale în vigoare, să aprobe propriile regulamente de organizare și funcționare.\nLa elaborarea regulamentului de organizare și funcționare și a regulamentului de ordine interioară se respectă și prevederile din Statutul elevului, aprobat prin ordin al ministrului educației."}]};
